function missionRuntimePillClass(runtime) {
    const heartbeat = safeString(runtime?.heartbeat);
    const status = missionStatusValue(runtime?.primary?.status);
    if (!runtime || runtime.activeCount <= 0) return 'neutral';
    if (status === 'blocked' || status === 'awaiting_approval') return 'warn';
    if (heartbeat === 'stalled') return 'danger';
    if (status === 'queued' || status === 'pending' || heartbeat === 'starting') return 'neutral';
    return 'ok';
}

function missionRuntimeStatusText(runtime) {
    if (!runtime || runtime.activeCount <= 0) return 'Waiting for active work';
    const room = safeString(runtime?.primary?.room).replace(/_/g, ' ');
    const bits = [
        missionStatusLabel(runtime?.primary?.status),
        room ? `room ${room}` : '',
        `updated ${missionRelativeTime(runtime?.updatedAt)}`,
    ].filter(Boolean);
    return bits.join(' | ');
}

function renderMissionRuntimeHero(payload, jobsPayload = null) {
    const ui = ensureMissionRuntimeHero();
    if (!ui) return;
    const preferredSessionId = missionPreferredSessionId();
    const runtime = missionBuildRuntimeState(payload, jobsPayload, {
        sessionId: preferredSessionId,
        fallbackToAll: true,
    });
    const taskState = preferredSessionId
        && runtime.sessionScoped
        && runtime.sessionId === preferredSessionId
        && taskContinuityLatestState
        && typeof taskContinuityLatestState === 'object'
        ? taskContinuityLatestState
        : null;
    const taskStatus = taskContinuityStatusLabel(taskState?.status);
    const taskGoal = safeString(taskState?.active_goal).trim();
    const taskProgress = safeString(taskState?.last_progress).trim();
    const taskError = taskState ? safeString(taskContinuityLatestError).trim() : '';
    const missingInputs = Array.isArray(taskState?.missing_inputs)
        ? taskState.missing_inputs.map((item) => safeString(item).trim()).filter(Boolean)
        : [];
    const primary = runtime.primary;
    const hasRuntime = runtime.activeCount > 0;
    const hasCurrentTask = hasRuntime || Boolean(taskGoal || taskProgress || taskError || missingInputs.length || taskStatus === 'blocked');
    const summaryText = taskProgress
        || safeString(primary?.summary)
        || safeString(runtime.primaryJob ? missionJobSummary(runtime.primaryJob) : '')
        || 'Mission Control is where delegated work shows up first.';
    if (ui.title instanceof HTMLElement) {
        ui.title.textContent = hasCurrentTask
            ? (taskGoal || safeString(primary?.name) || 'Current delegated task')
            : 'No current task';
    }
    if (ui.summary instanceof HTMLElement) {
        ui.summary.textContent = hasCurrentTask
            ? summaryText
            : 'When Thomas delegates work, the live task will appear here instead of inside chat.';
    }
    if (ui.pill instanceof HTMLElement) {
        let pillClass = missionRuntimePillClass(runtime);
        let pillText = hasRuntime ? missionHeartbeatLabel(runtime.heartbeat) : 'Idle';
        if (!hasRuntime && taskStatus === 'blocked') {
            pillClass = 'warn';
            pillText = 'Blocked';
        } else if (!hasRuntime && hasCurrentTask) {
            pillClass = 'neutral';
            pillText = 'Queued';
        }
        ui.pill.className = `mission-meta-pill ${pillClass}`;
        ui.pill.textContent = pillText;
    }
    if (ui.status instanceof HTMLElement) {
        const statusBits = [];
        if (hasRuntime) {
            statusBits.push(missionRuntimeStatusText(runtime));
        } else if (taskStatus === 'blocked') {
            statusBits.push('Waiting on input');
        } else if (hasCurrentTask) {
            statusBits.push('Queued for delegation');
        } else {
            statusBits.push('Waiting for delegated work');
        }
        if (runtime.sessionScoped && runtime.sessionId) {
            statusBits.push(`session ${safeString(runtime.sessionId).slice(0, 16)}`);
        }
        if (missingInputs.length > 0) {
            statusBits.push(`needs ${missingInputs.slice(0, 2).join(', ')}`);
        } else if (taskError) {
            statusBits.push(taskError);
        }
        ui.status.textContent = statusBits.filter(Boolean).join(' | ');
    }
    const hasProgress = hasRuntime && typeof runtime.progressPct === 'number';
    if (ui.bar instanceof HTMLElement) {
        ui.bar.classList.toggle('is-indeterminate', hasRuntime && !hasProgress);
    }
    if (ui.fill instanceof HTMLElement) {
        ui.fill.style.width = hasProgress ? `${runtime.progressPct}%` : (hasRuntime ? '34%' : (hasCurrentTask ? '18%' : '0%'));
    }
    if (ui.elapsed instanceof HTMLElement) {
        ui.elapsed.textContent = hasRuntime
            ? `Elapsed ${runtime.runtimeLabel}`
            : (hasCurrentTask ? 'Elapsed waiting' : 'Elapsed --');
    }
    if (ui.heartbeat instanceof HTMLElement) {
        ui.heartbeat.textContent = hasRuntime
            ? `Heartbeat ${missionHeartbeatLabel(runtime.heartbeat)}`
            : (hasCurrentTask ? `Task ${taskStatus === 'in_progress' ? 'queued' : taskStatus.replace('_', ' ')}` : 'Heartbeat idle');
    }
    if (ui.agents instanceof HTMLElement) {
        ui.agents.textContent = `${runtime.activeCount} delegated agent${runtime.activeCount === 1 ? '' : 's'}`;
    }
    if (ui.list instanceof HTMLElement) {
        const rows = hasRuntime ? runtime.liveAgents.slice(0, 4) : [];
        if (!rows.length) {
            ui.list.innerHTML = '<div class="mission-runtime-empty">No delegated agents are running right now.</div>';
        } else {
            ui.list.innerHTML = rows.map((item) => {
                const title = safeString(item?.name) || 'worker';
                const detail = [
                    missionStatusLabel(item?.status),
                    safeString(item?.room).replace(/_/g, ' '),
                    `updated ${missionRelativeTime(item?.updated_at)}`,
                ].filter(Boolean).join(' | ');
                return `
                    <article class="mission-runtime-task">
                        <div class="mission-runtime-task-head">
                            <strong>${escapeHtml(title)}</strong>
                            <span class="mission-pill status-${escapeHtml(missionStatusValue(item?.status))}">${escapeHtml(missionStatusLabel(item?.status))}</span>
                        </div>
                        <span class="mission-runtime-task-meta">${escapeHtml(detail)}</span>
                    </article>
                `;
            }).join('');
        }
    }
}

async function fetchTaskContinuitySessionActivity(sessionToken) {
    const sid = safeString(sessionToken || taskContinuityLatestSessionId);
    if (!sid) return taskContinuityLatestActivity;
    const [missionResp, jobsResp] = await Promise.all([
        fetchJsonSafe('/api/mission/control'),
        fetchJsonSafe(`/api/mission/jobs?session_id=${encodeURIComponent(sid)}&limit=36`),
    ]);
    const missionPayload = missionResp.ok && missionResp.data && typeof missionResp.data === 'object'
        ? missionResp.data
        : (taskContinuityMissionPayload || { agents: [], generated_at: '' });
    const jobsPayload = jobsResp.ok && jobsResp.data && typeof jobsResp.data === 'object'
        ? jobsResp.data
        : (taskContinuityMissionJobs || { jobs: [] });
    taskContinuityMissionPayload = missionPayload;
    taskContinuityMissionJobs = jobsPayload;
    const activity = missionBuildRuntimeState(missionPayload, jobsPayload, { sessionId: sid });
    taskContinuityLatestActivity = activity;
    return activity;
}

// RECOVERED (2026-03-18): Was in dead app_parts/part-002b.js, never made it to live runtime.
function taskContinuityStatusTone(statusRaw) {
    const status = safeString(statusRaw).toLowerCase();
    if (status === 'complete' || status === 'done') return 'complete';
    if (status === 'blocked' || status === 'error') return 'blocked';
    if (!status || status === 'idle') return 'idle';
    return 'working';
}

function taskContinuityStatusLabel(statusRaw) {
    const status = safeString(statusRaw).toLowerCase();
    if (status === 'complete' || status === 'done') return 'complete';
    if (status === 'blocked' || status === 'error') return 'blocked';
    if (status === 'idle') return 'idle';
    return 'in_progress';
}

function ensureTaskContinuityToggleUi() {
    if (!taskContinuityPanel) return null;
    const head = taskContinuityPanel.querySelector('.task-continuity-head');
    if (!(head instanceof HTMLElement)) return null;

    let actions = head.querySelector('.task-continuity-actions');
    if (!(actions instanceof HTMLElement)) {
        actions = document.createElement('div');
        actions.className = 'task-continuity-actions';
        head.appendChild(actions);
    }

    let toggleBtn = document.getElementById('taskContinuityToggleBtn');
    if (!(toggleBtn instanceof HTMLButtonElement)) {
        toggleBtn = document.createElement('button');
        toggleBtn.type = 'button';
        toggleBtn.id = 'taskContinuityToggleBtn';
        toggleBtn.className = 'btn-icon task-continuity-toggle';
        toggleBtn.innerHTML = '<i class="ph ph-caret-up"></i>';
    }

    const refreshInActions = taskContinuityRefreshBtn instanceof HTMLElement
        && taskContinuityRefreshBtn.parentNode === actions;
    if (toggleBtn.parentNode !== actions) {
        if (refreshInActions) {
            actions.insertBefore(toggleBtn, taskContinuityRefreshBtn);
        } else {
            actions.appendChild(toggleBtn);
        }
    }
    if (taskContinuityRefreshBtn && taskContinuityRefreshBtn.parentNode !== actions) {
        actions.appendChild(taskContinuityRefreshBtn);
    }

    return toggleBtn;
}

function taskContinuityHasDisplayContent({ state = null, activity = null, error = '' } = {}) {
    const normalizedError = safeString(error).trim();
    const normalizedStatus = taskContinuityStatusLabel(state?.status);
    const activeGoal = safeString(state?.active_goal).trim();
    const progress = safeString(state?.last_progress).trim();
    const missingInputs = Array.isArray(state?.missing_inputs) ? state.missing_inputs.filter(Boolean) : [];
    const activeWorkers = Number(activity?.activeCount || 0) > 0;

    if (normalizedError) return true;
    if (missingInputs.length > 0) return true;
    if (activeWorkers) return true;
    if (normalizedStatus === 'blocked') return true;
    if (normalizedStatus === 'in_progress') {
        return Boolean(activeGoal || progress);
    }
    return false;
}

function taskContinuityShouldForceExpand({ error = '' } = {}) {
    return Boolean(safeString(error).trim());
}

function setTaskContinuityCollapsed(nextCollapsed, { remember = false } = {}) {
    if (!taskContinuityPanel) return;
    const collapsed = Boolean(nextCollapsed);
    if (remember) {
        taskContinuityCollapseOverride = collapsed;
    }
    taskContinuityPanel.classList.toggle('is-collapsed', collapsed);

    const toggleBtn = ensureTaskContinuityToggleUi();
    if (!(toggleBtn instanceof HTMLButtonElement)) return;

    const expanded = !collapsed;
    const label = expanded ? 'Collapse task details' : 'Expand task details';
    toggleBtn.setAttribute('aria-expanded', expanded ? 'true' : 'false');
    toggleBtn.setAttribute('aria-label', label);
    toggleBtn.title = label;
    const icon = toggleBtn.querySelector('i');
    if (icon) {
        icon.className = expanded ? 'ph ph-caret-up' : 'ph ph-caret-down';
    }
}

function syncTaskContinuityPanelVisibility() {
    if (!taskContinuityPanel) return;
    const visibleInNav = taskContinuityShouldBeVisible();
    const hasDisplayContent = taskContinuityHasDisplayContent({
        state: taskContinuityLatestState,
        activity: taskContinuityLatestActivity,
        error: taskContinuityLatestError,
    });
    const show = visibleInNav && hasDisplayContent;
    taskContinuityPanel.classList.toggle('hidden', !show);
    if (!show) {
        setChatAgentPresence(null);
    }
}

function taskContinuityShouldBeVisible() {
    if (!taskContinuityPanel) return false;
    if (isSettingsScreenOpen()) return false;
    return sidebarNavMode === 'chat' || sidebarNavMode === 'search';
}

function stopTaskContinuityAutoRefresh() {
    if (taskContinuityAutoRefreshTimer) {
        window.clearInterval(taskContinuityAutoRefreshTimer);
        taskContinuityAutoRefreshTimer = 0;
    }
}

function startTaskContinuityAutoRefresh() {
    if (taskContinuityAutoRefreshTimer) return;
    taskContinuityAutoRefreshTimer = window.setInterval(() => {
        if (!taskContinuityShouldBeVisible()) return;
        void refreshTaskContinuity();
    }, TASK_CONTINUITY_REFRESH_INTERVAL_MS);
}

function renderTaskContinuity(state, events, sessionToken, { error = '', activity = null } = {}) {
    if (!taskContinuityPanel) return;

    const hasState = Boolean(state && typeof state === 'object');
    const normalizedEvents = Array.isArray(events) ? events.slice(0, 6) : [];
    const status = taskContinuityStatusLabel(hasState ? state.status : (error ? 'blocked' : 'in_progress'));
    const activeGoal = hasState ? safeString(state.active_goal) : '';
    const progress = hasState ? safeString(state.last_progress) : '';
    const missingInputs = hasState && Array.isArray(state.missing_inputs) ? state.missing_inputs.filter(Boolean) : [];
    const updatedAtRaw = hasState ? safeString(state.updated_at) : '';
    const sessionLabelRaw = safeString(sessionToken);
    const sessionLabel = sessionLabelRaw.length > 16 ? `${sessionLabelRaw.slice(0, 16)}` : (sessionLabelRaw || '--');
    const runtimeActivity = activity && typeof activity === 'object' ? activity : taskContinuityLatestActivity;

    if (hasState) {
        taskContinuityLatestState = state;
    }
    if (normalizedEvents.length) {
        taskContinuityLatestEvents = normalizedEvents;
    }
    if (sessionLabelRaw) {
        taskContinuityLatestSessionId = sessionLabelRaw;
    }
    if (runtimeActivity && typeof runtimeActivity === 'object') {
        taskContinuityLatestActivity = runtimeActivity;
    }
    taskContinuityLatestError = safeString(error);

    if (taskContinuityStatusPill) {
        taskContinuityStatusPill.textContent = status;
        taskContinuityStatusPill.classList.remove('is-complete', 'is-blocked');
        if (status === 'complete') taskContinuityStatusPill.classList.add('is-complete');
        if (status === 'blocked') taskContinuityStatusPill.classList.add('is-blocked');
    }

    if (taskContinuityGoal) {
        if (activeGoal) {
            taskContinuityGoal.textContent = activeGoal;
        } else if (error) {
            taskContinuityGoal.textContent = 'Task continuity is temporarily unavailable.';
        } else {
            taskContinuityGoal.textContent = 'No active task tracked yet.';
        }
    }

    if (taskContinuityProgress) {
        if (progress) {
            taskContinuityProgress.textContent = progress;
        } else if (error) {
            taskContinuityProgress.textContent = error;
        } else {
            taskContinuityProgress.textContent = 'Waiting for first update.';
        }
    }

    if (taskContinuityBlockersWrap && taskContinuityBlockersList) {
        taskContinuityBlockersWrap.classList.toggle('hidden', missingInputs.length === 0);
        taskContinuityBlockersList.innerHTML = missingInputs
            .map((item) => `<li>${escapeHtml(safeString(item))}</li>`)
            .join('');
    }

    if (taskContinuityEventsList) {
        if (normalizedEvents.length > 0) {
            taskContinuityEventsList.classList.remove('hidden');
            taskContinuityEventsList.innerHTML = normalizedEvents.map((entry) => {
                const source = safeString(entry?.source).replace(/^chat\./, '');
                const line = safeString(entry?.last_progress);
                const when = missionRelativeTime(entry?.created_at);
                const textLine = [source || 'event', line].filter(Boolean).join(' | ');
                const suffix = when && when !== '--' ? ` (${when})` : '';
                return `<li title="${escapeHtml(textLine)}">${escapeHtml(textLine)}${escapeHtml(suffix)}</li>`;
            }).join('');
        } else {
            taskContinuityEventsList.classList.add('hidden');
            taskContinuityEventsList.innerHTML = '';
        }
    }

    if (taskContinuityUpdatedAt) {
        taskContinuityUpdatedAt.textContent = updatedAtRaw ? `Updated ${missionRelativeTime(updatedAtRaw)}` : 'Not synced';
    }
    if (taskContinuitySession) {
        taskContinuitySession.textContent = `Session: ${sessionLabel}`;
    }

    const hasDisplayContent = taskContinuityHasDisplayContent({
        state,
        activity: runtimeActivity,
        error,
    });
    const forceExpand = taskContinuityShouldForceExpand({
        state,
        activity: runtimeActivity,
        error,
    });
    const autoCollapsed = hasDisplayContent && !forceExpand;
    if (!hasDisplayContent || forceExpand) {
        taskContinuityCollapseOverride = null;
    }
    setTaskContinuityCollapsed(forceExpand ? false : (taskContinuityCollapseOverride ?? autoCollapsed));
    renderTaskContinuitySessionActivity(runtimeActivity);
    setChatAgentPresence(runtimeActivity);
    syncTaskContinuityPanelVisibility();
    if (missionState?.active || sidebarNavMode === 'mission') {
        const missionPayload = missionState?.lastPayload && typeof missionState.lastPayload === 'object'
            ? missionState.lastPayload
            : null;
        const missionJobs = missionState?.lastJobsPayload && typeof missionState.lastJobsPayload === 'object'
            ? missionState.lastJobsPayload
            : null;
        if (missionPayload) {
            renderMissionRuntimeHero(missionPayload, missionJobs);
        }
    }
}


function chatHistoryHasMessageId(messageId) {
    const normalizedId = safeString(messageId);
    if (!normalizedId) return false;
    return chatHistory.some((msg) => safeString(msg?.id) === normalizedId);
}

function appendAssistantChatHistoryMessage(content, messageId) {
    const normalizedId = safeString(messageId);
    const normalizedContent = safeString(content).trim();
    if (!normalizedId || !normalizedContent) return false;
    if (chatHistoryHasMessageId(normalizedId) || document.getElementById(normalizedId)) return false;
    renderMessage({ role: 'assistant', content: normalizedContent, id: normalizedId });
    chatHistory.push({
        id: normalizedId,
        role: 'assistant',
        content: normalizedContent,
        createdAt: Date.now(),
        status: 'complete',
        toolCalls: [],
    });
    return true;
}

function buildEvolveJobSummaryMessage(job) {
    const jobId = safeString(job?.id);
    const status = safeString(job?.status).toLowerCase();
    const result = job?.result && typeof job.result === 'object' ? job.result : {};
    const session = result?.session && typeof result.session === 'object' ? result.session : {};
    const sessionLabel = safeString(session.session_id || result.session_id || jobId) || 'evolve session';
    const sessionStatus = safeString(session.status || status || 'completed') || 'completed';
    const changedFiles = Array.isArray(session.changed_files)
        ? session.changed_files.map((item) => safeString(item)).filter(Boolean)
        : [];
    const changedCount = changedFiles.length;
    if (status === 'succeeded') {
        const headline = `Evolve session ${sessionLabel} finished ${sessionStatus}.`;
        const changedLine = changedCount > 0
            ? `Changed ${changedCount} ${changedCount === 1 ? 'file' : 'files'} on the green side.`
            : 'No filesystem changes were recorded.';
        const fileLine = changedFiles.length > 0
            ? `Files: ${changedFiles.slice(0, 6).join(', ')}${changedFiles.length > 6 ? ', ...' : ''}`
            : '';
        const promoteLine = session.promotable
            ? 'It is ready for review in Mission Control.'
            : 'It is not promotable yet; review the run details in Mission Control.';
        return [headline, changedLine, fileLine, promoteLine].filter(Boolean).join('\n\n');
    }
    const error = job?.error && typeof job.error === 'object' ? job.error : {};
    const errorText = safeString(error.message || error.detail || error.text);
    let failureLead = `Evolve session ${sessionLabel} completed with status ${status || 'unknown'}.`;
    if (status === 'cancelled') {
        failureLead = `Evolve session ${sessionLabel} was cancelled.`;
    } else if (status === 'failed' || status === 'dead') {
        failureLead = `Evolve session ${sessionLabel} failed.`;
    }
    return [failureLead, errorText, 'Mission Control has the run details.'].filter(Boolean).join('\n\n');
}

async function refreshEvolveChatReplies({ sessionOverride = '', force = false } = {}) {
    const sid = safeString(sessionOverride || sessionId || activeChatId || taskContinuityLatestSessionId);
    if (!sid) return;
    if (evolveChatRepliesInFlight && !force) return;
    evolveChatRepliesInFlight = true;
    try {
        const res = await fetchJsonSafe(`/api/mission/jobs?kind=evolve_session&session_id=${encodeURIComponent(sid)}&limit=24`);
        if (!res.ok) return;
        const payload = res.data && typeof res.data === 'object' ? res.data : {};
        const jobs = Array.isArray(payload.jobs) ? payload.jobs.slice() : [];
        jobs.sort((a, b) => safeString(a?.created_at).localeCompare(safeString(b?.created_at)));
        let appended = false;
        jobs.forEach((job) => {
            const jobId = safeString(job?.id);
            const status = safeString(job?.status).toLowerCase();
            if (!jobId || !EVOLVE_TERMINAL_JOB_STATUSES.has(status)) return;
            const messageId = `mission-evolve-result-${jobId}`;
            const content = buildEvolveJobSummaryMessage(job);
            if (appendAssistantChatHistoryMessage(content, messageId)) {
                appended = true;
            }
        });
        if (appended) {
            syncActiveChatSidebarEntry();
            void persistActiveChat({ quiet: true });
        }
    } catch (error) {
        console.warn('Evolve chat reply refresh failed', error);
    } finally {
        evolveChatRepliesInFlight = false;
    }
}

async function refreshTaskContinuity({ sessionOverride = '', force = false } = {}) {
    if (taskContinuityInFlight && !force) return;

    const sid = safeString(sessionOverride || sessionId || activeChatId || taskContinuityLatestSessionId);
    const currentUrl = sid
        ? `/api/task-ledger/current?session_id=${encodeURIComponent(sid)}`
        : '/api/task-ledger/current';
    const historyUrl = sid
        ? `/api/task-ledger/history?session_id=${encodeURIComponent(sid)}&limit=6`
        : '/api/task-ledger/history?limit=6';
    let evolveReplySessionId = sid;

    taskContinuityInFlight = true;
    if (taskContinuityRefreshBtn) taskContinuityRefreshBtn.disabled = true;
    try {
        const [currentResp, historyResp, activity] = await Promise.all([
            fetchJsonSafe(currentUrl),
            fetchJsonSafe(historyUrl),
            fetchTaskContinuitySessionActivity(sid),
        ]);
        if (!currentResp.ok) {
            throw new Error(currentResp.text || `Task continuity HTTP ${currentResp.status}`);
        }
        if (!historyResp.ok) {
            throw new Error(historyResp.text || `Task history HTTP ${historyResp.status}`);
        }
        const currentPayload = currentResp.data && typeof currentResp.data === 'object' ? currentResp.data : {};
        const historyPayload = historyResp.data && typeof historyResp.data === 'object' ? historyResp.data : {};
        const state = currentPayload.state && typeof currentPayload.state === 'object' ? currentPayload.state : null;
        const events = Array.isArray(historyPayload.events) ? historyPayload.events : [];
        const resolvedSid = safeString(currentPayload.session_id || historyPayload.session_id || sid);
        evolveReplySessionId = resolvedSid || sid;
        renderTaskContinuity(state, events, resolvedSid, { activity });
    } catch (error) {
        const fallbackState = taskContinuityLatestState;
        const fallbackEvents = taskContinuityLatestEvents;
        const fallbackSid = safeString(taskContinuityLatestSessionId || sid);
        evolveReplySessionId = fallbackSid || sid;
        renderTaskContinuity(fallbackState, fallbackEvents, fallbackSid, {
            error: safeString(error?.message) || 'Sync failed.',
            activity: taskContinuityLatestActivity,
        });
    } finally {
        taskContinuityInFlight = false;
        if (taskContinuityRefreshBtn) taskContinuityRefreshBtn.disabled = false;
        syncTaskContinuityPanelVisibility();
    }
    void refreshEvolveChatReplies({ sessionOverride: evolveReplySessionId, force });
}


function updateTaskContinuityVisibility({ refresh = false } = {}) {
    if (!taskContinuityPanel) return;
    const visible = taskContinuityShouldBeVisible();
    if (!visible) {
        taskContinuityPanel.classList.add('hidden');
        stopTaskContinuityAutoRefresh();
        setChatAgentPresence(null);
        return;
    }
    startTaskContinuityAutoRefresh();
    syncTaskContinuityPanelVisibility();
    if (refresh) {
        void refreshTaskContinuity({ force: true });
    }
}

async function emitOnboardingTelemetry(eventName, payload = {}) {
    const normalized = safeString(eventName);
    if (!normalized) return;
    const basePayload = payload && typeof payload === 'object' ? { ...payload } : {};
    const telemetryTiming = ensureOnboardingTelemetryClock();
    if (!safeString(basePayload.onboarding_session_id)) {
        basePayload.onboarding_session_id = telemetryTiming.onboarding_session_id;
    }
    if (!Number.isFinite(Number(basePayload.elapsed_ms))) {
        basePayload.elapsed_ms = telemetryTiming.elapsed_ms;
    }
    try {
        await fetch('/api/onboarding/telemetry', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                event: normalized,
                payload: basePayload,
            }),
        });
    } catch {
        // Best-effort telemetry only.
    }
}

function getOnboardingFromPrefs() {
    return currentPreferences?.onboarding || {};
}

function isOnboardingComplete() {
    return Boolean(getOnboardingFromPrefs()?.setup_completed);
}

function mapRecommendedPath(bootstrap) {
    const recommended = safeString(bootstrap?.quick_start?.recommended_path).toLowerCase();
    if (recommended === 'codex') return 'codex';
    if (recommended === 'local') return 'local';
    if (recommended === 'cloud') return 'manual';
    return '';
}

function easySetupStepName(step) {
    if (step <= 1) return 'choose_path';
    if (step === 2) return 'connect';
    if (step === 3) return 'downloads';
    if (step === 4) return 'brain_ready';
    return 'choose_path';
}

function stepFromOnboardingName(nameRaw) {
    const name = safeString(nameRaw).toLowerCase();
    if (name === 'connect') return 2;
    if (name === 'downloads') return 3;
    if (name === 'brain_ready') return 4;
    if (name === 'interview' || name === 'completed') return 4;
    return 1;
}

function setEasySetupStatus(targetEl, text, tone = '') {
    if (!targetEl) return;
    targetEl.textContent = safeString(text);
    targetEl.classList.remove('ok', 'error');
    if (tone === 'ok') targetEl.classList.add('ok');
    if (tone === 'error') targetEl.classList.add('error');
    if (tone === 'error') {
        notifyUser(targetEl.textContent, {
            tone: 'error',
            durationMs: 3400,
        });
    }
}

function hideAssistantSuggestions({ force = false } = {}) {
    if (!assistantSuggestionRail || !assistantSuggestionBubbles) return;
    if (!force && !suggestionDismissible) return;
    _stopSuggestionAutoScroll();
    suggestionRailVersion += 1;
    suggestionContext = '';
    suggestionDismissible = true;
    assistantSuggestionBubbles.innerHTML = '';
    assistantSuggestionBubbles.removeAttribute('data-mode');
    assistantSuggestionBubbles.removeAttribute('data-ready');
    assistantSuggestionRail.classList.add('hidden');
    assistantSuggestionRail.removeAttribute('data-context');
    if (assistantSuggestionTitle) assistantSuggestionTitle.textContent = 'Suggestions';
    if (assistantSuggestionDismissBtn) assistantSuggestionDismissBtn.classList.add('hidden');
}

// CSS marquee handles the scrolling animation via .assistant-suggestion-track
// These are kept as no-ops for any callers that reference them
function _startSuggestionAutoScroll() {}
function _stopSuggestionAutoScroll() {}

function setElementA11y(element, { title = '', label = '' } = {}) {
    if (!(element instanceof HTMLElement)) return;
    if (title) element.title = title;
    if (label) element.setAttribute('aria-label', label);
}

function syncSendButtonA11y() {
    const label = isGenerating ? 'Stop response' : 'Send message';
    setElementA11y(sendBtn, { title: label, label });
}

function configureComposerSurface() {
    setElementA11y(attachBtn, { title: 'Add or create', label: 'Add or create' });
    setElementA11y(micBtn, { title: 'Use microphone', label: 'Use microphone' });
    setElementA11y(sidebarToggleBtn, { title: 'Toggle sidebar', label: 'Toggle sidebar' });
    setElementA11y(modelSetupBtn, { title: 'Configure model', label: 'Configure model' });
    syncSendButtonA11y();

    if (composerActionPopover instanceof HTMLElement) {
        composerActionPopover.setAttribute('aria-label', 'Add or create actions');
    }
    if (!(composerActionList instanceof HTMLElement)) return;

    const priorityOrder = ['add_files', 'research', 'evolve', 'create_image', 'create_video', 'create_song', 'games'];
    const hiddenActions = new Set();
    const buttonByAction = new Map();
    Array.from(composerActionList.querySelectorAll('[data-action]')).forEach((button) => {
        if (!(button instanceof HTMLButtonElement)) return;
        buttonByAction.set(safeString(button.dataset.action).toLowerCase(), button);
    });

    priorityOrder.forEach((action) => {
        const button = buttonByAction.get(action);
        if (button) composerActionList.appendChild(button);
    });

    buttonByAction.forEach((button, action) => {
        const isVisiblePrimary = priorityOrder.includes(action);
        button.classList.toggle('hidden', hiddenActions.has(action));
        button.classList.toggle('is-secondary', !hiddenActions.has(action) && !isVisiblePrimary);
        if (action === 'add_files') {
            button.textContent = 'Add files';
            button.title = 'Attach files to this chat';
        } else if (action === 'research') {
            button.textContent = 'Research';
            button.title = 'Run a research-oriented prompt';
        } else if (action === 'evolve') {
            button.textContent = 'Evolve';
            button.title = 'Launch a green-side self-improvement session';
        } else if (action === 'create_image') {
            button.textContent = 'Create image';
            button.title = 'Start an image generation request';
        } else if (action === 'create_video') {
            button.textContent = 'Create video';
            button.title = 'Start a video generation request';
        } else if (action === 'create_song') {
            button.textContent = 'Create song';
            button.title = 'Start a music generation request';
        } else if (action === 'games') {
            button.textContent = 'Games';
            button.title = 'Open built-in chat games';
        }
    });
}

function isCompactWebLayout() {
    try {
        if (typeof window?.matchMedia === 'function') {
            return window.matchMedia(UI_COMPACT_LAYOUT_MEDIA_QUERY).matches;
        }
    } catch {
        // Fall back to viewport width.
    }
    return window.innerWidth <= 760;
}

function applyResponsiveSidebarState() {
    if (!(sidebar instanceof HTMLElement)) return;
    const viewportMode = isCompactWebLayout() ? 'compact' : 'wide';
    const previousMode = lastSidebarResponsiveViewport;
    lastSidebarResponsiveViewport = viewportMode;
    if (viewportMode === 'compact') {
        if (previousMode !== 'compact') {
            sidebar.classList.add('collapsed');
        }
        return;
    }
    if (previousMode === 'compact' || previousMode === '') {
        sidebar.classList.toggle('collapsed', loadStoredSidebarCollapsed());
    }
}

function setAssistantSuggestions({ title = 'Suggestions', options = [], context = 'general', dismissible = true } = {}) {
    if (!assistantSuggestionRail || !assistantSuggestionBubbles) return;
    if (isGenerating) return;

    const validOptions = (Array.isArray(options) ? options : []).filter((option) => {
        return Boolean(safeString(option?.label) || safeString(option?.value));
    });
    if (validOptions.length === 0) {
        hideAssistantSuggestions({ force: true });
        return;
    }

    suggestionRailVersion += 1;
    const renderVersion = suggestionRailVersion;
    suggestionContext = safeString(context) || 'general';
    suggestionDismissible = Boolean(dismissible);
    const heading = safeString(title) || 'Suggestions';

    assistantSuggestionRail.classList.remove('hidden');
    assistantSuggestionRail.dataset.context = suggestionContext;
    if (assistantSuggestionTitle) {
        assistantSuggestionTitle.textContent = heading;
    }
    if (assistantSuggestionDismissBtn) {
        assistantSuggestionDismissBtn.classList.toggle('hidden', !suggestionDismissible);
    }

    assistantSuggestionBubbles.innerHTML = '';
    assistantSuggestionBubbles.dataset.mode = 'marquee';
    assistantSuggestionBubbles.dataset.ready = 'false';

    const track = document.createElement('div');
    track.className = 'assistant-suggestion-track';

    function createChipButton(option) {
        const button = document.createElement('button');
        const isAction = safeString(option?.kind) === 'action';
        button.className = isAction
            ? 'onboarding-action-chip assistant-suggestion-chip'
            : 'onboarding-option-chip assistant-suggestion-chip';
        if (safeString(option?.tone) === 'primary') button.classList.add('primary');
        if (safeString(option?.tone) === 'danger') button.classList.add('danger');
        button.type = 'button';
        button.textContent = safeString(option?.label) || safeString(option?.value);

        button.addEventListener('click', async () => {
            if (!assistantSuggestionBubbles) return;
            const buttons = Array.from(assistantSuggestionBubbles.querySelectorAll('button'));
            buttons.forEach((b) => { b.disabled = true; });
            button.classList.add('selected');

            try {
                if (typeof option?.onChoose === 'function') {
                    await option.onChoose(option);
                } else {
                    const sendPrompt = safeString(option?.send_prompt || option?.sendPrompt);
                    const insertPrompt = safeString(option?.insert_prompt || option?.insertPrompt);
                    if (sendPrompt) {
                        composerTextarea.value = sendPrompt;
                        composerTextarea.dispatchEvent(new Event('input'));
                        await handleSend();
                    } else if (insertPrompt) {
                        composerTextarea.value = insertPrompt;
                        composerTextarea.dispatchEvent(new Event('input'));
                        composerTextarea.focus();
                    }
                }
            } catch (err) {
                console.error('Suggestion action failed', err);
            } finally {
                if (renderVersion !== suggestionRailVersion) return;
                if (Boolean(option?.keep_after_choose)) {
                    buttons.forEach((b) => { b.disabled = false; });
                    button.classList.remove('selected');
                } else {
                    hideAssistantSuggestions({ force: true });
                }
            }
        });
        return button;
    }

    const loopOptions = validOptions.slice(0, 12);
    const primaryGroup = document.createElement('div');
    primaryGroup.className = 'assistant-suggestion-group';
    loopOptions.forEach((option) => {
        primaryGroup.appendChild(createChipButton(option));
    });
    track.appendChild(primaryGroup);

    const duplicateGroup = document.createElement('div');
    duplicateGroup.className = 'assistant-suggestion-group is-duplicate';
    duplicateGroup.setAttribute('aria-hidden', 'true');
    loopOptions.forEach((option) => {
        duplicateGroup.appendChild(createChipButton(option));
    });
    track.appendChild(duplicateGroup);

    assistantSuggestionBubbles.appendChild(track);

    requestAnimationFrame(() => {
        if (renderVersion !== suggestionRailVersion || !primaryGroup.isConnected || !track.isConnected) return;
        const groupWidth = Math.max(1, Math.ceil(primaryGroup.getBoundingClientRect().width));
        const pixelsPerSecond = 16;
        const durationSeconds = Math.max(40, Math.min(88, groupWidth / pixelsPerSecond));
        track.style.setProperty('--assistant-group-width', `${groupWidth}px`);
        track.style.setProperty('--assistant-scroll-duration', `${durationSeconds}s`);
        assistantSuggestionBubbles.dataset.ready = 'true';
    });
}

function withSuggestionContext(prompt, { userText = '', assistantText = '' } = {}) {
    const base = safeString(prompt);
    const user = safeString(userText).slice(0, 260);
    const assistant = safeString(assistantText).slice(0, 260);
    const contextParts = [];
    if (user) contextParts.push(`User context: ${user}`);
    if (assistant) contextParts.push(`Latest response: ${assistant}`);
    if (contextParts.length === 0) return base;
    return `${base}\n\nContext:\n- ${contextParts.join('\n- ')}`;
}

function classifySuggestionIntent({ userText = '', assistantText = '' } = {}) {
    const user = safeString(userText).toLowerCase();
    const assistant = safeString(assistantText).toLowerCase();
    const combined = `${user} ${assistant}`.trim();
    const hasAny = (tokens = []) => tokens.some((token) => combined.includes(token));

    if (hasAny(['error', 'failed', 'exception', 'stack trace', 'traceback', 'not working', "can't", 'cannot', 'bug'])) {
        return 'troubleshooting';
    }
    if (hasAny(['meeting', 'agenda', 'minutes', 'follow-up', 'follow up', 'standup', 'retro'])) {
        return 'meeting';
    }
    if (hasAny(['email', 'message', 'post', 'resume', 'cover letter', 'proposal', 'announcement', 'copy', 'blog'])) {
        return 'writing';
    }
    if (hasAny(['plan', 'roadmap', 'milestone', 'timeline', 'project', 'launch', 'rollout', 'trip', 'event', 'strategy'])) {
        return 'planning';
    }
    if (hasAny(['compare', 'comparison', 'pros and cons', 'which', 'best option', 'tradeoff', 'trade-off', 'decide', 'decision', 'choose'])) {
        return 'decision';
    }
    if (hasAny(['budget', 'cost', 'pricing', 'price', 'expense', 'financial', 'roi'])) {
        return 'finance';
    }
    if (hasAny(['research', 'analyze', 'analysis', 'investigate', 'summarize', 'summary', 'source', 'evidence'])) {
        return 'research';
    }
    if (hasAny(['learn', 'teach', 'tutorial', 'explain', 'understand', 'study'])) {
        return 'learning';
    }
    if (hasAny(['schedule', 'calendar', 'todo', 'to-do', 'task list', 'prioritize', 'weekly'])) {
        return 'productivity';
    }
    if (hasAny(['brainstorm', 'ideas', 'creative', 'name', 'tagline', 'concept', 'campaign', 'story'])) {
        return 'creative';
    }
    if (hasAny(['code', 'coding', 'script', 'api', 'function', 'class', 'repo', 'pull request', 'test case'])) {
        return 'code';
    }
    return 'general';
}

function normalizeSuggestionOptions(options = []) {
    const unique = [];
    const seen = new Set();
    (Array.isArray(options) ? options : []).forEach((option) => {
        const label = safeString(option?.label || option?.value);
        if (!label) return;
        const key = label.toLowerCase();
        if (seen.has(key)) return;
        seen.add(key);
        unique.push(option);
    });
    return unique.slice(0, 9);
}

function withUniversalSuggestionOptions(baseOptions = [], context = {}) {
    const universal = [
        {
            label: 'Summarize where we are',
            kind: 'option',
            send_prompt: withSuggestionContext('Give a quick summary of where we are and what matters most next.', context),
        },
        {
            label: 'Ask clarifying questions',
            kind: 'option',
            send_prompt: withSuggestionContext('Ask the minimum clarifying questions needed to improve the result.', context),
        },
        {
            label: 'Give me 3 alternatives',
            kind: 'option',
            send_prompt: withSuggestionContext('Offer 3 viable alternatives with tradeoffs.', context),
        },
    ];
    return normalizeSuggestionOptions([...(Array.isArray(baseOptions) ? baseOptions : []), ...universal]);
}

function buildIntentSuggestionOptions(intent, context = {}) {
    const keepMoving = {
        label: 'Keep this moving',
        kind: 'action',
        tone: 'primary',
        send_prompt: withSuggestionContext(
            'Continue this exact task. Give me the best next step and execute it directly where possible.',
            context
        ),
    };

    if (intent === 'planning') {
        return withUniversalSuggestionOptions([
            keepMoving,
            { label: 'Turn into checklist', kind: 'option', send_prompt: withSuggestionContext('Turn this into a concrete checklist with sequence and owners.', context) },
            { label: 'Estimate timeline', kind: 'option', send_prompt: withSuggestionContext('Estimate a realistic timeline with dependencies and risk notes.', context) },
            { label: 'Surface blockers', kind: 'option', send_prompt: withSuggestionContext('Identify likely blockers early and propose mitigations.', context) },
            { label: 'Define success criteria', kind: 'option', send_prompt: withSuggestionContext('Define clear success criteria and measurable outcomes.', context) },
        ], context);
    }
    if (intent === 'writing') {
        return withUniversalSuggestionOptions([
            keepMoving,
            { label: 'Draft version 1', kind: 'option', send_prompt: withSuggestionContext('Write a strong first draft using the current context.', context) },
            { label: 'Make it tighter', kind: 'option', send_prompt: withSuggestionContext('Rewrite this to be shorter, clearer, and more persuasive.', context) },
            { label: 'Adjust tone', kind: 'option', send_prompt: withSuggestionContext('Give 3 tone variants: formal, friendly, and direct.', context) },
            { label: 'Audience rewrite', kind: 'option', send_prompt: withSuggestionContext('Rewrite this for the target audience and goal.', context) },
        ], context);
    }
    if (intent === 'decision') {
        return withUniversalSuggestionOptions([
            keepMoving,
            { label: 'Pros/cons table', kind: 'option', send_prompt: withSuggestionContext('Create a pros and cons table for the main options.', context) },
            { label: 'Recommend one', kind: 'option', send_prompt: withSuggestionContext('Recommend one option decisively and explain why.', context) },
            { label: 'Missing inputs', kind: 'option', send_prompt: withSuggestionContext('List the missing information needed for a confident decision.', context) },
            { label: 'Decision matrix', kind: 'option', send_prompt: withSuggestionContext('Build a weighted decision matrix for the leading options.', context) },
        ], context);
    }
    if (intent === 'research') {
        return withUniversalSuggestionOptions([
            keepMoving,
            { label: 'Plain-language summary', kind: 'option', send_prompt: withSuggestionContext('Summarize the key findings in plain language.', context) },
            { label: 'Compare options', kind: 'option', send_prompt: withSuggestionContext('Compare top options with tradeoffs and recommendations.', context) },
            { label: 'Sources + caveats', kind: 'option', send_prompt: withSuggestionContext('Give source-style reasoning and call out uncertainty clearly.', context) },
            { label: 'What changed recently?', kind: 'option', send_prompt: withSuggestionContext('Highlight recent changes or updates relevant to this topic.', context) },
        ], context);
    }
    if (intent === 'learning') {
        return withUniversalSuggestionOptions([
            keepMoving,
            { label: 'Teach step-by-step', kind: 'option', send_prompt: withSuggestionContext('Teach this step-by-step with examples and no jargon.', context) },
            { label: 'Quick practice', kind: 'option', send_prompt: withSuggestionContext('Give a short practice exercise to lock this in.', context) },
            { label: "Explain like I'm new", kind: 'option', send_prompt: withSuggestionContext('Explain this for a beginner with analogies.', context) },
            { label: 'Cheat sheet', kind: 'option', send_prompt: withSuggestionContext('Create a concise cheat sheet I can reference later.', context) },
        ], context);
    }
    if (intent === 'meeting') {
        return withUniversalSuggestionOptions([
            keepMoving,
            { label: 'Draft agenda', kind: 'option', send_prompt: withSuggestionContext('Create a sharp meeting agenda with goals and timing.', context) },
            { label: 'Action items', kind: 'option', send_prompt: withSuggestionContext('Convert this into action items with owners and deadlines.', context) },
            { label: 'Follow-up message', kind: 'option', send_prompt: withSuggestionContext('Draft a concise follow-up message for stakeholders.', context) },
            { label: 'Talking points', kind: 'option', send_prompt: withSuggestionContext('Create concise talking points for the meeting.', context) },
        ], context);
    }
    if (intent === 'productivity') {
        return withUniversalSuggestionOptions([
            keepMoving,
            { label: 'Prioritize next 3', kind: 'option', send_prompt: withSuggestionContext('Prioritize the next 3 highest-impact tasks.', context) },
            { label: 'Time-block plan', kind: 'option', send_prompt: withSuggestionContext('Create a realistic time-blocked schedule for today/this week.', context) },
            { label: 'Simple checklist', kind: 'option', send_prompt: withSuggestionContext('Turn this into an actionable checklist.', context) },
            { label: 'What can I drop?', kind: 'option', send_prompt: withSuggestionContext('Identify what can be deferred or dropped with low risk.', context) },
        ], context);
    }
    if (intent === 'creative') {
        return withUniversalSuggestionOptions([
            keepMoving,
            { label: 'Generate ideas', kind: 'option', send_prompt: withSuggestionContext('Generate 12 original ideas and rank the top 3.', context) },
            { label: 'Pick strongest concept', kind: 'option', send_prompt: withSuggestionContext('Pick the strongest concept and justify the choice.', context) },
            { label: 'Create variations', kind: 'option', send_prompt: withSuggestionContext('Create multiple variations with different styles and audiences.', context) },
            { label: 'Name + tagline options', kind: 'option', send_prompt: withSuggestionContext('Generate strong name and tagline options with rationale.', context) },
        ], context);
    }
    if (intent === 'finance') {
        return withUniversalSuggestionOptions([
            keepMoving,
            { label: 'Build budget', kind: 'option', send_prompt: withSuggestionContext('Build a practical budget with best/target/worst cases.', context) },
            { label: 'Compare spend options', kind: 'option', send_prompt: withSuggestionContext('Compare spending options and show tradeoffs.', context) },
            { label: 'Find cost cuts', kind: 'option', send_prompt: withSuggestionContext('Identify safe places to reduce cost without hurting outcomes.', context) },
            { label: 'ROI snapshot', kind: 'option', send_prompt: withSuggestionContext('Give a simple ROI snapshot for each option.', context) },
        ], context);
    }
    if (intent === 'troubleshooting') {
        return withUniversalSuggestionOptions([
            keepMoving,
            { label: 'Find root cause', kind: 'option', send_prompt: withSuggestionContext('Diagnose the most likely root cause with evidence.', context) },
            { label: 'Fastest safe fix', kind: 'option', send_prompt: withSuggestionContext('Give the fastest safe fix and verification steps.', context) },
            { label: 'Prevent repeat', kind: 'option', send_prompt: withSuggestionContext('Give a prevention checklist to avoid this recurring.', context) },
            { label: 'Rollback plan', kind: 'option', send_prompt: withSuggestionContext('Provide a rollback/safety plan before risky changes.', context) },
        ], context);
    }
    if (intent === 'code') {
        return withUniversalSuggestionOptions([
            keepMoving,
            { label: 'Implement next step', kind: 'option', send_prompt: withSuggestionContext('Implement the next concrete step and show changes.', context) },
            { label: 'Add tests', kind: 'option', send_prompt: withSuggestionContext('Add targeted tests covering risky paths and edge cases.', context) },
            { label: 'Risk review', kind: 'option', send_prompt: withSuggestionContext('Review this implementation for bugs and regressions.', context) },
            { label: 'Write docs for this', kind: 'option', send_prompt: withSuggestionContext('Document what this does and how to use it.', context) },
        ], context);
    }

    return withUniversalSuggestionOptions([
        keepMoving,
        { label: 'Next 3 actions', kind: 'option', send_prompt: withSuggestionContext('Give the next 3 highest-impact actions from here.', context) },
        { label: 'Alternative approach', kind: 'option', send_prompt: withSuggestionContext('Offer an alternative approach with clear tradeoffs.', context) },
        { label: 'Make it concrete', kind: 'option', send_prompt: withSuggestionContext('Make this more concrete with specific examples and outputs.', context) },
        { label: 'Clarify assumptions', kind: 'option', send_prompt: withSuggestionContext('List assumptions and what to validate first.', context) },
    ], context);
}

function buildStarterSuggestionOptions() {
    if (!isOnboardingComplete()) {
        return [
            {
                label: 'Run Easy Setup',
                kind: 'action',
                tone: 'primary',
                onChoose: async () => {
                    ensureChatVisible();
                    await openEasySetup({ source: 'suggestion', force: false, restart: false });
                },
            },
            {
                label: withAgentName('Is {{agent}} safe?'),
                kind: 'option',
                send_prompt: withAgentName('Is {{agent}} safe to run? Explain approvals, downloads, and security controls in plain language.'),
            },
            {
                label: 'What does setup do?',
                kind: 'option',
                send_prompt: 'Explain Easy Setup in plain English and what each step unlocks.',
            },
            {
                label: 'Minimal setup',
                kind: 'action',
                onChoose: async () => {
                    ensureChatVisible();
                    await openEasySetup({ source: 'suggestion', force: false, restart: true });
                    handleEasySetupPathSelect('manual');
                },
            },
        ];
    }

    return [
        {
            label: 'Plan something',
            kind: 'action',
            tone: 'primary',
            send_prompt: 'Help me plan something important with milestones, priorities, and a practical first step.',
        },
        {
            label: 'Draft a message',
            kind: 'option',
            send_prompt: 'Help me draft a clear, effective message/email. Ask 2-3 clarifying questions first.',
        },
        {
            label: 'Research a topic',
            kind: 'option',
            send_prompt: 'Research this topic and compare the best options with tradeoffs and a recommendation.',
        },
        {
            label: 'Brainstorm ideas',
            kind: 'option',
            send_prompt: 'Brainstorm a wide range of ideas, then shortlist the strongest 3 with reasoning.',
        },
        {
            label: 'Organize tasks',
            kind: 'option',
            send_prompt: 'Turn my current priorities into a focused, realistic task plan.',
        },
        {
            label: 'Help me decide',
            kind: 'option',
            send_prompt: 'Help me decide between options with a clear recommendation and tradeoffs.',
        },
    ];
}

function showStarterSuggestionRail({ force = false, title = '' } = {}) {
    if (!force && safeString(suggestionContext) === 'onboarding') return;
    if (easySetupState.interviewStarted) return;
    const onboardingDone = isOnboardingComplete();
    const heading = safeString(title) || 'Suggestions';
    setAssistantSuggestions({
        title: heading,
        context: onboardingDone ? 'starter' : 'setup',
        dismissible: onboardingDone,
        options: buildStarterSuggestionOptions(),
    });
}

async function fetchBootDoctorRecoveryNotice() {
    const probe = await fetchJsonSafe('/api/bootdoctor/recovery_notice?consume=1', { timeoutMs: 2000 });
    if (!probe.ok) return null;
    const notice = probe.data && typeof probe.data === 'object' ? probe.data.notice : null;
    if (!notice || typeof notice !== 'object') return null;
    return notice;
}

async function maybeRenderSessionIntro() {
    if (!chatMessagesInner) return;
    const sid = safeString(sessionId);
    if (!sid || introShownSessionIds.has(sid)) return;
    if (chatMessagesInner.children.length > 0) return;
    introShownSessionIds.add(sid);

    const notice = await fetchBootDoctorRecoveryNotice();
    const message = safeString(notice?.message);
    const noticeId = `bootdoctor-recovery-${safeString(notice?.updated_at_utc || sid)}`;
    if (!message) return;
    const appended = appendAssistantChatHistoryMessage(message, noticeId);
    if (!appended) return;
    if (welcomeScreen) welcomeScreen.classList.add('hidden');
    if (chatScrollArea) chatScrollArea.classList.remove('hidden');
    showStarterSuggestionRail({ force: true, title: 'Recovered' });
}

function maybeShowAssistantFollowups({ assistantText = '', userText = '' } = {}) {
    if (!isOnboardingComplete()) return;
    if (easySetupState.interviewStarted) return;
    if (safeString(suggestionContext) === 'onboarding') return;
    const context = {
        userText: safeString(userText),
        assistantText: safeString(assistantText),
    };
    const intent = classifySuggestionIntent(context);
    setAssistantSuggestions({
        title: 'Suggestions',
        context: `followup_${intent}`,
        dismissible: true,
        options: buildIntentSuggestionOptions(intent, context),
    });
}

function refreshEasySetupProfileOptions() {
    const profiles = Array.isArray(availableModelProfiles) ? availableModelProfiles : [];
    const manualProfiles = profiles.filter((p) => {
        const provider = safeString(p?.provider).toLowerCase();
        return provider !== 'codex' && provider !== 'ollama' && provider !== 'local';
    });
    const localProfiles = profiles.filter((p) => {
        const provider = safeString(p?.provider).toLowerCase();
        return provider === 'ollama' || provider === 'local';
    });

    if (easySetupManualProfile) {
        easySetupManualProfile.innerHTML = '';
        const source = manualProfiles.length > 0 ? manualProfiles : profiles.filter((p) => safeString(p?.name).toLowerCase() !== 'codex');
        source.forEach((profile) => {
            const option = document.createElement('option');
            option.value = safeString(profile?.name);
            option.textContent = `${safeString(profile?.name)} (${safeString(profile?.provider) || 'provider'})`;
            easySetupManualProfile.appendChild(option);
        });
        if (easySetupManualProfile.options.length === 0) {
            const fallback = document.createElement('option');
            fallback.value = '';
            fallback.textContent = 'No cloud profile configured';
            easySetupManualProfile.appendChild(fallback);
        }
    }

    if (easySetupLocalProfile) {
        easySetupLocalProfile.innerHTML = '';
        const source = localProfiles.length > 0 ? localProfiles : [{ name: 'local', provider: 'ollama' }];
        source.forEach((profile) => {
            const option = document.createElement('option');
            option.value = safeString(profile?.name) || 'local';
            option.textContent = `${safeString(profile?.name) || 'local'} (${safeString(profile?.provider) || 'ollama'})`;
            easySetupLocalProfile.appendChild(option);
        });
    }
}

function renderEasySetupPathCards() {
    if (!easySetupPathGrid) return;
    easySetupPathGrid.querySelectorAll('[data-path]').forEach((btn) => {
        const selected = safeString(btn.getAttribute('data-path')) === safeString(easySetupState.selectedPath);
        btn.classList.toggle('selected', selected);
    });
}

function syncEasySetupConnectionBlocks() {
    if (easySetupCodexBlock) easySetupCodexBlock.classList.toggle('hidden', easySetupState.selectedPath !== 'codex');
    if (easySetupManualBlock) easySetupManualBlock.classList.toggle('hidden', easySetupState.selectedPath !== 'manual');
    if (easySetupLocalBlock) easySetupLocalBlock.classList.toggle('hidden', easySetupState.selectedPath !== 'local');

    if (easySetupConnectionMeta) {
        if (easySetupState.selectedPath === 'codex') {
            easySetupConnectionMeta.textContent = 'ChatGPT OAuth path. Sign in, confirm account status, and validate a Codex profile.';
        } else if (easySetupState.selectedPath === 'manual') {
            easySetupConnectionMeta.textContent = 'Manual key path. Save API key to chosen profile and run live connectivity validation.';
        } else if (easySetupState.selectedPath === 'local') {
            easySetupConnectionMeta.textContent = 'Local path. Validate Ollama endpoint and profile readiness on this machine.';
        } else {
            easySetupConnectionMeta.textContent = 'Select a path first, then run a real verification.';
        }
    }
}

function buildEasySetupDependencyPlan(bootstrap, selectedPath) {
    const tools = bootstrap?.tools || {};
    const plan = [];

    const addDep = (id, title, ready, required, note, installUrl = '') => {
        plan.push({
            id,
            title,
            ready: Boolean(ready),
            required: Boolean(required),
            note: safeString(note),
            install_url: safeString(installUrl),
        });
    };

    if (selectedPath === 'codex') {
        addDep('node', 'Node.js runtime', tools?.node?.installed, true, 'Runs the Codex CLI runtime (official Node.js installer).', tools?.node?.install_url || 'https://nodejs.org/en/download');
        addDep('npm', 'npm package manager', tools?.npm?.installed, true, 'Installs and updates Codex CLI packages.', tools?.npm?.install_url || 'https://nodejs.org/en/download');
        addDep('codex', 'Codex CLI', tools?.codex?.installed, true, 'Handles ChatGPT/Codex sign-in and bridge execution.', tools?.codex?.install_url || 'https://developers.openai.com/codex');
    } else if (selectedPath === 'local') {
        addDep('ollama_installed', 'Ollama installed', tools?.ollama?.installed, true, 'Local runtime for on-device model execution.', tools?.ollama?.install_url || 'https://ollama.com/download');
        addDep('ollama_running', 'Ollama service running', tools?.ollama?.running, true, 'Verifies local Ollama service is reachable.', tools?.ollama?.install_url || 'https://ollama.com/download');
    } else if (selectedPath === 'manual') {
        addDep('manual_key', 'Provider key connected', easySetupState.verified, false, 'Manual key flow does not require local runtime downloads.', '');
        addDep('codex_optional', 'Codex CLI (optional)', tools?.codex?.installed, false, 'Optional only if you want ChatGPT OAuth later.', tools?.codex?.install_url || 'https://developers.openai.com/codex');
    }

    return plan;
}

function missingRequiredDependencies(plan) {
    return (plan || []).filter((item) => Boolean(item.required) && !Boolean(item.ready));
}

function buildEasySetupDependencyTrustNote(selectedPath, plan) {
    const path = safeString(selectedPath);
    const items = Array.isArray(plan) ? plan : [];
    const required = items.filter((item) => Boolean(item?.required));
    const missingRequired = required.filter((item) => !Boolean(item?.ready)).length;
    const requiredCount = required.length;
    const requiredText = requiredCount === 0
        ? 'This path does not require extra local runtime downloads.'
        : `This path uses ${requiredCount} required core tool${requiredCount === 1 ? '' : 's'}.`;
    const missingText = missingRequired > 0
        ? `${missingRequired} required item${missingRequired === 1 ? '' : 's'} still need approval.`
        : 'Required items are already available or not needed.';
    let pathGuidance = '';
    if (path === 'manual') {
        pathGuidance = 'Manual API Key is the lowest-download path.';
    } else if (path === 'codex') {
        pathGuidance = 'Codex path requires official Node.js, npm, and Codex CLI tooling.';
    } else if (path === 'local') {
        pathGuidance = 'Local path requires Ollama running on this machine.';
    }
    return `Security check: nothing installs until you approve it. ${requiredText} ${missingText} ${pathGuidance}`.trim();
}

function renderEasySetupDependencies() {
    if (!easySetupDependencyList) return;
    easySetupDependencyList.innerHTML = '';
    const plan = Array.isArray(easySetupState.dependencyPlan) ? easySetupState.dependencyPlan : [];
    if (plan.length === 0) {
        easySetupDependencyList.innerHTML = '<div class="easy-setup-note">No dependency checks were generated for this path.</div>';
        if (easySetupDependencyTrustNote) {
            easySetupDependencyTrustNote.textContent = 'Security check: this path currently has no dependency checks.';
        }
        return;
    }
    plan.forEach((dep) => {
        const row = document.createElement('div');
        row.className = 'easy-setup-dep-item';
        const stateClass = dep.ready ? 'ready' : (dep.required ? 'missing' : '');
        const stateText = dep.ready ? 'Ready' : (dep.required ? 'Required' : 'Optional');
        row.innerHTML = `
            <div>
                <strong>${escapeHtml(dep.title)}</strong>
                <span>${escapeHtml(dep.note)}</span>
            </div>
            <span class="easy-setup-dep-pill ${stateClass}">${stateText}</span>
        `;
        easySetupDependencyList.appendChild(row);
    });
    if (easySetupDependencyTrustNote) {
        easySetupDependencyTrustNote.textContent = buildEasySetupDependencyTrustNote(easySetupState.selectedPath, plan);
    }
}

function setEasySetupDependencyDefaultStatus() {
    const missing = missingRequiredDependencies(easySetupState.dependencyPlan).length;
    if (missing > 0) {
        setEasySetupStatus(easySetupDependencyStatus, 'Approve required downloads to continue.');
    } else {
        setEasySetupStatus(easySetupDependencyStatus, 'No required downloads pending for this path. Continue when ready.', 'ok');
    }
}

function renderEasySetupReviewPanel() {
    if (!easySetupReviewPanel) return;
    easySetupReviewPanel.innerHTML = '';
    const plan = Array.isArray(easySetupState.dependencyPlan) ? easySetupState.dependencyPlan : [];
    if (plan.length === 0) {
        easySetupReviewPanel.classList.add('hidden');
        return;
    }
    plan.forEach((dep) => {
        const item = document.createElement('div');
        item.className = 'easy-setup-review-item';
        const state = dep.ready ? 'ready' : (dep.required ? 'missing' : 'optional');
        const installUrl = safeString(dep.install_url);
        item.innerHTML = `<strong>${escapeHtml(dep.title)}</strong> - ${escapeHtml(dep.note)} (status: ${escapeHtml(state)})`;
        if (installUrl) {
            const link = document.createElement('a');
            link.href = installUrl;
            link.target = '_blank';
            link.rel = 'noreferrer';
            link.textContent = 'Install link';
            item.appendChild(document.createTextNode(' '));
            item.appendChild(link);
        }
        easySetupReviewPanel.appendChild(item);
    });
}

function updateEasySetupReadyList() {
    if (!easySetupReadyList) return;
    const verifiedProfile = safeString(easySetupState.verifiedProfile) || 'n/a';
    const codexModelCount = Array.isArray(easySetupState.codexModels) ? easySetupState.codexModels.length : 0;
    const depPlan = Array.isArray(easySetupState.dependencyPlan) ? easySetupState.dependencyPlan : [];
    const depMissing = missingRequiredDependencies(depPlan).length;

    const rows = [
        `Connection path: ${safeString(easySetupState.selectedPath) || 'not selected'}`,
        `Verification: ${easySetupState.verified ? 'passed' : 'not verified'}`,
        `Validated profile: ${verifiedProfile}`,
        `Codex models detected: ${codexModelCount}`,
        depMissing > 0
            ? `Required downloads still missing: ${depMissing}`
            : 'Required downloads: complete or not needed for selected path.',
    ];

    easySetupReadyList.innerHTML = '';
    rows.forEach((rowText) => {
        const row = document.createElement('div');
        row.className = 'easy-setup-ready-item';
        row.innerHTML = `<i class="ph ph-check-circle"></i><span>${escapeHtml(rowText)}</span>`;
        easySetupReadyList.appendChild(row);
    });
}

function updateEasySetupNavigation() {
    if (!easySetupBackBtn || !easySetupNextBtn) return;
    easySetupBackBtn.style.visibility = easySetupState.step <= 1 ? 'hidden' : 'visible';
    easySetupNextBtn.textContent = easySetupState.step >= 4 ? 'Continue in chat' : 'Continue';

    let disableNext = false;
    if (easySetupState.step === 1) {
        disableNext = !safeString(easySetupState.selectedPath);
    } else if (easySetupState.step === 2) {
        disableNext = !easySetupState.verified;
    } else if (easySetupState.step === 3) {
        const missing = missingRequiredDependencies(easySetupState.dependencyPlan).length;
        disableNext = missing > 0 && safeString(easySetupState.dependenciesAction) === 'pending';
    }
    easySetupNextBtn.disabled = disableNext;

    const dismissAllowed = !easySetupState.required;
    if (easySetupDismissBtn) {
        easySetupDismissBtn.textContent = easySetupState.required ? 'Skip for now' : 'Close';
        easySetupDismissBtn.classList.toggle('hidden', false);
    }
    if (easySetupCloseBtn) {
        easySetupCloseBtn.classList.toggle('hidden', !dismissAllowed);
    }
    if (easySetupBackdrop) {
        easySetupBackdrop.classList.toggle('easy-setup-backdrop-locked', !dismissAllowed);
    }
}

function setEasySetupStep(step) {
    easySetupState.step = Math.max(1, Math.min(4, Number(step) || 1));
    if (easySetupStep1) easySetupStep1.classList.toggle('hidden', easySetupState.step !== 1);
    if (easySetupStep2) easySetupStep2.classList.toggle('hidden', easySetupState.step !== 2);
    if (easySetupStep3) easySetupStep3.classList.toggle('hidden', easySetupState.step !== 3);
    if (easySetupStep4) easySetupStep4.classList.toggle('hidden', easySetupState.step !== 4);

    if (easySetupProgressFill) {
        easySetupProgressFill.style.width = `${(easySetupState.step / 4) * 100}%`;
    }
    if (easySetupProgressText) {
        easySetupProgressText.textContent = `Step ${easySetupState.step} of 4`;
    }

    renderEasySetupPathCards();
    syncEasySetupConnectionBlocks();
    if (easySetupState.step === 3) {
        renderEasySetupDependencies();
    }
    if (easySetupState.step === 4) {
        updateEasySetupReadyList();
    }
    updateEasySetupNavigation();
}

async function loadEasySetupBootstrap() {
    const res = await fetchJsonSafe('/api/setup/bootstrap');
    if (!res.ok || !res.data) {
        throw new Error(res.text || `Setup bootstrap failed (${res.status})`);
    }
    easySetupState.bootstrap = res.data;
    return res.data;
}

function recommendedLocalModelIdsFromPlan(localPlan) {
    const rows = Array.isArray(localPlan?.recommended_models) ? localPlan.recommended_models : [];
    const ids = [];
    rows.forEach((row) => {
        const id = safeString(row?.id);
        if (!id) return;
        if (!ids.includes(id)) ids.push(id);
    });
    return ids;
}

async function runEasySetupLocalModelSync(profile = 'local') {
    let modelIds = recommendedLocalModelIdsFromPlan(easySetupState.bootstrap?.local_plan);
    if (modelIds.length === 0) {
        const recRes = await fetchJsonSafe(`/api/local/recommendations?profile=${encodeURIComponent(profile)}`);
        if (recRes.ok && recRes.data) {
            const nextPlan = recRes.data?.local_plan;
            modelIds = recommendedLocalModelIdsFromPlan(nextPlan);
            if (nextPlan && easySetupState.bootstrap && typeof easySetupState.bootstrap === 'object') {
                easySetupState.bootstrap.local_plan = nextPlan;
            }
        }
    }

    if (modelIds.length === 0) {
        return {
            skipped: true,
            summary: 'No hardware-recommended local models for this device tier. Continuing with local profile only.',
        };
    }

    const syncRes = await fetchJsonSafe('/api/local/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            profile,
            model_ids: modelIds,
            use_recommended: false,
            pull_missing_only: true,
            verify_only: false,
        }),
        timeoutMs: 1800000,
    });
    if (!syncRes.ok || !syncRes.data) {
        const reason = safeString(syncRes.text) || `Local model sync failed (${syncRes.status})`;
        throw new Error(`${reason} Remediation: ensure Ollama is running and retry.`);
    }

    const rows = Array.isArray(syncRes.data?.results) ? syncRes.data.results : [];
    const failedRows = rows.filter((row) => !Boolean(row?.ok));
    if (failedRows.length > 0) {
        const failed = failedRows.map((row) => safeString(row?.model_id)).filter(Boolean).join(', ');
        const detail = failed ? ` Failed: ${failed}.` : '';
        throw new Error(`Local model sync completed with failures.${detail} Remediation: run Auto Repair and retry.`);
    }

    const pulledCount = rows.filter((row) => Boolean(row?.pulled)).length;
    const reusedCount = rows.filter((row) => Boolean(row?.already_installed)).length;
    const verifiedCount = rows.filter((row) => Boolean(row?.verified)).length;
    let summary = `Verified ${verifiedCount}/${rows.length} local model${rows.length === 1 ? '' : 's'}.`;
    if (pulledCount > 0) summary += ` Pulled ${pulledCount} missing.`;
    if (reusedCount > 0) summary += ` Reused ${reusedCount} already installed.`;
    return {
        skipped: false,
        summary,
    };
}

async function persistOnboardingPrefs(overrides = {}) {
    const existing = getOnboardingFromPrefs();
    const mergedAnswers = {
        ...(existing.answers || {}),
        ...(easySetupState.interviewAnswers || {}),
        ...(overrides.answers || {}),
        connection_path: safeString(easySetupState.selectedPath),
        dependency_action: safeString(easySetupState.dependenciesAction) || 'pending',
    };
    const dependencyPlanPayload = overrides.dependency_plan !== undefined
        ? overrides.dependency_plan
        : {
            path: safeString(easySetupState.selectedPath),
            items: Array.isArray(easySetupState.dependencyPlan) ? easySetupState.dependencyPlan : [],
        };

    const onboardingPatch = {
        version: ONBOARDING_VERSION,
        setup_completed: Boolean(
            Object.prototype.hasOwnProperty.call(overrides, 'setup_completed')
                ? overrides.setup_completed
                : existing.setup_completed
        ),
        current_step: Object.prototype.hasOwnProperty.call(overrides, 'current_step')
            ? overrides.current_step
            : easySetupStepName(easySetupState.step),
        connection_method: Object.prototype.hasOwnProperty.call(overrides, 'connection_method')
            ? overrides.connection_method
            : (safeString(easySetupState.selectedPath) || existing.connection_method || null),
        dependency_plan: dependencyPlanPayload,
        answers: mergedAnswers,
    };

    if (Object.prototype.hasOwnProperty.call(overrides, 'completed_at')) {
        onboardingPatch.completed_at = overrides.completed_at;
    }
    if (Object.prototype.hasOwnProperty.call(overrides, 'dismissed_at')) {
        onboardingPatch.dismissed_at = overrides.dismissed_at;
    }

    try {
        const res = await fetch('/api/preferences', {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ onboarding: onboardingPatch }),
        });
        if (!res.ok) return null;
        currentPreferences = await res.json();
        return currentPreferences?.onboarding || null;
    } catch {
        return null;
    }
}

function closeEasySetup() {
    if (!easySetupModal) return;
    easySetupModal.classList.remove('active');
    easySetupModal.style.display = 'none';
}

function hasEasySetupDismissRecord() {
    const onboarding = getOnboardingFromPrefs();
    return Boolean(safeString(onboarding?.dismissed_at));
}

function blockEasySetupClose(source = 'close_request') {
    const message = withAgentName('Setup is required before {{agent}} can run. Complete Easy Setup to continue.');
    if (easySetupState.step === 1 && easySetupRecommendedHint) {
        easySetupRecommendedHint.textContent = message;
    } else {
        const target = easySetupState.step >= 3 ? easySetupDependencyStatus : easySetupConnectionStatus;
        setEasySetupStatus(target, message, 'error');
    }
    emitOnboardingTelemetry('wizard.close_blocked', {
        source: safeString(source),
        step: easySetupStepName(easySetupState.step),
        path: safeString(easySetupState.selectedPath),
    });
}

function requestEasySetupClose(source = 'close_request') {
    if (easySetupState.required && source !== 'footer_skip') {
        blockEasySetupClose(source);
        return;
    }
    if (source === 'footer_skip' && easySetupState.required) {
        easySetupState.required = false;
        void persistOnboardingPrefs({
            dismissed_at: onboardingNowIso(),
        });
        emitOnboardingTelemetry('wizard.skipped', {
            source: safeString(source),
            step: easySetupStepName(easySetupState.step),
            path: safeString(easySetupState.selectedPath),
        });
    }
    closeEasySetup();
    emitOnboardingTelemetry('wizard.closed', {
        source: safeString(source),
        step: easySetupStepName(easySetupState.step),
        path: safeString(easySetupState.selectedPath),
    });
}

async function openEasySetup({ source = 'manual', force = false, restart = false } = {}) {
    if (!easySetupModal) return;
    if (!currentPreferences) {
        await refreshIdentityState();
    }

    const onboarding = getOnboardingFromPrefs();
    const setupCompleted = Boolean(onboarding?.setup_completed);
    if (!force && setupCompleted) {
        return;
    }
    easySetupState.required = !setupCompleted && !hasEasySetupDismissRecord();
    hideAssistantSuggestions({ force: true });

    easySetupState.source = safeString(source) || 'manual';
    easySetupState.onboardingSessionId = createOnboardingTelemetrySessionId();
    easySetupState.telemetryStartedAtMs = Date.now();
    if (restart) {
        easySetupState.interviewAnswers = {};
        easySetupState.interviewStarted = false;
        easySetupState.interviewStage = 'idle';
        easySetupState.interviewIndex = -1;
        easySetupState.interviewSkipChosen = false;
        easySetupState.dependenciesAction = 'pending';
        easySetupState.selectedPath = '';
    } else {
        easySetupState.interviewAnswers = { ...(onboarding?.answers || {}) };
        const restoredDependencyAction = safeString(onboarding?.answers?.dependency_action);
        easySetupState.dependenciesAction = restoredDependencyAction === 'approved' ? 'approved' : 'pending';
    }

    try {
        const bootstrap = await loadEasySetupBootstrap();
        const recommendedPath = mapRecommendedPath(bootstrap);
        if (!safeString(easySetupState.selectedPath)) {
            easySetupState.selectedPath = safeString(onboarding?.connection_method) || recommendedPath || 'manual';
        }
        easySetupState.dependencyPlan = buildEasySetupDependencyPlan(bootstrap, easySetupState.selectedPath);

        if (easySetupRecommendedHint) {
            const quickStartReason = safeString(bootstrap?.quick_start?.reason);
            if (recommendedPath) {
                easySetupRecommendedHint.textContent = `Recommended: ${recommendedPath}. ${quickStartReason}`;
            } else {
                easySetupRecommendedHint.textContent = quickStartReason || 'Select the path you want. We will verify before applying.';
            }
        }
    } catch (err) {
        if (easySetupRecommendedHint) {
            easySetupRecommendedHint.textContent = `Bootstrap check failed: ${safeString(err?.message) || 'unable to detect local readiness'}`;
        }
    }

    refreshEasySetupProfileOptions();
    renderEasySetupPathCards();
    syncEasySetupConnectionBlocks();
    setEasySetupStatus(easySetupConnectionStatus, 'Run connection test to continue.');
    setEasySetupDependencyDefaultStatus();

    const desiredStep = restart ? 1 : stepFromOnboardingName(onboarding?.current_step);
    setEasySetupStep(desiredStep);
    easySetupModal.classList.add('active');
    easySetupModal.style.display = 'flex';
    emitOnboardingTelemetry('wizard.opened', {
        source: easySetupState.source,
        path: safeString(easySetupState.selectedPath),
        step: easySetupStepName(easySetupState.step),
    });
}

async function maybeAutoOpenEasySetup() {
    if (isOnboardingComplete()) {
        return;
    }
    if (hasEasySetupDismissRecord()) {
        return;
    }
    await openEasySetup({ source: 'auto', force: false, restart: false });
}

function handleEasySetupPathSelect(path) {
    easySetupState.selectedPath = safeString(path);
    easySetupState.verified = false;
    easySetupState.verifiedProfile = '';
    easySetupState.codexModels = [];
    easySetupState.dependenciesAction = 'pending';
    easySetupState.dependencyPlan = buildEasySetupDependencyPlan(easySetupState.bootstrap, easySetupState.selectedPath);
    renderEasySetupPathCards();
    syncEasySetupConnectionBlocks();
    setEasySetupStatus(easySetupConnectionStatus, 'Path selected. Run connection test.');
    setEasySetupDependencyDefaultStatus();
    updateEasySetupNavigation();
}

async function handleEasySetupConnectionTest() {
    if (!safeString(easySetupState.selectedPath)) {
        setEasySetupStatus(easySetupConnectionStatus, 'Pick a connection path first.', 'error');
        return;
    }

    easySetupState.verified = false;
    easySetupState.verifiedProfile = '';
    setEasySetupStatus(easySetupConnectionStatus, 'Running live connection checks...');

    try {
        if (easySetupState.selectedPath === 'codex') {
            const statusRes = await fetchJsonSafe('/api/codex/status');
            let loggedIn = Boolean(statusRes.data?.logged_in);
            if (!loggedIn) {
                const loginRes = await fetchJsonSafe('/api/codex/login', { method: 'POST' });
                loggedIn = Boolean(loginRes.data?.ok);
                if (!loggedIn) {
                    const errText = safeString(loginRes.data?.error) || 'Codex login failed.';
                    throw new Error(`${errText} Remediation: install/login Codex CLI and retry.`);
                }
            }
            const modelsRes = await fetchJsonSafe('/api/codex/models');
            easySetupState.codexModels = Array.isArray(modelsRes.data?.models) ? modelsRes.data.models : [];

            const codexProfile = availableModelProfiles.find((p) => safeString(p?.provider).toLowerCase() === 'codex');
            if (codexProfile?.name) {
                const validateRes = await fetchJsonSafe(`/api/models/${encodeURIComponent(codexProfile.name)}/validate?tool_smoke=0`);
                if (!validateRes.ok || !Boolean(validateRes.data?.ok)) {
                    const reason = safeString(validateRes.data?.error) || safeString(validateRes.text) || 'Codex profile validation failed.';
                    throw new Error(`${reason} Remediation: run auto repair and retry.`);
                }
                easySetupState.verifiedProfile = safeString(codexProfile.name);
            } else {
                easySetupState.verifiedProfile = 'codex';
            }

            easySetupState.verified = true;
            const codexName = safeString(statusRes.data?.display_name) || safeString(statusRes.data?.email) || 'Codex account';
            setEasySetupStatus(
                easySetupConnectionStatus,
                `Connected as ${codexName}. Models detected: ${easySetupState.codexModels.length}.`,
                'ok'
            );
            if (easySetupCodexMeta) {
                easySetupCodexMeta.textContent = `Signed in. Detected ${easySetupState.codexModels.length} Codex model(s).`;
            }
        } else if (easySetupState.selectedPath === 'manual') {
            const profile = safeString(easySetupManualProfile?.value);
            if (!profile) {
                throw new Error('No manual profile is configured. Add a cloud model profile first.');
            }
            const apiKey = safeString(easySetupManualApiKey?.value);
            if (apiKey) {
                const secretRes = await fetchJsonSafe(`/api/secrets/${encodeURIComponent(profile)}`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        api_key: apiKey,
                        persist: Boolean(easySetupManualPersist?.checked),
                    }),
                });
                if (!secretRes.ok) {
                    const reason = safeString(secretRes.text) || `Could not save key for profile "${profile}".`;
                    throw new Error(`${reason} Remediation: verify key format and profile.`);
                }
            }

            const validateRes = await fetchJsonSafe(`/api/models/${encodeURIComponent(profile)}/validate?tool_smoke=0`);
            if (!validateRes.ok || !Boolean(validateRes.data?.ok)) {
                const reason = safeString(validateRes.data?.error) || safeString(validateRes.text) || 'Profile validation failed.';
                throw new Error(`${reason} Remediation: verify provider key and endpoint.`);
            }

            easySetupState.verified = true;
            easySetupState.verifiedProfile = profile;
            setEasySetupStatus(
                easySetupConnectionStatus,
                `Manual profile "${profile}" validated.`,
                'ok'
            );
        } else {
            const profile = safeString(easySetupLocalProfile?.value) || 'local';
            const validateRes = await fetchJsonSafe(`/api/models/${encodeURIComponent(profile)}/validate?tool_smoke=0`);
            if (!validateRes.ok || !Boolean(validateRes.data?.ok)) {
                const reason = safeString(validateRes.data?.error) || safeString(validateRes.text) || 'Local validation failed.';
                throw new Error(`${reason} Remediation: install/start Ollama or run auto repair.`);
            }
            setEasySetupStatus(easySetupConnectionStatus, `Local profile "${profile}" validated. Syncing recommended local models...`);
            const localSync = await runEasySetupLocalModelSync(profile);
            easySetupState.verified = true;
            easySetupState.verifiedProfile = profile;
            const syncSummary = safeString(localSync?.summary);
            setEasySetupStatus(
                easySetupConnectionStatus,
                syncSummary ? `Local profile "${profile}" validated. ${syncSummary}` : `Local profile "${profile}" validated.`,
                'ok'
            );
        }
    } catch (err) {
        easySetupState.verified = false;
        easySetupState.verifiedProfile = '';
        setEasySetupStatus(easySetupConnectionStatus, safeString(err?.message) || 'Connection check failed.', 'error');
    }

    easySetupState.dependencyPlan = buildEasySetupDependencyPlan(easySetupState.bootstrap, easySetupState.selectedPath);
    setEasySetupDependencyDefaultStatus();
    updateEasySetupNavigation();
    await persistOnboardingPrefs({
        current_step: 'connect',
        connection_method: safeString(easySetupState.selectedPath) || null,
    });
    emitOnboardingTelemetry('wizard.connection_tested', {
        path: safeString(easySetupState.selectedPath),
        verified: Boolean(easySetupState.verified),
        profile: safeString(easySetupState.verifiedProfile),
    });
}

async function runEasySetupRepair(trigger = 'repair') {
    setEasySetupStatus(easySetupDependencyStatus, 'Running setup repair. You may need to approve system installer prompts.');
    const res = await fetchJsonSafe('/api/setup/repair', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            auto_install_tools: true,
            skip_install: false,
            skip_doctor: false,
        }),
    });

    if (!res.ok || !res.data) {
        const reason = safeString(res.data?.error) || safeString(res.text) || 'Repair call failed.';
        setEasySetupStatus(easySetupDependencyStatus, `${reason} Remediation: run repair from command line and retry.`, 'error');
        emitOnboardingTelemetry('wizard.download_approval_failed', {
            trigger,
            error: reason,
        });
        return false;
    }

    if (!Boolean(res.data?.ok)) {
        const errorMsg = safeString(res.data?.error) || `Repair exited with code ${res.data?.exit_code}.`;
        const stderrTail = safeString(res.data?.stderr_tail);
        const finalMsg = stderrTail ? `${errorMsg}\n${stderrTail}` : errorMsg;
        setEasySetupStatus(easySetupDependencyStatus, `${finalMsg} Remediation: approve prompts and retry.`, 'error');
        emitOnboardingTelemetry('wizard.download_approval_failed', {
            trigger,
            error: errorMsg,
        });
        return false;
    }

    const reportPath = safeString(res.data?.report_path);
    setEasySetupStatus(
        easySetupDependencyStatus,
        reportPath
            ? `Repair completed. Report: ${reportPath}`
            : 'Repair completed successfully.',
        'ok'
    );
    emitOnboardingTelemetry('wizard.download_approved', {
        trigger,
        report_path: reportPath,
    });
    return true;
}

async function handleEasySetupApproveAll() {
    const ok = await runEasySetupRepair('approve_all');
    if (!ok) return;
    try {
        await loadEasySetupBootstrap();
    } catch {
        // Ignore refresh failures; keep existing plan.
    }
    easySetupState.dependencyPlan = buildEasySetupDependencyPlan(easySetupState.bootstrap, easySetupState.selectedPath);
    easySetupState.dependenciesAction = 'approved';
    renderEasySetupDependencies();
    renderEasySetupReviewPanel();
    updateEasySetupNavigation();
    await persistOnboardingPrefs({
        current_step: 'downloads',
        answers: { dependency_action: 'approved' },
    });
}

function handleEasySetupReviewDownloads() {
    if (!easySetupReviewPanel) return;
    renderEasySetupReviewPanel();
    easySetupReviewPanel.classList.toggle('hidden');
}

async function handleEasySetupNext() {
    if (easySetupState.step === 1) {
        if (!safeString(easySetupState.selectedPath)) {
            setEasySetupStatus(easySetupConnectionStatus, 'Select a connection path first.', 'error');
            return;
        }
        setEasySetupStep(2);
        await persistOnboardingPrefs({ current_step: 'connect', dismissed_at: null });
        emitOnboardingTelemetry('wizard.step_advanced', { step: 'connect', path: easySetupState.selectedPath });
        return;
    }

    if (easySetupState.step === 2) {
        if (!easySetupState.verified) {
            setEasySetupStatus(
                easySetupConnectionStatus,
                'Connection must verify before continuing. Use "Connect and Test".',
                'error'
            );
            return;
        }
        easySetupState.dependencyPlan = buildEasySetupDependencyPlan(easySetupState.bootstrap, easySetupState.selectedPath);
        setEasySetupStep(3);
        await persistOnboardingPrefs({ current_step: 'downloads' });
        emitOnboardingTelemetry('wizard.step_advanced', { step: 'downloads', path: easySetupState.selectedPath });
        return;
    }

    if (easySetupState.step === 3) {
        const missing = missingRequiredDependencies(easySetupState.dependencyPlan).length;
        if (missing > 0 && safeString(easySetupState.dependenciesAction) === 'pending') {
            setEasySetupStatus(
                easySetupDependencyStatus,
                'Approve required downloads before continuing.',
                'error'
            );
            return;
        }
        setEasySetupStep(4);
        await persistOnboardingPrefs({ current_step: 'brain_ready' });
        emitOnboardingTelemetry('wizard.step_advanced', { step: 'brain_ready', path: easySetupState.selectedPath });
        return;
    }

    closeEasySetup();
    ensureChatVisible();
    beginOnboardingInterview();
}

async function handleEasySetupBack() {
    if (easySetupState.step <= 1) return;
    setEasySetupStep(easySetupState.step - 1);
    await persistOnboardingPrefs({ current_step: easySetupStepName(easySetupState.step) });
}

function initEasySetup() {
    if (!easySetupModal) return;
    if (easySetupDismissBtn) {
        easySetupDismissBtn.textContent = 'Skip for now';
        easySetupDismissBtn.classList.remove('hidden');
    }
    if (easySetupCloseBtn) {
        easySetupCloseBtn.classList.add('hidden');
    }

    if (easySetupPathGrid) {
        easySetupPathGrid.querySelectorAll('[data-path]').forEach((btn) => {
            btn.addEventListener('click', () => {
                handleEasySetupPathSelect(btn.getAttribute('data-path'));
            });
        });
    }

    if (easySetupCloseBtn) easySetupCloseBtn.addEventListener('click', () => requestEasySetupClose('close_button'));
    if (easySetupBackdrop) easySetupBackdrop.addEventListener('click', () => requestEasySetupClose('backdrop'));
    if (easySetupDismissBtn) easySetupDismissBtn.addEventListener('click', () => requestEasySetupClose('footer_skip'));
    if (easySetupBackBtn) {
        easySetupBackBtn.addEventListener('click', () => {
            handleEasySetupBack();
        });
    }
    if (easySetupNextBtn) {
        easySetupNextBtn.addEventListener('click', () => {
            handleEasySetupNext();
        });
    }
    if (easySetupTestConnectionBtn) {
        easySetupTestConnectionBtn.addEventListener('click', () => {
            handleEasySetupConnectionTest();
        });
    }
    if (easySetupAutoRepairBtn) {
        easySetupAutoRepairBtn.addEventListener('click', async () => {
            const ok = await runEasySetupRepair('connect_step');
            if (ok) {
                try {
                    await loadEasySetupBootstrap();
                } catch {
                    // Best effort only.
                }
                easySetupState.dependencyPlan = buildEasySetupDependencyPlan(easySetupState.bootstrap, easySetupState.selectedPath);
                renderEasySetupDependencies();
                updateEasySetupNavigation();
            }
        });
    }
    if (easySetupApproveAllBtn) {
        easySetupApproveAllBtn.addEventListener('click', () => {
            handleEasySetupApproveAll();
        });
    }
    if (easySetupReviewDownloadsBtn) easySetupReviewDownloadsBtn.addEventListener('click', handleEasySetupReviewDownloads);
    if (rerunEasySetupBtn) {
        rerunEasySetupBtn.addEventListener('click', async () => {
            if (isSettingsScreenOpen()) closeSettingsModal({ restoreNav: false });
            await openEasySetup({ source: 'settings', force: true, restart: true });
        });
    }

    syncEasySetupConnectionBlocks();
    setEasySetupStatus(easySetupConnectionStatus, 'Choose a path and run connection test.');
    setEasySetupDependencyDefaultStatus();
    setEasySetupStep(1);
}

function renderOnboardingChoiceBubble(prompt, options, onChoose) {
    if (safeString(prompt)) {
        renderMessage({ role: 'assistant', content: prompt });
    }
    setAssistantSuggestions({
        title: 'Onboarding choices',
        context: 'onboarding',
        dismissible: false,
        options: (options || []).map((option) => ({
            ...option,
            keep_after_choose: false,
            onChoose: async () => {
                if (typeof onChoose === 'function') {
                    await onChoose(option);
                }
            },
        })),
    });
}

function deriveOnboardingDefaults(answers) {
    const experience = safeString(answers?.experience) || 'builder';
    const autonomyPref = safeString(answers?.autonomy) || 'balanced';
    const costPref = safeString(answers?.cost_quality) || 'balanced';
    const memoryPref = safeString(answers?.memory) || 'remember';
    const personalityPref = safeString(answers?.personality) || 'balanced';
    const workflowPref = safeString(answers?.workflow) || 'build_features';
    const togglesPref = safeString(answers?.default_toggles) || 'safe_defaults';

    let autonomyLevel = 2;
    if (experience === 'new') autonomyLevel = 1;
    if (experience === 'expert') autonomyLevel = 4;
    if (autonomyPref === 'guided') autonomyLevel -= 1;
    if (autonomyPref === 'aggressive') autonomyLevel += 1;
    autonomyLevel = Math.max(1, Math.min(4, autonomyLevel));

    let tokenEconomy = 'optimal';
    if (costPref === 'low_cost') tokenEconomy = 'cheap';
    if (costPref === 'max_quality') tokenEconomy = 'max';

    const memoryEnabled = memoryPref === 'remember';
    const sessionOnlyMemory = memoryPref === 'session_only';
    const requireCommandApproval = togglesPref === 'safe_defaults' || workflowPref === 'ops_reliability';
    const allowNetwork = togglesPref !== 'safe_defaults';
    const showTokenMeter = togglesPref === 'power_mode';
    const debugPanelEnabled = togglesPref === 'power_mode';
    const desktopNotifications = togglesPref !== 'quiet_mode';
    const showTimestamps = personalityPref === 'direct_technical' || workflowPref === 'ops_reliability';
    const uiDensity = togglesPref === 'power_mode' ? 'compact' : 'comfortable';
    const defaultMode = workflowPref === 'research' ? 'thinking' : 'auto';
    let profileType = 'adaptive';
    if (experience === 'new' || personalityPref === 'calm_guide') profileType = 'non_coder';
    if (experience === 'expert' || personalityPref === 'direct_technical') profileType = 'coder';

    return {
        autonomyLevel,
        tokenEconomy,
        memoryEnabled,
        sessionOnlyMemory,
        requireCommandApproval,
        allowNetwork,
        showTokenMeter,
        debugPanelEnabled,
        desktopNotifications,
        showTimestamps,
        uiDensity,
        defaultMode,
        profileType,
    };
}

async function applyOnboardingCompletion({ skippedInterview = false } = {}) {
    const onboardingAnswers = {
        ...(getOnboardingFromPrefs()?.answers || {}),
        ...(easySetupState.interviewAnswers || {}),
        interview_skipped: Boolean(skippedInterview),
        connection_path: safeString(easySetupState.selectedPath),
        dependency_action: safeString(easySetupState.dependenciesAction) || 'pending',
    };
    const derived = deriveOnboardingDefaults(onboardingAnswers);
    const completedAt = onboardingNowIso();

    const patch = {
        autonomy: { default_level: `L${derived.autonomyLevel}` },
        memory: { enabled_global: derived.memoryEnabled },
        notifications: { desktop: derived.desktopNotifications },
        profile: { profile_type: derived.profileType },
        advanced: {
            runtime: {
                default_mode: derived.defaultMode,
                default_token_economy: derived.tokenEconomy,
            },
            tools: {
                require_command_approval: derived.requireCommandApproval,
                allow_network: derived.allowNetwork,
            },
            interface: {
                show_timestamps: derived.showTimestamps,
                show_token_meter: derived.showTokenMeter,
                debug_panel_enabled: derived.debugPanelEnabled,
                ui_density: derived.uiDensity,
            },
        },
        onboarding: {
            setup_completed: true,
            version: ONBOARDING_VERSION,
            completed_at: completedAt,
            dismissed_at: null,
            current_step: 'completed',
            connection_method: safeString(easySetupState.selectedPath) || null,
            dependency_plan: {
                path: safeString(easySetupState.selectedPath),
                items: Array.isArray(easySetupState.dependencyPlan) ? easySetupState.dependencyPlan : [],
            },
            answers: onboardingAnswers,
        },
    };

    const res = await fetch('/api/preferences', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(patch),
    });
    if (!res.ok) {
        const reason = await res.text();
        throw new Error(reason || `Failed to finalize onboarding (${res.status})`);
    }
    currentPreferences = await res.json();

    if (derived.sessionOnlyMemory && sessionId) {
        await fetch(`/api/preferences?thread_id=${encodeURIComponent(sessionId)}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ memory: { thread_enabled: true } }),
        }).catch(() => { });
    }

    activeAutonomyLevel = derived.autonomyLevel;
    activeTokenEconomy = derived.tokenEconomy === 'optimal' ? 'balanced' : derived.tokenEconomy;
    activeChatMode = normalizeChatMode(derived.defaultMode) || 'auto';
    setSegmentedControlSelection('setupAutonomyGroup', String(activeAutonomyLevel));
    setSegmentedControlSelection('setupEconomyGroup', activeTokenEconomy);
    if (settingAdvDefaultMode) settingAdvDefaultMode.value = activeChatMode;
    if (setupMemoryToggle) setupMemoryToggle.checked = Boolean(currentPreferences?.memory?.enabled_global);
    if (settingMemoryEnabled) settingMemoryEnabled.checked = Boolean(currentPreferences?.memory?.enabled_global);
    updateSidebarIdentity();
    easySetupState.interviewStarted = false;
    easySetupState.interviewStage = 'idle';
    easySetupState.interviewIndex = -1;
    hideAssistantSuggestions({ force: true });
    showStarterSuggestionRail({ force: true });

    emitOnboardingTelemetry('completed', {
        skipped_interview: Boolean(skippedInterview),
        connection_method: safeString(easySetupState.selectedPath),
        autonomy_level: derived.autonomyLevel,
        token_economy: derived.tokenEconomy,
    });
}

function includesAny(text, terms = []) {
    return (terms || []).some((term) => text.includes(term));
}

function isSecurityTrustConcern(textRaw) {
    const text = safeString(textRaw).toLowerCase();
    if (!text) return false;
    return includesAny(text, [
        'security',
        'secure',
        'unsafe',
        'cyber',
        'risk',
        'risky',
        'trust',
        'dependency',
        'dependencies',
        'dependency tree',
        'dependency trees',
        'install',
        'installer',
        'download',
        'permission',
        'permissions',
        'malware',
        'virus',
        'supply chain',
    ]);
}

function buildSetupSafetyMessage() {
    return [
        'Fair concern. Setup is designed to be explicit and user-controlled:',
        withAgentName('- No silent installs: {{agent}} only runs dependency installs after your approval.'),
        '- Dependency step shows why each tool is needed and where it comes from.',
        '- You can choose the lowest-download path: Manual API Key.',
        '- Safe defaults keep command approval on so actions stay supervised.',
    ].join('\n');
}

function showSetupSafetySuggestions() {
    setAssistantSuggestions({
        title: 'Setup safety',
        context: 'setup_safety',
        dismissible: false,
        options: [
            {
                label: 'Run Easy Setup',
                kind: 'action',
                tone: 'primary',
                onChoose: async () => {
                    ensureChatVisible();
                    await openEasySetup({ source: 'safety_suggestion', force: false, restart: false });
                },
            },
            {
                label: 'Use lowest-download setup',
                kind: 'action',
                onChoose: async () => {
                    ensureChatVisible();
                    await openEasySetup({ source: 'safety_suggestion', force: false, restart: true });
                    handleEasySetupPathSelect('manual');
                },
            },
            {
                label: 'Show exact downloads',
                kind: 'option',
                send_prompt: withAgentName('Show exactly what {{agent}} installs in each setup path and why each dependency is required.'),
            },
        ],
    });
}

function resolveOnboardingOptionLabel(question, value) {
    const options = Array.isArray(question?.options) ? question.options : [];
    const found = options.find((option) => safeString(option?.value) === safeString(value));
    return safeString(found?.label) || safeString(value);
}

function formatOnboardingQuestionOptionList(question) {
    const options = Array.isArray(question?.options) ? question.options : [];
    return options.map((option) => `"${safeString(option?.label)}"`).filter(Boolean).join(', ');
}

function parseOnboardingQuestionAnswer(question, textRaw) {
    const text = safeString(textRaw).toLowerCase();
    if (!text) return '';
    if (text === 'skip' || includesAny(text, ['skip interview', 'skip questions', 'skip setup', 'skip this'])) {
        return '__skip_interview__';
    }

    const options = Array.isArray(question?.options) ? question.options : [];
    for (const option of options) {
        const valueToken = safeString(option?.value).toLowerCase().replace(/_/g, ' ');
        const labelToken = safeString(option?.label).toLowerCase();
        if ((valueToken && text.includes(valueToken)) || (labelToken && text.includes(labelToken))) {
            return safeString(option?.value);
        }
    }

    const questionId = safeString(question?.id);
    if (questionId === 'experience') {
        if (includesAny(text, ['new', 'beginner', 'novice', 'first time', 'first-time', 'non technical', 'non-technical', 'just starting'])) return 'new';
        if (includesAny(text, ['expert', 'advanced', 'senior', 'professional', 'pro'])) return 'expert';
        if (includesAny(text, ['builder', 'intermediate', 'some experience', 'comfortable'])) return 'builder';
    }
    if (questionId === 'personality') {
        if (includesAny(text, ['direct', 'technical', 'blunt', 'straight', 'no fluff', 'concise'])) return 'direct_technical';
        if (includesAny(text, ['calm', 'friendly', 'gentle', 'coach', 'guide', 'supportive'])) return 'calm_guide';
        if (includesAny(text, ['balanced', 'normal', 'neutral', 'mix'])) return 'balanced';
    }
    if (questionId === 'autonomy') {
        if (includesAny(text, ['guided', 'careful', 'safe', 'step by step', 'step-by-step', 'confirm', 'approval', 'ask first'])) return 'guided';
        if (includesAny(text, ['aggressive', 'autonomous', 'fully auto', 'take over', 'run with it', 'do it all', 'max autonomy'])) return 'aggressive';
        if (includesAny(text, ['balanced', 'normal', 'middle'])) return 'balanced';
    }
    if (questionId === 'cost_quality') {
        if (includesAny(text, ['low cost', 'cheap', 'budget', 'save money', 'cost first', 'economy'])) return 'low_cost';
        if (includesAny(text, ['max quality', 'highest quality', 'best quality', 'quality first', 'accuracy', 'premium'])) return 'max_quality';
        if (includesAny(text, ['balanced', 'middle'])) return 'balanced';
    }
    if (questionId === 'memory') {
        if (includesAny(text, ['disable memory', 'no memory', 'dont remember', 'do not remember', 'forget', 'private'])) return 'disabled';
        if (includesAny(text, ['session only', 'this session', 'temporary', 'temp memory'])) return 'session_only';
        if (includesAny(text, ['remember', 'across sessions', 'persistent', 'save context'])) return 'remember';
    }
    if (questionId === 'workflow') {
        if (includesAny(text, ['build', 'ship', 'feature', 'features', 'product', 'app', 'coding', 'code'])) return 'build_features';
        if (includesAny(text, ['research', 'investigate', 'analyze', 'compare', 'study'])) return 'research';
        if (includesAny(text, ['ops', 'reliability', 'incident', 'monitoring', 'infra', 'infrastructure', 'production', 'stability'])) return 'ops_reliability';
    }
    if (questionId === 'default_toggles') {
        if (includesAny(text, ['safe', 'conservative', 'cautious', 'guardrails', 'approval'])) return 'safe_defaults';
        if (includesAny(text, ['power', 'advanced', 'fast', 'max control', 'pro mode'])) return 'power_mode';
        if (includesAny(text, ['quiet', 'minimal', 'silent', 'fewer notifications', 'no notifications'])) return 'quiet_mode';
    }

    return '';
}

function parseOnboardingSkipConfirmAction(textRaw) {
    const text = safeString(textRaw).toLowerCase();
    if (!text) return '';
    if (includesAny(text, ['finish', 'defaults', 'default settings', 'skip it', 'yes'])) return 'finish_defaults';
    if (includesAny(text, ['resume', 'continue', 'questions', 'go back', 'no'])) return 'resume';
    return '';
}

function parseOnboardingReviewAction(textRaw) {
    const text = safeString(textRaw).toLowerCase();
    if (!text) return '';
    if (includesAny(text, ['open settings', 'settings', 'tweak settings'])) return 'settings';
    if (includesAny(text, ['defaults', 'skip interview', 'finish with defaults', 'use defaults'])) return 'skip';
    if (includesAny(text, ['finish', 'apply', 'done', 'complete', 'looks good', 'yes'])) return 'apply';
    return '';
}

async function submitOnboardingInterviewAnswer(question, value, { source = 'bubble' } = {}) {
    const index = Number(easySetupState.interviewIndex);
    easySetupState.interviewAnswers[question.id] = value;
    easySetupState.interviewIndex = index + 1;
    easySetupState.interviewStage = 'question';
    await persistOnboardingPrefs({
        current_step: 'interview',
        answers: { [question.id]: value },
    });
    emitOnboardingTelemetry('interview.answer', {
        question_id: question.id,
        value,
        source: safeString(source) || 'bubble',
    });
    if (safeString(source) === 'text') {
        const answerLabel = resolveOnboardingOptionLabel(question, value);
        renderMessage({
            role: 'assistant',
            content: `Got it. **${answerLabel}** works for that.`,
        });
    }
    promptOnboardingQuestion();
}

async function promptInterviewSkipConfirm() {
    easySetupState.interviewStage = 'skip_confirm';
    renderOnboardingChoiceBubble(
        'You can skip the intake and finish with safe defaults. Want me to do that?',
        [
            { value: 'finish_defaults', label: 'Finish setup with defaults', kind: 'action', tone: 'primary' },
            { value: 'resume', label: 'Resume questions', kind: 'action' },
        ],
        async (choice) => {
            renderMessage({ role: 'user', content: safeString(choice?.label) });
            const action = safeString(choice?.value);
            if (action === 'finish_defaults') {
                try {
                    await applyOnboardingCompletion({ skippedInterview: true });
                    renderMessage({
                        role: 'assistant',
                        content: withAgentName('Setup complete. {{agent}} is ready with safe defaults. You can tune anything in Settings later.'),
                    });
                } catch (err) {
                    renderMessage({
                        role: 'assistant',
                        content: `Could not finalize setup: ${safeString(err?.message) || 'unknown error'}`,
                    });
                }
                return;
            }
            easySetupState.interviewSkipChosen = false;
            promptOnboardingQuestion();
        }
    );
}

function promptOnboardingQuestion() {
    const index = Number(easySetupState.interviewIndex);
    if (index >= onboardingInterviewQuestions.length) {
        easySetupState.interviewStage = 'review';
        const answers = easySetupState.interviewAnswers || {};
        const summary = [
            `Experience: ${safeString(answers.experience) || 'builder'}`,
            `Autonomy: ${safeString(answers.autonomy) || 'balanced'}`,
            `Cost/quality: ${safeString(answers.cost_quality) || 'balanced'}`,
            `Memory: ${safeString(answers.memory) || 'remember'}`,
            `Workflow: ${safeString(answers.workflow) || 'build_features'}`,
        ];
        renderMessage({
            role: 'assistant',
            content: `### Review profile\n${summary.map((line) => `- ${line}`).join('\n')}\n\nSay "finish setup", "use defaults", or "open settings".`,
        });
        renderOnboardingChoiceBubble(
            'Final step',
            [
                { value: 'apply', label: 'Finish setup', kind: 'action', tone: 'primary' },
                { value: 'skip', label: 'Finish with defaults', kind: 'action' },
                { value: 'settings', label: 'Open Settings first', kind: 'action' },
            ],
            async (choice) => {
                renderMessage({ role: 'user', content: safeString(choice?.label) });
                const action = safeString(choice?.value);
                if (action === 'settings') {
                    openSettingsModal();
                    renderMessage({
                        role: 'assistant',
                        content: 'Settings opened. Return and tell me to finish setup when you are ready.',
                    });
                    return;
                }
                try {
                    await applyOnboardingCompletion({ skippedInterview: action === 'skip' });
                    renderMessage({
                        role: 'assistant',
                        content: withAgentName('Onboarding complete. {{agent}} is connected and ready.'),
                    });
                } catch (err) {
                    renderMessage({
                        role: 'assistant',
                        content: `Could not finalize setup: ${safeString(err?.message) || 'unknown error'}`,
                    });
                }
            }
        );
        return;
    }

    easySetupState.interviewStage = 'question';
    const question = onboardingInterviewQuestions[index];
    const questionPrompt = withAgentName(question.prompt);
    renderOnboardingChoiceBubble(
        `### ${escapeHtml(questionPrompt)}\nReply naturally or tap an option.`,
        [
            ...question.options.map((option) => ({ ...option, kind: 'option' })),
            { value: '__skip_interview__', label: 'Skip intake', kind: 'action' },
        ],
        async (choice) => {
            renderMessage({ role: 'user', content: safeString(choice?.label) });
            const value = safeString(choice?.value);
            if (value === '__skip_interview__') {
                easySetupState.interviewSkipChosen = true;
                await promptInterviewSkipConfirm();
                return;
            }
            await submitOnboardingInterviewAnswer(question, value, { source: 'bubble' });
        }
    );
}

async function handleOnboardingChatInput(textRaw, { docsCount = 0, imagesCount = 0 } = {}) {
    const text = safeString(textRaw);
    if (docsCount > 0 || imagesCount > 0) {
        renderMessage({
            role: 'assistant',
            content: 'For onboarding, plain text replies work best. I ignored attachments for this step.',
        });
    }
    if (!text) {
        renderMessage({
            role: 'assistant',
            content: 'Reply with your preference in plain language, or use a suggestion bubble.',
        });
        return;
    }

    const stage = safeString(easySetupState.interviewStage) || 'question';
    if (stage === 'skip_confirm') {
        const action = parseOnboardingSkipConfirmAction(text);
        if (!action) {
            if (isSecurityTrustConcern(text)) {
                renderMessage({
                    role: 'assistant',
                    content: `${buildSetupSafetyMessage()}\n\nWhen ready, say "finish with defaults" or "resume questions".`,
                });
                return;
            }
            renderMessage({
                role: 'assistant',
                content: 'Say "finish with defaults" or "resume questions".',
            });
            return;
        }
        if (action === 'finish_defaults') {
            try {
                await applyOnboardingCompletion({ skippedInterview: true });
                renderMessage({
                    role: 'assistant',
                    content: withAgentName('Setup complete. {{agent}} is ready with safe defaults.'),
                });
            } catch (err) {
                renderMessage({
                    role: 'assistant',
                    content: `Could not finalize setup: ${safeString(err?.message) || 'unknown error'}`,
                });
            }
            return;
        }
        easySetupState.interviewSkipChosen = false;
        promptOnboardingQuestion();
        return;
    }

    if (stage === 'review') {
        const action = parseOnboardingReviewAction(text);
        if (!action) {
            if (isSecurityTrustConcern(text)) {
                renderMessage({
                    role: 'assistant',
                    content: `${buildSetupSafetyMessage()}\n\nWhen ready, say "finish setup", "use defaults", or "open settings".`,
                });
                return;
            }
            renderMessage({
                role: 'assistant',
                content: 'Say "finish setup", "use defaults", or "open settings".',
            });
            return;
        }
        if (action === 'settings') {
            openSettingsModal();
            renderMessage({
                role: 'assistant',
                content: 'Settings opened. Return when you want me to finish onboarding.',
            });
            return;
        }
        try {
            await applyOnboardingCompletion({ skippedInterview: action === 'skip' });
            renderMessage({
                role: 'assistant',
                content: withAgentName('Onboarding complete. {{agent}} is connected and ready.'),
            });
        } catch (err) {
            renderMessage({
                role: 'assistant',
                content: `Could not finalize setup: ${safeString(err?.message) || 'unknown error'}`,
            });
        }
        return;
    }

    const question = onboardingInterviewQuestions[Number(easySetupState.interviewIndex)];
    if (!question) {
        promptOnboardingQuestion();
        return;
    }

    const parsedValue = parseOnboardingQuestionAnswer(question, text);
    if (parsedValue === '__skip_interview__') {
        easySetupState.interviewSkipChosen = true;
        await promptInterviewSkipConfirm();
        return;
    }
    if (!parsedValue) {
        if (isSecurityTrustConcern(text)) {
            const optionHints = formatOnboardingQuestionOptionList(question);
            renderMessage({
                role: 'assistant',
                content: `${buildSetupSafetyMessage()}\n\nWhen you are ready, answer this step: ${withAgentName(question.prompt)}\nI can map replies like: ${optionHints}.`,
            });
            return;
        }
        const optionHints = formatOnboardingQuestionOptionList(question);
        renderMessage({
            role: 'assistant',
            content: `I can map that, but I am not fully sure yet. Try phrasing it closer to one of: ${optionHints}.`,
        });
        return;
    }

    await submitOnboardingInterviewAnswer(question, parsedValue, { source: 'text' });
}

async function beginOnboardingInterview() {
    easySetupState.interviewStarted = true;
    easySetupState.interviewStage = 'question';
    easySetupState.interviewIndex = 0;
    ensureChatVisible();
    await persistOnboardingPrefs({ current_step: 'interview', dismissed_at: null });
    renderMessage({
        role: 'assistant',
        content: 'Brain handshake complete. I am caffeinated and morally obligated to make this easy. Tell me your preferences in plain English and I will translate them into setup defaults.',
    });
    promptOnboardingQuestion();
    emitOnboardingTelemetry('interview.started', {
        path: safeString(easySetupState.selectedPath),
    });
}

// 
//   INITIALIZATION & COMPOSER                                              
//   Main init(), composer setup, slash palette, message building           
// 

/**
 * Initialize the ultra-premium UI behaviors
 */
function init() {
    if (appRoot) {
        appRoot.classList.remove('debug-dock-open');
        appRoot.classList.remove('settings-active');
        appRoot.classList.remove('chat-game-open');
    }
    if (settingsModal) {
        settingsModal.classList.add('hidden');
    }
    initComposer();
    _initThinkingDropdown();
    configureComposerSurface();
    initActions();
    initChatSearch();
    initChatGame();
    initFeatures();
    initEasySetup();
    loadInitialState().catch((error) => {
        console.error('Boot initialization failed', error);
        notifyUser('Thomas had trouble loading. Retrying startup tasks.', {
            tone: 'warning',
            durationMs: 2600,
            debugKind: 'error',
        });
    });
    initComposerDeepLink();
    syncChatComposerOffset();
    window.addEventListener('resize', () => syncChatComposerOffset(), { passive: true });
    if (window.visualViewport) {
        window.visualViewport.addEventListener('resize', () => syncChatComposerOffset());
    }
    if (composerContainer && 'ResizeObserver' in window) {
        const resizeObs = new ResizeObserver(() => syncChatComposerOffset());
        resizeObs.observe(composerContainer);
    }
}

function syncChatComposerOffset() {
    if (_composerOffsetRaf) return;
    _composerOffsetRaf = window.requestAnimationFrame(() => {
        _composerOffsetRaf = 0;
        if (!(chatMessagesInner instanceof HTMLElement) || !(composerContainer instanceof HTMLElement)) return;
        const shouldPinToBottom = (chatScrollArea instanceof HTMLElement)
            && ((chatScrollArea.scrollHeight - chatScrollArea.clientHeight - chatScrollArea.scrollTop) <= CHAT_SCROLL_BOTTOM_EPSILON);
        const rect = composerContainer.getBoundingClientRect();
        const offset = Math.max(CHAT_COMPOSER_OFFSET_MIN, Math.ceil(rect.height) + CHAT_COMPOSER_OFFSET_BUFFER);
        if (Math.abs(offset - _lastComposerOffset) < CHAT_COMPOSER_OFFSET_EPSILON) return;
        _lastComposerOffset = offset;
        const offsetValue = `${offset}px`;
        chatMessagesInner.style.setProperty('--composer-offset', offsetValue);
        document.documentElement.style.setProperty('--composer-offset', offsetValue);
        if (shouldPinToBottom && chatScrollArea instanceof HTMLElement) {
            window.requestAnimationFrame(() => {
                chatScrollArea.scrollTop = chatScrollArea.scrollHeight;
            });
        }
    });
}

/**
 * Composer behaviors: Auto-expand, Enter-to-send
 */
function composerSyncSendButtonState() {
    if (isGenerating) return;
    const canSend = composerTextarea.value.trim().length > 0 || pendingDocs.length > 0 || pendingImages.length > 0;
    sendBtn.disabled = !canSend;
    sendBtn.style.color = canSend ? 'var(--text-primary)' : '';
    syncSendButtonA11y();
}

/*  Thinking / Reasoning Effort Dropdown  */
function _initThinkingDropdown() {
    const inputRow = composerTextarea?.closest('.composer-input-row');
    if (!inputRow) return;
    const micBtn = document.getElementById('micBtn');

    // Create the thinking toggle button
    const thinkBtn = document.createElement('button');
    thinkBtn.className = 'btn-icon thinking-effort-btn';
    thinkBtn.id = 'thinkingEffortBtn';
    thinkBtn.type = 'button';
    thinkBtn.setAttribute('aria-haspopup', 'menu');
    thinkBtn.setAttribute('aria-expanded', 'false');
    thinkBtn.innerHTML = '<i class="ph ph-brain"></i>';

    // Create the dropdown
    const dropdown = document.createElement('div');
    dropdown.className = 'thinking-effort-dropdown hidden';
    dropdown.id = 'thinkingEffortDropdown';
    dropdown.setAttribute('role', 'menu');
    dropdown.innerHTML = `
        <div class="thinking-effort-dropdown-title">Thinking Mode</div>
        <button class="thinking-effort-option" data-effort="" type="button">
            <i class="ph ph-lightning"></i>
            <div><strong>Auto</strong><span class="thinking-effort-desc">Model decides when to think</span></div>
        </button>
        <button class="thinking-effort-option" data-effort="low" type="button">
            <i class="ph ph-minus-circle"></i>
            <div><strong>Quick</strong><span class="thinking-effort-desc">Fast, less reasoning</span></div>
        </button>
        <button class="thinking-effort-option" data-effort="medium" type="button">
            <i class="ph ph-equals"></i>
            <div><strong>Balanced</strong><span class="thinking-effort-desc">Default reasoning depth</span></div>
        </button>
        <button class="thinking-effort-option" data-effort="high" type="button">
            <i class="ph ph-brain"></i>
            <div><strong>Deep Think</strong><span class="thinking-effort-desc">Maximum reasoning, slower</span></div>
        </button>
    `;

    // Insert before mic button
    if (micBtn) {
        inputRow.insertBefore(thinkBtn, micBtn);
    } else {
        inputRow.insertBefore(thinkBtn, sendBtn);
    }
    thinkBtn.insertAdjacentElement('afterend', dropdown);

    // Inject styles
    const style = document.createElement('style');
    style.textContent = `
        .thinking-effort-btn { position: relative; }
        .thinking-effort-btn.active { color: var(--accent) !important; }
        .thinking-effort-dropdown {
            position: absolute; bottom: calc(100% + 8px); right: 0;
            background: var(--bg-surface, #1f232c); border: 1px solid var(--border-light, rgba(255,255,255,0.12));
            border-radius: var(--radius-lg, 12px); padding: 8px; min-width: 220px;
            box-shadow: var(--shadow-strong, 0 22px 60px rgba(0,0,0,0.45));
            z-index: var(--z-dropdown, 20);
        }
        .thinking-effort-dropdown.hidden { display: none; }
        .thinking-effort-dropdown-title {
            font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em;
            color: var(--text-muted, #929bb0); padding: 4px 8px 8px; border-bottom: 1px solid var(--border-light, rgba(255,255,255,0.12));
            margin-bottom: 4px;
        }
        .thinking-effort-option {
            display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px 10px;
            background: none; border: none; border-radius: var(--radius-md, 8px);
            color: var(--text-primary, #ececf1); cursor: pointer; text-align: left; font-size: 13px;
        }
        .thinking-effort-option:hover { background: var(--bg-surface-hover, #242936); }
        .thinking-effort-option.selected { background: rgba(88, 166, 255, 0.12); color: var(--accent, #58a6ff); }
        .thinking-effort-option i { font-size: 18px; width: 20px; text-align: center; flex-shrink: 0; }
        .thinking-effort-option div { display: flex; flex-direction: column; }
        .thinking-effort-desc { font-size: 11px; color: var(--text-muted, #929bb0); margin-top: 1px; }
        .thinking-effort-option.selected .thinking-effort-desc { color: var(--accent, #58a6ff); opacity: 0.7; }
    `;
    document.head.appendChild(style);

    // Sync selection UI
    function syncSelection() {
        dropdown.querySelectorAll('.thinking-effort-option').forEach(opt => {
            opt.classList.toggle('selected', (opt.dataset.effort || '') === (activeReasoningEffort || ''));
        });
        thinkBtn.classList.toggle('active', !!activeReasoningEffort);
        const selectedLabel = dropdown.querySelector('.thinking-effort-option.selected strong')?.textContent || 'Auto';
        const buttonLabel = `Thinking mode: ${selectedLabel}`;
        setElementA11y(thinkBtn, { title: buttonLabel, label: buttonLabel });
    }

    function syncDropdownExpandedState() {
        thinkBtn.setAttribute('aria-expanded', dropdown.classList.contains('hidden') ? 'false' : 'true');
    }
    syncSelection();
    syncDropdownExpandedState();

    // Toggle dropdown
    thinkBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        dropdown.classList.toggle('hidden');
        syncDropdownExpandedState();
    });

    // Handle option clicks
    dropdown.addEventListener('click', (e) => {
        const opt = e.target.closest('.thinking-effort-option');
        if (!opt) return;
        activeReasoningEffort = normalizeReasoningEffort(opt.dataset.effort);
        syncSelection();
        dropdown.classList.add('hidden');
        syncDropdownExpandedState();
    });

    // Close on outside click
    document.addEventListener('click', (e) => {
        if (!thinkBtn.contains(e.target) && !dropdown.contains(e.target)) {
            dropdown.classList.add('hidden');
            syncDropdownExpandedState();
        }
    });
}

function initComposer() {
    composerTextarea.addEventListener('input', () => {
        // Auto-resize
        composerTextarea.style.height = 'auto';
        composerTextarea.style.height = (composerTextarea.scrollHeight) + 'px';

        // Toggle send button state
        composerSyncSendButtonState();

        // Slash command palette
        _updateSlashPalette();
        syncChatComposerOffset();
    });

    composerTextarea.addEventListener('keydown', (e) => {
        if (_modelPaletteVisible) {
            if (e.key === 'ArrowDown') { e.preventDefault(); _modelPaletteNav(1); return; }
            if (e.key === 'ArrowUp') { e.preventDefault(); _modelPaletteNav(-1); return; }
            if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); _modelPaletteSelect(); return; }
            if (e.key === 'Escape') { e.preventDefault(); _hideModelPalette(); return; }
            if (e.key === 'Tab') { e.preventDefault(); _modelPaletteSelect(); return; }
        }

        // Slash palette navigation
        if (_slashPaletteVisible) {
            if (e.key === 'ArrowDown') { e.preventDefault(); _slashPaletteNav(1); return; }
            if (e.key === 'ArrowUp') { e.preventDefault(); _slashPaletteNav(-1); return; }
            if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); _slashPaletteSelect(); return; }
            if (e.key === 'Escape') { e.preventDefault(); _hideSlashPalette(); return; }
            if (e.key === 'Tab') { e.preventDefault(); _slashPaletteSelect(); return; }
        }
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            if (!sendBtn.disabled) {
                sendBtn.click();
            }
        }
    });

    //  Paste images from clipboard 
    composerTextarea.addEventListener('paste', (e) => {
        const items = e.clipboardData?.items;
        if (!items) return;
        for (const item of items) {
            if (item.type.startsWith('image/')) {
                e.preventDefault();
                const file = item.getAsFile();
                if (!file) continue;
                const reader = new FileReader();
                reader.onload = (re) => {
                    pendingImages.push({ data_url: re.target.result, name: file.name || 'pasted-image.png' });
                    renderAttachmentsPreview();
                    composerSyncSendButtonState();
                    showToast('Image pasted');
                };
                reader.readAsDataURL(file);
                break; // only handle first image
            }
        }
    });

    //  Drag-and-drop files onto composer 
    const composerArea = composerTextarea.closest('.composer') || composerTextarea.parentElement;
    if (composerArea) {
        let _dragCounter = 0;

        // Create drop overlay
        const dropOverlay = document.createElement('div');
        dropOverlay.className = 'composer-drop-overlay';
        dropOverlay.innerHTML = '<span><i class="ph ph-upload-simple"></i> Drop files here</span>';
        composerArea.style.position = composerArea.style.position || 'relative';
        composerArea.appendChild(dropOverlay);

        composerArea.addEventListener('dragenter', (e) => {
            e.preventDefault();
            _dragCounter++;
            dropOverlay.classList.add('visible');
        });
        composerArea.addEventListener('dragleave', (e) => {
            e.preventDefault();
            _dragCounter--;
            if (_dragCounter <= 0) {
                _dragCounter = 0;
                dropOverlay.classList.remove('visible');
            }
        });
        composerArea.addEventListener('dragover', (e) => {
            e.preventDefault();
            e.dataTransfer.dropEffect = 'copy';
        });
        composerArea.addEventListener('drop', async (e) => {
            e.preventDefault();
            _dragCounter = 0;
            dropOverlay.classList.remove('visible');

            const files = e.dataTransfer?.files;
            if (!files || files.length === 0) return;

            for (const file of files) {
                if (file.type.startsWith('image/')) {
                    const reader = new FileReader();
                    reader.onload = (re) => {
                        pendingImages.push({ data_url: re.target.result, name: file.name });
                        renderAttachmentsPreview();
                        composerSyncSendButtonState();
                    };
                    reader.readAsDataURL(file);
                } else {
                    try {
                        const text = await file.text();
                        pendingDocs.push({ name: file.name, text: text });
                        renderAttachmentsPreview();
                        composerSyncSendButtonState();
                    } catch (err) {
                        console.warn('Failed to read dropped file:', err);
                    }
                }
            }
            showToast(`${files.length} file(s) attached`);
        });
    }
}

//  Slash Command Palette 
const SLASH_COMMANDS = [
    { cmd: '/research',  desc: 'Deep research mode  thorough web search + synthesis' },
    { cmd: '/image',     desc: 'Generate an image from a description' },
    { cmd: '/code',      desc: 'Code-focused mode  programming assistance' },
    { cmd: '/write',     desc: 'Writing mode  essays, emails, creative text' },
    { cmd: '/analyze',   desc: 'Analyze documents, data, or complex topics' },
    { cmd: '/model',     desc: 'Switch active model/profile inline' },
    { cmd: '/status',    desc: 'Show live engine status and runtime details' },
    { cmd: '/issues',    desc: 'Run code issue detection and automated fixes' },
    { cmd: '/upgrade',   desc: 'Run self-upgrade engine cycle' },
    { cmd: '/sync',      desc: 'Run workspace sync cycle (commit / housekeeping)' },
    { cmd: '/ui-audit',  desc: 'Run UI workflow review and polish checks' },
    { cmd: '/clear',     desc: 'Clear the conversation and start fresh' },
    { cmd: '/export',    desc: 'Export this conversation as markdown or JSON' },
    { cmd: '/help',      desc: 'Show available commands and keyboard shortcuts' },
];

let _slashPaletteVisible = false;
let _slashPaletteIndex = 0;
let _slashPaletteFiltered = [];
let _slashPaletteEl = null;
let _modelPaletteVisible = false;
let _modelPaletteIndex = 0;
let _modelPaletteOptions = [];
let _modelPaletteEl = null;

function _getSlashPaletteEl() {
    if (_slashPaletteEl) return _slashPaletteEl;
    _slashPaletteEl = document.createElement('div');
    _slashPaletteEl.className = 'slash-palette';
    const composerArea = composerTextarea.closest('.composer') || composerTextarea.parentElement;
    if (composerArea) {
        composerArea.style.position = composerArea.style.position || 'relative';
        composerArea.appendChild(_slashPaletteEl);
    }
    return _slashPaletteEl;
}

function _updateSlashPalette() {
    if (_modelPaletteVisible) return;
    const text = composerTextarea.value;
    if (!text.startsWith('/') || text.includes(' ') || text.includes('\n')) {
        _hideSlashPalette();
        return;
    }
    const query = text.toLowerCase();
    _slashPaletteFiltered = SLASH_COMMANDS.filter(c => c.cmd.startsWith(query));
    if (_slashPaletteFiltered.length === 0) {
        _hideSlashPalette();
        return;
    }
    _slashPaletteIndex = Math.min(_slashPaletteIndex, _slashPaletteFiltered.length - 1);
    _renderSlashPalette();
    _slashPaletteVisible = true;
}

function _renderSlashPalette() {
    const el = _getSlashPaletteEl();
    el.innerHTML = _slashPaletteFiltered.map((c, i) =>
        `<div class="slash-palette-item${i === _slashPaletteIndex ? ' active' : ''}" data-idx="${i}">
            <span class="slash-cmd">${escapeHtml(c.cmd)}</span>
            <span class="slash-desc">${escapeHtml(c.desc)}</span>
        </div>`
    ).join('');
    el.classList.add('visible');

    // Click to select
    el.querySelectorAll('.slash-palette-item').forEach(item => {
        item.addEventListener('click', (e) => {
            _slashPaletteIndex = parseInt(item.dataset.idx, 10);
            _slashPaletteSelect();
        });
    });
}

function _hideSlashPalette() {
    _slashPaletteVisible = false;
    _slashPaletteIndex = 0;
    if (_slashPaletteEl) _slashPaletteEl.classList.remove('visible');
}

function _slashPaletteNav(dir) {
    _slashPaletteIndex = Math.max(0, Math.min(_slashPaletteFiltered.length - 1, _slashPaletteIndex + dir));
    _renderSlashPalette();
}

function _slashPaletteSelect() {
    const selected = _slashPaletteFiltered[_slashPaletteIndex];
    if (!selected) { _hideSlashPalette(); return; }

    _hideSlashPalette();

    if (selected.cmd === '/model') {
        _openModelPalette();
        return;
    }

    // Handle action commands
    if (selected.cmd === '/clear') {
        composerTextarea.value = '';
        composerTextarea.dispatchEvent(new Event('input'));
        if (typeof startNewSession === 'function') startNewSession();
        return;
    }
    if (selected.cmd === '/export') {
        composerTextarea.value = '';
        composerTextarea.dispatchEvent(new Event('input'));
        exportChatConversation();
        return;
    }
    if (selected.cmd === '/help') {
        composerTextarea.value = '';
        composerTextarea.dispatchEvent(new Event('input'));
        showToast('Shortcuts: Esc=stop, Ctrl+Shift+N=new chat, /=commands');
        return;
    }

    // Mode commands  set the mode and clear the slash text
    const modeId = selected.cmd.replace('/', '');
    composerTextarea.value = '';
    composerTextarea.dispatchEvent(new Event('input'));
    if (typeof composerSetMode === 'function') {
        composerSetMode(modeId);
    }
}

function _getModelPaletteEl() {
    if (_modelPaletteEl) return _modelPaletteEl;
    _modelPaletteEl = document.createElement('div');
    _modelPaletteEl.className = 'slash-palette model-palette';
    const composerArea = composerTextarea.closest('.composer') || composerTextarea.parentElement;
    if (composerArea) {
        composerArea.style.position = composerArea.style.position || 'relative';
        composerArea.appendChild(_modelPaletteEl);
    }
    return _modelPaletteEl;
}

function _buildModelPaletteOptions() {
    const profiles = Array.isArray(availableModelProfiles) ? availableModelProfiles : [];
    return profiles
        .filter((profile) => safeString(profile?.name))
        .map((profile) => {
            const name = safeString(profile.name);
            const provider = safeString(profile.provider);
            const modelId = safeString(profile.model).split('/').pop();
            const status = profile?.has_api_key === false ? 'not configured' : 'ready';
            return {
                profile: name,
                title: name,
                detail: [provider, modelId, status].filter(Boolean).join(' | '),
            };
        });
}

function _openModelPalette() {
    _modelPaletteOptions = _buildModelPaletteOptions();
    if (_modelPaletteOptions.length === 0) {
        notifyUser('No model profiles available yet.', { tone: 'warn', durationMs: 2200, debugKind: 'engine-action' });
        return;
    }
    _modelPaletteIndex = 0;
    _modelPaletteVisible = true;
    composerTextarea.value = '';
    composerTextarea.dispatchEvent(new Event('input'));
    _renderModelPalette();
}

function _renderModelPalette() {
    if (!_modelPaletteVisible) return;
    const el = _getModelPaletteEl();
    const activeProfile = safeString(modelSelector?.value);
    el.innerHTML = _modelPaletteOptions.map((option, index) => {
        const isActive = option.profile === activeProfile;
        return `<div class="slash-palette-item${index === _modelPaletteIndex ? ' active' : ''}" data-idx="${index}">
            <span class="slash-cmd">${escapeHtml(option.title)}${isActive ? ' ' : ''}</span>
            <span class="slash-desc">${escapeHtml(option.detail)}</span>
        </div>`;
    }).join('');
    el.classList.add('visible');
    el.querySelectorAll('.slash-palette-item').forEach((item) => {
        item.addEventListener('click', () => {
            _modelPaletteIndex = parseInt(item.dataset.idx, 10);
            _modelPaletteSelect();
        });
    });
}

function _hideModelPalette() {
    _modelPaletteVisible = false;
    _modelPaletteIndex = 0;
    _modelPaletteOptions = [];
    if (_modelPaletteEl) _modelPaletteEl.classList.remove('visible');
}

function _modelPaletteNav(dir) {
    _modelPaletteIndex = Math.max(0, Math.min(_modelPaletteOptions.length - 1, _modelPaletteIndex + dir));
    _renderModelPalette();
}

async function _persistModelProfileSelection(profile, modelId = '') {
    const patch = {
        advanced: {
            model: {
                active_profile: profile,
                model_id: modelId,
                reasoning_effort: normalizeReasoningEffort(activeReasoningEffort) || 'medium',
            },
        },
    };
    try {
        const res = await fetch('/api/preferences', {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(patch),
        });
        if (res.ok) {
            currentPreferences = await res.json();
            updateSidebarIdentity();
        }
    } catch (error) {
        console.error('Failed to persist /model selection:', error);
    }
}

function _modelPaletteSelect() {
    const selected = _modelPaletteOptions[_modelPaletteIndex];
    if (!selected) { _hideModelPalette(); return; }
    _hideModelPalette();
    const nextProfile = safeString(selected.profile);
    if (!nextProfile) return;
    applyProfileSelection(nextProfile, { allowLocalBackup: true });
    const nextModelId = resolveActiveModelIdForProfile(nextProfile);
    void _persistModelProfileSelection(nextProfile, nextModelId || '');
    notifyUser(`Model profile set to ${nextProfile}.`, {
        tone: 'success',
        durationMs: 2200,
        debugKind: 'engine-action',
    });
}

function composerShowGamesColumn(show) {
    if (!composerGamesColumn) return;
    composerGamesColumn.classList.toggle('hidden', !show);
    if (!composerActionList) return;
    const gamesBtn = composerActionList.querySelector('[data-action="games"]');
    if (gamesBtn instanceof HTMLButtonElement) {
        gamesBtn.classList.toggle('active', show);
        gamesBtn.setAttribute('aria-expanded', show ? 'true' : 'false');
    }
}

function composerResolveModePreset(modeIdRaw) {
    const modeId = String(modeIdRaw || '').trim().toLowerCase();
    if (!modeId) return null;
    return COMPOSER_MODE_PRESETS[modeId] || null;
}

function composerRenderModeChip() {
    if (!composerModeChip || !composerModeChipLabel) return;
    if (!composerModeSelection) {
        composerModeChip.classList.add('hidden');
        composerModeChipLabel.textContent = '';
        return;
    }
    composerModeChipLabel.textContent = composerModeSelection.label || 'Mode';
    composerModeChip.classList.remove('hidden');
}

function composerSetMode(modeIdRaw, { label = '', kind = '', promptPrefix = '' } = {}) {
    const preset = composerResolveModePreset(modeIdRaw);
    const modeId = preset?.id || String(modeIdRaw || '').trim().toLowerCase();
    if (!modeId) return null;
    composerModeSelection = {
        id: modeId,
        label: safeString(label) || safeString(preset?.label) || modeId,
        kind: safeString(kind) || safeString(preset?.kind),
        promptPrefix: safeString(promptPrefix) || safeString(preset?.promptPrefix),
    };
    composerRenderModeChip();
    return composerModeSelection;
}

function composerClearMode({ closeGame = true } = {}) {
    const activeModeKind = safeString(composerModeSelection?.kind);
    composerModeSelection = null;
    composerRenderModeChip();
    if (closeGame && activeModeKind === 'game') {
        chatGameClose({ clearMode: false });
    }
}

function composerBuildMessageForModel(textRaw, modeSelectionRaw = null) {
    const text = String(textRaw || '').trim();
    const modeSelection = modeSelectionRaw || composerModeSelection;
    const modePrompt = safeString(modeSelection?.promptPrefix);
    if (!modePrompt) return text;
    if (!text) return modePrompt;
    return `${modePrompt}

User request:
${text}`;
}

function composerCloseActionsMenu() {
    composerActionsOpen = false;
    if (composerActionPopover) {
        composerActionPopover.classList.add('hidden');
    }
    composerShowGamesColumn(false);
    if (attachBtn) {
        attachBtn.classList.remove('active');
        attachBtn.setAttribute('aria-expanded', 'false');
    }
}

function composerOpenActionsMenu() {
    composerActionsOpen = true;
    if (composerActionPopover) {
        composerActionPopover.classList.remove('hidden');
    }
    composerShowGamesColumn(false);
    if (attachBtn) {
        attachBtn.classList.add('active');
        attachBtn.setAttribute('aria-expanded', 'true');
    }
}

function composerToggleActionsMenu() {
    if (composerActionsOpen) {
        composerCloseActionsMenu();
        return;
    }
    composerOpenActionsMenu();
}

function composerHandleQuickAction(actionRaw) {
    const action = String(actionRaw || '').trim().toLowerCase();
    if (!action) return;

    if (action === 'games') {
        composerSetMode('games');
        const showing = composerGamesColumn ? !composerGamesColumn.classList.contains('hidden') : false;
        composerShowGamesColumn(!showing);
        return;
    }

    const mode = composerSetMode(action);
    if (!mode) return;
    composerCloseActionsMenu();

    if (mode.kind !== 'game') {
        chatGameClose({ clearMode: false });
    }

    if (action === 'add_files') {
        if (docFileInput) docFileInput.click();
        return;
    }

    if (composerTextarea) {
        composerTextarea.focus();
    }
}

function composerHandleGameChoice(gameRaw) {
    const game = String(gameRaw || '').trim().toLowerCase();
    if (!game) return;
    composerCloseActionsMenu();
    if (game === 'cloud_jump' || game === JETPACK_GAME_ID || game === DINO_GAME_ID) {
        composerSetMode(game);
        chatGameOpen(game);
        return;
    }
    composerSetMode('games');
    chatGameClose({ clearMode: false });
}

function chatGameGetHighScore(gameIdRaw = chatGameRuntime.activeGameId || 'cloud_jump') {
    const gameId = safeString(gameIdRaw).toLowerCase();
    const storageKey = CHAT_GAME_HIGHSCORE_STORAGE_KEYS[gameId] || CHAT_GAME_HIGHSCORE_STORAGE_KEYS.cloud_jump;
    try {
        const raw = window.localStorage.getItem(storageKey);
        const parsed = Number(raw);
        if (!Number.isFinite(parsed)) return 0;
        return Math.max(0, Math.floor(parsed));
    } catch {
        return 0;
    }
}

function chatGameSetHighScore(scoreRaw, gameIdRaw = chatGameRuntime.activeGameId || 'cloud_jump') {
    const gameId = safeString(gameIdRaw).toLowerCase();
    const storageKey = CHAT_GAME_HIGHSCORE_STORAGE_KEYS[gameId] || CHAT_GAME_HIGHSCORE_STORAGE_KEYS.cloud_jump;
    const score = Math.max(0, Math.floor(Number(scoreRaw) || 0));
    try {
        window.localStorage.setItem(storageKey, String(score));
    } catch {
        // no-op in storage restricted contexts
    }
}

function chatGameSetStatusText(text) {
    const next = safeString(text);
    if (chatGameStatusText) {
        chatGameStatusText.textContent = next;
    }
    if (composerDinoStatusText) {
        composerDinoStatusText.textContent = next;
    }
}

function chatGameSetPanelOpen(open) {
    const shouldOpen = Boolean(open);
    if (chatGamePanel) {
        chatGamePanel.classList.toggle('hidden', !shouldOpen);
    }
    if (appRoot) {
        appRoot.classList.remove('chat-game-open');
    }
}

function chatGameSetDinoSurfaceOpen(open) {
    const shouldOpen = Boolean(open);
    if (composerDinoShell) {
        composerDinoShell.classList.toggle('hidden', !shouldOpen);
        composerDinoShell.classList.toggle('is-open', shouldOpen);
    }
    if (composerBox) {
        composerBox.classList.toggle('dino-active', shouldOpen);
    }
    if (composerContainer) {
        composerContainer.classList.toggle('dino-active', shouldOpen);
    }
    if (composerDisclaimer) {
        composerDisclaimer.classList.toggle('hidden', shouldOpen);
    }
    if (chatGamePortal) {
        chatGamePortal.classList.add('hidden');
    }
    if (appRoot) {
        appRoot.classList.toggle('chat-game-dino-open', shouldOpen);
    }
}

// 
//   CHAT GAMES                                                             
//   Cloud Jump, Jetpack Joyride, Dino Run  physics, rendering, game loop  
// 

function chatGameSetCenterMuted(enable) {
    if (!appRoot) return;
    appRoot.classList.toggle('game-center-muted', Boolean(enable));
}

function chatGameSetPhaseClass(modeRaw = '') {
    if (chatGamePanel) {
        chatGamePanel.classList.remove('phase-intro', 'phase-ready', 'phase-launch', 'phase-playing', 'phase-game_over');
    }
    if (composerDinoShell) {
        composerDinoShell.classList.remove('phase-intro', 'phase-ready', 'phase-launch', 'phase-playing', 'phase-game_over');
    }
    const mode = safeString(modeRaw).toLowerCase();
    if (mode === 'intro' || mode === 'ready' || mode === 'launch' || mode === 'playing' || mode === 'game_over') {
        if (chatGamePanel) {
            chatGamePanel.classList.add(`phase-${mode}`);
        }
        if (composerDinoShell) {
            composerDinoShell.classList.add(`phase-${mode}`);
        }
    }
}

function chatGameToggleHiddenCanvasPriority(enable) {
    const demote = Boolean(enable);
    document.querySelectorAll('canvas').forEach((canvas) => {
        if (!(canvas instanceof HTMLCanvasElement)) return;
        if (canvas === chatGameCanvas) return;
        if (demote) {
            const rect = canvas.getBoundingClientRect();
            const hidden = rect.width < 2 || rect.height < 2 || Boolean(canvas.closest('.hidden'));
            if (!hidden) return;
            if (canvas.dataset.thomasCanvasDemoted === '1') return;
            canvas.dataset.thomasCanvasDemoted = '1';
            canvas.dataset.thomasCanvasWidth = String(canvas.width || 0);
            canvas.dataset.thomasCanvasHeight = String(canvas.height || 0);
            canvas.width = 1;
            canvas.height = 1;
            return;
        }
        if (canvas.dataset.thomasCanvasDemoted !== '1') return;
        const savedWidth = Number(canvas.dataset.thomasCanvasWidth);
        const savedHeight = Number(canvas.dataset.thomasCanvasHeight);
        if (Number.isFinite(savedWidth) && Number.isFinite(savedHeight) && savedWidth > 0 && savedHeight > 0) {
            canvas.width = savedWidth;
            canvas.height = savedHeight;
        }
        delete canvas.dataset.thomasCanvasDemoted;
        delete canvas.dataset.thomasCanvasWidth;
        delete canvas.dataset.thomasCanvasHeight;
    });
}

function chatGameClamp(value, min, max) {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return Number(min) || 0;
    return Math.min(Number(max) || 0, Math.max(Number(min) || 0, numeric));
}

function chatGameRandom(min, max) {
    const lo = Number(min) || 0;
    const hi = Number(max) || 0;
    return lo + (Math.random() * (hi - lo));
}

function chatGameEaseOutCubic(value) {
    const t = chatGameClamp(value, 0, 1);
    return 1 - ((1 - t) ** 3);
}

function chatGameEaseInOutCubic(value) {
    const t = chatGameClamp(value, 0, 1);
    if (t < 0.5) {
        return 4 * t * t * t;
    }
    return 1 - (((-2 * t) + 2) ** 3) / 2;
}

function chatGameLerp(start, end, t) {
    return Number(start) + ((Number(end) - Number(start)) * chatGameClamp(t, 0, 1));
}

function chatGameNormalizeOfficeAgent(agentRaw, fallbackId = 'agent-game') {
    const fallbackColor = '#9ad8ff';
    const candidate = agentRaw && typeof agentRaw === 'object' ? agentRaw : {};
    const id = safeString(candidate.id) || safeString(fallbackId) || 'agent-game';
    const resolvedName = normalizeAgentName(safeString(candidate.name) || 'Office Bot');
    const colorRaw = safeString(candidate.color);
    const color = /^#[0-9a-f]{6}$/i.test(colorRaw) ? colorRaw : fallbackColor;
    const costumeRaw = safeString(candidate.costume || 'none').toLowerCase();
    const costume = OFFICE_AGENT_COSTUME_POOL.includes(costumeRaw) ? costumeRaw : 'none';
    const tintRaw = safeString(candidate.tint).toLowerCase();
    return {
        id,
        name: resolvedName || 'Office Bot',
        color,
        costume,
        tint: tintRaw || officeAgentTintFromColor(color),
    };
}

function chatGameCollectOfficeAgentRoster() {
    const liveAgents = Array.isArray(officeState?.agents) ? officeState.agents : [];
    if (liveAgents.length) {
        return liveAgents.map((agent, index) => chatGameNormalizeOfficeAgent(agent, `agent-live-${index + 1}`));
    }

    const seedAgents = OFFICE_AGENT_SEEDS.map((seed, index) => ({
        id: `agent-${index + 1}`,
        name: seed.name,
        color: seed.color,
        costume: seed.costume,
        tint: seed.tint,
    }));
    const storedPrefs = loadStoredOfficeAgentPrefs();
    officeApplyStoredAgentPrefs(seedAgents, storedPrefs);
    return seedAgents.map((agent, index) => chatGameNormalizeOfficeAgent(agent, `agent-seed-${index + 1}`));
}

function chatGamePickOfficeAgentForRun() {
    const roster = chatGameCollectOfficeAgentRoster();
    if (!roster.length) {
        return chatGameNormalizeOfficeAgent({ name: 'Office Bot', costume: 'headset', color: '#9ad8ff' });
    }
    const pickIndex = Math.floor(Math.random() * roster.length);
    return chatGameNormalizeOfficeAgent(roster[pickIndex], `agent-pick-${pickIndex + 1}`);
}

function chatGameApplyBotAgentStyle(agentRaw) {
    const agent = chatGameNormalizeOfficeAgent(agentRaw);
    const palette = officeAgentPalette(agent);

    if (chatGameBot) {
        chatGameBot.classList.remove('costume-cap', 'costume-visor', 'costume-headset', 'costume-bowtie');
        if (agent.costume && agent.costume !== 'none') {
            chatGameBot.classList.add(`costume-${agent.costume}`);
        }
        chatGameBot.style.setProperty('--agent-primary', palette.primary);
        chatGameBot.style.setProperty('--agent-secondary', palette.secondary);
        chatGameBot.style.setProperty('--agent-glow', palette.glow);
        chatGameBot.style.setProperty('--agent-trim', '#0d1117');
    }
    if (chatGameBotWrap) {
        chatGameBotWrap.dataset.agentId = agent.id;
        chatGameBotWrap.dataset.agentName = agent.name;
    }
    if (chatGameBotName) {
        chatGameBotName.textContent = agent.name;
        chatGameBotName.title = agent.name;
    }
    return agent;
}

function chatGameDistanceToSegmentSquared(px, py, x1, y1, x2, y2) {
    const segmentDx = x2 - x1;
    const segmentDy = y2 - y1;
    const segmentLengthSq = (segmentDx * segmentDx) + (segmentDy * segmentDy);
    if (segmentLengthSq <= 0.0001) {
        const dx = px - x1;
        const dy = py - y1;
        return (dx * dx) + (dy * dy);
    }
    const projection = chatGameClamp(
        (((px - x1) * segmentDx) + ((py - y1) * segmentDy)) / segmentLengthSq,
        0,
        1,
    );
    const nearestX = x1 + (segmentDx * projection);
    const nearestY = y1 + (segmentDy * projection);
    const dx = px - nearestX;
    const dy = py - nearestY;
    return (dx * dx) + (dy * dy);
}

function chatGameCircleRectOverlap(cx, cy, radius, rx, ry, rw, rh) {
    const nearestX = chatGameClamp(cx, rx, rx + rw);
    const nearestY = chatGameClamp(cy, ry, ry + rh);
    const dx = cx - nearestX;
    const dy = cy - nearestY;
    return ((dx * dx) + (dy * dy)) <= (radius * radius);
}

function chatGameCreatePlatform(state, y, options = {}) {
    const width = Math.round(chatGameRandom(CHAT_GAME_PLATFORM_MIN_WIDTH, CHAT_GAME_PLATFORM_MAX_WIDTH));
    const safeMinX = Math.max(0, CHAT_GAME_PLATFORM_SAFE_MARGIN);
    const safeMaxX = Math.max(safeMinX, state.width - width - CHAT_GAME_PLATFORM_SAFE_MARGIN);
    const minCenter = safeMinX + (width * 0.5);
    const maxCenter = safeMaxX + (width * 0.5);
    const pathCenter = Number(state.platformGuideX);
    const targetCenterRaw = Number(state.pathTargetX);
    const optionCenter = Number(options?.centerX);
    const optionX = Number(options?.x);
    const optionDrift = Number(options?.drift);
    const optionDriftMax = Number(options?.driftMax);
    const targetCenter = chatGameClamp(
        Number.isFinite(targetCenterRaw) ? targetCenterRaw : (state.width * CHAT_GAME_PLATFORM_CENTER_RATIO),
        minCenter,
        maxCenter,
    );
    const guideCenter = Number.isFinite(pathCenter) ? pathCenter : targetCenter;

    let centerX = Number.isFinite(optionCenter)
        ? optionCenter
        : (
            Number.isFinite(optionX)
                ? (optionX + (width * 0.5))
                : (
                    guideCenter
                    + chatGameRandom(-CHAT_GAME_PLATFORM_PATH_STEP, CHAT_GAME_PLATFORM_PATH_STEP)
                    + ((targetCenter - guideCenter) * CHAT_GAME_PLATFORM_CENTER_CORRECTION)
                )
        );
    centerX = chatGameClamp(centerX, minCenter, maxCenter);

    const x = Number.isFinite(optionX)
        ? chatGameClamp(optionX, safeMinX, safeMaxX)
        : chatGameClamp(centerX - (width * 0.5), safeMinX, safeMaxX);

    const driftMax = Number.isFinite(optionDriftMax)
        ? Math.max(0, optionDriftMax)
        : CHAT_GAME_PLATFORM_DRIFT_MAX;
    const drift = Number.isFinite(optionDrift)
        ? optionDrift
        : (Math.random() < CHAT_GAME_PLATFORM_DRIFT_CHANCE ? chatGameRandom(-driftMax, driftMax) : 0);

    state.platformGuideX = x + (width * 0.5);
    return {
        id: state.platformSeq++,
        x,
        y,
        w: width,
        h: 10,
        drift,
    };
}

function chatGameSpawnPlatforms(state) {
    if (!state) return;
    const playerCenter = (Number(state.player?.x) || 0) + ((Number(state.player?.w) || 0) * 0.5);
    const desiredTarget = chatGameClamp(
        Number.isFinite(playerCenter) ? playerCenter : (state.width * CHAT_GAME_PLATFORM_CENTER_RATIO),
        state.width * 0.24,
        state.width * 0.76,
    );
    if (Number.isFinite(Number(state.pathTargetX))) {
        state.pathTargetX += (desiredTarget - Number(state.pathTargetX)) * CHAT_GAME_PLATFORM_CENTER_FOLLOW;
    } else {
        state.pathTargetX = desiredTarget;
    }
    let highestY = state.platforms.reduce((min, platform) => Math.min(min, platform.y), state.height);
    while (highestY > -156) {
        highestY -= chatGameRandom(CHAT_GAME_PLATFORM_GAP_MIN, CHAT_GAME_PLATFORM_GAP_MAX);
        state.platforms.push(chatGameCreatePlatform(state, highestY));
    }
}

function chatGameCollectPlatformSweeps(state, deltaFrames, fallSpeed) {
    const sweeps = [];
    const minX = Math.max(0, CHAT_GAME_PLATFORM_SAFE_MARGIN);
    state.platforms.forEach((platform) => {
        const previousY = platform.y;
        platform.y += fallSpeed * deltaFrames;
        platform.x += platform.drift * deltaFrames;
        const maxX = Math.max(minX, state.width - platform.w - CHAT_GAME_PLATFORM_SAFE_MARGIN);
        if (platform.x <= minX || platform.x >= maxX) {
            platform.drift *= -1;
            platform.x = chatGameClamp(platform.x, minX, maxX);
        }
        sweeps.push({ platform, previousY });
    });
    return sweeps;
}

function chatGameFindLandingPlatform(platformSweeps, player, previousBottom, currentBottom, options = {}) {
    if (!Array.isArray(platformSweeps) || !player) return null;
    const tolerance = chatGameClamp(Number(options?.tolerance) || 8, 2, 18);
    const footInset = chatGameClamp(Number(options?.footInset) || 2, 0, Math.max(0, player.w * 0.45));
    const footLeft = player.x + footInset;
    const footRight = player.x + player.w - footInset;
    let picked = null;
    let pickedTop = Number.POSITIVE_INFINITY;
    for (const sweep of platformSweeps) {
        const platform = sweep?.platform;
        if (!platform) continue;
        const sweepTop = Math.min(sweep.previousY, platform.y) - tolerance;
        const sweepBottom = Math.max(sweep.previousY, platform.y) + tolerance;
        const crossedVertical = previousBottom <= sweepBottom && currentBottom >= sweepTop;
        if (!crossedVertical) continue;
        const overlapX = footRight >= platform.x && footLeft <= (platform.x + platform.w);
        if (!overlapX) continue;
        const platformTop = platform.y;
        if (platformTop < pickedTop) {
            picked = platform;
            pickedTop = platformTop;
        }
    }
    return picked;
}

function chatGameResizeCanvas() {
    if (!(chatGameCanvas instanceof HTMLCanvasElement)) {
        return { width: 320, height: 560 };
    }
    const laneRect = chatGameLane instanceof HTMLElement ? chatGameLane.getBoundingClientRect() : null;
    const gameId = safeString(chatGameRuntime.activeGameId).toLowerCase();
    const isJetpackWide = gameId === JETPACK_GAME_ID;
    const width = Math.round(chatGameClamp(
        (laneRect?.width || 320) - 4,
        isJetpackWide ? 640 : 224,
        isJetpackWide ? 1800 : 360,
    ));
    const height = Math.round(chatGameClamp((laneRect?.height || 560) - 4, isJetpackWide ? 360 : 300, 960));
    if (chatGameCanvas.width !== width) {
        chatGameCanvas.width = width;
    }
    if (chatGameCanvas.height !== height) {
        chatGameCanvas.height = height;
    }
    return { width, height };
}

function chatGameResizeDinoCanvas() {
    if (!(composerDinoCanvas instanceof HTMLCanvasElement)) {
        return { width: 760, height: 214 };
    }
    const shellRect = composerDinoShell instanceof HTMLElement ? composerDinoShell.getBoundingClientRect() : null;
    const width = Math.round(chatGameClamp((shellRect?.width || 760) - 2, 360, 980));
    const height = Math.round(chatGameClamp((shellRect?.height || 214) - 2, 168, 340));
    if (composerDinoCanvas.width !== width) {
        composerDinoCanvas.width = width;
    }
    if (composerDinoCanvas.height !== height) {
        composerDinoCanvas.height = height;
    }
    return { width, height };
}

function chatGameGetPortalAnchorInDino(state) {
    const surfaceWidth = Math.max(360, Number(state?.width) || 0);
    const surfaceHeight = Math.max(168, Number(state?.height) || 0);
    const fallbackY = Math.max(34, surfaceHeight - DINO_GROUND_PADDING - 48);
    const fallback = { x: 6, y: fallbackY };
    if (!(attachBtn instanceof HTMLElement) || !(composerDinoShell instanceof HTMLElement)) {
        return fallback;
    }
    const shellRect = composerDinoShell.getBoundingClientRect();
    const plusRect = attachBtn.getBoundingClientRect();
    if (shellRect.width < 2 || plusRect.width < 2 || plusRect.height < 2) {
        return fallback;
    }
    const anchor = {
        x: chatGameClamp(
            (plusRect.left - shellRect.left) + (plusRect.width * 0.5) - (CHAT_GAME_BOT_WRAP_SIZE * 0.5),
            -24,
            surfaceWidth + 24,
        ),
        y: chatGameClamp(
            (plusRect.top - shellRect.top) + (plusRect.height * 0.5) - (CHAT_GAME_BOT_WRAP_SIZE * 0.5),
            -24,
            surfaceHeight + 24,
        ),
    };
    const shellLikelyUnstable = shellRect.width < (surfaceWidth * 0.5) || shellRect.height < (surfaceHeight * 0.5);
    if (!Number.isFinite(anchor.x) || !Number.isFinite(anchor.y)) {
        return fallback;
    }
    if (shellLikelyUnstable && anchor.y < (surfaceHeight * 0.42)) {
        return fallback;
    }
    if (anchor.y < 16 && surfaceHeight > 150) {
        return fallback;
    }
    return anchor;
}

function chatGameGetDoorAnchor(state) {
    const fallbackWidth = state?.width || 320;
    const fallbackHeight = state?.height || 560;
    const fallbackDoorWidth = 74;
    const fallbackDoorHeight = 110;
    const fallbackDoorLeft = fallbackWidth - fallbackDoorWidth - 8;
    const fallbackDoorTop = fallbackHeight - fallbackDoorHeight - 34;
    const fallbackX = fallbackDoorLeft + CHAT_GAME_DOOR_BOT_MOUNT_LEFT + CHAT_GAME_DOOR_BOT_ENTER_OFFSET_END;
    const fallbackY = fallbackDoorTop + fallbackDoorHeight - CHAT_GAME_DOOR_BOT_MOUNT_BOTTOM - CHAT_GAME_BOT_WRAP_SIZE;
    if (!(chatGameDoor instanceof HTMLElement) || !(chatGameLane instanceof HTMLElement)) {
        return {
            x: fallbackX,
            y: fallbackY,
            doorLeft: fallbackDoorLeft,
            doorTop: fallbackDoorTop,
            doorWidth: fallbackDoorWidth,
            doorHeight: fallbackDoorHeight,
        };
    }
    const laneRect = chatGameLane.getBoundingClientRect();
    const doorRect = chatGameDoor.getBoundingClientRect();
    const laneWidth = Math.max(1, Number(laneRect.width) || fallbackWidth);
    const laneHeight = Math.max(1, Number(laneRect.height) || fallbackHeight);
    if (laneRect.width < 2 || doorRect.width < 2) {
        return {
            x: fallbackX,
            y: fallbackY,
            doorLeft: fallbackDoorLeft,
            doorTop: fallbackDoorTop,
            doorWidth: fallbackDoorWidth,
            doorHeight: fallbackDoorHeight,
        };
    }
    const doorLeft = doorRect.left - laneRect.left;
    const doorTop = doorRect.top - laneRect.top;
    const anchorX = doorLeft + CHAT_GAME_DOOR_BOT_MOUNT_LEFT + CHAT_GAME_DOOR_BOT_ENTER_OFFSET_END;
    const anchorY = doorTop + doorRect.height - CHAT_GAME_DOOR_BOT_MOUNT_BOTTOM - CHAT_GAME_BOT_WRAP_SIZE;
    return {
        x: chatGameClamp(anchorX, -24, laneWidth + 24),
        y: chatGameClamp(anchorY, -24, laneHeight + 24),
        doorLeft: chatGameClamp(doorLeft, -120, laneWidth + 120),
        doorTop: chatGameClamp(doorTop, -120, laneHeight + 120),
        doorWidth: chatGameClamp(doorRect.width, 48, 180),
        doorHeight: chatGameClamp(doorRect.height, 72, 220),
    };
}

function chatGameCreateTopStartPlatforms(state) {
    if (!state) return;
    state.platforms = [];
    const safeMinX = Math.max(0, CHAT_GAME_PLATFORM_SAFE_MARGIN);
    const anchorWidth = 164;
    const anchorY = -18;
    const playerCenter = state.player.x + (state.player.w * 0.5);
    state.pathTargetX = chatGameClamp(
        playerCenter,
        state.width * 0.24,
        state.width * 0.76,
    );
    const anchorX = chatGameClamp(
        playerCenter - (anchorWidth / 2),
        safeMinX,
        Math.max(safeMinX, state.width - anchorWidth - CHAT_GAME_PLATFORM_SAFE_MARGIN),
    );
    state.platforms.push({
        id: state.platformSeq++,
        x: anchorX,
        y: anchorY,
        w: anchorWidth,
        h: 10,
        drift: 0,
    });
    state.platformGuideX = anchorX + (anchorWidth * 0.5);
    let seedY = anchorY - chatGameRandom(34, 46);
    for (let index = 0; index < CHAT_GAME_PLATFORM_RUNWAY_COUNT; index += 1) {
        const runwayBias = Math.sin(index * 0.78) * 18;
        const correction = (Number(state.pathTargetX) - Number(state.platformGuideX)) * 0.34;
        const guideX = Number(state.platformGuideX) + runwayBias + correction + chatGameRandom(-12, 12);
        state.platforms.push(chatGameCreatePlatform(state, seedY, {
            centerX: guideX,
            driftMax: index < 4 ? 0 : 0.08,
        }));
        seedY -= chatGameRandom(40, 56);
    }
    chatGameSpawnPlatforms(state);
}

function chatGameUpdateHud(state) {
    if (!state) return;
    const scoreText = String(Math.max(0, Math.floor(state.score)));
    const highText = String(Math.max(0, Math.floor(state.best)));
    if (state.id === DINO_GAME_ID) {
        if (composerDinoScore) {
            composerDinoScore.textContent = scoreText;
        }
        if (composerDinoHighScore) {
            composerDinoHighScore.textContent = highText;
        }
        return;
    }
    if (chatGameScore) {
        chatGameScore.textContent = scoreText;
    }
    if (chatGameHighScore) {
        chatGameHighScore.textContent = highText;
    }
}

function chatGameSyncScene(state) {
    if (!state) return;
    const activeGame = safeString(chatGameRuntime.activeGameId).toLowerCase();
    const isDino = activeGame === DINO_GAME_ID;
    const scene = state.scene || {};
    const selectedAgent = chatGameApplyBotAgentStyle(state.selectedAgent || chatGamePickOfficeAgentForRun());
    if (!state.selectedAgent || state.selectedAgent.id !== selectedAgent.id) {
        state.selectedAgent = selectedAgent;
    }
    const botScale = chatGameClamp(Number(scene.botScale) || 1, 0.24, 1.8);
    const botRotate = chatGameClamp(Number(scene.botRotate) || 0, -1200, 1200);
    chatGameSetPhaseClass(state.mode);
    if (chatGamePanel) {
        chatGamePanel.classList.toggle('door-visible', Boolean(scene.doorVisible));
    }
    if (chatGameDoor) {
        chatGameDoor.style.setProperty('--door-open', chatGameClamp(scene.doorOpen, 0, 1).toFixed(3));
        chatGameDoor.style.setProperty('--door-light', chatGameClamp(scene.light, 0, 1).toFixed(3));
    }
    if (chatGamePortal) {
        const portal = state.portal || {};
        const portalVisible = isDino && Boolean(portal.visible);
        chatGamePortal.classList.toggle('hidden', !portalVisible);
        if (portalVisible) {
            chatGamePortal.style.left = `${(Number(portal.x) || 0).toFixed(2)}px`;
            chatGamePortal.style.top = `${(Number(portal.y) || 0).toFixed(2)}px`;
            chatGamePortal.style.setProperty('--portal-spin', `${chatGameClamp(Number(portal.spin) || 0, -10000, 10000).toFixed(2)}deg`);
            chatGamePortal.style.setProperty('--portal-scale', chatGameClamp(Number(portal.scale) || 1, 0.2, 2.8).toFixed(3));
            chatGamePortal.style.setProperty('--portal-glow', chatGameClamp(Number(portal.glow) || 0.7, 0, 1).toFixed(3));
        }
    }
    if (chatGameBotWrap) {
        const botX = Number(scene.botX) || 0;
        const botY = Number(scene.botY) || 0;
        const insideDoor = Boolean(scene.botInside);
        chatGameBotWrap.style.setProperty('--bot-rotate', botRotate.toFixed(2));
        const botPlayfieldHost = isDino && composerDinoShell instanceof HTMLElement ? composerDinoShell : chatGameLane;
        if (insideDoor && !isDino && chatGameDoor instanceof HTMLElement) {
            if (chatGameBotWrap.parentElement !== chatGameDoor) {
                chatGameDoor.appendChild(chatGameBotWrap);
            }
            const doorOffsetX = Number(scene.botDoorOffsetX) || 0;
            chatGameBotWrap.style.left = `${CHAT_GAME_DOOR_BOT_MOUNT_LEFT}px`;
            chatGameBotWrap.style.top = 'auto';
            chatGameBotWrap.style.bottom = `${CHAT_GAME_DOOR_BOT_MOUNT_BOTTOM}px`;
            chatGameBotWrap.style.transform = `translate3d(${doorOffsetX.toFixed(2)}px, 0px, 0px) rotate(${botRotate.toFixed(2)}deg) scale(${botScale.toFixed(3)})`;
        } else {
            if (botPlayfieldHost instanceof HTMLElement && chatGameBotWrap.parentElement !== botPlayfieldHost) {
                botPlayfieldHost.appendChild(chatGameBotWrap);
            }
            chatGameBotWrap.style.left = '0px';
            chatGameBotWrap.style.top = '0px';
            chatGameBotWrap.style.bottom = 'auto';
            chatGameBotWrap.style.transform = `translate3d(${botX.toFixed(2)}px, ${botY.toFixed(2)}px, 0px) rotate(${botRotate.toFixed(2)}deg) scale(${botScale.toFixed(3)})`;
        }
        chatGameBotWrap.classList.toggle('visible', Boolean(scene.botVisible));
        chatGameBotWrap.classList.toggle('inside-door', Boolean(scene.botInside));
        chatGameBotWrap.classList.toggle('jetpack-on', activeGame === JETPACK_GAME_ID && Boolean(scene.botJetpack));
        chatGameBotWrap.classList.toggle('dino-ride', isDino);
        if (isDino) {
            chatGameBotWrap.classList.remove('jetpack-on');
        }
        const moving = Boolean(scene.botRunning) || (state.mode === 'playing' && Math.abs(state.player?.vx || 0) > 0.35);
        chatGameBotWrap.classList.toggle('is-running', moving);
        chatGameBotWrap.classList.toggle('dir-left', Number(state.player?.facing || -1) < 0);
    }
    if (chatGameBot) {
        chatGameBot.classList.toggle('looking-user', state.mode === 'ready');
    }
}

function chatGameResetCloudJump() {
    if (!(chatGameCanvas instanceof HTMLCanvasElement)) return;
    const surface = chatGameResizeCanvas();
    const width = surface.width;
    const height = surface.height;
    const best = chatGameGetHighScore();
    const selectedAgent = chatGamePickOfficeAgentForRun();
    const state = {
        mode: 'intro',
        selectedAgent,
        width,
        height,
        tick: 0,
        introSeconds: 0,
        readySeconds: 0,
        score: 0,
        best,
        distance: 0,
        playFrames: 0,
        gravity: 0.41,
        horizontalSpeed: 4.6,
        jumpVelocity: -10.6,
        baseFallSpeed: 1.16,
        launchSeconds: 0,
        scrollLine: height * 0.34,
        startY: height - 140,
        platformGuideX: (width * CHAT_GAME_START_X_RATIO),
        pathTargetX: (width * CHAT_GAME_PLATFORM_CENTER_RATIO),
        platformSeq: 1,
        platforms: [],
        player: {
            x: (width * CHAT_GAME_START_X_RATIO) - 15,
            y: height - 150,
            w: 30,
            h: 34,
            vx: 0,
            vy: 0,
            facing: -1,
        },
        scene: {
            doorVisible: false,
            doorOpen: 0,
            light: 0,
            botVisible: false,
            botRunning: false,
            botInside: true,
            botDoorOffsetX: CHAT_GAME_DOOR_BOT_ENTER_OFFSET_START,
            botX: width - 50,
            botY: height - 150,
            botScale: 1,
            botJetpack: false,
        },
    };

    const doorAnchor = chatGameGetDoorAnchor(state);
    const startY = Number(doorAnchor.y) || (height - 140);
    state.player.x = chatGameClamp(state.player.x, 18, Math.max(18, width - state.player.w - 18));
    state.startY = startY;
    state.player.y = startY;
    state.platformGuideX = state.player.x + (state.player.w * 0.5);
    state.pathTargetX = state.platformGuideX;
    state.scene.botX = Number(doorAnchor.doorLeft || 0) + CHAT_GAME_DOOR_BOT_MOUNT_LEFT + CHAT_GAME_DOOR_BOT_ENTER_OFFSET_START;
    state.scene.botY = startY;
    chatGameRuntime.cloudJump = state;
    chatGameRuntime.lastFrameMs = 0;
    chatGameUpdateHud(state);
    chatGameSetStatusText('Door opening...');
    chatGameSyncScene(state);
}

function chatGameStartRun(state = chatGameRuntime.cloudJump) {
    if (!state || state.mode !== 'ready') return false;
    state.mode = 'launch';
    state.launchSeconds = 0;
    state.playFrames = 0;
    state.score = 0;
    state.distance = 0;
    chatGameCreateTopStartPlatforms(state);
    state.player.y = Number(state.startY) || state.player.y;
    state.player.vy = 0;
    state.player.vx = 0;
    chatGameSetStatusText('Platforms incoming. First landing starts the run.');
    chatGameSyncScene(state);
    return true;
}

function chatGameStepIntro(state, deltaFrames) {
    const stepSeconds = deltaFrames / 60;
    state.tick += deltaFrames;
    state.introSeconds += stepSeconds;

    const elapsed = state.introSeconds;
    const scene = state.scene;
    scene.botScale = 1;
    scene.botJetpack = false;
    scene.doorVisible = elapsed >= 0.08;
    scene.doorOpen = chatGameClamp((elapsed - 0.32) / 0.46, 0, 1);
    scene.light = chatGameClamp((elapsed - 0.42) / 0.4, 0, 1);

    const doorMetrics = chatGameGetDoorAnchor(state);
    const insideBaseY = doorMetrics.y;
    const insideOffsetStart = CHAT_GAME_DOOR_BOT_ENTER_OFFSET_START;
    const insideOffsetEnd = CHAT_GAME_DOOR_BOT_ENTER_OFFSET_END;
    const worldXFromDoorOffset = (offsetX) => (
        Number(doorMetrics.doorLeft || 0) + CHAT_GAME_DOOR_BOT_MOUNT_LEFT + offsetX
    );
    const holdInsideStart = 0.22;
    const holdInsideEnd = 1.12;
    const emergeEnd = 1.58;
    const runEnd = 2.72;
    const doorCloseStart = runEnd - 0.34;

    if (elapsed < holdInsideStart) {
        scene.botVisible = false;
        scene.botRunning = false;
        scene.botInside = true;
        scene.botDoorOffsetX = insideOffsetStart;
        scene.botX = worldXFromDoorOffset(scene.botDoorOffsetX);
        scene.botY = insideBaseY;
        state.player.y = insideBaseY;
        state.player.facing = -1;
    } else if (elapsed < holdInsideEnd) {
        scene.botVisible = true;
        scene.botRunning = false;
        scene.botInside = true;
        scene.botDoorOffsetX = insideOffsetStart;
        scene.botX = worldXFromDoorOffset(scene.botDoorOffsetX);
        scene.botY = insideBaseY;
        state.player.y = insideBaseY;
        state.player.facing = -1;
    } else if (elapsed < emergeEnd) {
        const emergeProgress = chatGameClamp((elapsed - holdInsideEnd) / Math.max(0.001, emergeEnd - holdInsideEnd), 0, 1);
        const eased = chatGameEaseOutCubic(emergeProgress);
        scene.botVisible = true;
        scene.botRunning = emergeProgress > 0.08;
        scene.botInside = true;
        scene.botDoorOffsetX = insideOffsetStart + ((insideOffsetEnd - insideOffsetStart) * eased);
        scene.botX = worldXFromDoorOffset(scene.botDoorOffsetX);
        scene.botY = insideBaseY;
        state.player.y = insideBaseY;
        state.player.facing = -1;
    } else {
        const runProgress = chatGameClamp((elapsed - emergeEnd) / Math.max(0.001, runEnd - emergeEnd), 0, 1);
        const eased = chatGameEaseOutCubic(runProgress);
        const startX = worldXFromDoorOffset(insideOffsetEnd);
        const endX = state.player.x;
        const closeProgress = chatGameClamp((elapsed - doorCloseStart) / Math.max(0.001, runEnd - doorCloseStart), 0, 1);
        scene.botVisible = true;
        scene.botRunning = runProgress < 0.98;
        scene.botInside = false;
        scene.botDoorOffsetX = 0;
        scene.botX = startX + ((endX - startX) * eased);
        scene.botY = insideBaseY + (Math.sin(runProgress * Math.PI) * 1.4);
        scene.doorOpen = 1 - closeProgress;
        scene.light *= (1 - closeProgress);
        scene.doorVisible = closeProgress < 0.98;
        state.player.y = insideBaseY;
        state.startY = insideBaseY;
        state.player.facing = -1;
    }

    if (elapsed >= (runEnd + 0.16)) {
        state.mode = 'ready';
        state.readySeconds = 0;
        scene.botVisible = true;
        scene.botRunning = false;
        scene.botInside = false;
        scene.botDoorOffsetX = 0;
        scene.doorVisible = false;
        scene.doorOpen = 0;
        scene.light = 0;
        scene.botX = state.player.x;
        scene.botY = state.startY;
        state.player.y = state.startY;
        chatGameSetStatusText('Press Space to start | Esc to exit');
    }
}

function chatGameStepReady(state, deltaFrames) {
    state.tick += deltaFrames;
    state.readySeconds += (deltaFrames / 60);
    const scene = state.scene;
    scene.botScale = 1;
    scene.botJetpack = false;
    scene.doorVisible = false;
    scene.doorOpen = 0;
    scene.light = 0;
    scene.botVisible = true;
    scene.botRunning = false;
    scene.botInside = false;
    scene.botDoorOffsetX = 0;
    state.player.vx = 0;
    state.player.vy = 0;
    state.player.y = state.startY;
    scene.botX = state.player.x;
    scene.botY = state.player.y + (Math.sin(state.tick * 0.11) * 0.8);
}

function chatGameStepLaunch(state, deltaFrames) {
    state.tick += deltaFrames;
    state.launchSeconds += (deltaFrames / 60);

    const player = state.player;
    const horizontal = (chatGameRuntime.input.right ? 1 : 0) - (chatGameRuntime.input.left ? 1 : 0);
    player.vx = horizontal * (state.horizontalSpeed * 0.92);
    player.x += player.vx * deltaFrames;
    if (player.vx > 0.12) {
        player.facing = 1;
    } else if (player.vx < -0.12) {
        player.facing = -1;
    }
    if (player.x > state.width) {
        player.x = -player.w;
    } else if ((player.x + player.w) < 0) {
        player.x = state.width;
    }

    const groundY = Number(state.startY) || player.y;
    player.y = groundY;
    player.vy = 0;

    const playerBottom = player.y + player.h;
    const launchSweeps = chatGameCollectPlatformSweeps(state, deltaFrames, CHAT_GAME_LAUNCH_PLATFORM_FALL_SPEED);
    const landedPlatform = chatGameFindLandingPlatform(
        launchSweeps,
        player,
        playerBottom - 4,
        playerBottom + 4,
        { tolerance: 10, footInset: 3 },
    );

    state.platforms = state.platforms.filter((platform) => platform.y < (state.height + 44));
    chatGameSpawnPlatforms(state);

    const scene = state.scene;
    scene.botScale = 1;
    scene.botJetpack = false;
    scene.doorVisible = false;
    scene.doorOpen = 0;
    scene.light = 0;
    scene.botVisible = true;
    scene.botX = player.x;
    scene.botY = player.y;
    scene.botRunning = Math.abs(player.vx) > 0.3;
    scene.botInside = false;
    scene.botDoorOffsetX = 0;

    if (landedPlatform) {
        player.y = landedPlatform.y - player.h;
        player.vy = state.jumpVelocity;
        state.mode = 'playing';
        state.playFrames = 0;
        state.launchSeconds = 0;
        chatGameSetStatusText('Run active. Keep landing to stay up.');
        return;
    }

    if (state.launchSeconds > CHAT_GAME_PLATFORM_LAUNCH_RESPAWN_SECONDS) {
        state.launchSeconds = 0;
        chatGameCreateTopStartPlatforms(state);
        chatGameSetStatusText('Platforms realigned. First landing starts the run.');
    }
}

function chatGameStepPlaying(state, deltaFrames) {
    state.tick += deltaFrames;
    state.playFrames += deltaFrames;

    const player = state.player;
    const horizontal = (chatGameRuntime.input.right ? 1 : 0) - (chatGameRuntime.input.left ? 1 : 0);
    player.vx = horizontal * state.horizontalSpeed;
    player.x += player.vx * deltaFrames;
    if (player.vx > 0.12) {
        player.facing = 1;
    } else if (player.vx < -0.12) {
        player.facing = -1;
    }
    if (player.x > state.width) {
        player.x = -player.w;
    } else if ((player.x + player.w) < 0) {
        player.x = state.width;
    }

    const previousBottom = player.y + player.h;
    player.vy += state.gravity * deltaFrames;
    player.vy = Math.min(player.vy, 14.8);
    player.y += player.vy * deltaFrames;

    const platformFallSpeed = state.baseFallSpeed + Math.min(2.2, state.score * 0.009);
    const platformSweeps = chatGameCollectPlatformSweeps(state, deltaFrames, platformFallSpeed);

    if (player.vy > 0) {
        const currentBottom = player.y + player.h;
        const landedPlatform = chatGameFindLandingPlatform(
            platformSweeps,
            player,
            previousBottom,
            currentBottom,
            { tolerance: 8, footInset: 3 },
        );
        if (landedPlatform) {
            player.y = landedPlatform.y - player.h;
            player.vy = state.jumpVelocity;
        }
    }

    if (player.y < state.scrollLine) {
        const travel = state.scrollLine - player.y;
        player.y = state.scrollLine;
        state.platforms.forEach((platform) => {
            platform.y += travel;
        });
        state.distance += travel;
    }

    const climbScore = Math.max(0, Math.floor(state.distance / 5));
    const timeScore = Math.max(0, Math.floor(state.playFrames * 0.08));
    state.score = Math.max(state.score, climbScore + timeScore);

    state.platforms = state.platforms.filter((platform) => platform.y < (state.height + 44));
    chatGameSpawnPlatforms(state);

    const scene = state.scene;
    scene.botScale = 1;
    scene.botJetpack = false;
    scene.doorVisible = false;
    scene.doorOpen = 0;
    scene.light = 0;
    scene.botVisible = true;
    scene.botX = player.x;
    scene.botY = player.y;
    scene.botRunning = Math.abs(player.vx) > 0.4;
    scene.botInside = false;
    scene.botDoorOffsetX = 0;

    if (player.y > (state.height + 42)) {
        state.mode = 'game_over';
        state.best = Math.max(state.best, state.score);
        chatGameSetHighScore(state.best);
        player.vx = 0;
        player.vy = 0;
        scene.botRunning = false;
        chatGameSetStatusText('Game over. Space to run again | Esc to exit');
    }
}

function chatGameStepGameOver(state, deltaFrames) {
    state.tick += deltaFrames;
    const scene = state.scene;
    scene.botScale = 1;
    scene.botJetpack = false;
    scene.doorVisible = false;
    scene.doorOpen = 0;
    scene.light = 0;
    scene.botVisible = true;
    scene.botRunning = false;
    scene.botInside = false;
    scene.botDoorOffsetX = 0;
    scene.botX = state.player.x;
    scene.botY = Math.min(state.height - state.player.h - 12, state.player.y + (Math.sin(state.tick * 0.08) * 0.6));
}

function chatGameStepCloudJump(deltaFrames) {
    const state = chatGameRuntime.cloudJump;
    if (!state) return;
    const frames = Number.isFinite(deltaFrames) ? Math.max(0, deltaFrames) : 1;

    if (state.mode === 'intro') {
        chatGameStepIntro(state, frames);
    } else if (state.mode === 'ready') {
        chatGameStepReady(state, frames);
    } else if (state.mode === 'launch') {
        chatGameStepLaunch(state, frames);
    } else if (state.mode === 'playing') {
        chatGameStepPlaying(state, frames);
    } else if (state.mode === 'game_over') {
        chatGameStepGameOver(state, frames);
    }
    chatGameUpdateHud(state);
    chatGameSyncScene(state);
}

function chatGameRenderCloudJump() {
    if (!(chatGameCanvas instanceof HTMLCanvasElement)) return;
    const ctx = chatGameCanvas.getContext('2d');
    const state = chatGameRuntime.cloudJump;
    if (!ctx || !state) return;

    const width = state.width;
    const height = state.height;
    ctx.clearRect(0, 0, width, height);

    state.platforms.forEach((platform) => {
        const shimmer = 0.64 + (Math.sin((state.tick * 0.05) + (platform.id * 0.18)) * 0.13);
        ctx.fillStyle = `rgba(70, 175, 248, ${chatGameClamp(shimmer, 0.32, 0.86).toFixed(3)})`;
        ctx.fillRect(platform.x, platform.y, platform.w, platform.h);
        ctx.fillStyle = 'rgba(230, 246, 255, 0.92)';
        ctx.fillRect(platform.x + 2, platform.y + 2, platform.w - 4, 3);
    });

    if (state.mode === 'game_over') {
        ctx.fillStyle = 'rgba(236, 246, 255, 0.88)';
        ctx.font = '700 14px "Segoe UI", sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Run Ended', width * 0.5, Math.max(36, height * 0.18));
    }
    chatGameSyncScene(state);
}

function chatGameGetJetpackFlightBounds(state, entityHeight = 0) {
    const minY = JETPACK_PLAYER_TOP_PADDING;
    const maxY = Math.max(
        minY,
        state.height - Number(entityHeight || 0) - JETPACK_PLAYER_BOTTOM_PADDING,
    );
    return { minY, maxY };
}

function chatGameCreateJetpackObstacle(state, xOverride = null) {
    const hasXOverride = xOverride !== null && xOverride !== undefined && Number.isFinite(Number(xOverride));
    const spawnX = hasXOverride
        ? Number(xOverride)
        : (state.width + chatGameRandom(48, 138));
    const roll = Math.random();
    const bounds = chatGameGetJetpackFlightBounds(state);
    const centerMinY = bounds.minY + 42;
    const centerMaxY = Math.max(centerMinY, bounds.maxY - 42);

    if (roll < 0.58) {
        const angles = [-64, -48, -32, -18, 18, 32, 48, 64];
        const angleDeg = angles[Math.floor(Math.random() * angles.length)];
        return {
            id: state.obstacleSeq++,
            type: 'zapper',
            cx: spawnX,
            cy: chatGameRandom(centerMinY, centerMaxY),
            length: Math.round(chatGameRandom(JETPACK_ZAPPER_LENGTH_MIN, JETPACK_ZAPPER_LENGTH_MAX)),
            thickness: JETPACK_ZAPPER_THICKNESS,
            angle: angleDeg * (Math.PI / 180),
            passed: false,
        };
    }

    if (roll < 0.84) {
        const missileMinY = bounds.minY + 10;
        const missileMaxY = Math.max(missileMinY, bounds.maxY - JETPACK_MISSILE_HEIGHT - 10);
        return {
            id: state.obstacleSeq++,
            type: 'missile',
            x: spawnX,
            y: chatGameRandom(missileMinY, missileMaxY),
            w: JETPACK_MISSILE_WIDTH,
            h: JETPACK_MISSILE_HEIGHT,
            vy: chatGameRandom(-0.44, 0.44),
            passed: false,
        };
    }

    const laserHeight = Math.round(chatGameRandom(JETPACK_LASER_HEIGHT_MIN, JETPACK_LASER_HEIGHT_MAX));
    const side = Math.random() < 0.5 ? 'top' : 'bottom';
    return {
        id: state.obstacleSeq++,
        type: 'laser_wall',
        x: spawnX,
        y: side === 'top' ? 0 : Math.max(0, state.height - laserHeight),
        w: JETPACK_LASER_WIDTH,
        h: laserHeight,
        side,
        passed: false,
    };
}

function chatGameGetJetpackObstacleHorizontalBounds(obstacle) {
    if (!obstacle) return { left: 0, right: 0 };
    if (obstacle.type === 'zapper') {
        const halfLength = (obstacle.length || 0) * 0.5;
        const dx = Math.cos(obstacle.angle || 0) * halfLength;
        const edgePadding = (obstacle.thickness || 0) * 0.5;
        const left = Math.min((obstacle.cx || 0) - dx, (obstacle.cx || 0) + dx) - edgePadding;
        const right = Math.max((obstacle.cx || 0) - dx, (obstacle.cx || 0) + dx) + edgePadding;
        return { left, right };
    }
    return {
        left: obstacle.x || 0,
        right: (obstacle.x || 0) + (obstacle.w || 0),
    };
}

function chatGameGetJetpackObstacleRightEdge(obstacle) {
    return chatGameGetJetpackObstacleHorizontalBounds(obstacle).right;
}

function chatGameStepJetpackObstacle(obstacle, state, deltaFrames) {
    if (!obstacle || !state) return;
    const scroll = state.scrollSpeed * deltaFrames;
    if (obstacle.type === 'zapper') {
        obstacle.cx -= scroll;
        return;
    }

    obstacle.x -= scroll;
    if (obstacle.type === 'missile') {
        obstacle.y += (obstacle.vy || 0) * deltaFrames;
        const bounds = chatGameGetJetpackFlightBounds(state, obstacle.h || 0);
        if (obstacle.y <= bounds.minY || obstacle.y >= bounds.maxY) {
            obstacle.vy = -(obstacle.vy || 0);
            obstacle.y = chatGameClamp(obstacle.y, bounds.minY, bounds.maxY);
        }
    }
}

function chatGameJetpackObstacleCollision(state, obstacle) {
    if (!state || !obstacle) return false;
    const player = state.player;
    const hitX = player.x + (player.w * 0.53);
    const hitY = player.y + (player.h * 0.54);
    const hitRadius = Math.max(7, (Math.min(player.w, player.h) * 0.34) - JETPACK_HITBOX_PADDING);

    if (obstacle.type === 'zapper') {
        const halfLength = (obstacle.length || 0) * 0.5;
        const dx = Math.cos(obstacle.angle || 0) * halfLength;
        const dy = Math.sin(obstacle.angle || 0) * halfLength;
        const x1 = (obstacle.cx || 0) - dx;
        const y1 = (obstacle.cy || 0) - dy;
        const x2 = (obstacle.cx || 0) + dx;
        const y2 = (obstacle.cy || 0) + dy;
        const hitDistance = hitRadius + ((obstacle.thickness || JETPACK_ZAPPER_THICKNESS) * 0.52);
        return chatGameDistanceToSegmentSquared(hitX, hitY, x1, y1, x2, y2) <= (hitDistance * hitDistance);
    }

    return chatGameCircleRectOverlap(
        hitX,
        hitY,
        hitRadius,
        obstacle.x || 0,
        obstacle.y || 0,
        obstacle.w || 0,
        obstacle.h || 0,
    );
}

function chatGameComputeJetpackIntroPose(state, progress) {
    const targetX = state.player.x;
    const targetY = state.player.y;
    const p = chatGameClamp(progress, 0, 1);
    const eased = chatGameEaseOutCubic(p);
    const settle = chatGameEaseInOutCubic(chatGameClamp((p - 0.72) / 0.28, 0, 1));
    const stuntPower = ((1 - p) ** 1.05);

    const travelX = chatGameLerp(JETPACK_FLIGHT_START_X, targetX, eased);
    const travelY = chatGameLerp(JETPACK_FLIGHT_START_Y, targetY, eased);
    const swirlX = Math.sin((p * Math.PI * 8.8) + 0.35) * (132 * stuntPower);
    const swirlY = Math.cos((p * Math.PI * 11.4) + 0.82) * (74 * stuntPower);
    const figureY = Math.sin(p * Math.PI * 4.6) * Math.sin(p * Math.PI * 9.2) * (58 * stuntPower);
    const preSettleX = travelX + swirlX;
    const preSettleY = travelY + swirlY + figureY;

    return {
        x: chatGameLerp(preSettleX, targetX, settle),
        y: chatGameLerp(preSettleY, targetY, settle),
        rotate: (Math.sin(p * Math.PI * 10.6) * 95 * stuntPower) + (Math.cos(p * Math.PI * 5.4) * 24 * stuntPower),
        scale: chatGameClamp(
            0.16 + (eased * 0.92) + (Math.sin(p * Math.PI * 7.2) * 0.08 * stuntPower),
            0.16,
            1.08,
        ),
    };
}

function chatGameResetJetpackJoyride() {
    if (!(chatGameCanvas instanceof HTMLCanvasElement)) return;
    const surface = chatGameResizeCanvas();
    const width = surface.width;
    const height = surface.height;
    const best = chatGameGetHighScore(JETPACK_GAME_ID);
    const selectedAgent = chatGamePickOfficeAgentForRun();
    const playerX = chatGameClamp((width * JETPACK_PLAYER_X_RATIO) - 15, 40, Math.max(40, width - 76));
    const bounds = chatGameGetJetpackFlightBounds({ height }, 34);
    const playerY = chatGameClamp((height * JETPACK_PLAYER_Y_RATIO), bounds.minY, bounds.maxY);
    const state = {
        id: JETPACK_GAME_ID,
        selectedAgent,
        mode: 'intro',
        width,
        height,
        tick: 0,
        introSeconds: 0,
        score: 0,
        best,
        playFrames: 0,
        moveSpeed: JETPACK_MOVE_SPEED,
        scrollSpeed: JETPACK_SCROLL_BASE,
        spawnFrames: 24,
        obstacleSeq: 1,
        obstacles: [],
        player: {
            x: playerX,
            y: playerY,
            w: 30,
            h: 34,
            vx: 0,
            vy: 0,
            facing: 1,
        },
        scene: {
            doorVisible: false,
            doorOpen: 0,
            light: 0,
            botVisible: true,
            botRunning: false,
            botInside: false,
            botDoorOffsetX: 0,
            botX: JETPACK_FLIGHT_START_X,
            botY: JETPACK_FLIGHT_START_Y,
            botScale: 0.16,
            botRotate: 0,
            botJetpack: true,
        },
    };
    chatGameRuntime.jetpackJoyride = state;
    chatGameRuntime.lastFrameMs = 0;
    chatGameUpdateHud(state);
    chatGameSetStatusText('Jetpack inbound...');
    chatGameSyncScene(state);
}

function chatGameStartJetpackRun(state = chatGameRuntime.jetpackJoyride) {
    if (!state || state.mode !== 'ready') return false;
    state.mode = 'playing';
    state.score = 0;
    state.playFrames = 0;
    state.obstacles = [];
    state.spawnFrames = 10;
    state.scrollSpeed = JETPACK_SCROLL_BASE;
    state.player.vx = 0;
    state.player.vy = 0;
    if (state.scene) {
        state.scene.botRotate = 0;
    }
    chatGameSetStatusText('Run active. Use Up/Down to dodge hazards.');
    chatGameSyncScene(state);
    return true;
}

function chatGameStepJetpackIntro(state, deltaFrames) {
    const stepSeconds = deltaFrames / 60;
    state.tick += deltaFrames;
    state.introSeconds += stepSeconds;

    const player = state.player;
    const scene = state.scene;
    const elapsed = state.introSeconds;
    const targetX = player.x;
    const targetY = player.y;

    scene.doorVisible = false;
    scene.doorOpen = 0;
    scene.light = 0;
    scene.botVisible = true;
    scene.botJetpack = true;
    scene.botInside = false;
    scene.botDoorOffsetX = 0;
    scene.botRunning = false;

    if (elapsed < JETPACK_INTRO_DURATION_SECONDS) {
        const progress = chatGameClamp(elapsed / JETPACK_INTRO_DURATION_SECONDS, 0, 1);
        const pose = chatGameComputeJetpackIntroPose(state, progress);
        scene.botScale = pose.scale;
        scene.botRotate = pose.rotate;
        scene.botX = pose.x;
        scene.botY = pose.y;
        player.vy = 0;
    } else {
        state.mode = 'ready';
        scene.botScale = 1;
        scene.botRotate = 0;
        scene.botX = targetX;
        scene.botY = targetY;
        player.vy = 0;
        chatGameSetStatusText('Press Space to start | Esc to exit');
    }
}

function chatGameStepJetpackReady(state, deltaFrames) {
    state.tick += deltaFrames;
    const scene = state.scene;
    const player = state.player;
    const bounds = chatGameGetJetpackFlightBounds(state, player.h);
    player.y = chatGameClamp(player.y, bounds.minY, bounds.maxY);
    player.vx = 0;
    player.vy = 0;

    scene.doorVisible = false;
    scene.doorOpen = 0;
    scene.light = 0;
    scene.botVisible = true;
    scene.botRunning = false;
    scene.botInside = false;
    scene.botDoorOffsetX = 0;
    scene.botScale = 1;
    scene.botRotate = Math.sin(state.tick * 0.08) * 2.2;
    scene.botJetpack = true;
    scene.botX = player.x;
    scene.botY = player.y + (Math.sin(state.tick * 0.11) * 1.2);
}

function chatGameStepJetpackPlaying(state, deltaFrames) {
    state.tick += deltaFrames;
    state.playFrames += deltaFrames;
    const player = state.player;
    const scene = state.scene;
    const movingUp = Boolean(chatGameRuntime.input.up) && !Boolean(chatGameRuntime.input.down);
    const movingDown = Boolean(chatGameRuntime.input.down) && !Boolean(chatGameRuntime.input.up);
    const moveSpeed = state.moveSpeed || JETPACK_MOVE_SPEED;

    if (movingUp) {
        player.y -= moveSpeed * deltaFrames;
        player.vy = -moveSpeed;
    } else if (movingDown) {
        player.y += moveSpeed * deltaFrames;
        player.vy = moveSpeed;
    } else {
        player.vy = 0;
    }

    const bounds = chatGameGetJetpackFlightBounds(state, player.h);
    player.y = chatGameClamp(player.y, bounds.minY, bounds.maxY);

    state.scrollSpeed = JETPACK_SCROLL_BASE + Math.min(JETPACK_SCROLL_MAX_BONUS, state.score * 0.028);
    state.spawnFrames -= deltaFrames;
    if (state.spawnFrames <= 0) {
        state.obstacles.push(chatGameCreateJetpackObstacle(state));
        state.spawnFrames = chatGameRandom(JETPACK_SPAWN_FRAMES_MIN, JETPACK_SPAWN_FRAMES_MAX);
    }

    let crashed = false;
    state.obstacles.forEach((obstacle) => {
        chatGameStepJetpackObstacle(obstacle, state, deltaFrames);
        const rightEdge = chatGameGetJetpackObstacleRightEdge(obstacle);
        if (!obstacle.passed && rightEdge < player.x) {
            obstacle.passed = true;
            state.score += 1;
        }
        if (!crashed && chatGameJetpackObstacleCollision(state, obstacle)) {
            crashed = true;
        }
    });
    state.obstacles = state.obstacles.filter((obstacle) => chatGameGetJetpackObstacleRightEdge(obstacle) > -56);

    scene.doorVisible = false;
    scene.doorOpen = 0;
    scene.light = 0;
    scene.botVisible = true;
    scene.botRunning = movingUp || movingDown;
    scene.botInside = false;
    scene.botDoorOffsetX = 0;
    scene.botScale = 1;
    scene.botJetpack = true;
    scene.botRotate = movingUp ? -10 : (movingDown ? 10 : Math.sin(state.tick * 0.06) * 2);
    scene.botX = player.x;
    scene.botY = player.y;

    if (crashed) {
        state.mode = 'game_over';
        state.best = Math.max(state.best, state.score);
        chatGameSetHighScore(state.best, JETPACK_GAME_ID);
        player.vy = 0;
        scene.botRotate = 0;
        scene.botJetpack = false;
        chatGameSetStatusText('Run ended. Space to run again | Esc to exit');
    }
}

function chatGameStepJetpackGameOver(state, deltaFrames) {
    state.tick += deltaFrames;
    const scene = state.scene;
    const player = state.player;
    scene.doorVisible = false;
    scene.doorOpen = 0;
    scene.light = 0;
    scene.botVisible = true;
    scene.botRunning = false;
    scene.botInside = false;
    scene.botDoorOffsetX = 0;
    scene.botScale = 1;
    scene.botRotate = 0;
    scene.botJetpack = false;
    scene.botX = player.x;
    scene.botY = player.y + (Math.sin(state.tick * 0.06) * 0.5);
}

function chatGameStepJetpack(deltaFrames) {
    const state = chatGameRuntime.jetpackJoyride;
    if (!state) return;
    const frames = Number.isFinite(deltaFrames) ? Math.max(0, deltaFrames) : 1;

    if (state.mode === 'intro') {
        chatGameStepJetpackIntro(state, frames);
    } else if (state.mode === 'ready') {
        chatGameStepJetpackReady(state, frames);
    } else if (state.mode === 'playing') {
        chatGameStepJetpackPlaying(state, frames);
    } else if (state.mode === 'game_over') {
        chatGameStepJetpackGameOver(state, frames);
    }
    chatGameUpdateHud(state);
    chatGameSyncScene(state);
}

function chatGameRenderJetpack() {
    if (!(chatGameCanvas instanceof HTMLCanvasElement)) return;
    const ctx = chatGameCanvas.getContext('2d');
    const state = chatGameRuntime.jetpackJoyride;
    if (!ctx || !state) return;

    const width = state.width;
    const height = state.height;
    ctx.clearRect(0, 0, width, height);

    state.obstacles.forEach((obstacle) => {
        if (obstacle.type === 'zapper') {
            const halfLength = (obstacle.length || 0) * 0.5;
            const dx = Math.cos(obstacle.angle || 0) * halfLength;
            const dy = Math.sin(obstacle.angle || 0) * halfLength;
            const x1 = (obstacle.cx || 0) - dx;
            const y1 = (obstacle.cy || 0) - dy;
            const x2 = (obstacle.cx || 0) + dx;
            const y2 = (obstacle.cy || 0) + dy;
            const thickness = obstacle.thickness || JETPACK_ZAPPER_THICKNESS;

            ctx.lineCap = 'round';
            ctx.strokeStyle = 'rgba(100, 200, 255, 0.26)';
            ctx.lineWidth = thickness + 8;
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.stroke();

            ctx.strokeStyle = 'rgba(56, 165, 248, 0.96)';
            ctx.lineWidth = thickness;
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.stroke();

            ctx.fillStyle = 'rgba(228, 246, 255, 0.95)';
            ctx.beginPath();
            ctx.arc(x1, y1, (thickness * 0.55), 0, Math.PI * 2);
            ctx.arc(x2, y2, (thickness * 0.55), 0, Math.PI * 2);
            ctx.fill();
            return;
        }

        if (obstacle.type === 'missile') {
            const x = obstacle.x || 0;
            const y = obstacle.y || 0;
            const w = obstacle.w || JETPACK_MISSILE_WIDTH;
            const h = obstacle.h || JETPACK_MISSILE_HEIGHT;
            const nose = 10;

            ctx.fillStyle = 'rgba(58, 170, 248, 0.96)';
            ctx.fillRect(x, y, w, h);
            ctx.fillStyle = 'rgba(228, 246, 255, 0.92)';
            ctx.fillRect(x + 2, y + 2, Math.max(6, w - 10), 4);
            ctx.beginPath();
            ctx.moveTo(x + w, y + 2);
            ctx.lineTo(x + w + nose, y + (h * 0.5));
            ctx.lineTo(x + w, y + h - 2);
            ctx.closePath();
            ctx.fill();
            ctx.fillStyle = 'rgba(255, 168, 86, 0.9)';
            ctx.fillRect(x - 6, y + 5, 6, Math.max(4, h - 10));
            return;
        }

        if (obstacle.type === 'laser_wall') {
            const x = obstacle.x || 0;
            const y = obstacle.y || 0;
            const w = obstacle.w || JETPACK_LASER_WIDTH;
            const h = obstacle.h || 0;
            const beamAlpha = 0.68 + (Math.sin((state.tick * 0.07) + (obstacle.id * 0.2)) * 0.14);

            ctx.fillStyle = `rgba(64, 184, 255, ${chatGameClamp(beamAlpha, 0.42, 0.92).toFixed(3)})`;
            ctx.fillRect(x, y, w, h);
            ctx.fillStyle = 'rgba(227, 246, 255, 0.9)';
            ctx.fillRect(x + 2, y + 2, Math.max(0, w - 4), 4);
            ctx.fillRect(x + 2, Math.max(y + h - 6, y), Math.max(0, w - 4), 4);
            ctx.fillStyle = 'rgba(118, 211, 255, 0.26)';
            ctx.fillRect(x - 4, y, 4, h);
        }
    });

    if (state.mode === 'game_over') {
        ctx.fillStyle = 'rgba(236, 246, 255, 0.88)';
        ctx.font = '700 14px "Segoe UI", sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Run Ended', width * 0.5, Math.max(36, height * 0.18));
    }
    chatGameSyncScene(state);
}

function chatGameCreateDinoObstacle(state) {
    const roll = Math.random();
    if (roll < 0.22) {
        const w = Math.round(chatGameRandom(30, 48));
        const h = Math.round(chatGameRandom(18, 28));
        return {
            id: state.obstacleSeq++,
            type: 'drone',
            x: state.width + chatGameRandom(18, 96),
            y: Math.round(state.groundY - chatGameRandom(44, 92)),
            w,
            h,
            passed: false,
        };
    }
    const w = Math.round(chatGameRandom(16, 32));
    const h = Math.round(chatGameRandom(24, 46));
    return {
        id: state.obstacleSeq++,
        type: 'cactus',
        x: state.width + chatGameRandom(18, 96),
        y: Math.round(state.groundY + DINO_PLAYER_NORMAL_HEIGHT - h),
        w,
        h,
        passed: false,
    };
}

function chatGameResetDinoRun() {
    if (!(composerDinoCanvas instanceof HTMLCanvasElement)) return;
    const surface = chatGameResizeDinoCanvas();
    const width = surface.width;
    const height = surface.height;
    const selectedAgent = chatGamePickOfficeAgentForRun();
    const best = chatGameGetHighScore(DINO_GAME_ID);
    const playerX = chatGameClamp((width * DINO_PLAYER_X_RATIO), 48, Math.max(48, width - 140));
    const portalAnchor = chatGameGetPortalAnchorInDino({ width, height });
    const groundY = height - DINO_GROUND_PADDING - DINO_PLAYER_NORMAL_HEIGHT;
    const portalY = chatGameClamp(Math.min(portalAnchor.y - 18, groundY + 4), 18, height - 52);
    const state = {
        id: DINO_GAME_ID,
        selectedAgent,
        mode: 'intro',
        width,
        height,
        tick: 0,
        introSeconds: 0,
        playFrames: 0,
        score: 0,
        best,
        speed: DINO_SCROLL_BASE,
        spawnFrames: 36,
        obstacleSeq: 1,
        scrollX: 0,
        groundY,
        portal: {
            x: portalAnchor.x,
            y: portalY,
            visible: true,
            spin: 0,
            scale: 0.26,
            glow: 0.84,
        },
        player: {
            x: playerX,
            y: 0,
            w: DINO_PLAYER_WIDTH,
            h: DINO_PLAYER_NORMAL_HEIGHT,
            vx: 0,
            vy: 0,
            onGround: true,
            ducking: false,
            facing: 1,
        },
        obstacles: [],
        scene: {
            doorVisible: false,
            doorOpen: 0,
            light: 0,
            botVisible: true,
            botRunning: false,
            botInside: false,
            botDoorOffsetX: 0,
            botX: portalAnchor.x,
            botY: portalY,
            botScale: 0.3,
            botRotate: 0,
            botJetpack: false,
        },
    };
    state.player.y = state.groundY;
    chatGameRuntime.dinoRun = state;
    chatGameRuntime.lastFrameMs = 0;
    chatGameUpdateHud(state);
    chatGameSetStatusText('Portal spin-up...');
    chatGameSyncScene(state);

    const stabilizePortalAnchor = () => {
        const live = chatGameRuntime.dinoRun;
        if (!live || live.id !== DINO_GAME_ID || live.mode !== 'intro') return;
        const nextAnchor = chatGameGetPortalAnchorInDino(live);
        live.portal.x = nextAnchor.x;
        live.portal.y = chatGameClamp(Math.min(nextAnchor.y - 18, live.groundY + 4), 18, live.height - 52);
        if (live.introSeconds < 0.16) {
            live.scene.botX = nextAnchor.x;
            live.scene.botY = live.portal.y;
        }
        chatGameSyncScene(live);
    };

    window.requestAnimationFrame(() => {
        stabilizePortalAnchor();
        window.requestAnimationFrame(stabilizePortalAnchor);
    });
}

function chatGameStartDinoRun(state = chatGameRuntime.dinoRun) {
    if (!state || state.mode !== 'ready') return false;
    state.mode = 'playing';
    state.score = 0;
    state.playFrames = 0;
    state.speed = DINO_SCROLL_BASE;
    state.spawnFrames = chatGameRandom(DINO_SPAWN_FRAMES_MIN, DINO_SPAWN_FRAMES_MAX);
    state.obstacles = [];
    state.player.vy = 0;
    state.player.onGround = true;
    state.player.ducking = false;
    state.player.h = DINO_PLAYER_NORMAL_HEIGHT;
    state.player.y = state.height - DINO_GROUND_PADDING - state.player.h;
    state.portal.visible = false;
    chatGameSetStatusText('Run active. Space to jump | Down to duck.');
    chatGameSyncScene(state);
    return true;
}

function chatGameDinoJump(state = chatGameRuntime.dinoRun) {
    if (!state || state.mode !== 'playing') return false;
    const player = state.player;
    if (!player.onGround) return false;
    player.vy = DINO_JUMP_VELOCITY;
    player.onGround = false;
    return true;
}

function chatGameSetDinoDuck(state, wantsDuck) {
    const player = state?.player;
    if (!player || !player.onGround) return;
    if (wantsDuck && !player.ducking) {
        const delta = DINO_PLAYER_NORMAL_HEIGHT - DINO_PLAYER_DUCK_HEIGHT;
        player.ducking = true;
        player.h = DINO_PLAYER_DUCK_HEIGHT;
        player.y += delta;
    } else if (!wantsDuck && player.ducking) {
        const delta = DINO_PLAYER_NORMAL_HEIGHT - DINO_PLAYER_DUCK_HEIGHT;
        player.ducking = false;
        player.h = DINO_PLAYER_NORMAL_HEIGHT;
        player.y -= delta;
    }
}

function chatGameDinoCollision(state, obstacle) {
    const player = state?.player;
    if (!player || !obstacle) return false;
    const padding = 4;
    const px = player.x + padding;
    const py = player.y + padding;
    const pw = Math.max(1, player.w - (padding * 2));
    const ph = Math.max(1, player.h - (padding * 2));
    return (
        px < obstacle.x + obstacle.w
        && px + pw > obstacle.x
        && py < obstacle.y + obstacle.h
        && py + ph > obstacle.y
    );
}

function chatGameStepDinoIntro(state, deltaFrames) {
    state.tick += deltaFrames;
    state.introSeconds += (deltaFrames / 60);
    const scene = state.scene;
    const player = state.player;
    const portal = state.portal;
    const progress = chatGameClamp(state.introSeconds / DINO_INTRO_DURATION_SECONDS, 0, 1);
    const warmup = chatGameClamp(progress / 0.34, 0, 1);
    const walkProgress = chatGameEaseOutCubic(chatGameClamp((progress - 0.34) / 0.62, 0, 1));

    portal.visible = progress < 0.95;
    portal.spin += (deltaFrames * chatGameLerp(33, 16, warmup));
    portal.scale = chatGameLerp(0.24, 1.46, warmup) + (Math.sin(state.tick * 0.11) * (0.03 + (0.05 * warmup)));
    portal.glow = 0.82 + (Math.sin(state.tick * 0.11) * 0.14);

    scene.doorVisible = false;
    scene.doorOpen = 0;
    scene.light = 0;
    scene.botInside = false;
    scene.botDoorOffsetX = 0;
    scene.botVisible = progress > 0.34;
    scene.botRunning = walkProgress > 0.06 && walkProgress < 0.98;
    scene.botJetpack = false;
    scene.botScale = chatGameClamp(0.74 + (walkProgress * 0.26), 0.7, 1);
    scene.botRotate = 0;
    scene.botX = chatGameLerp(portal.x + 1, player.x, walkProgress);
    scene.botY = state.groundY;
    player.y = state.groundY;
    player.vy = 0;
    player.onGround = true;

    if (progress >= 1) {
        state.mode = 'ready';
        scene.botVisible = true;
        scene.botRunning = false;
        scene.botScale = 1;
        scene.botRotate = 0;
        scene.botX = player.x;
        scene.botY = player.y;
        portal.visible = false;
        chatGameSetStatusText('Press Space to start | Esc to exit');
    }
}

function chatGameStepDinoReady(state, deltaFrames) {
    state.tick += deltaFrames;
    state.scrollX += (DINO_SCROLL_BASE * 0.38) * deltaFrames;
    const scene = state.scene;
    const player = state.player;
    player.ducking = false;
    player.h = DINO_PLAYER_NORMAL_HEIGHT;
    player.y = state.height - DINO_GROUND_PADDING - player.h;
    player.vy = 0;
    player.onGround = true;

    scene.doorVisible = false;
    scene.doorOpen = 0;
    scene.light = 0;
    scene.botVisible = true;
    scene.botRunning = false;
    scene.botInside = false;
    scene.botDoorOffsetX = 0;
    scene.botScale = 1;
    scene.botRotate = 0;
    scene.botJetpack = false;
    scene.botX = player.x;
    scene.botY = player.y + (Math.sin(state.tick * 0.12) * 0.9);
}

function chatGameStepDinoPlaying(state, deltaFrames) {
    state.tick += deltaFrames;
    state.playFrames += deltaFrames;
    const player = state.player;
    const scene = state.scene;

    chatGameSetDinoDuck(state, Boolean(chatGameRuntime.input.down));

    player.vy += DINO_GRAVITY * deltaFrames;
    player.vy = Math.min(player.vy, 16);
    player.y += player.vy * deltaFrames;
    const groundY = state.height - DINO_GROUND_PADDING - player.h;
    if (player.y >= groundY) {
        player.y = groundY;
        player.vy = 0;
        player.onGround = true;
    } else {
        player.onGround = false;
    }

    state.speed = DINO_SCROLL_BASE + Math.min(DINO_SCROLL_MAX_BONUS, (Math.floor(state.score) * 0.015));
    state.spawnFrames -= deltaFrames;
    if (state.spawnFrames <= 0) {
        state.obstacles.push(chatGameCreateDinoObstacle(state));
        const speedTighten = Math.min(24, Math.floor(state.score) * 0.02);
        state.spawnFrames = chatGameRandom(
            Math.max(30, DINO_SPAWN_FRAMES_MIN - speedTighten),
            Math.max(46, DINO_SPAWN_FRAMES_MAX - speedTighten),
        );
    }

    state.scrollX += state.speed * deltaFrames;
    let crashed = false;
    state.obstacles.forEach((obstacle) => {
        obstacle.x -= state.speed * deltaFrames;
        if (!obstacle.passed && (obstacle.x + obstacle.w) < player.x) {
            obstacle.passed = true;
            state.score += 1;
        }
        if (!crashed && chatGameDinoCollision(state, obstacle)) {
            crashed = true;
        }
    });
    state.obstacles = state.obstacles.filter((obstacle) => (obstacle.x + obstacle.w) >= -28);
    state.score += state.speed * deltaFrames * 0.11;

    scene.doorVisible = false;
    scene.doorOpen = 0;
    scene.light = 0;
    scene.botVisible = true;
    scene.botInside = false;
    scene.botDoorOffsetX = 0;
    scene.botRunning = player.onGround && !player.ducking;
    scene.botScale = player.ducking ? 0.9 : 1;
    scene.botRotate = player.onGround ? 0 : -8;
    scene.botJetpack = false;
    scene.botX = player.x;
    scene.botY = player.y;

    if (crashed) {
        state.mode = 'game_over';
        state.best = Math.max(state.best, Math.floor(state.score));
        chatGameSetHighScore(state.best, DINO_GAME_ID);
        player.vy = 0;
        scene.botRunning = false;
        scene.botScale = 1;
        scene.botRotate = 0;
        chatGameSetStatusText('Run ended. Space to run again | Esc to exit');
    }
}

function chatGameStepDinoGameOver(state, deltaFrames) {
    state.tick += deltaFrames;
    const scene = state.scene;
    const player = state.player;
    scene.doorVisible = false;
    scene.doorOpen = 0;
    scene.light = 0;
    scene.botVisible = true;
    scene.botRunning = false;
    scene.botInside = false;
    scene.botDoorOffsetX = 0;
    scene.botScale = 1;
    scene.botRotate = 0;
    scene.botJetpack = false;
    scene.botX = player.x;
    scene.botY = player.y + (Math.sin(state.tick * 0.08) * 0.5);
}

function chatGameStepDino(deltaFrames) {
    const state = chatGameRuntime.dinoRun;
    if (!state) return;
    const frames = Number.isFinite(deltaFrames) ? Math.max(0, deltaFrames) : 1;

    if (state.mode === 'intro') {
        chatGameStepDinoIntro(state, frames);
    } else if (state.mode === 'ready') {
        chatGameStepDinoReady(state, frames);
    } else if (state.mode === 'playing') {
        chatGameStepDinoPlaying(state, frames);
    } else if (state.mode === 'game_over') {
        chatGameStepDinoGameOver(state, frames);
    }
    chatGameUpdateHud(state);
    chatGameSyncScene(state);
}

function chatGameRenderDino() {
    if (!(composerDinoCanvas instanceof HTMLCanvasElement)) return;
    const ctx = composerDinoCanvas.getContext('2d');
    const state = chatGameRuntime.dinoRun;
    if (!ctx || !state) return;
    const width = state.width;
    const height = state.height;
    const groundY = state.height - DINO_GROUND_PADDING;

    ctx.clearRect(0, 0, width, height);

    ctx.strokeStyle = 'rgba(98, 188, 255, 0.9)';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, groundY);
    ctx.lineTo(width, groundY);
    ctx.stroke();

    const stripeStep = 24;
    const stripeOffset = (state.scrollX % stripeStep);
    ctx.fillStyle = 'rgba(193, 232, 255, 0.84)';
    for (let x = -stripeStep; x < width + stripeStep; x += stripeStep) {
        const drawX = Math.round(x - stripeOffset);
        ctx.fillRect(drawX, groundY + 4, 10, 2);
    }

    state.obstacles.forEach((obstacle) => {
        if (obstacle.type === 'drone') {
            ctx.fillStyle = 'rgba(83, 179, 248, 0.92)';
            ctx.fillRect(obstacle.x, obstacle.y + 3, obstacle.w, obstacle.h - 6);
            ctx.fillStyle = 'rgba(232, 247, 255, 0.94)';
            ctx.fillRect(obstacle.x + 4, obstacle.y + 5, Math.max(8, obstacle.w - 8), 4);
            ctx.fillStyle = 'rgba(255, 173, 104, 0.88)';
            ctx.fillRect(obstacle.x - 3, obstacle.y + (obstacle.h * 0.5) - 2, 3, 4);
            return;
        }
        ctx.fillStyle = 'rgba(66, 176, 246, 0.96)';
        ctx.fillRect(obstacle.x, obstacle.y, obstacle.w, obstacle.h);
        ctx.fillStyle = 'rgba(228, 246, 255, 0.92)';
        ctx.fillRect(obstacle.x + 2, obstacle.y + 2, Math.max(4, obstacle.w - 4), 3);
    });

    if (state.mode === 'game_over') {
        ctx.fillStyle = 'rgba(236, 246, 255, 0.88)';
        ctx.font = '700 14px "Segoe UI", sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Run Ended', width * 0.5, Math.max(28, height * 0.24));
    }
    chatGameSyncScene(state);
}

function chatGameStep(deltaFrames = 1) {
    const frames = Number.isFinite(deltaFrames) ? Math.max(0, deltaFrames) : 1;
    if (chatGameRuntime.activeGameId === 'cloud_jump') {
        chatGameStepCloudJump(frames);
    } else if (chatGameRuntime.activeGameId === JETPACK_GAME_ID) {
        chatGameStepJetpack(frames);
    } else if (chatGameRuntime.activeGameId === DINO_GAME_ID) {
        chatGameStepDino(frames);
    }
}

function chatGameRender() {
    if (chatGameRuntime.activeGameId === 'cloud_jump') {
        chatGameRenderCloudJump();
    } else if (chatGameRuntime.activeGameId === JETPACK_GAME_ID) {
        chatGameRenderJetpack();
    } else if (chatGameRuntime.activeGameId === DINO_GAME_ID) {
        chatGameRenderDino();
    }
}

function chatGameStartLoop() {
    chatGameStopLoop();
    const runFrame = (timestampMs) => {
        if (!chatGameRuntime.activeGameId) return;
        if (!chatGameRuntime.lastFrameMs) {
            chatGameRuntime.lastFrameMs = timestampMs;
        }
        const elapsedMs = Math.max(0, timestampMs - chatGameRuntime.lastFrameMs);
        chatGameRuntime.lastFrameMs = timestampMs;
        const deltaFrames = Math.min(2.8, Math.max(0.6, elapsedMs / (1000 / 60)));
        chatGameStep(deltaFrames);
        chatGameRender();
        chatGameRuntime.rafId = window.requestAnimationFrame(runFrame);
    };
    chatGameRuntime.rafId = window.requestAnimationFrame(runFrame);
}

function chatGameStopLoop() {
    if (chatGameRuntime.rafId) {
        window.cancelAnimationFrame(chatGameRuntime.rafId);
    }
    chatGameRuntime.rafId = 0;
    chatGameRuntime.lastFrameMs = 0;
}

function chatGameOpen(gameId = 'cloud_jump') {
    const gameKey = String(gameId || '').trim().toLowerCase();
    if (gameKey !== 'cloud_jump' && gameKey !== JETPACK_GAME_ID && gameKey !== DINO_GAME_ID) return;
    if (gameKey === DINO_GAME_ID && !(composerDinoCanvas instanceof HTMLCanvasElement)) return;
    if (gameKey !== DINO_GAME_ID && !(chatGameCanvas instanceof HTMLCanvasElement)) return;
    chatGameToggleHiddenCanvasPriority(true);
    chatGameRuntime.activeGameId = gameKey;
    chatGameRuntime.input.left = false;
    chatGameRuntime.input.right = false;
    chatGameRuntime.input.up = false;
    chatGameRuntime.input.down = false;
    chatGameRuntime.input.thrust = false;
    chatGameRuntime.cloudJump = null;
    chatGameRuntime.jetpackJoyride = null;
    chatGameRuntime.dinoRun = null;
    const isDino = gameKey === DINO_GAME_ID;
    chatGameSetPanelOpen(!isDino);
    chatGameSetDinoSurfaceOpen(isDino);
    if (chatGamePanel) {
        chatGamePanel.classList.toggle('jetpack-mode', gameKey === JETPACK_GAME_ID);
    }
    chatGameSetCenterMuted(gameKey === JETPACK_GAME_ID);
    if (gameKey === 'cloud_jump') {
        chatGameResetCloudJump();
    } else if (gameKey === JETPACK_GAME_ID) {
        chatGameResetJetpackJoyride();
    } else {
        chatGameResetDinoRun();
    }
    chatGameRender();
    chatGameStartLoop();
}

function chatGameClose({ clearMode = false } = {}) {
    chatGameStopLoop();
    chatGameToggleHiddenCanvasPriority(false);
    const closingGameId = chatGameRuntime.activeGameId || 'cloud_jump';
    chatGameRuntime.activeGameId = '';
    chatGameRuntime.cloudJump = null;
    chatGameRuntime.jetpackJoyride = null;
    chatGameRuntime.dinoRun = null;
    chatGameRuntime.input.left = false;
    chatGameRuntime.input.right = false;
    chatGameRuntime.input.up = false;
    chatGameRuntime.input.down = false;
    chatGameRuntime.input.thrust = false;
    chatGameSetPanelOpen(false);
    chatGameSetDinoSurfaceOpen(false);
    chatGameSetCenterMuted(false);
    chatGameSetPhaseClass('');
    if (chatGamePanel) {
        chatGamePanel.classList.remove('door-visible');
        chatGamePanel.classList.remove('jetpack-mode');
    }
    if (chatGameDoor) {
        chatGameDoor.style.removeProperty('--door-open');
        chatGameDoor.style.removeProperty('--door-light');
    }
    if (chatGameBotWrap) {
        chatGameBotWrap.classList.remove('visible', 'inside-door', 'is-running', 'dir-left', 'jetpack-on', 'dino-ride');
        delete chatGameBotWrap.dataset.agentId;
        delete chatGameBotWrap.dataset.agentName;
        if (chatGameLane instanceof HTMLElement && chatGameBotWrap.parentElement !== chatGameLane) {
            chatGameLane.appendChild(chatGameBotWrap);
        }
        chatGameBotWrap.style.left = '0px';
        chatGameBotWrap.style.top = '0px';
        chatGameBotWrap.style.bottom = 'auto';
        chatGameBotWrap.style.transform = 'translate3d(0px, 0px, 0px) rotate(0deg) scale(1)';
        chatGameBotWrap.style.removeProperty('--bot-rotate');
    }
    if (chatGameBot) {
        chatGameBot.classList.remove('looking-user');
        chatGameBot.classList.remove('costume-cap', 'costume-visor', 'costume-headset', 'costume-bowtie');
        chatGameBot.style.removeProperty('--agent-primary');
        chatGameBot.style.removeProperty('--agent-secondary');
        chatGameBot.style.removeProperty('--agent-glow');
        chatGameBot.style.removeProperty('--agent-trim');
    }
    if (chatGameBotName) {
        chatGameBotName.textContent = 'Office Bot';
        chatGameBotName.title = 'Office Bot';
    }
    const best = chatGameGetHighScore(closingGameId);
    if (chatGameScore) chatGameScore.textContent = '0';
    if (chatGameHighScore) chatGameHighScore.textContent = String(best);
    if (composerDinoScore) composerDinoScore.textContent = '0';
    if (composerDinoHighScore) composerDinoHighScore.textContent = String(chatGameGetHighScore(DINO_GAME_ID));
    chatGameSetStatusText('Press Space to start | Esc to exit');
    if (clearMode && safeString(composerModeSelection?.kind) === 'game') {
        composerClearMode({ closeGame: false });
    }
}

function chatGameRestartActive() {
    if (chatGameRuntime.activeGameId === 'cloud_jump') {
        chatGameResetCloudJump();
    } else if (chatGameRuntime.activeGameId === JETPACK_GAME_ID) {
        chatGameResetJetpackJoyride();
    } else if (chatGameRuntime.activeGameId === DINO_GAME_ID) {
        chatGameResetDinoRun();
    } else {
        return;
    }
    chatGameRender();
    chatGameStartLoop();
}

function chatGameRenderToTextPayload() {
    const panelOpen = Boolean(
        (chatGamePanel && !chatGamePanel.classList.contains('hidden'))
        || (composerDinoShell && !composerDinoShell.classList.contains('hidden')),
    );
    const activeGame = chatGameRuntime.activeGameId || 'none';
    const base = {
        coordinate_system: 'origin top-left; +x right; +y down',
        panel_open: panelOpen,
        active_game: activeGame,
    };
    if (activeGame === 'cloud_jump' && chatGameRuntime.cloudJump) {
        const state = chatGameRuntime.cloudJump;
        return JSON.stringify({
            ...base,
            mode: state.mode,
            score: Math.floor(state.score),
            high_score: Math.floor(state.best),
            door: {
                visible: Boolean(state.scene?.doorVisible),
                open: Number((state.scene?.doorOpen || 0).toFixed(3)),
                light: Number((state.scene?.light || 0).toFixed(3)),
            },
            selected_agent: {
                id: safeString(state.selectedAgent?.id),
                name: safeString(state.selectedAgent?.name),
                costume: safeString(state.selectedAgent?.costume),
                color: safeString(state.selectedAgent?.color),
            },
            bot: {
                visible: Boolean(state.scene?.botVisible),
                x: Number((state.scene?.botX || 0).toFixed(2)),
                y: Number((state.scene?.botY || 0).toFixed(2)),
                running: Boolean(state.scene?.botRunning),
            },
            player: {
                x: Number(state.player.x.toFixed(2)),
                y: Number(state.player.y.toFixed(2)),
                vx: Number(state.player.vx.toFixed(2)),
                vy: Number(state.player.vy.toFixed(2)),
                w: state.player.w,
                h: state.player.h,
            },
            platforms: state.platforms.slice(0, 14).map((platform) => ({
                x: Number(platform.x.toFixed(2)),
                y: Number(platform.y.toFixed(2)),
                w: platform.w,
                h: platform.h,
            })),
        });
    }
    if (activeGame === JETPACK_GAME_ID && chatGameRuntime.jetpackJoyride) {
        const state = chatGameRuntime.jetpackJoyride;
        return JSON.stringify({
            ...base,
            mode: state.mode,
            score: Math.floor(state.score),
            high_score: Math.floor(state.best),
            door: {
                visible: Boolean(state.scene?.doorVisible),
                open: Number((state.scene?.doorOpen || 0).toFixed(3)),
                light: Number((state.scene?.light || 0).toFixed(3)),
            },
            selected_agent: {
                id: safeString(state.selectedAgent?.id),
                name: safeString(state.selectedAgent?.name),
                costume: safeString(state.selectedAgent?.costume),
                color: safeString(state.selectedAgent?.color),
            },
            bot: {
                visible: Boolean(state.scene?.botVisible),
                x: Number((state.scene?.botX || 0).toFixed(2)),
                y: Number((state.scene?.botY || 0).toFixed(2)),
                running: Boolean(state.scene?.botRunning),
            },
            player: {
                x: Number(state.player.x.toFixed(2)),
                y: Number(state.player.y.toFixed(2)),
                vx: Number(state.player.vx.toFixed(2)),
                vy: Number(state.player.vy.toFixed(2)),
                w: state.player.w,
                h: state.player.h,
            },
            obstacles: state.obstacles.slice(0, 12).map((obstacle) => {
                if (obstacle.type === 'zapper') {
                    return {
                        type: 'zapper',
                        cx: Number((obstacle.cx || 0).toFixed(2)),
                        cy: Number((obstacle.cy || 0).toFixed(2)),
                        length: obstacle.length,
                        angle: Number((obstacle.angle || 0).toFixed(3)),
                    };
                }
                return {
                    type: obstacle.type,
                    x: Number((obstacle.x || 0).toFixed(2)),
                    y: Number((obstacle.y || 0).toFixed(2)),
                    w: obstacle.w,
                    h: obstacle.h,
                };
            }),
        });
    }
    if (activeGame === DINO_GAME_ID && chatGameRuntime.dinoRun) {
        const state = chatGameRuntime.dinoRun;
        return JSON.stringify({
            ...base,
            mode: state.mode,
            score: Math.floor(state.score),
            high_score: Math.floor(state.best),
            portal: {
                visible: Boolean(state.portal?.visible),
                x: Number((state.portal?.x || 0).toFixed(2)),
                y: Number((state.portal?.y || 0).toFixed(2)),
            },
            selected_agent: {
                id: safeString(state.selectedAgent?.id),
                name: safeString(state.selectedAgent?.name),
                costume: safeString(state.selectedAgent?.costume),
                color: safeString(state.selectedAgent?.color),
            },
            bot: {
                visible: Boolean(state.scene?.botVisible),
                x: Number((state.scene?.botX || 0).toFixed(2)),
                y: Number((state.scene?.botY || 0).toFixed(2)),
                running: Boolean(state.scene?.botRunning),
            },
            player: {
                x: Number(state.player.x.toFixed(2)),
                y: Number(state.player.y.toFixed(2)),
                vx: Number((state.player.vx || 0).toFixed(2)),
                vy: Number((state.player.vy || 0).toFixed(2)),
                w: state.player.w,
                h: state.player.h,
                ducking: Boolean(state.player.ducking),
            },
            obstacles: state.obstacles.slice(0, 12).map((obstacle) => ({
                type: obstacle.type,
                x: Number((obstacle.x || 0).toFixed(2)),
                y: Number((obstacle.y || 0).toFixed(2)),
                w: obstacle.w,
                h: obstacle.h,
            })),
        });
    }
    if (!chatGameRuntime.cloudJump && !chatGameRuntime.jetpackJoyride && !chatGameRuntime.dinoRun) {
        return JSON.stringify(base);
    }
    return JSON.stringify(base);
}

function chatGameAdvanceTime(ms = 16) {
    if (!chatGameRuntime.activeGameId) return;
    const totalMs = Number.isFinite(ms) ? Math.max(1, Number(ms)) : 16;
    const steps = Math.max(1, Math.round(totalMs / (1000 / 60)));
    for (let i = 0; i < steps; i += 1) {
        chatGameStep(1);
    }
    chatGameRender();
}

window.render_game_to_text = chatGameRenderToTextPayload;
window.advanceTime = chatGameAdvanceTime;

function chatGameHandleKeyInput(event, pressed) {
    if (!chatGameRuntime.activeGameId) return;
    const target = event.target;
    const targetIsInput = (
        target instanceof HTMLInputElement
        || target instanceof HTMLTextAreaElement
        || (target instanceof HTMLElement && target.isContentEditable)
    );
    if (targetIsInput) return;

    const key = String(event.key || '').toLowerCase();
    const activeGame = chatGameRuntime.activeGameId;

    if (activeGame === 'cloud_jump') {
        if (key === 'arrowleft' || key === 'a') {
            chatGameRuntime.input.left = pressed;
            event.preventDefault();
            return;
        }
        if (key === 'arrowright' || key === 'd') {
            chatGameRuntime.input.right = pressed;
            event.preventDefault();
            return;
        }
        if (key === ' ' || key === 'spacebar') {
            if (!pressed) return;
            event.preventDefault();
            const state = chatGameRuntime.cloudJump;
            if (state?.mode === 'ready') {
                chatGameStartRun(state);
                return;
            }
            if (state?.mode === 'game_over') {
                chatGameRestartActive();
            }
            return;
        }
    } else if (activeGame === JETPACK_GAME_ID) {
        if (key === 'arrowup' || key === 'w') {
            chatGameRuntime.input.up = pressed;
            event.preventDefault();
            return;
        }
        if (key === 'arrowdown' || key === 's') {
            chatGameRuntime.input.down = pressed;
            event.preventDefault();
            return;
        }
        if (key === ' ' || key === 'spacebar') {
            if (!pressed) return;
            event.preventDefault();
            const state = chatGameRuntime.jetpackJoyride;
            if (state?.mode === 'ready') {
                chatGameStartJetpackRun(state);
                return;
            }
            if (state?.mode === 'game_over') {
                chatGameRestartActive();
            }
            return;
        }
    } else if (activeGame === DINO_GAME_ID) {
        const dinoState = chatGameRuntime.dinoRun;
        const triggerDinoPrimary = () => {
            if (!dinoState) return;
            if (dinoState.mode === 'ready') {
                chatGameStartDinoRun(dinoState);
                return;
            }
            if (dinoState.mode === 'playing') {
                chatGameDinoJump(dinoState);
                return;
            }
            if (dinoState.mode === 'game_over') {
                chatGameRestartActive();
            }
        };

        if (key === 'arrowdown' || key === 's') {
            chatGameRuntime.input.down = pressed;
            event.preventDefault();
            return;
        }
        if (key === 'arrowup' || key === 'w') {
            chatGameRuntime.input.up = pressed;
            if (!pressed) return;
            event.preventDefault();
            triggerDinoPrimary();
            return;
        }
        if (key === ' ' || key === 'spacebar') {
            if (!pressed) return;
            event.preventDefault();
            triggerDinoPrimary();
            return;
        }
    }

    if (!pressed) return;
    if (key === 'r') {
        chatGameRestartActive();
        return;
    }
    if (key === 'escape') {
        chatGameClose({ clearMode: true });
    }
}

function initChatGame() {
    const best = chatGameGetHighScore();
    if (chatGameScore) chatGameScore.textContent = '0';
    if (chatGameHighScore) chatGameHighScore.textContent = String(best);
    if (composerDinoScore) composerDinoScore.textContent = '0';
    if (composerDinoHighScore) composerDinoHighScore.textContent = String(chatGameGetHighScore(DINO_GAME_ID));
    chatGameSetStatusText('Press Space to start | Esc to exit');
    chatGameSetPanelOpen(false);
    chatGameSetDinoSurfaceOpen(false);
    chatGameSetCenterMuted(false);
    chatGameSetPhaseClass('');
    if (chatGamePanel) {
        chatGamePanel.classList.remove('door-visible');
        chatGamePanel.classList.remove('jetpack-mode');
    }

    if (chatGameCloseBtn) {
        chatGameCloseBtn.addEventListener('click', () => {
            chatGameClose({ clearMode: true });
        });
    }
    if (chatGameRestartBtn) {
        chatGameRestartBtn.addEventListener('click', () => {
            chatGameRestartActive();
        });
    }

    document.addEventListener('keydown', (event) => {
        chatGameHandleKeyInput(event, true);
    });
    document.addEventListener('keyup', (event) => {
        chatGameHandleKeyInput(event, false);
    });
}

// 
//   ACTIONS & INTERACTIONS                                                 
//   Send/stop, file attach, chat search, keyboard shortcuts, streaming     
// 

function initActions() {
    function prepareManualSendFromComposer() {
        if (typeof window.__thomasStopMicCapture === 'function') {
            window.__thomasStopMicCapture({ send: false });
        }
    }

    sendBtn.addEventListener('click', () => {
        if (isGenerating) {
            const hasQueuedInput = composerTextarea.value.trim().length > 0 || pendingDocs.length > 0 || pendingImages.length > 0;
            if (hasQueuedInput) {
                prepareManualSendFromComposer();
                void handleSend();
            } else {
                // It's a stop button right now
                stopGeneration();
            }
        } else {
            prepareManualSendFromComposer();
            void handleSend();
        }
    });

    // Delegated click handlers for chat area (code copy + message copy)
    chatMessagesInner.addEventListener('click', (e) => {
        // Code block copy button
        const copyCodeBtn = e.target.closest('.code-block-copy');
        if (copyCodeBtn) {
            const wrapper = copyCodeBtn.closest('.code-block-wrapper');
            const code = wrapper ? wrapper.querySelector('code') : null;
            if (code) {
                navigator.clipboard.writeText(code.textContent).then(() => {
                    copyCodeBtn.innerHTML = '<i class="ph ph-check"></i> Copied';
                    showToast('Copied to clipboard');
                    setTimeout(() => { copyCodeBtn.innerHTML = '<i class="ph ph-copy"></i> Copy'; }, 2000);
                });
            }
            return;
        }
        // Message copy button
        const msgCopyBtn = e.target.closest('.msg-action-btn[data-action="copy"]');
        if (msgCopyBtn) {
            const row = msgCopyBtn.closest('.message-row');
            const content = row ? row.querySelector('.message-content') : null;
            if (content) {
                navigator.clipboard.writeText(content.innerText || content.textContent).then(() => {
                    showToast('Copied to clipboard');
                });
            }
            return;
        }
        // Edit user message button
        const msgEditBtn = e.target.closest('.msg-action-btn[data-action="edit"]');
        if (msgEditBtn) {
            const row = msgEditBtn.closest('.message-row');
            if (row) beginEditMessage(row);
            return;
        }
        // Regenerate assistant response button
        const msgRegenBtn = e.target.closest('.msg-action-btn[data-action="regenerate"]');
        if (msgRegenBtn) {
            const row = msgRegenBtn.closest('.message-row');
            if (row) regenerateResponse(row);
            return;
        }
        // Save edited message button
        const msgSaveBtn = e.target.closest('.msg-edit-save');
        if (msgSaveBtn) {
            const row = msgSaveBtn.closest('.message-row');
            if (row) commitEditMessage(row);
            return;
        }
        // Cancel edit button
        const msgCancelBtn = e.target.closest('.msg-edit-cancel');
        if (msgCancelBtn) {
            const row = msgCancelBtn.closest('.message-row');
            if (row) cancelEditMessage(row);
            return;
        }
        // Pin message button
        const msgPinBtn = e.target.closest('.msg-action-btn[data-action="pin"]');
        if (msgPinBtn) {
            const row = msgPinBtn.closest('.message-row');
            if (row) togglePinMessage(row);
            return;
        }
    });

    // Attachments
    attachBtn.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        composerToggleActionsMenu();
    });

    if (composerModeChipCloseBtn) {
        composerModeChipCloseBtn.addEventListener('click', (event) => {
            event.preventDefault();
            event.stopPropagation();
            composerClearMode();
            if (composerTextarea) {
                composerTextarea.focus();
            }
        });
    }

    if (composerActionList) {
        composerActionList.addEventListener('click', (event) => {
            if (!(event.target instanceof Element)) return;
            const button = event.target.closest('[data-action]');
            if (!(button instanceof HTMLButtonElement)) return;
            composerHandleQuickAction(button.dataset.action);
        });
    }
    if (composerGamesColumn) {
        composerGamesColumn.addEventListener('click', (event) => {
            if (!(event.target instanceof Element)) return;
            const button = event.target.closest('[data-game]');
            if (!(button instanceof HTMLButtonElement)) return;
            composerHandleGameChoice(button.dataset.game);
        });
    }
    document.addEventListener('click', (event) => {
        if (!composerActionsOpen) return;
        if (!(event.target instanceof Element)) return;
        if (event.target.closest('#attachBtn')) return;
        if (event.target.closest('#composerActionPopover')) return;
        composerCloseActionsMenu();
    });
    // Microphone
    let recognition = null;
    let micShouldListen = false;
    let micIsListening = false;
    let micPendingSend = false;
    let micSuppressTranscriptUntil = 0;
    let micBaseText = '';
    let micFinalText = '';

    function suppressMicTranscript(ms = 1200) {
        micSuppressTranscriptUntil = Date.now() + Math.max(0, Number(ms) || 0);
    }

    function joinSpeechText(leftRaw, rightRaw) {
        const left = safeString(leftRaw).trim();
        const right = safeString(rightRaw).trim();
        if (!right) return left;
        if (!left) return right;
        const needsSpace = !/\s$/.test(left) && !/^[,.;:!?)]/.test(right);
        return needsSpace ? `${left} ${right}` : `${left}${right}`;
    }

    function renderMicTranscript(interimRaw = '') {
        if (!micShouldListen && !micIsListening) return;
        if (Date.now() < micSuppressTranscriptUntil || Date.now() < composerInputLockUntil) return;
        const spokenText = joinSpeechText(micFinalText, interimRaw);
        composerTextarea.value = joinSpeechText(micBaseText, spokenText);
        composerTextarea.dispatchEvent(new Event('input'));
    }

    function resetMicDraftState() {
        micBaseText = '';
        micFinalText = '';
    }

    function flushPendingMicSend() {
        if (!micPendingSend) return;
        micPendingSend = false;
        suppressMicTranscript();
        resetMicDraftState();
        void handleSend();
    }

    function stopMicCapture({ send = false } = {}) {
        if (!recognition) return;
        micShouldListen = false;
        micPendingSend = Boolean(send);
        if (!micIsListening) {
            micBtn.style.color = 'var(--text-secondary)';
            flushPendingMicSend();
            return;
        }
        try {
            recognition.stop();
        } catch {
            micIsListening = false;
            micBtn.style.color = 'var(--text-secondary)';
            flushPendingMicSend();
        }
    }

    function startMicCapture() {
        if (!recognition || micShouldListen || micIsListening) return;
        resetMicDraftState();
        micBaseText = safeString(composerTextarea.value);
        micPendingSend = false;
        micShouldListen = true;
        try {
            recognition.start();
        } catch {
            micShouldListen = false;
            micIsListening = false;
            micBtn.style.color = 'var(--text-secondary)';
            notifyUser('Unable to start microphone capture right now.', {
                tone: 'warning',
                debugKind: 'warning',
                durationMs: 2800,
            });
        }
    }
    window.__thomasStopMicCapture = ({ send = false } = {}) => {
        stopMicCapture({ send });
        suppressMicTranscript(2200);
        resetMicDraftState();
    };

    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') {
            // Close any open overlays/modals/popovers
            const thinkDrop = document.getElementById('thinkingEffortDropdown');
            if (thinkDrop && !thinkDrop.classList.contains('hidden')) {
                thinkDrop.classList.add('hidden');
                return;
            }
            if (settingsModal && !settingsModal.classList.contains('hidden')) {
                settingsModal.classList.add('hidden');
                return;
            }
            if (easySetupModal && !easySetupModal.classList.contains('hidden')) {
                easySetupModal.classList.add('hidden');
                if (easySetupBackdrop) easySetupBackdrop.classList.add('hidden');
                return;
            }
            // Stop generation if running
            if (isGenerating) {
                stopGeneration();
                return;
            }
            composerCloseActionsMenu();
        }
        // Ctrl+Shift+N  new chat
        if ((event.ctrlKey || event.metaKey) && event.shiftKey && event.key === 'N') {
            event.preventDefault();
            if (typeof startNewSession === 'function') startNewSession();
        }
        // Ctrl+F  in-chat search
        if ((event.ctrlKey || event.metaKey) && !event.shiftKey && event.key === 'f') {
            // Only override Ctrl+F when chat area is visible
            const chatVisible = chatScrollArea && !chatScrollArea.classList.contains('hidden');
            if (chatVisible) {
                event.preventDefault();
                toggleChatSearch();
            }
        }
        // Ctrl+Shift+E  export conversation
        if ((event.ctrlKey || event.metaKey) && event.shiftKey && event.key === 'E') {
            event.preventDefault();
            exportChatConversation();
        }
        if (
            event.key === 'End'
            && !event.ctrlKey
            && !event.metaKey
            && !event.altKey
            && !event.shiftKey
            && (micShouldListen || micIsListening)
        ) {
            event.preventDefault();
            stopMicCapture({ send: true });
        }
    });

    docFileInput.addEventListener('change', async (e) => {
        composerCloseActionsMenu();
        for (const file of e.target.files) {
            if (file.type.startsWith('image/')) {
                const reader = new FileReader();
                reader.onload = (re) => {
                    pendingImages.push({ data_url: re.target.result, name: file.name });
                    renderAttachmentsPreview();
                    composerSyncSendButtonState();
                };
                reader.readAsDataURL(file);
            } else {
                const text = await file.text();
                pendingDocs.push({ name: file.name, text: text });
                renderAttachmentsPreview();
                composerSyncSendButtonState();
            }
        }
        docFileInput.value = ''; // reset
        composerSyncSendButtonState();
    });

    if ('SpeechRecognition' in window || 'webkitSpeechRecognition' in window) {
        const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        recognition = new SpeechRecognition();
        recognition.continuous = true;
        recognition.interimResults = true;

        recognition.onstart = () => {
            micIsListening = true;
            micBtn.style.color = 'var(--danger-ink)';
        };

        recognition.onresult = (e) => {
            let interimText = '';
            for (let i = e.resultIndex; i < e.results.length; i += 1) {
                const result = e.results[i];
                const transcript = safeString(result?.[0]?.transcript).trim();
                if (!transcript) continue;
                if (result.isFinal) {
                    micFinalText = joinSpeechText(micFinalText, transcript);
                } else {
                    interimText = joinSpeechText(interimText, transcript);
                }
            }
            renderMicTranscript(interimText);
        };

        recognition.onend = () => {
            micIsListening = false;
            if (micShouldListen) {
                try {
                    recognition.start();
                    return;
                } catch {
                    micShouldListen = false;
                }
            }
            micBtn.style.color = 'var(--text-secondary)';
            flushPendingMicSend();
        };

        recognition.onerror = (e) => {
            micIsListening = false;
            if (safeString(e?.error) === 'not-allowed' || safeString(e?.error) === 'service-not-allowed') {
                micShouldListen = false;
                micPendingSend = false;
                notifyUser('Microphone permission was denied.', {
                    tone: 'warning',
                    debugKind: 'warning',
                    durationMs: 2800,
                });
            }
            micBtn.style.color = 'var(--text-secondary)';
        };
    }

    micBtn.addEventListener('click', () => {
        if (recognition) {
            if (micShouldListen || micIsListening) {
                stopMicCapture({ send: false });
            } else {
                startMicCapture();
            }
        } else {
            notifyUser("Speech recognition isn't supported in this browser.", {
                tone: 'warning',
                debugKind: 'warning',
                durationMs: 2800,
            });
        }
    });

    // Suggestion chips
    document.querySelectorAll('.suggestion-chip').forEach(btn => {
        btn.addEventListener('click', (e) => {
            composerTextarea.value = e.currentTarget.innerText.trim();
            composerTextarea.dispatchEvent(new Event('input')); // trigger resize and enable button
            composerTextarea.focus();
        });
    });

    if (assistantSuggestionDismissBtn) {
        assistantSuggestionDismissBtn.addEventListener('click', () => {
            hideAssistantSuggestions();
        });
    }
}

/**
 * Execute the send flow
 */
function buildSendJobFromComposer(textRaw = '') {
    const text = safeString(textRaw).trim();
    const docsToSend = [...pendingDocs];
    const imagesToSend = [...pendingImages];
    const modeId = safeString(composerModeSelection?.id).toLowerCase();
    const modeLabel = safeString(composerModeSelection?.label);
    const modeKind = safeString(composerModeSelection?.kind);
    const modePromptPrefix = safeString(composerModeSelection?.promptPrefix);
    if (!text && docsToSend.length === 0 && imagesToSend.length === 0 && modeId !== 'evolve') return null;
    const clientMessageId = `u-${Date.now()}-${Math.floor(Math.random() * 100000)}`;

    composerTextarea.value = '';
    composerTextarea.dispatchEvent(new Event('input'));
    pendingDocs = [];
    pendingImages = [];
    renderAttachmentsPreview();

    const suggestionUserContext = [
        safeString(text),
        docsToSend.length > 0 ? `Attached ${docsToSend.length} document(s)` : '',
        imagesToSend.length > 0 ? `Attached ${imagesToSend.length} image(s)` : '',
    ].filter(Boolean).join(' | ');
    return {
        text,
        docsToSend,
        imagesToSend,
        suggestionUserContext,
        clientMessageId,
        composerModeId: modeId,
        composerModeLabel: modeLabel,
        composerModeKind: modeKind,
        composerModePromptPrefix: modePromptPrefix,
    };
}

async function drainQueuedSends() {
    if (isGenerating || queuedSendDrainActive || pendingSendQueue.length === 0) return;
    queuedSendDrainActive = true;
    try {
        while (!isGenerating && pendingSendQueue.length > 0) {
            const next = pendingSendQueue.shift();
            if (!next) continue;
            await runChatSendJob(next);
        }
    } finally {
        queuedSendDrainActive = false;
        composerSyncSendButtonState();
    }
}

async function runEvolveMissionJob(sendJob, { profile = '', modelId = '' } = {}) {
    const goal = safeString(sendJob?.text).trim();
    const chatSessionId = safeString(sessionId || activeChatId);
    const payload = {
        kind: 'evolve_session',
        name: goal ? `Evolve: ${goal.slice(0, 48)}` : 'Evolve Thomas',
        goal,
        prompt: goal,
        profile: safeString(profile),
        model_id: safeString(modelId),
        session_id: chatSessionId,
        passes: 1,
        promote_on_pass: false,
    };
    const res = await fetch('/api/mission/jobs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
    });
    if (!res.ok) {
        const details = await res.text();
        throw new Error(details || `HTTP ${res.status}`);
    }
    const created = await res.json();
    const job = created?.job || {};
    const jobId = safeString(job.id) || `${Date.now()}`;
    const jobName = safeString(job.name) || safeString(payload.name) || 'Evolve Thomas';
    const assistantMessageId = `mission-evolve-queued-${jobId}`;
    const assistantContent = `${jobName} is running in the background.

I'll reply here when it finishes. Mission Control is available from the left sidebar if you want live details.

Green-side evolve mode is syncing blue -> green, running a self-improvement pass, and verifying before any promotion.`;
    if (appendAssistantChatHistoryMessage(assistantContent, assistantMessageId)) {
        syncActiveChatSidebarEntry();
        void persistActiveChat({ quiet: true });
    }
    composerClearMode();
    notifyUser(`${jobName} queued.`, {
        tone: 'success',
        durationMs: 1900,
        debugKind: 'mission-job',
    });
    void refreshTaskContinuity({ sessionOverride: chatSessionId, force: true });
    void missionRefresh({ force: true, silent: true });
}

async function runChatSendJob(sendJob) {
    const text = safeString(sendJob?.text).trim();
    const docsToSend = Array.isArray(sendJob?.docsToSend) ? sendJob.docsToSend : [];
    const imagesToSend = Array.isArray(sendJob?.imagesToSend) ? sendJob.imagesToSend : [];
    const suggestionUserContext = safeString(sendJob?.suggestionUserContext);
    const queuedModeId = safeString(sendJob?.composerModeId).toLowerCase();
    const clientMessageId = safeString(sendJob?.clientMessageId) || `u-${Date.now()}-${Math.floor(Math.random() * 100000)}`;
    if (!text && docsToSend.length === 0 && imagesToSend.length === 0 && queuedModeId !== 'evolve') return;

    if (safeString(suggestionContext) !== 'onboarding') {
        hideAssistantSuggestions({ force: true });
    }
    if (safeString(text)) {
        officeMaybeQueueTaskFromPrompt(text, 'chat');
    }

    if (welcomeScreen && !welcomeScreen.classList.contains('hidden')) {
        welcomeScreen.classList.add('hidden');
        chatScrollArea.classList.remove('hidden');
    }

    // Build user message content once for both display and history.
    let userContent = safeString(text);
    if (docsToSend.length > 0) userContent += `\n\n*(Attached ${docsToSend.length} document(s))*`;
    if (imagesToSend.length > 0) userContent += `\n\n*(Attached ${imagesToSend.length} image(s))*`;
    userContent = userContent || (queuedModeId === 'evolve' ? '(Evolve Thomas)' : '(Sent Attachments)');

    // Skip rendering if already shown when queued
    if (!sendJob._alreadyRendered) {
        const existingUserRow = document.getElementById(clientMessageId);
        if (!existingUserRow) {
            renderMessage({ role: 'user', content: userContent, id: clientMessageId });
        }
    }
    if (!safeString(activeChatId)) {
        activeChatId = safeString(sessionId) || `chat-${Date.now()}`;
    }
    chatHistory.push({
        id: clientMessageId,
        role: 'user',
        content: userContent,
        createdAt: Date.now(),
        status: 'complete',
        toolCalls: [],
    });
    syncActiveChatSidebarEntry();
    void persistActiveChat({ quiet: true });

    const sendMode = {
        id: safeString(sendJob?.composerModeId).toLowerCase(),
        label: safeString(sendJob?.composerModeLabel),
        kind: safeString(sendJob?.composerModeKind),
        promptPrefix: safeString(sendJob?.composerModePromptPrefix),
    };
    let finalPrompt = setupPersonalitySelector.value;
    if (finalPrompt === 'custom') {
        finalPrompt = setupCustomPrompt.value.trim();
    }

    const selectedProfile = modelSelector.value || setupProviderSelector.value;
    const studioChatContext = typeof moduleStudioBuildChatContext === 'function' ? moduleStudioBuildChatContext() : { enabled: false, preferredProfile: '', context: {} };
    const preferredProfile = safeString(studioChatContext.preferredProfile);
    const resolvedProfile = preferredProfile || selectedProfile;
    if (preferredProfile && preferredProfile !== safeString(selectedProfile) && typeof applyProfileSelection === 'function') {
        applyProfileSelection(preferredProfile);
    }
    if (sendMode.id === 'evolve') {
        try {
            await runEvolveMissionJob(sendJob, { profile: resolvedProfile, modelId: resolveActiveModelIdForProfile(resolvedProfile) || '' });
        } catch (error) {
            console.error('Evolve mission launch failed', error);
            notifyUser(`Failed to launch evolve mode: ${safeString(error?.message) || 'unknown error'}`, {
                tone: 'warning',
                durationMs: 2600,
                debugKind: 'mission-job',
            });
        }
        return;
    }

    setGeneratingState(true);
    pushDebugEvent('chat', 'Started chat request');

    const modelMessage = composerBuildMessageForModel(text, sendMode);
    const requestedMode = normalizeChatMode(activeChatMode) || 'auto';
    const fastMode = requestedMode !== 'thinking';
    const payload = {
        message: modelMessage || text,
        docs: docsToSend,
        images: imagesToSend,
        session_id: sessionId,
        profile: resolvedProfile,
        model: resolvedProfile,
        model_id: resolveActiveModelIdForProfile(resolvedProfile) || undefined,
        mode: requestedMode,
        autonomy_level: autonomyLevelManuallySet ? activeAutonomyLevel : 1,
        token_economy: activeTokenEconomy,
        reasoning_effort: normalizeReasoningEffort(activeReasoningEffort) || undefined,
        system_prompt: finalPrompt || undefined,
        fast_mode: fastMode,
    };
    if (studioChatContext.enabled) {
        payload.asset_studio_mode = 'comfy_studio';
        payload.asset_studio_context = studioChatContext.context || {};
    }

    await streamChatResponse(payload, { userContext: suggestionUserContext });
}

async function handleSend() {
    composerCloseActionsMenu();
    const text = composerTextarea.value.trim();
    if (!text && pendingDocs.length === 0 && pendingImages.length === 0) return;
    composerInputLockUntil = Date.now() + 1600;

    if (isOnboardingSlashCommand(text) && pendingDocs.length === 0 && pendingImages.length === 0) {
        composerTextarea.value = '';
        composerTextarea.dispatchEvent(new Event('input'));
        ensureChatVisible();
        renderMessage({ role: 'user', content: text });
        renderMessage({ role: 'assistant', content: 'Opening Easy Setup. We will verify your connection before setup continues.' });
        openEasySetup({ source: 'slash', force: true });
        return;
    }

    if (!isOnboardingComplete()) {
        if (easySetupState.interviewStarted) {
            const docsToSend = [...pendingDocs];
            const imagesToSend = [...pendingImages];
            composerTextarea.value = '';
            composerTextarea.dispatchEvent(new Event('input'));
            pendingDocs = [];
            pendingImages = [];
            renderAttachmentsPreview();
            ensureChatVisible();

            let uiText = text;
            if (docsToSend.length > 0) uiText += `\n\n*(Attached ${docsToSend.length} document(s))*`;
            if (imagesToSend.length > 0) uiText += `\n\n*(Attached ${imagesToSend.length} image(s))*`;
            if (safeString(uiText)) {
                renderMessage({ role: 'user', content: uiText });
            }

            await handleOnboardingChatInput(text, {
                docsCount: docsToSend.length,
                imagesCount: imagesToSend.length,
            });
            return;
        }

        composerTextarea.value = '';
        composerTextarea.dispatchEvent(new Event('input'));
        pendingDocs = [];
        pendingImages = [];
        renderAttachmentsPreview();
        ensureChatVisible();
        if (safeString(text)) {
            renderMessage({ role: 'user', content: text });
        }
        if (isSecurityTrustConcern(text)) {
            renderMessage({
                role: 'assistant',
                content: `${buildSetupSafetyMessage()}\n\nFinish Easy Setup first, then I can run normal chat tasks.`,
            });
            showSetupSafetySuggestions();
        } else {
            renderMessage({
                role: 'assistant',
                content: withAgentName('Finish Easy Setup first. {{agent}} requires setup before chat can run.'),
            });
        }
        openEasySetup({ source: 'mandatory', force: false, restart: false });
        return;
    }

    const sendJob = buildSendJobFromComposer(text);
    if (!sendJob) return;
    if (isGenerating) {
        // FIX (2026-03-18): Don't abort the current generation when user
        // sends a new message. Instead, send it as an interrupt to the backend
        // so Thomas can keep working while the user keeps chatting.
        // The backend queues the message and the active run picks it up.
        const interruptPayload = {
            text: text,
            session_id: sessionId,
            profile: currentProfile || '',
            busy_strategy: 'interrupt',
        };
        // Render user message immediately
        renderMessage({ role: 'user', content: text });
        chatHistory.push({
            role: 'user',
            content: text,
            createdAt: Date.now(),
            status: 'complete',
        });
        // Fire and forget — don't block, don't abort current stream
        const chatEndpoint = window.__THOMAS_CHAT_V2__ ? '/api/v2/chat' : '/api/chat';
        fetch(chatEndpoint, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(interruptPayload),
        }).catch(err => console.warn('[Thomas] Interrupt send failed:', err));
        // Clear composer
        composerTextarea.value = '';
        composerTextarea.dispatchEvent(new Event('input'));
        composerSyncSendButtonState();
        return;
    }

    await runChatSendJob(sendJob);
}

