function normalizeNavMode(modeRaw) {
    const mode = safeString(modeRaw).toLowerCase();
    if (mode === 'search' || mode === 'office' || mode === 'mission' || mode === 'content') return mode;
    if (MODULE_NAV_MODE_SET.has(mode)) return mode;
    return 'chat';
}

function moduleSeed(modeRaw) {
    const mode = safeString(modeRaw).toLowerCase();
    if (MODULE_MODE_SEEDS[mode]) return MODULE_MODE_SEEDS[mode];
    const plugin = moduleInstalledPluginForMode(mode);
    if (plugin) {
        return {
            title: safeString(plugin?.display_name) || 'Installed Plugin',
            subtitle: safeString(plugin?.subtitle) || safeString(plugin?.description) || 'Installed plugin surface.',
            pill: 'Plugin',
            kpis: [],
            actions: [],
        };
    }
    return MODULE_MODE_SEEDS.dashboard;
}

function moduleModeSurface(modeRaw) {
    const mode = safeString(modeRaw).toLowerCase();
    if (MODULE_MODE_SURFACES[mode]) return MODULE_MODE_SURFACES[mode];
    if (moduleInstalledPluginForMode(mode)) {
        return { layout: 'catalog', sections: [] };
    }
    return MODULE_MODE_SURFACES.dashboard;
}

function moduleSectionIcon(sectionLabelRaw) {
    const key = safeString(sectionLabelRaw).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
    if (MODULE_SECTION_ICONS[key]) return MODULE_SECTION_ICONS[key];
    return 'ph-dot-outline';
}

function moduleEnsureRuntime() {
    if (!moduleWorkspace) return null;
    if (!moduleState) {
        moduleState = {
            controlsBound: false,
            timerId: 0,
            activeMode: 'dashboard',
            lastRenderedMode: '',
            modeEnterTimer: 0,
            triageFilters: {},
            subnavFocus: {},
            workbenchMode: '',
            workbench: {},
            hidden: {},
            activity: {},
            refreshedAt: {},
            marketplace: {
                apps: [],
                modules: [],
                plugins: [],
                categories: [],
                generatedAt: '',
                loading: false,
                error: '',
                search: '',
                filter: 'all',
                lastRefreshedAt: 0,
                refreshPromise: null,
            },
        };
    }
    return moduleState;
}

function moduleEnsureHiddenBucket(mode, section) {
    const state = moduleEnsureRuntime();
    if (!state) return null;
    if (!state.hidden[mode]) {
        state.hidden[mode] = {
            queue: new Set(),
            health: new Set(),
            triage: new Set(),
        };
    }
    if (!state.hidden[mode][section]) {
        state.hidden[mode][section] = new Set();
    }
    return state.hidden[mode][section];
}

function moduleHideItem(mode, section, itemId) {
    const id = safeString(itemId);
    if (!id) return;
    const bucket = moduleEnsureHiddenBucket(mode, section);
    if (bucket) bucket.add(id);
}

function moduleIsItemHidden(mode, section, itemId) {
    const id = safeString(itemId);
    if (!id) return false;
    const bucket = moduleEnsureHiddenBucket(mode, section);
    return Boolean(bucket && bucket.has(id));
}

function moduleVisibleItems(mode, section, rowsRaw) {
    const rows = Array.isArray(rowsRaw) ? rowsRaw : [];
    return rows.filter((row) => !moduleIsItemHidden(mode, section, row?.id));
}

function moduleToneClass(toneRaw) {
    const tone = safeString(toneRaw).toLowerCase();
    if (tone === 'ok' || tone === 'success' || tone === 'live') return 'ok';
    if (tone === 'warn' || tone === 'warning' || tone === 'watch') return 'warn';
    if (tone === 'error' || tone === 'danger' || tone === 'critical') return 'error';
    if (tone === 'done' || tone === 'complete') return 'done';
    return '';
}

function moduleTouch(mode) {
    const state = moduleEnsureRuntime();
    if (!state) return;
    state.refreshedAt[mode] = Date.now();
}

function moduleRecordActivity(mode, title, tone = 'ok') {
    const state = moduleEnsureRuntime();
    if (!state) return;
    if (!Array.isArray(state.activity[mode])) {
        state.activity[mode] = [];
    }
    const badge = tone === 'error' ? 'Alert' : (tone === 'warn' ? 'Update' : 'Action');
    state.activity[mode].unshift({
        id: `act-${Date.now()}-${Math.round(Math.random() * 10_000)}`,
        title: safeString(title) || 'Action completed.',
        meta: 'just now',
        badge,
        tone,
    });
    if (state.activity[mode].length > 14) {
        state.activity[mode] = state.activity[mode].slice(0, 14);
    }
}

function moduleBuildSnapshot() {
    const missionPayload = missionState?.lastPayload && typeof missionState.lastPayload === 'object'
        ? missionState.lastPayload
        : {};
    const jobsPayload = missionState?.lastJobsPayload && typeof missionState.lastJobsPayload === 'object'
        ? missionState.lastJobsPayload
        : {};
    const contentPayload = contentState?.payload && typeof contentState.payload === 'object'
        ? contentState.payload
        : contentEmptyPayload();
    const summary = contentPayload?.summary && typeof contentPayload.summary === 'object'
        ? contentPayload.summary
        : {};
    const controlSurface = contentPayload?.control_surface && typeof contentPayload.control_surface === 'object'
        ? contentPayload.control_surface
        : {};
    const approvals = missionPayload?.approvals && typeof missionPayload.approvals === 'object'
        ? missionPayload.approvals
        : {};

    return {
        missionPayload,
        jobs: Array.isArray(jobsPayload?.jobs) ? jobsPayload.jobs : [],
        events: Array.isArray(missionPayload?.events) ? missionPayload.events : [],
        agents: Array.isArray(missionPayload?.agents) ? missionPayload.agents : [],
        platforms: Array.isArray(contentPayload?.platforms) ? contentPayload.platforms : [],
        workflows: Array.isArray(contentPayload?.workflows) ? contentPayload.workflows : [],
        scheduler: Array.isArray(contentPayload?.scheduler) ? contentPayload.scheduler : [],
        tools: Array.isArray(contentPayload?.tools) ? contentPayload.tools : [],
        healthChecks: Array.isArray(controlSurface?.health_checks) ? controlSurface.health_checks : [],
        summary,
        controlSurface,
        totals: missionPayload?.totals && typeof missionPayload.totals === 'object' ? missionPayload.totals : {},
        approvalsAutonomy: Array.isArray(approvals?.autonomy) ? approvals.autonomy : [],
        approvalsGuardrails: Array.isArray(approvals?.guardrails) ? approvals.guardrails : [],
        approvalsPending: contentToCount(
            missionPayload?.totals?.approvals_pending,
            contentToCount(approvals?.pending_total, 0),
        ),
        sessions: Array.isArray(sidebarSessions) ? sidebarSessions : [],
        spend: spendState?.payload && typeof spendState.payload === 'object' ? spendState.payload : {},
        goalStats: goalsState?.payload && typeof goalsState.payload === 'object' ? goalsState.payload : {},
        marketplace: moduleGetMarketplaceState(),
    };
}
function moduleGetMarketplaceState() {
    const state = moduleEnsureRuntime();
    if (!state || !state.marketplace || typeof state.marketplace !== 'object') {
        return {
            apps: [],
            modules: [],
            loading: false,
            error: '',
            lastRefreshedAt: 0,
            refreshPromise: null,
        };
    }
    return {
        apps: Array.isArray(state.marketplace.apps) ? state.marketplace.apps : [],
        modules: Array.isArray(state.marketplace.modules) ? state.marketplace.modules : [],
        loading: Boolean(state.marketplace.loading),
        error: safeString(state.marketplace.error),
        lastRefreshedAt: Number(state.marketplace.lastRefreshedAt) || 0,
        refreshPromise: state.marketplace.refreshPromise || null,
    };
}


function moduleFetchJsonSafe(url, options = {}) {
    const normalizedUrl = safeString(url);
    if (!normalizedUrl) {
        return Promise.reject(new Error('Missing request URL'));
    }
    return fetch(normalizedUrl, {
        headers: {
            Accept: 'application/json',
            ...(options.headers || {}),
        },
        ...options,
    }).then(async (response) => {
        const text = await response.text();
        let payload = null;
        if (text) {
            try {
                payload = JSON.parse(text);
            } catch {
                payload = null;
            }
        }
        if (!response.ok) {
            const message = safeString(payload?.error) || safeString(payload?.message) || text || `${response.status} ${response.statusText}`;
            const err = new Error(message || 'Request failed');
            err.status = response.status;
            throw err;
        }
        return payload;
    });
}

function moduleParseVersionParts(versionRaw) {
    const raw = safeString(versionRaw).replace(/^\s*v/i, '');
    const matches = String(raw || '').match(/\d+/g) || [];
    const parts = matches.slice(0, 3).map((part) => {
        const n = Number.parseInt(part, 10);
        return Number.isFinite(n) ? n : 0;
});
    while (parts.length < 3) {
        parts.push(0);
    }
    return parts;
}

function moduleIsVersionNewer(candidateRaw, currentRaw) {
    const candidate = moduleParseVersionParts(candidateRaw);
    const current = moduleParseVersionParts(currentRaw);
    for (let i = 0; i < 3; i += 1) {
        const c = Number.isFinite(candidate[i]) ? candidate[i] : 0;
        const p = Number.isFinite(current[i]) ? current[i] : 0;
        if (c > p) return true;
        if (c < p) return false;
    }
    return false;
}

function moduleMarketplaceSectionId(value) {
    const section = safeString(value).toLowerCase();
    if (!section || section === 'all') return 'all';
    if (section === 'templates' || section === 'template') return 'templates';
    if (section === 'agents' || section === 'agent') return 'agents';
    if (section === 'apps' || section === 'app' || section === 'tools') return 'apps';
    return 'featured';
}

function moduleMarketplaceGuessSection(appRaw = {}, moduleId = '', title = '', description = '') {
    const hints = [
        safeString(appRaw?.section),
        safeString(appRaw?.category),
        safeString(appRaw?.kind),
        safeString(appRaw?.type),
        safeString(appRaw?.module_type),
        safeString(moduleId),
        safeString(title),
        safeString(description),
    ];
    const blob = hints.join(' ').toLowerCase();
    if (/(template|workflow|prompt|playbook|preset)/.test(blob)) return 'templates';
    if (/(agent|assistant|operator|crew|bot)/.test(blob)) return 'agents';
    if (/(integration|tool|connector|plugin|utility|app)/.test(blob)) return 'apps';
    return 'featured';
}

function moduleMarketplaceSectionLabel(sectionRaw = 'featured') {
    const section = safeString(sectionRaw).toLowerCase();
    if (section === 'templates') return 'Templates';
    if (section === 'agents') return 'Agents';
    if (section === 'apps') return 'Apps';
    return 'Featured';
}

function moduleLatestReleaseVersion(appRaw) {
    const app = appRaw && typeof appRaw === 'object' ? appRaw : {};
    const release = app?.latest_release && typeof app.latest_release === 'object' ? app.latest_release : {};
    return safeString(release?.module_version || app?.module_version || app?.version);
}

function moduleBuildMarketplaceInstalledMap(modulesRaw = []) {
    const modules = Array.isArray(modulesRaw) ? modulesRaw : [];
    const out = {};
    modules.forEach((row) => {
        const moduleId = safeString(row?.module_id);
        if (!moduleId) return;
        out[moduleId] = {
            module_id: moduleId,
            display_name: safeString(row?.display_name) || moduleId,
            description: safeString(row?.description),
            version: safeString(row?.version),
            status: safeString(row?.status).toLowerCase(),
            installed_at: safeString(row?.installed_at),
            updated_at: safeString(row?.updated_at),
        };
    });
    return out;
}

function moduleRefreshMarketplace({ force = false } = {}) {
    const state = moduleEnsureRuntime();
    if (!state) return null;
    const now = Date.now();
    if (!force && state.marketplace.refreshPromise) {
        return state.marketplace.refreshPromise;
    }
    if (
        !force &&
        Number(state.marketplace.lastRefreshedAt) > 0 &&
        now - Number(state.marketplace.lastRefreshedAt) < MODULE_MARKETPLACE_REFRESH_TTL_MS &&
        Array.isArray(state.marketplace.apps)
    ) {
        return null;
    }
    state.marketplace.loading = true;
    state.marketplace.error = '';
    const refreshPromise = (async () => {
        try {
            const [catalogPayload, installedPayload] = await Promise.all([
                moduleFetchJsonSafe('/api/marketplace/plugins?limit=600'),
                moduleFetchJsonSafe('/api/marketplace/installed'),
            ]);
            const plugins = Array.isArray(catalogPayload?.plugins) ? catalogPayload.plugins : [];
            const installedPlugins = Array.isArray(installedPayload?.plugins) ? installedPayload.plugins : [];
            installedPlugins.forEach((plugin) => {
                const modeId = safeString(plugin?.mode_id).toLowerCase();
                if (modeId) MODULE_NAV_MODE_SET.add(modeId);
            });
            state.marketplace.generatedAt = safeString(catalogPayload?.generated_at);
            state.marketplace.categories = Array.isArray(catalogPayload?.categories) ? catalogPayload.categories : [];
            state.marketplace.plugins = installedPlugins.map((plugin) => ({
                ...plugin,
                plugin_id: safeString(plugin?.plugin_id),
                mode_id: safeString(plugin?.mode_id),
                display_name: safeString(plugin?.display_name),
                subtitle: safeString(plugin?.subtitle),
                description: safeString(plugin?.description),
                icon: safeString(plugin?.icon),
                surface_url: safeString(plugin?.surface_url),
                surface_mode: safeString(plugin?.surface_mode),
                surface_title: safeString(plugin?.surface_title),
                version: safeString(plugin?.version),
                enabled: Boolean(plugin?.enabled),
                installed_at: safeString(plugin?.installed_at),
                updated_at: safeString(plugin?.updated_at),
                publisher_id: safeString(plugin?.publisher_id),
                publisher_name: safeString(plugin?.publisher_name),
            })).filter((plugin) => plugin.plugin_id && plugin.mode_id);
            state.marketplace.modules = state.marketplace.plugins.map((plugin) => ({
                module_id: plugin.plugin_id,
                display_name: plugin.display_name,
                description: plugin.description || plugin.subtitle,
                version: plugin.version,
                status: plugin.enabled ? 'enabled' : 'disabled',
                installed_at: plugin.installed_at,
                updated_at: plugin.updated_at,
            }));
            state.marketplace.apps = plugins.map((plugin) => {
                const categoryId = safeString(plugin?.category).toLowerCase() || 'other';
                const categoryLabel = safeString(plugin?.category_label) || safeString(plugin?.category) || 'Plugin';
                const target = safeString(plugin?.target);
                const mode = safeString(plugin?.mode);
                const downloadUrl = safeString(plugin?.download_url);
                const downloadAvailable = Boolean(plugin?.download_available || downloadUrl);
                return {
                    module_id: safeString(plugin?.id),
                    display_name: safeString(plugin?.display_name || plugin?.name) || safeString(plugin?.id) || 'Marketplace item',
                    subtitle: safeString(plugin?.subtitle),
                    description: safeString(plugin?.description) || 'No description available.',
                    section: 'apps',
                    kind: safeString(plugin?.kind) || 'extension_pack',
                    type: 'plugin',
                    category: categoryLabel,
                    category_id: categoryId,
                    category_label: categoryLabel,
                    target,
                    mode,
                    mode_id: safeString(plugin?.mode_id),
                    entrypoint: safeString(plugin?.entrypoint),
                    tags: [categoryLabel, target, mode].filter(Boolean),
                    requirements: [],
                    capabilities: Array.isArray(plugin?.capabilities) ? plugin.capabilities : [],
                    version: safeString(plugin?.version),
                    latest_release: { module_version: safeString(plugin?.version) },
                    install: {
                        install_endpoint: safeString(plugin?.install_url),
                        uninstall_endpoint: safeString(plugin?.uninstall_url),
                        enable_endpoint: safeString(plugin?.enable_url),
                        disable_endpoint: safeString(plugin?.disable_url),
                        release_manifest_endpoint: downloadUrl,
                        release_download_endpoint: downloadUrl,
                        repo_url: safeString(plugin?.source) || 'extensions/catalog.json',
                    },
                    download_available: downloadAvailable,
                    installable: Boolean(plugin?.installable),
                    installed: Boolean(plugin?.installed),
                    enabled: Boolean(plugin?.enabled),
                    surface_url: safeString(plugin?.surface_url),
                    surface_mode: safeString(plugin?.surface_mode),
                    surface_title: safeString(plugin?.surface?.title || plugin?.surface_title),
                    icon: safeString(plugin?.icon),
                    compatibility: { eligible: Boolean(plugin?.installable || downloadAvailable) },
                    publisher: safeString(plugin?.publisher_name || plugin?.publisher_id || plugin?.source) || 'extensions/catalog.json',
                    publisher_id: safeString(plugin?.publisher_id),
                    publisher_name: safeString(plugin?.publisher_name),
                };
            }).filter((plugin) => safeString(plugin?.module_id));
            state.marketplace.error = '';
            moduleRenderInstalledPluginNav();
        } catch (error) {
            state.marketplace.error = safeString(error?.message) || 'Unable to refresh marketplace catalog.';
            if (!Array.isArray(state.marketplace.apps)) state.marketplace.apps = [];
            if (!Array.isArray(state.marketplace.modules)) state.marketplace.modules = [];
            if (!Array.isArray(state.marketplace.plugins)) state.marketplace.plugins = [];
            moduleRenderInstalledPluginNav();
        } finally {
            state.marketplace.loading = false;
            state.marketplace.refreshPromise = null;
            state.marketplace.lastRefreshedAt = Date.now();
        }
    })();
    state.marketplace.refreshPromise = refreshPromise;
    return refreshPromise;
}

async function moduleInstallMarketplacePlugin(moduleIdRaw, payload = {}) {
    const moduleId = safeString(moduleIdRaw);
    if (!moduleId) {
        return { ok: false, error: 'Missing module id.' };
    }
    try {
        const result = await moduleFetchJsonSafe(`/api/marketplace/plugins/${encodeURIComponent(moduleId)}/install`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload || {}),
        });
        return { ok: Boolean(result?.ok), data: result, plugin: result?.plugin || null };
    } catch (error) {
        return { ok: false, error: safeString(error?.message) || 'Unable to install plugin.' };
    }
}

async function moduleInstallMarketplacePluginFromDeepLink(deepLinkRaw) {
    const deepLink = safeString(deepLinkRaw);
    if (!deepLink) {
        return { ok: false, error: 'Missing plugin install link.' };
    }
    try {
        const result = await moduleFetchJsonSafe('/api/marketplace/install-from-deep-link', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ deep_link: deepLink }),
        });
        return { ok: Boolean(result?.ok), data: result, plugin: result?.plugin || null, request: result?.request || null };
    } catch (error) {
        return { ok: false, error: safeString(error?.message) || 'Unable to install plugin from Thomas link.' };
    }
}

async function moduleUninstallMarketplacePlugin(moduleIdRaw) {
    const moduleId = safeString(moduleIdRaw);
    if (!moduleId) {
        return { ok: false, error: 'Missing module id.' };
    }
    try {
        const result = await moduleFetchJsonSafe(`/api/marketplace/plugins/${encodeURIComponent(moduleId)}/uninstall`, { method: 'POST' });
        return { ok: Boolean(result?.ok), data: result };
    } catch (error) {
        return { ok: false, error: safeString(error?.message) || 'Unable to uninstall plugin.' };
    }
}

async function moduleSetMarketplacePluginEnabled(moduleIdRaw, enabled = false) {
    const moduleId = safeString(moduleIdRaw);
    if (!moduleId) {
        return { ok: false, error: 'Missing module id.' };
    }
    const action = enabled ? 'enable' : 'disable';
    try {
        const result = await moduleFetchJsonSafe(`/api/marketplace/plugins/${encodeURIComponent(moduleId)}/${action}`, { method: 'POST' });
        return { ok: Boolean(result?.ok), data: result, plugin: result?.plugin || null };
    } catch (error) {
        return { ok: false, error: safeString(error?.message) || 'Unable to update plugin state.' };
    }
}

async function moduleImportMarketplacePlugin(file) {
    if (!(file instanceof File)) {
        return { ok: false, error: 'Pick a plugin ZIP first.' };
    }
    const formData = new FormData();
    formData.append('file', file, file.name || 'plugin.zip');
    try {
        const response = await fetch('/api/marketplace/import', {
            method: 'POST',
            body: formData,
        });
        const text = await response.text();
        let payload = {};
        if (text) {
            try {
                payload = JSON.parse(text);
            } catch {
                payload = {};
            }
        }
        if (!response.ok) {
            throw new Error(safeString(payload?.error) || text || 'Unable to import plugin.');
        }
        return { ok: Boolean(payload?.ok), data: payload, plugin: payload?.plugin || null };
    } catch (error) {
        return { ok: false, error: safeString(error?.message) || 'Unable to import plugin.' };
    }
}

function moduleBuildMarketplaceRows(snapshot, { limit = 10, section = 'all', search = '' } = {}) {
    const apps = Array.isArray(snapshot?.marketplace?.apps) ? snapshot.marketplace.apps : [];
    const modules = Array.isArray(snapshot?.marketplace?.modules) ? snapshot.marketplace.modules : [];
    const installedById = moduleBuildMarketplaceInstalledMap(modules);
    const seen = new Set();
    const rows = [];
    const targetSection = moduleMarketplaceSectionId(section);
    const searchText = safeString(search).trim().toLowerCase();
    const hasSearch = searchText.length > 0;
    const hasSectionFilter = safeString(targetSection).toLowerCase() !== 'all';
    const normalizeList = (raw) => {
        const list = Array.isArray(raw) ? raw : [];
        const out = [];
        list.forEach((item) => {
            const value = safeString(item);
            if (!value) return;
            const lower = value.toLowerCase();
            if (!out.includes(lower)) out.push(lower);
        });
        return out;
    };
    const addRow = (row) => {
        if (!row?.id) return;
        const rowSection = safeString(row?.section || row?.sectionLabel);
        if (hasSectionFilter && rowSection.toLowerCase() !== targetSection) return;
        if (hasSearch) {
            const text = [
                row?.id,
                row?.title,
                row?.description,
                row?.sectionLabel,
                row?.statusLabel,
                row?.source,
                row?.meta,
                ...(Array.isArray(row?.tags) ? row.tags : []),
                ...(Array.isArray(row?.requirements) ? row.requirements : []),
                ...(Array.isArray(row?.capabilities) ? row.capabilities : []),
            ].filter(Boolean).join(' ').toLowerCase();
            if (!text.includes(searchText)) return;
        }
        rows.push(row);
    };
    apps.forEach((app, index) => {
        const moduleId = safeString(app?.module_id);
        if (!moduleId || seen.has(moduleId)) return;
        const installed = installedById[moduleId];
        const installedVersion = safeString(installed?.version);
        const latestVersion = moduleLatestReleaseVersion(app);
        const appInstall = app?.install && typeof app.install === 'object' ? app.install : {};
        const manifestUrl = safeString(appInstall?.release_manifest_endpoint);
        const downloadUrl = safeString(appInstall?.release_download_endpoint);
        const compatibility = app?.compatibility && typeof app.compatibility === 'object' ? app.compatibility : {};
        const eligibleRaw = compatibility?.eligible;
        const eligible = safeString(eligibleRaw).toLowerCase() !== 'false' && eligibleRaw !== false;
        const isInstalled = Boolean(installed);
        const isEnabled = isInstalled && safeString(installed?.status).toLowerCase() === 'enabled';
        const needsUpdate = isInstalled && latestVersion && installedVersion && moduleIsVersionNewer(latestVersion, installedVersion);
        const title = safeString(app?.display_name) || safeString(app?.module_id) || safeString(app?.name) || `module-${index + 1}`;
        const description = safeString(app?.description) || safeString(app?.summary) || safeString(app?.blurb) || 'No description available.';
        const sectionHint = safeString(app?.section) || safeString(app?.kind) || safeString(app?.type);
        const sectionId = sectionHint
            ? moduleMarketplaceSectionId(sectionHint)
            : moduleMarketplaceGuessSection(app, moduleId, title, description);
        const source = safeString(app?.publisher) || safeString(app?.author) || safeString(app?.owner) || safeString(appInstall?.repo_url) || safeString(app?.repo_url);
        const tags = normalizeList(app?.tags);
        const requirements = normalizeList(app?.requirements);
        const capabilities = normalizeList(app?.capabilities);
        const statusBits = [];
        if (!eligible) statusBits.push('Incompatible with this session');
        if (installedVersion) statusBits.push(`Installed ${installedVersion}`);
        if (latestVersion) statusBits.push(`Latest ${latestVersion}`);
        if (needsUpdate) statusBits.push('Update available');
        if (source) statusBits.push(`Source ${source}`);
        const tone = needsUpdate ? 'warn' : (isInstalled ? (isEnabled ? 'ok' : 'warn') : (eligible ? 'ok' : 'error'));
        const badge = isInstalled ? (isEnabled ? 'installed' : 'disabled') : (eligible ? 'available' : 'blocked');
        const statusLabel = isInstalled ? (isEnabled ? 'Enabled' : 'Disabled') : (eligible ? 'Available' : 'Blocked');
        const actions = [];
        if (isInstalled) {
            actions.push({
                id: isEnabled ? 'disable' : 'enable',
                label: isEnabled ? 'Disable' : 'Enable',
            });
        } else if (eligible && (manifestUrl || downloadUrl)) {
            actions.push({
                id: 'install',
                label: 'Install',
                actionUrl: downloadUrl || manifestUrl || source,
            });
        }
        if (manifestUrl || downloadUrl || source) {
        actions.push({
            id: needsUpdate ? 'latest' : 'latest',
            label: needsUpdate ? 'Update' : 'Details',
            actionUrl: manifestUrl || downloadUrl || source,
        });
        }
        addRow({
            id: moduleId,
            section: sectionId,
            sectionLabel: moduleMarketplaceSectionLabel(sectionId),
            title,
            meta: statusBits.slice(0, 4).join(' | '),
            description,
            badge,
            tone,
            statusLabel,
            installedVersion,
            latestVersion,
            needsUpdate,
            eligible,
            isInstalled,
            isEnabled,
            source,
            tags,
            requirements,
            capabilities,
            actions,
        });
        seen.add(moduleId);
    });
    modules.forEach((module) => {
        const moduleId = safeString(module?.module_id);
        if (!moduleId || seen.has(moduleId)) return;
        const status = safeString(module?.status).toLowerCase();
        const version = safeString(module?.version);
        const title = safeString(module?.display_name) || moduleId;
        const enabled = status === 'enabled';
        const sectionId = moduleMarketplaceGuessSection(module, moduleId, title, safeString(module?.description));
        const description = safeString(module?.description) || safeString(module?.meta) || 'Installed module from local runtime.';
        const requirements = normalizeList(module?.requirements);
        const capabilities = normalizeList(module?.capabilities);
        addRow({
            id: moduleId,
            section: sectionId,
            sectionLabel: moduleMarketplaceSectionLabel(sectionId),
            title,
            meta: version ? `Installed ${version}` : 'Installed locally',
            description,
            badge: enabled ? 'installed' : 'disabled',
            tone: enabled ? 'ok' : 'warn',
            statusLabel: enabled ? 'Enabled' : 'Disabled',
            installedVersion: version,
            needsUpdate: false,
            eligible: true,
            isInstalled: true,
            isEnabled: enabled,
            requirements,
            capabilities,
            actions: [{
                id: enabled ? 'disable' : 'enable',
                label: enabled ? 'Disable' : 'Enable',
            }],
        });
        seen.add(moduleId);
    });
    rows.sort((a, b) => safeString(a?.section).localeCompare(safeString(b?.section)) || safeString(a?.title).localeCompare(safeString(b?.title)));
    if (limit <= 0) {
        return rows;
    }
    const safeLimit = Math.max(1, Number(limit) || 0);
    return rows.slice(0, safeLimit);
}

function moduleEventSort(eventsRaw = []) {
    return [...eventsRaw].sort((a, b) => missionToEpoch(b?.ts) - missionToEpoch(a?.ts));
}

function moduleEventNarrative(event) {
    const text = safeString(event?.text);
    const source = safeString(event?.source).replace(/_/g, ' ');
    if (text) return text;
    if (source) return source;
    return 'No details provided.';
}

function moduleEventTags(event) {
    const text = `${safeString(event?.type)} ${safeString(event?.source)} ${safeString(event?.text)}`.toLowerCase();
    const tags = new Set();

    if (/(inbox|email|dm|sms|message|thread|reply|respond|follow[ -]?up)/.test(text)) {
        tags.add('inbox');
        tags.add('needs_reply');
    }
    if (/(urgent|critical|p1|sev1|outage|failed|error|blocked|dead|down|panic)/.test(text)) {
        tags.add('urgent');
        tags.add('critical');
        tags.add('errors');
        tags.add('high');
    }
    if (/(approval|approve|guardrail|review|escalat)/.test(text)) {
        tags.add('approvals');
        tags.add('high');
    }
    if (/(newsletter|digest|bulletin|broadcast)/.test(text)) {
        tags.add('newsletter');
        tags.add('fyi');
        tags.add('low');
    }
    if (/(receipt|invoice|payment|subscription|finance|budget|spend)/.test(text)) {
        tags.add('receipts');
        tags.add('finance');
    }
    if (/(workflow|flow|automation|cron|job|run)/.test(text)) {
        tags.add('workflows');
        tags.add('automations');
    }
    if (/(integrat|connector|webhook|oauth|token|scope|api key)/.test(text)) {
        tags.add('integrations');
    }
    if (/(build|deploy|ci|test|pr|issue|repo|commit|code)/.test(text)) {
        tags.add('dev');
    }
    if (/(video|audio|image|render|asset|studio|thumbnail|caption)/.test(text)) {
        tags.add('studio');
    }
    if (/(game|playtest|unity|unreal|godot|npc|level)/.test(text)) {
        tags.add('game');
    }
    if (/(3d|cad|print|mesh|slicer|stl|obj)/.test(text)) {
        tags.add('lab_3d');
    }
    if (/(research|citation|source|brief|analysis|competitor|pdf)/.test(text)) {
        tags.add('research');
    }
    if (/(people|contact|client|vendor|relationship)/.test(text)) {
        tags.add('people');
    }
    if (/(device|mobile|handoff|offline|voice|camera|push|companion)/.test(text)) {
        tags.add('infinite');
    }
    if (/(warn|degrad|retry|delay|pending)/.test(text)) {
        tags.add('high');
    }

    if (!tags.has('critical') && !tags.has('high') && !tags.has('low')) {
        tags.add('normal');
    }
    if (!tags.size) {
        tags.add('fyi');
        tags.add('normal');
    }
    return tags;
}

function moduleEventTone(tags) {
    if (tags.has('critical') || tags.has('errors')) return 'error';
    if (tags.has('urgent') || tags.has('high')) return 'warn';
    return 'ok';
}

function moduleBuildEventRows(eventsRaw = [], { limit = 8, includeTags = [] } = {}) {
    const filters = includeTags.map((tag) => safeString(tag).toLowerCase()).filter(Boolean);
    const rows = [];
    moduleEventSort(eventsRaw).forEach((event, index) => {
        const tags = moduleEventTags(event);
        if (filters.length && !filters.some((tag) => tags.has(tag))) {
            return;
        }
        const typeLabel = safeString(event?.type).replace(/_/g, ' ') || 'event';
        const sourceLabel = safeString(event?.source).replace(/_/g, ' ') || 'signal';
        rows.push({
            id: `event-${missionToEpoch(event?.ts) || Date.now()}-${index}`,
            title: typeLabel,
            meta: `${moduleEventNarrative(event)} | ${missionRelativeTime(event?.ts)}`,
            badge: sourceLabel,
            tone: moduleEventTone(tags),
            tags: Array.from(tags),
            actions: [{ id: 'open', label: 'Open' }, { id: 'ack', label: 'Acknowledge' }],
        });
    });
    return rows.slice(0, Math.max(1, limit));
}

function moduleBuildJobRows(jobsRaw = [], { limit = 8, recurring = null, keyword = '' } = {}) {
    const keywordLower = safeString(keyword).toLowerCase();
    const rows = [];
    const jobs = [...jobsRaw].sort((a, b) => {
        const byStatus = missionJobStatusRank(a?.status) - missionJobStatusRank(b?.status);
        if (byStatus !== 0) return byStatus;
        return missionToEpoch(b?.updated_at) - missionToEpoch(a?.updated_at);
    });
    jobs.forEach((job, index) => {
        const descriptor = missionScheduleDescriptor(job);
        if (typeof recurring === 'boolean' && descriptor.recurring !== recurring) return;
        const summary = missionJobSummary(job);
        const name = safeString(job?.name) || safeString(job?.id) || 'Mission job';
        const searchText = `${name} ${summary} ${safeString(job?.kind)}`.toLowerCase();
        if (keywordLower && !searchText.includes(keywordLower)) return;
        const status = missionStatusValue(job?.status);
        const tone = (status === 'failed' || status === 'dead' || status === 'cancelled')
            ? 'error'
            : (status === 'awaiting_approval' || status === 'blocked' ? 'warn' : 'ok');
        rows.push({
            id: safeString(job?.id) || `job-${index}`,
            title: name,
            meta: `${summary} | ${descriptor.cadence} | ${descriptor.next === '--' ? 'next --' : `next ${descriptor.next}`}`,
            badge: descriptor.recurring ? 'cron' : 'task',
            tone,
            actions: [{ id: 'open', label: 'Open' }, { id: 'done', label: 'Done' }],
        });
    });
    return rows.slice(0, Math.max(1, limit));
}

function moduleBuildApprovalRows(snapshot, { limit = 8 } = {}) {
    const rows = [];
    snapshot.approvalsAutonomy.forEach((item, index) => {
        const action = item?.action && typeof item.action === 'object' ? item.action : {};
        rows.push({
            id: safeString(item?.id) || `approval-auto-${index}`,
            title: safeString(action?.title || action?.tool_name || item?.id) || 'Autonomy approval',
            meta: `${safeString(action?.summary) || safeString(item?.decision_reason) || 'Approval required'} | requested ${missionRelativeTime(item?.requested_at)}`,
            badge: 'approval',
            tone: 'warn',
            tags: ['approvals', 'high'],
            actions: [{ id: 'open', label: 'Open' }, { id: 'ack', label: 'Acknowledge' }],
        });
    });
    snapshot.approvalsGuardrails.forEach((item, index) => {
        const tool = safeString(item?.tool_name) || 'tool';
        rows.push({
            id: safeString(item?.tool_call_id || item?.run_id) || `approval-guard-${index}`,
            title: `Tool approval: ${tool}`,
            meta: `${safeString(item?.reason) || 'Guardrails requested review'} | requested ${missionRelativeTime(item?.requested_at)}`,
            badge: 'guardrails',
            tone: 'warn',
            tags: ['approvals', 'high'],
            actions: [{ id: 'open', label: 'Open' }, { id: 'ack', label: 'Acknowledge' }],
        });
    });
    return rows.slice(0, Math.max(1, limit));
}

function moduleBuildAgentRows(agentsRaw = [], { limit = 8 } = {}) {
    return [...agentsRaw]
        .sort((a, b) => missionStatusRank(a?.status) - missionStatusRank(b?.status))
        .slice(0, Math.max(1, limit))
        .map((agent, index) => {
            const status = missionStatusValue(agent?.status);
            const tone = (status === 'failed' || status === 'dead' || status === 'cancelled')
                ? 'error'
                : (status === 'blocked' || status === 'awaiting_approval' ? 'warn' : 'ok');
            const room = safeString(agent?.room) || 'unassigned';
            return {
                id: safeString(agent?.id) || `agent-${index}`,
                title: safeString(agent?.name) || `Agent ${index + 1}`,
                meta: `${safeString(agent?.summary) || 'No summary'} | room ${room} | ${missionRelativeTime(agent?.updated_at)}`,
                badge: missionStatusLabel(status),
                tone,
                actions: [{ id: 'open', label: 'Open' }, { id: 'done', label: 'Done' }],
            };
        });
}

function moduleBuildPlatformRows(platformsRaw = [], { limit = 8 } = {}) {
    return [...platformsRaw]
        .slice(0, Math.max(1, limit))
        .map((platform, index) => {
            const connected = contentPlatformConnected(platform);
            const name = safeString(platform?.name) || `platform-${index + 1}`;
            const queued = contentToCount(platform?.queued);
            const running = contentToCount(platform?.running);
            const failed = contentToCount(platform?.failed);
            return {
                id: name.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
                title: name,
                meta: `${connected ? 'connected' : 'not connected'} | queued ${queued} | running ${running} | failed ${failed}`,
                badge: connected ? 'connected' : 'offline',
                tone: connected ? (failed > 0 ? 'warn' : 'ok') : 'error',
                actions: [{ id: 'open', label: 'Open' }, { id: connected ? 'done' : 'reconnect', label: connected ? 'Done' : 'Reconnect' }],
            };
        });
}

function moduleBuildWorkflowRows(workflowsRaw = [], { limit = 8 } = {}) {
    return [...workflowsRaw]
        .slice(0, Math.max(1, limit))
        .map((workflow, index) => {
            const name = safeString(workflow?.name) || `workflow-${index + 1}`;
            const trigger = safeString(workflow?.trigger) || 'trigger';
            const approval = safeString(workflow?.approval) || 'no approval policy';
            const active = contentToCount(workflow?.active_jobs);
            const total = contentToCount(workflow?.total_jobs);
            return {
                id: name.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
                title: name,
                meta: `${trigger} | ${approval} | ${active} active / ${total} total`,
                badge: 'workflow',
                tone: active > 0 ? 'ok' : '',
                actions: [{ id: 'open', label: 'Open' }, { id: 'done', label: 'Done' }],
            };
        });
}

function moduleBuildSchedulerRows(scheduleRaw = [], { limit = 8 } = {}) {
    return [...scheduleRaw]
        .slice(0, Math.max(1, limit))
        .map((item, index) => {
            const runAt = safeString(item?.run_at);
            const day = safeString(item?.day) || contentFormatScheduleDay(runAt);
            const time = safeString(item?.time) || contentFormatScheduleTime(runAt);
            const platform = safeString(item?.platform || item?.channel) || 'all channels';
            const type = safeString(item?.type || item?.workflow) || 'scheduled content';
            const status = safeString(item?.status) || 'queued';
            const tone = /failed|error|cancel/i.test(status) ? 'error' : (/await|pending/i.test(status) ? 'warn' : 'ok');
            return {
                id: `scheduler-${index}-${platform}`.toLowerCase().replace(/[^a-z0-9-]+/g, '-'),
                title: `${day} ${time} - ${platform}`,
                meta: `${type} | ${status}`,
                badge: 'schedule',
                tone,
                actions: [{ id: 'open', label: 'Open' }, { id: 'done', label: 'Done' }],
            };
        });
}

function moduleBuildToolRows(toolsRaw = [], { limit = 8 } = {}) {
    return [...toolsRaw]
        .slice(0, Math.max(1, limit))
        .map((tool, index) => {
            const name = safeString(tool?.name) || safeString(tool?.label) || `tool-${index + 1}`;
            const detail = safeString(tool?.description || tool?.detail || tool?.summary) || 'No detail';
            const status = safeString(tool?.status) || '';
            const tone = /fail|error|down|offline/i.test(status)
                ? 'error'
                : (/warn|degrad|pending/i.test(status) ? 'warn' : 'ok');
            return {
                id: name.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
                title: name,
                meta: status ? `${detail} | ${status}` : detail,
                badge: 'tool',
                tone,
                actions: [{ id: 'open', label: 'Open' }, { id: 'done', label: 'Done' }],
            };
        });
}

function moduleBuildHealthRows(snapshot, { limit = 8 } = {}) {
    const rows = [];
    const runStore = Boolean(snapshot.missionPayload?.engine?.run_store_enabled);
    const autonomy = Boolean(snapshot.missionPayload?.engine?.autonomy_enabled);
    rows.push({
        id: 'health-engine',
        title: 'Autonomy engine',
        meta: `run-store ${runStore ? 'on' : 'off'} | autonomy ${autonomy ? 'on' : 'off'}`,
        badge: autonomy ? 'online' : 'limited',
        tone: autonomy ? 'ok' : 'warn',
        actions: [{ id: 'open', label: 'Open' }],
    });
    snapshot.healthChecks.forEach((check, index) => {
        const name = safeString(check?.name) || `health-${index + 1}`;
        const status = safeString(check?.status) || 'unknown';
        const detail = safeString(check?.detail) || 'No detail';
        const tone = /fail|error|down|offline/i.test(status)
            ? 'error'
            : (/warn|degrad|pending/i.test(status) ? 'warn' : 'ok');
        rows.push({
            id: `health-check-${index}`,
            title: name,
            meta: `${detail} | ${status}`,
            badge: 'check',
            tone,
            actions: [{ id: 'open', label: 'Open' }, { id: 'ack', label: 'Acknowledge' }],
        });
    });
    if (!snapshot.healthChecks.length) {
        rows.push(...moduleBuildPlatformRows(snapshot.platforms, { limit: 3 }));
    }
    return rows.slice(0, Math.max(1, limit));
}

function moduleBuildContactContextRows(snapshot) {
    return [
        {
            id: 'contact-sessions',
            title: 'Recent chat session context',
            meta: `${snapshot.sessions.length} sessions currently available in chat history`,
            badge: 'context',
            tone: snapshot.sessions.length > 0 ? 'ok' : 'warn',
            actions: [{ id: 'open', label: 'Open' }],
        },
        {
            id: 'contact-approvals',
            title: 'Open commitments requiring approval',
            meta: `${snapshot.approvalsPending} approvals currently waiting`,
            badge: 'commitments',
            tone: snapshot.approvalsPending > 0 ? 'warn' : 'ok',
            actions: [{ id: 'open', label: 'Open' }],
        },
    ];
}

function moduleCollectSignals(snapshot = moduleBuildSnapshot()) {
    const marketplaceApps = Array.isArray(snapshot.marketplace?.apps) ? snapshot.marketplace.apps : [];
    const marketplaceModules = Array.isArray(snapshot.marketplace?.modules) ? snapshot.marketplace.modules : [];
    const marketplaceInstalledById = moduleBuildMarketplaceInstalledMap(marketplaceModules);
    const cronJobs = snapshot.jobs.filter((job) => missionScheduleDescriptor(job).recurring).length;
    const taskJobs = Math.max(0, snapshot.jobs.length - cronJobs);
    const connected = snapshot.platforms.filter((platform) => contentPlatformConnected(platform)).length;
    const known = contentToCount(snapshot.summary?.known_platforms, snapshot.platforms.length);
    const degraded = Math.max(0, known - connected);
    const workflows = contentToCount(snapshot.summary?.workflows, snapshot.workflows.length);
    const scheduleRows = snapshot.scheduler.length;
    const toolsCount = snapshot.tools.length;
    const vibeStats = vibeCodeCollectStats();

    let inboxUnread = 0;
    let inboxUrgent = 0;
    let inboxNeedsReply = 0;
    let inboxNewsletters = 0;
    let notifCritical = 0;
    let notifHigh = 0;
    let notifNormal = 0;
    let financeSignals = 0;
    let researchSignals = 0;
    let gameSignals = 0;
    let labSignals = 0;
    let infiniteSignals = 0;

    snapshot.events.forEach((event) => {
        const tags = moduleEventTags(event);
        if (tags.has('inbox') || tags.has('needs_reply') || tags.has('newsletter') || tags.has('receipts')) inboxUnread += 1;
        if (tags.has('urgent')) inboxUrgent += 1;
        if (tags.has('needs_reply')) inboxNeedsReply += 1;
        if (tags.has('newsletter')) inboxNewsletters += 1;
        if (tags.has('critical')) notifCritical += 1;
        if (tags.has('high')) notifHigh += 1;
        if (tags.has('normal') || tags.has('low')) notifNormal += 1;
        if (tags.has('finance')) financeSignals += 1;
        if (tags.has('research')) researchSignals += 1;
        if (tags.has('game')) gameSignals += 1;
        if (tags.has('lab_3d')) labSignals += 1;
        if (tags.has('infinite')) infiniteSignals += 1;
    });

    return {
        task_jobs: taskJobs + (snapshot.goalStats?.open_n || 0) + (snapshot.goalStats?.ip_n || 0),
        cron_jobs: cronJobs,
        approvals_pending: snapshot.approvalsPending,
        integrations_connected: connected,
        integrations_degraded: degraded,
        integrations_reconnects: degraded,
        connectors_total: known,
        flow_active: workflows,
        flow_failures: snapshot.jobs.filter((job) => {
            const status = missionStatusValue(job?.status);
            return status === 'failed' || status === 'dead' || status === 'cancelled';
        }).length,
        flow_approvals: snapshot.approvalsPending,
        webhook_rate: snapshot.events.filter((event) => moduleEventTags(event).has('integrations')).length,
        inbox_unread: inboxUnread,
        inbox_urgent: inboxUrgent,
        inbox_needs_reply: inboxNeedsReply,
        inbox_newsletters: inboxNewsletters,
        notif_rules: snapshot.healthChecks.length,
        notif_bundled: notifNormal,
        notif_escalations: notifCritical,
        notif_muted: 0,
        agent_active: snapshot.agents.filter((agent) => {
            const status = missionStatusValue(agent?.status);
            return status === 'running' || status === 'active';
        }).length,
        agent_delegated: snapshot.agents.length,
        agent_approval_only: snapshot.approvalsPending,
        agent_escalations: snapshot.agents.filter((agent) => missionStatusValue(agent?.status) === 'blocked').length,
        render_queue: scheduleRows,
        exports_today: snapshot.events.filter((event) => moduleEventTags(event).has('studio')).length,
        brand_kits: 0,
        assets_total: 0,
        dev_pr_open: snapshot.events.filter((event) => moduleEventTags(event).has('dev')).length,
        dev_failures: snapshot.jobs.filter((job) => missionStatusValue(job?.status) === 'failed').length,
        deploys_today: snapshot.events.filter((event) => /deploy|release/.test(`${safeString(event?.type)} ${safeString(event?.text)}`.toLowerCase())).length,
        hotfixes_open: snapshot.jobs.filter((job) => /hotfix/i.test(safeString(job?.name))).length,
        apps_published: workflows,
        apps_draft: snapshot.jobs.filter((job) => /draft|pending/i.test(safeString(job?.status))).length,
        roles_total: 0,
        game_projects: gameSignals,
        game_playtests: snapshot.events.filter((event) => /playtest/.test(`${safeString(event?.type)} ${safeString(event?.text)}`.toLowerCase())).length,
        game_bugs: snapshot.events.filter((event) => {
            const tags = moduleEventTags(event);
            return tags.has('game') && tags.has('errors');
        }).length,
        game_gen_jobs: snapshot.jobs.filter((job) => /game/i.test(`${safeString(job?.name)} ${safeString(job?.kind)}`)).length,
        print_queue: snapshot.jobs.filter((job) => /print|slice|3d|cad/i.test(`${safeString(job?.name)} ${safeString(job?.kind)}`)).length,
        model_revisions: labSignals,
        materials_total: 0,
        printer_uptime: null,
        research_briefs: researchSignals,
        research_citations: snapshot.events.filter((event) => /citation|source/i.test(`${safeString(event?.text)} ${safeString(event?.type)}`)).length,
        research_competitors: snapshot.events.filter((event) => /competitor/i.test(`${safeString(event?.text)} ${safeString(event?.type)}`)).length,
        research_docs: snapshot.events.filter((event) => { const tags = moduleEventTags(event); return tags.has('research') && /doc|pdf|brief/i.test(safeString(event?.text) + ' ' + safeString(event?.type)); }).length,
        people_contacts: snapshot.sessions.length,
        people_followups: inboxNeedsReply,
        people_at_risk: snapshot.events.filter((event) => /stale|risk|no response/i.test(`${safeString(event?.text)} ${safeString(event?.type)}`.toLowerCase())).length,
        people_commitments: snapshot.approvalsPending,
        finance_burn: snapshot.spend?.total_usd != null ? '$' + Number(snapshot.spend.total_usd).toFixed(2) : null,
        finance_subscriptions: Object.keys(snapshot.spend?.by_model || {}).length || null,
        finance_anomalies: financeSignals,
        finance_approvals: snapshot.approvalsPending,
        webhooks_live: snapshot.healthChecks.filter((check) => /webhook/i.test(safeString(check?.name))).length || connected,
        market_installed: marketplaceModules.length,
        market_updates: marketplaceApps.reduce((count, app) => {
            const moduleId = safeString(app?.module_id);
            if (!moduleId) return count;
            const installed = marketplaceInstalledById[moduleId];
            if (!installed) return count;
            const installedVersion = safeString(installed.version || installed?.installed_version || installed?.module_version);
            const latestVersion = moduleLatestReleaseVersion(app);
            if (installedVersion && latestVersion && moduleIsVersionNewer(latestVersion, installedVersion)) {
                return count + 1;
            }
            return count;
        }, 0),
        market_private: marketplaceApps.filter((app) => {
            const access = safeString(app?.access_level).toLowerCase();
            const visibility = safeString(app?.visibility).toLowerCase();
            const compatibility = app?.compatibility && typeof app.compatibility === 'object' ? app.compatibility : {};
            const hasCompatibility = Object.prototype.toString.call(compatibility) === '[object Object]';
            const ineligible = hasCompatibility && !Boolean(compatibility?.eligible);
            return access === 'private' || visibility === 'private' || ineligible;
        }).length,
        market_saves: 0,
        vault_secrets: contentToCount(snapshot.summary?.api_keys_configured, null),
        vault_expiring: 0,
        vault_sources: toolsCount,
        vault_retention: null,
        timeline_events: snapshot.events.length,
        timeline_automated: snapshot.events.filter((event) => /automation|workflow|job|run/.test(`${safeString(event?.type)} ${safeString(event?.text)}`.toLowerCase())).length,
        timeline_approvals: snapshot.approvalsAutonomy.length + snapshot.approvalsGuardrails.length,
        timeline_retries: snapshot.events.filter((event) => /retry/.test(`${safeString(event?.type)} ${safeString(event?.text)}`.toLowerCase())).length,
        trace_count: vibeStats.trace_count,
        runtime_steps: vibeStats.runtime_steps,
        runtime_active: vibeStats.runtime_active,
        runtime_errors: vibeStats.runtime_errors,
        runtime_discovered: vibeStats.runtime_discovered,
        runtime_cut_edges: vibeStats.runtime_cut_edges,
        modules_disabled: vibeStats.modules_disabled,
        devices_paired: 0,
        handoffs_pending: infiniteSignals,
        offline_captures: snapshot.events.filter((event) => /offline|capture/.test(`${safeString(event?.type)} ${safeString(event?.text)}`.toLowerCase())).length,
        push_routes: null,
    };
}

function moduleResolveMetric(metric, signals) {
    const key = safeString(metric?.key);
    if (!key) return '--';
    if (!Object.prototype.hasOwnProperty.call(signals, key)) return '--';
    const value = signals[key];
    if (value === null || value === undefined) return '--';
    if (typeof value === 'number' && Number.isFinite(value)) return value.toLocaleString();
    const text = safeString(value);
    return text || '--';
}

function moduleBuildTriage(mode, snapshot) {
    if (mode !== 'inbox' && mode !== 'notifications' && mode !== 'timeline') {
        return null;
    }
    if (mode === 'inbox') {
        return {
            title: 'Triage Modes',
            meta: 'urgent / needs reply / FYI / newsletter / receipts',
            defaultFilter: 'urgent',
            filters: ['all', 'urgent', 'needs_reply', 'fyi', 'newsletter', 'receipts'],
            rows: moduleBuildEventRows(snapshot.events, { limit: 40, includeTags: ['inbox', 'urgent', 'needs_reply', 'newsletter', 'receipts', 'fyi'] }),
        };
    }
    if (mode === 'notifications') {
        return {
            title: 'Severity Queue',
            meta: 'critical / high / normal / low',
            defaultFilter: 'critical',
            filters: ['all', 'critical', 'high', 'normal', 'low'],
            rows: moduleBuildEventRows(snapshot.events, { limit: 40, includeTags: ['critical', 'high', 'normal', 'low'] }),
        };
    }
    return {
        title: 'Timeline Filters',
        meta: 'all / errors / approvals / workflows',
        defaultFilter: 'errors',
        filters: ['all', 'errors', 'approvals', 'workflows'],
        rows: moduleBuildEventRows(snapshot.events, { limit: 40, includeTags: ['errors', 'approvals', 'workflows'] }),
    };
}

function moduleModeLayout(mode) {
    return safeString(moduleModeSurface(mode)?.layout) || 'hub';
}

