function moduleWorkbenchState(mode) {
    const state = moduleEnsureRuntime();
    if (!state) return null;
    if (!state.workbench[mode]) {
        if (mode === 'lab_3d') {
            state.workbench[mode] = {
                mounted: false,
                tool: 'rect',
                shapes: [],
                objects: [],
                selectedId: '',
                nextId: 1,
                draft: null,
                drawing: false,
                dragStart: null,
                canvasWidth: 860,
                canvasHeight: 420,
                grid: 24,
                snap: true,
                units: 'mm',
                transformSpace: 'world',
                transformSnap: false,
                showGrid: true,
                wireframe: false,
                ossReady: false,
                ossLoading: false,
                ossError: '',
            };
        } else if (mode === 'automations') {
            state.workbench[mode] = {
                mounted: false,
                nextId: 1,
                selectedId: '',
                nodes: [],
                edges: [],
                connectingFrom: '',
                logs: [],
                graphData: null,
                runInput: '{\n  "subject": "Ops status",\n  "priority": "high"\n}',
                runReport: null,
                selectedProjectId: '',
                ossReady: false,
                ossLoading: false,
                ossError: '',
            };
        } else if (mode === 'app_builder') {
            state.workbench[mode] = {
                mounted: false,
                nextId: 1,
                selectedId: '',
                components: [],
                device: 'desktop',
                grid: 16,
                selectedProjectId: '',
                previewHtml: '',
                ossReady: false,
                ossLoading: false,
                ossError: '',
            };
        } else if (mode === 'studio') {
            state.workbench[mode] = {
                mounted: false,
                nextId: 1,
                assets: [],
                timeline: [],
                playhead: 0,
                timer: 0,
                playing: false,
                selectedAssetId: '',
                selectedClipId: '',
                forge: null,
                assetQuery: '',
                assetType: 'all',
                audioPreset: 'podcast_clean',
                renderPreset: 'master_1080p',
                generationTool: 'comfyui',
                generationPrompt: 'cute helper robot in a clean office',
                batchQueue: [],
                ossReady: false,
                ossLoading: false,
                ossError: '',
            };
        } else if (mode === 'dev_studio') {
            state.workbench[mode] = {
                mounted: false,
                code: '',
                issues: [],
                logs: [],
                ossReady: false,
                ossLoading: false,
                ossError: '',
            };
        } else if (mode === 'game_studio') {
            const width = 20;
            const height = 12;
            state.workbench[mode] = {
                mounted: false,
                gridWidth: width,
                gridHeight: height,
                brush: 1,
                dragging: false,
                tiles: Array.from({ length: height }, () => Array.from({ length: width }, () => 0)),
                logs: [],
                highScore: 0,
                selectedProjectId: '',
                viewMode: 'split',
                playTarget: 'auto',
                godotProjectPath: 'C:/games/MyGodotProject',
                unrealProjectPath: 'C:/games/MyUnrealProject/MyGame.uproject',
                unrealViewportUrl: 'http://127.0.0.1:8888',
                viewportConnected: false,
                viewportLoadState: 'idle',
                viewportBlockedHint: false,
                unrealRcUrl: 'http://127.0.0.1:30010',
                unrealRcEndpoint: '/remote/object/call',
                unrealRcPayload: '{\n  "objectPath": "/Game/Blueprints/BP_GameMode.BP_GameMode_C",\n  "functionName": "RunEditorTick",\n  "parameters": {}\n}',
                unrealRcResponse: '',
                sceneActors: [],
                selectedActorId: '',
                nextActorId: 1,
                assets: moduleGameStudioDefaultAssets(),
                selectedAssetId: 'asset-floor-grid',
                assetFilterType: 'all',
                assetSearch: '',
                bridge: {
                    status: 'idle',
                    lastPingMs: 0,
                    lastSeenAt: 0,
                    lastError: '',
                    routes: [],
                    pullCount: 0,
                    pushCount: 0,
                    actorSyncPath: '/Game/Blueprints/BP_LevelBridge.BP_LevelBridge_C',
                },
                bridgePollTimer: 0,
                selectedEngine: 'unreal',
                engineProjects: {},
                activeProjectByEngine: {},
                studioChat: [],
                chatDraft: '',
                projectDraftName: '',
                projectDraftPath: 'C:/games/MyUnrealProject/MyGame.uproject',
                ossReady: false,
                ossLoading: false,
                ossError: '',
            };
        } else if (mode === 'research_lab') {
            state.workbench[mode] = {
                mounted: false,
                lastQuery: '',
                queries: [],
                sources: [],
                notes: '',
                claims: [],
                synthesis: '',
                activeSourceId: '',
            };
        } else {
            state.workbench[mode] = { mounted: false };
        }
    }
    return state.workbench[mode];
}

function moduleWorkbenchTeardown(mode) {
    const state = moduleEnsureRuntime();
    if (!state) return;
    const wb = state.workbench?.[mode];
    if (!wb || typeof wb !== 'object') return;
    if (mode === 'studio' && Number(wb.timer) > 0) {
        window.clearInterval(wb.timer);
        wb.timer = 0;
        wb.playing = false;
    }
    if (mode === 'lab_3d' && wb.ossEngine?.dispose) {
        try {
            wb.ossEngine.dispose();
        } catch (_error) {}
        wb.ossEngine = null;
    }
    if (mode === 'automations') {
        try {
            wb.ossGraph?.stop?.();
        } catch (_error) {}
        try {
            wb.ossGraphCanvas?.setGraph?.(null, true);
        } catch (_error) {}
        wb.ossGraph = null;
        wb.ossGraphCanvas = null;
    }
    if (mode === 'app_builder' && wb.ossGrid?.destroy) {
        try {
            wb.ossGrid.destroy(false);
        } catch (_error) {}
        wb.ossGrid = null;
    }
    if (mode === 'studio') {
        if (wb.waveSurfer?.destroy) {
            try {
                wb.waveSurfer.destroy();
            } catch (_error) {}
        }
        wb.waveSurfer = null;
        wb.waveContainer = null;
        wb.lastWaveAssetId = '';
    }
    if (mode === 'dev_studio') {
        if (wb.monacoEditor?.dispose) {
            try {
                wb.monacoEditor.dispose();
            } catch (_error) {}
        }
        if (wb.monacoModel?.dispose) {
            try {
                wb.monacoModel.dispose();
            } catch (_error) {}
        }
        wb.monacoEditor = null;
        wb.monacoModel = null;
        if (wb.aceEditor?.destroy) {
            try {
                wb.aceEditor.destroy();
            } catch (_error) {}
        }
        if (wb.aceEditor?.container) {
            wb.aceEditor.container.innerHTML = '';
        }
        wb.aceEditor = null;
    }
    if (mode === 'game_studio' && wb.phaserGame?.destroy) {
        try {
            wb.phaserGame.destroy(true);
        } catch (_error) {}
        wb.phaserGame = null;
    }
    if (mode === 'game_studio' && Number(wb.viewportProbeTimer) > 0) {
        window.clearTimeout(Number(wb.viewportProbeTimer));
        wb.viewportProbeTimer = 0;
    }
    if (mode === 'game_studio' && Number(wb.bridgePollTimer) > 0) {
        window.clearInterval(Number(wb.bridgePollTimer));
        wb.bridgePollTimer = 0;
    }
}

function moduleWorkbenchHeader(container, title, subtitle) {
    const head = document.createElement('header');
    head.className = 'module-wb-header';
    head.innerHTML = `
        <h3>${escapeHtml(title || 'Workbench')}</h3>
        <p>${escapeHtml(subtitle || 'Interactive workspace')}</p>
    `;
    container.appendChild(head);
}

const MODULE_WORKBENCH_OPERATOR_COPY = Object.freeze({
    default: 'Thomas executes the work in the background. Use this tab to dispatch tasks, monitor progress, and review outputs.',
    studio: 'Thomas runs connected asset pipelines and tool jobs. Use this tab to queue work, watch status, and review artifacts.',
    dev_studio: 'Thomas runs engineering work and checks. Use this tab to assign coding tasks, monitor results, and review patches.',
    app_builder: 'Thomas builds app structure from your intent. Use this tab to steer requirements, inspect generated UI, and publish safely.',
    game_studio: 'Thomas runs game pipeline jobs across tools. Use this tab to dispatch builds/content generation and review playtest outputs.',
    lab_3d: 'Thomas runs 3D and fabrication pipelines. Use this tab to dispatch modeling/slicing jobs and verify print-ready outputs.',
    research_lab: 'Thomas runs deep research workflows. Use this tab to track source-backed progress and final brief outputs.',
    automations: 'Thomas executes automation flows. Use this tab to define routes, monitor run health, and handle approvals.',
    vibe_code: 'Thomas exposes a controllable system flowchart. Use this tab to inspect, disconnect, and reconnect runtime paths.',
});

function moduleWorkbenchOperatorNote(modeRaw) {
    const mode = safeString(modeRaw).toLowerCase();
    return MODULE_WORKBENCH_OPERATOR_COPY[mode] || MODULE_WORKBENCH_OPERATOR_COPY.default;
}

function moduleWorkbenchOperatorPreamble(container, modeRaw) {
    if (!(container instanceof HTMLElement)) return;
    const note = moduleWorkbenchOperatorNote(modeRaw);
    const panel = document.createElement('section');
    panel.className = 'module-wb-operator-note';
    panel.setAttribute('aria-label', 'Thomas operator mode');
    panel.innerHTML = `
        <strong>Operator Mode</strong>
        <p>${escapeHtml(note)}</p>
    `;
    container.appendChild(panel);
}

function moduleRenderWorkbench(modeRaw, snapshot, signals, definition, { force = false } = {}) {
    if (!moduleWorkbench) return;
    const mode = MODULE_NAV_MODE_SET.has(modeRaw) ? modeRaw : 'dashboard';
    const runtime = moduleEnsureRuntime();
    if (!runtime) return;
    if (!MODULE_WORKBENCH_MODES.has(mode)) {
        if (runtime.workbenchMode && runtime.workbenchMode !== mode) {
            moduleWorkbenchTeardown(runtime.workbenchMode);
        }
        moduleWorkbench.classList.add('hidden');
        moduleWorkbench.dataset.mode = '';
        moduleWorkbench.innerHTML = '';
        runtime.workbenchMode = '';
        return;
    }

    const wb = moduleWorkbenchState(mode);
    if (!wb) {
        moduleWorkbench.classList.add('hidden');
        return;
    }

    const modeChanged = runtime.workbenchMode !== mode;
    moduleWorkbench.classList.remove('hidden');
    moduleWorkbench.dataset.mode = mode;

    if (!force && !modeChanged && wb.mounted) {
        return;
    }

    if (modeChanged && runtime.workbenchMode) {
        moduleWorkbenchTeardown(runtime.workbenchMode);
    }

    moduleWorkbench.innerHTML = '';
    moduleWorkbenchOperatorPreamble(moduleWorkbench, mode);
    if (mode === 'lab_3d') {
        moduleRenderWorkbenchLab3d(moduleWorkbench, wb, { signals, snapshot, definition });
    } else if (mode === 'automations') {
        moduleRenderWorkbenchAutomations(moduleWorkbench, wb, { signals, snapshot, definition });
    } else if (mode === 'app_builder') {
        moduleRenderWorkbenchAppBuilder(moduleWorkbench, wb, { signals, snapshot, definition });
    } else if (mode === 'studio') {
        moduleRenderWorkbenchStudio(moduleWorkbench, wb, { signals, snapshot, definition });
    } else if (mode === 'dev_studio') {
        moduleRenderWorkbenchDevStudio(moduleWorkbench, wb, { signals, snapshot, definition });
    } else if (mode === 'game_studio') {
        moduleRenderWorkbenchGameStudio(moduleWorkbench, wb, { signals, snapshot, definition });
    } else if (mode === 'research_lab') {
        moduleRenderWorkbenchResearch(moduleWorkbench, wb, { signals, snapshot, definition });
    } else if (mode === 'vibe_code') {
        moduleRenderWorkbenchVibeCode(moduleWorkbench, wb, { signals, snapshot, definition });
    } else {
        moduleWorkbench.classList.add('hidden');
    }

    wb.mounted = true;
    runtime.workbenchMode = mode;
}

function moduleRenderWorkbenchVibeCode(container, wb, _context = {}) {
    if (!(container instanceof HTMLElement)) return;
    const mount = document.createElement('section');
    mount.className = 'module-wb-vibe-shell';
    container.appendChild(mount);
    vibeCodeEnsurePanel(mount);
    vibeCodeRender();
    wb.mounted = true;
}

function moduleWorkbenchClamp(value, min, max) {
    const number = Number(value);
    if (!Number.isFinite(number)) return min;
    if (number < min) return min;
    if (number > max) return max;
    return number;
}

function moduleWorkbenchTimeStamp() {
    return new Date().toISOString().slice(11, 19);
}

function moduleLab3dDefaultColor(type) {
    if (type === 'circle') return '#79d2b8';
    if (type === 'line') return '#ffd59a';
    return '#83c6ff';
}

function moduleLab3dShapeById(wb, shapeId) {
    if (!wb || !Array.isArray(wb.shapes)) return null;
    return wb.shapes.find((shape) => safeString(shape?.id) === safeString(shapeId)) || null;
}

function moduleLab3dMetrics(shapeRaw) {
    const shape = shapeRaw && typeof shapeRaw === 'object' ? shapeRaw : {};
    const type = safeString(shape.type);
    if (type === 'line') {
        const dx = (Number(shape.x2) || 0) - (Number(shape.x) || 0);
        const dy = (Number(shape.y2) || 0) - (Number(shape.y) || 0);
        const length = Math.sqrt((dx * dx) + (dy * dy));
        return { area: 0, perimeter: length, volume: 0 };
    }
    const depth = Math.max(0, Number(shape.depth) || 0);
    if (type === 'circle') {
        const radius = Math.max(1, Math.max(Number(shape.w) || 0, Number(shape.h) || 0) / 2);
        const area = Math.PI * radius * radius;
        const perimeter = 2 * Math.PI * radius;
        return { area, perimeter, volume: area * depth };
    }
    const width = Math.max(0, Number(shape.w) || 0);
    const height = Math.max(0, Number(shape.h) || 0);
    const area = width * height;
    const perimeter = (width * 2) + (height * 2);
    return { area, perimeter, volume: area * depth };
}

function moduleLab3dHitShape(shapeRaw, pointRaw) {
    const shape = shapeRaw && typeof shapeRaw === 'object' ? shapeRaw : {};
    const point = pointRaw && typeof pointRaw === 'object' ? pointRaw : { x: 0, y: 0 };
    const type = safeString(shape.type);
    if (type === 'line') {
        const x1 = Number(shape.x) || 0;
        const y1 = Number(shape.y) || 0;
        const x2 = Number(shape.x2) || x1;
        const y2 = Number(shape.y2) || y1;
        const px = Number(point.x) || 0;
        const py = Number(point.y) || 0;
        const abx = x2 - x1;
        const aby = y2 - y1;
        const denom = (abx * abx) + (aby * aby);
        if (denom <= 0.001) return Math.hypot(px - x1, py - y1) < 8;
        const t = moduleWorkbenchClamp((((px - x1) * abx) + ((py - y1) * aby)) / denom, 0, 1);
        const cx = x1 + (abx * t);
        const cy = y1 + (aby * t);
        return Math.hypot(px - cx, py - cy) < 8;
    }
    const x = Number(shape.x) || 0;
    const y = Number(shape.y) || 0;
    const w = Number(shape.w) || 0;
    const h = Number(shape.h) || 0;
    if (type === 'circle') {
        const cx = x + (w / 2);
        const cy = y + (h / 2);
        const r = Math.max(1, Math.max(w, h) / 2);
        const dx = (Number(point.x) || 0) - cx;
        const dy = (Number(point.y) || 0) - cy;
        return ((dx * dx) + (dy * dy)) <= (r * r);
    }
    return (Number(point.x) || 0) >= x
        && (Number(point.x) || 0) <= (x + w)
        && (Number(point.y) || 0) >= y
        && (Number(point.y) || 0) <= (y + h);
}

