function moduleRenderWorkbenchLab3dOss(container, wb) {
    if (!container || !wb) return false;
    if (wb.ossError) return false;
    if (!wb.ossReady || !wb.ossThree) {
        moduleWorkbenchRenderEngineLoading(
            container,
            '3D Lab CAD Engine',
            'Three.js viewport with transform controls and scene export.',
            'Loading Three.js modules...',
            'Falling back to local sketch mode if loading fails.',
        );
        if (!wb.ossLoading) {
            wb.ossLoading = true;
            void moduleWorkbenchLoadThreeBundle().then((bundle) => {
                wb.ossThree = bundle;
                wb.ossReady = true;
                wb.ossLoading = false;
                wb.ossError = '';
                moduleWorkbenchRefreshMode('lab_3d');
            }).catch((error) => {
                wb.ossLoading = false;
                wb.ossReady = false;
                wb.ossError = safeString(error?.message) || 'Failed to load 3D engine.';
                notifyUser('3D engine failed to load, using fallback canvas.', { tone: 'warn', durationMs: 2400, debugKind: 'lab3d' });
                moduleWorkbenchRefreshMode('lab_3d');
            });
        }
        return true;
    }

    const { THREE, OrbitControls, TransformControls, GLTFExporter, STLExporter } = wb.ossThree;
    if (!THREE || !OrbitControls || !TransformControls) return false;
    if (!Array.isArray(wb.objects)) wb.objects = [];
    wb.nextId = Math.max(1, Number(wb.nextId) || 1);
    wb.units = safeString(wb.units) || 'mm';
    wb.transformMode = safeString(wb.transformMode) || 'translate';
    wb.transformSpace = safeString(wb.transformSpace) === 'local' ? 'local' : 'world';
    wb.transformSnap = Boolean(wb.transformSnap);
    wb.showGrid = wb.showGrid !== false;
    wb.wireframe = Boolean(wb.wireframe);
    wb.selectedId = safeString(wb.selectedId);
    wb.selectedProjectId = safeString(wb.selectedProjectId);

    if (!wb.objects.length) {
        wb.objects.push({
            id: `mesh-${wb.nextId++}`,
            name: 'Base Cube',
            type: 'box',
            color: '#7fbfff',
            position: { x: 0, y: 0.5, z: 0 },
            rotation: { x: 0, y: 0, z: 0 },
            scale: { x: 1, y: 1, z: 1 },
        });
    }

    moduleWorkbenchHeader(container, '3D Lab CAD Engine', 'Thomas runs 3D scene jobs while you monitor geometry, transforms, and export state.');
    const shell = document.createElement('section');
    shell.className = 'module-wb-shell module-wb-shell-lab3d-oss';
    shell.innerHTML = `
        <div class="module-wb-toolbar">
            <div class="module-wb-tool-group">
                <button type="button" class="module-wb-tool-btn" data-lab3d-add="box"><i class="ph ph-cube"></i><span>Cube</span></button>
                <button type="button" class="module-wb-tool-btn" data-lab3d-add="sphere"><i class="ph ph-circle"></i><span>Sphere</span></button>
                <button type="button" class="module-wb-tool-btn" data-lab3d-add="cylinder"><i class="ph ph-cylinder"></i><span>Cylinder</span></button>
            </div>
            <div class="module-wb-tool-group">
                <button type="button" class="module-wb-tool-btn${wb.transformMode === 'translate' ? ' active' : ''}" data-lab3d-transform="translate">Move</button>
                <button type="button" class="module-wb-tool-btn${wb.transformMode === 'rotate' ? ' active' : ''}" data-lab3d-transform="rotate">Rotate</button>
                <button type="button" class="module-wb-tool-btn${wb.transformMode === 'scale' ? ' active' : ''}" data-lab3d-transform="scale">Scale</button>
            </div>
            <div class="module-wb-toolbar-actions">
                <button type="button" class="module-item-btn" data-lab3d-action="snap">${wb.transformSnap ? 'Snap On' : 'Snap Off'}</button>
                <button type="button" class="module-item-btn" data-lab3d-action="space">${wb.transformSpace === 'local' ? 'Local' : 'World'}</button>
                <button type="button" class="module-item-btn" data-lab3d-action="wireframe">${wb.wireframe ? 'Wireframe' : 'Shaded'}</button>
                <button type="button" class="module-item-btn" data-lab3d-action="grid">${wb.showGrid ? 'Grid On' : 'Grid Off'}</button>
                <button type="button" class="module-item-btn" data-lab3d-action="import_json">Import JSON</button>
                <button type="button" class="module-item-btn" data-lab3d-action="delete">Delete</button>
                <button type="button" class="module-item-btn" data-lab3d-action="export">Export JSON</button>
                <button type="button" class="module-item-btn" data-lab3d-action="export_gltf">Export GLTF</button>
                <button type="button" class="module-item-btn" data-lab3d-action="export_stl">Export STL</button>
            </div>
        </div>
        ${moduleWorkbenchRenderProjectControls('lab_3d', 'Model Projects')}
        <div class="module-wb-main-grid module-wb-main-grid-lab3d">
            <section class="module-wb-stage-card">
                <div class="module-wb-stage-head"><span class="module-wb-stage-title">Viewport</span><span class="module-wb-stage-meta" data-lab3d-status></span></div>
                <div class="module-wb-3d-stage" data-lab3d-stage></div>
                <p class="module-wb-hint">Click meshes to select. Drag gizmo handles for precision transforms.</p>
            </section>
            <aside class="module-wb-inspector-card" data-lab3d-inspector></aside>
        </div>
        ${moduleWorkbenchRenderOssStack('lab_3d')}
        <input type="file" class="hidden" data-lab3d-import-json accept=".json,application/json" />
    `;
    container.appendChild(shell);

    const stage = shell.querySelector('[data-lab3d-stage]');
    const inspector = shell.querySelector('[data-lab3d-inspector]');
    const status = shell.querySelector('[data-lab3d-status]');
    const importInput = shell.querySelector('[data-lab3d-import-json]');
    if (!(stage instanceof HTMLElement) || !(inspector instanceof HTMLElement) || !(status instanceof HTMLElement)) {
        return false;
    }

    if (wb.ossEngine?.dispose) {
        try {
            wb.ossEngine.dispose();
        } catch (_error) {}
    }

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0f1928);
    const camera = new THREE.PerspectiveCamera(52, 1, 0.1, 200);
    camera.position.set(4.2, 3.4, 6.1);
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.shadowMap.enabled = true;
    stage.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.08;
    controls.minDistance = 1.5;
    controls.maxDistance = 50;

    const transform = new TransformControls(camera, renderer.domElement);
    transform.setMode(wb.transformMode);
    transform.setSpace(wb.transformSpace);
    transform.size = 0.78;
    if (wb.transformSnap) {
        transform.setTranslationSnap(0.25);
        transform.setRotationSnap(Math.PI / 12);
        transform.setScaleSnap(0.1);
    } else {
        transform.setTranslationSnap(null);
        transform.setRotationSnap(null);
        transform.setScaleSnap(null);
    }
    transform.addEventListener('dragging-changed', (event) => {
        controls.enabled = !Boolean(event?.value);
    });
    if (typeof transform.getHelper === 'function') {
        scene.add(transform.getHelper());
    } else {
        scene.add(transform);
    }

    scene.add(new THREE.AmbientLight(0xffffff, 0.42));
    const keyLight = new THREE.DirectionalLight(0xd8ecff, 0.92);
    keyLight.position.set(4, 8, 5);
    keyLight.castShadow = true;
    scene.add(keyLight);
    const gridHelper = new THREE.GridHelper(24, 24, 0x2d5d8f, 0x1a334e);
    gridHelper.visible = wb.showGrid;
    scene.add(gridHelper);
    scene.add(new THREE.AxesHelper(1.25));

    const raycaster = new THREE.Raycaster();
    const pointer = new THREE.Vector2();
    const meshes = new Map();

    const cleanColor = (value, fallback = '#7fbfff') => (/^#[0-9a-f]{6}$/i.test(safeString(value)) ? safeString(value) : fallback);
    const ensureVector3 = (raw, fallback) => ({
        x: Number.isFinite(Number(raw?.x)) ? Number(raw.x) : fallback.x,
        y: Number.isFinite(Number(raw?.y)) ? Number(raw.y) : fallback.y,
        z: Number.isFinite(Number(raw?.z)) ? Number(raw.z) : fallback.z,
    });
    const geometryFor = (typeRaw) => {
        const type = safeString(typeRaw);
        if (type === 'sphere') return new THREE.SphereGeometry(0.55, 28, 20);
        if (type === 'cylinder') return new THREE.CylinderGeometry(0.42, 0.42, 1.15, 28);
        return new THREE.BoxGeometry(1, 1, 1);
    };
    const materialFor = (colorRaw) => new THREE.MeshStandardMaterial({
        color: cleanColor(colorRaw, '#7fbfff'),
        metalness: 0.2,
        roughness: 0.52,
        wireframe: wb.wireframe,
    });
    const toMesh = (spec) => {
        const mesh = new THREE.Mesh(geometryFor(spec.type), materialFor(spec.color));
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        mesh.userData.workbenchId = safeString(spec.id);
        const p = ensureVector3(spec.position, { x: 0, y: 0.5, z: 0 });
        const r = ensureVector3(spec.rotation, { x: 0, y: 0, z: 0 });
        const s = ensureVector3(spec.scale, { x: 1, y: 1, z: 1 });
        mesh.position.set(p.x, p.y, p.z);
        mesh.rotation.set(r.x, r.y, r.z);
        mesh.scale.set(Math.max(0.1, s.x), Math.max(0.1, s.y), Math.max(0.1, s.z));
        return mesh;
    };
    const updateSpecFromMesh = (spec, mesh) => {
        spec.position = { x: Number(mesh.position.x.toFixed(3)), y: Number(mesh.position.y.toFixed(3)), z: Number(mesh.position.z.toFixed(3)) };
        spec.rotation = { x: Number(mesh.rotation.x.toFixed(3)), y: Number(mesh.rotation.y.toFixed(3)), z: Number(mesh.rotation.z.toFixed(3)) };
        spec.scale = { x: Number(mesh.scale.x.toFixed(3)), y: Number(mesh.scale.y.toFixed(3)), z: Number(mesh.scale.z.toFixed(3)) };
        if (mesh.material?.color) {
            spec.color = `#${mesh.material.color.getHexString()}`;
        }
    };
    const specById = (id) => wb.objects.find((row) => safeString(row?.id) === safeString(id)) || null;
    const selectedSpec = () => specById(wb.selectedId);
    const selectedMesh = () => meshes.get(safeString(wb.selectedId)) || null;
    const setSelection = (idRaw) => {
        wb.selectedId = safeString(idRaw);
        const mesh = selectedMesh();
        if (mesh) {
            transform.attach(mesh);
        } else {
            transform.detach();
        }
    };
    const rebuildScene = () => {
        meshes.forEach((mesh) => {
            scene.remove(mesh);
            mesh.geometry?.dispose?.();
            if (Array.isArray(mesh.material)) {
                mesh.material.forEach((material) => material?.dispose?.());
            } else {
                mesh.material?.dispose?.();
            }
        });
        meshes.clear();
        wb.objects.forEach((spec) => {
            const mesh = toMesh(spec);
            meshes.set(safeString(spec.id), mesh);
            scene.add(mesh);
        });
        applyMaterialVisuals();
        if (!meshes.has(wb.selectedId) && wb.objects.length) {
            wb.selectedId = safeString(wb.objects[0].id);
        }
        setSelection(wb.selectedId);
    };
    const totalVolume = () => wb.objects.reduce((acc, spec) => {
        const scale = ensureVector3(spec.scale, { x: 1, y: 1, z: 1 });
        let base = 1;
        if (safeString(spec.type) === 'sphere') base = (4 / 3) * Math.PI * 0.55 * 0.55 * 0.55;
        if (safeString(spec.type) === 'cylinder') base = Math.PI * 0.42 * 0.42 * 1.15;
        return acc + (base * Math.max(0.1, scale.x) * Math.max(0.1, scale.y) * Math.max(0.1, scale.z));
    }, 0);
    const renderInspector = () => {
        const spec = selectedSpec();
        if (!spec) {
            inspector.innerHTML = `<h4>Inspector</h4><p class="module-wb-mini-note">Select a mesh to edit transforms.</p><div class="module-wb-metrics"><div><span>Bodies</span><strong>${wb.objects.length}</strong></div><div><span>Volume</span><strong>${totalVolume().toFixed(2)} ${escapeHtml(wb.units)}^3</strong></div><div><span>Mode</span><strong>${escapeHtml(wb.transformMode)}</strong></div></div>`;
            return;
        }
        const p = ensureVector3(spec.position, { x: 0, y: 0.5, z: 0 });
        const s = ensureVector3(spec.scale, { x: 1, y: 1, z: 1 });
        inspector.innerHTML = `
            <h4>${escapeHtml(safeString(spec.name) || 'Mesh')}</h4>
            <div class="module-wb-field-grid">
                <label class="module-wb-field">Name<input type="text" data-lab3d-prop="name" value="${escapeHtml(safeString(spec.name))}" /></label>
                <label class="module-wb-field">Color<input type="color" data-lab3d-prop="color" value="${escapeHtml(cleanColor(spec.color))}" /></label>
                <label class="module-wb-field">X<input type="number" step="0.1" data-lab3d-prop="x" value="${p.x}" /></label>
                <label class="module-wb-field">Y<input type="number" step="0.1" data-lab3d-prop="y" value="${p.y}" /></label>
                <label class="module-wb-field">Z<input type="number" step="0.1" data-lab3d-prop="z" value="${p.z}" /></label>
                <label class="module-wb-field">Scale<input type="number" step="0.1" min="0.1" data-lab3d-prop="scale" value="${s.x}" /></label>
            </div>
            <p class="module-wb-mini-note">Type: ${escapeHtml(safeString(spec.type) || 'box')} | ID: ${escapeHtml(safeString(spec.id))}</p>
        `;
    };
    const renderStatus = () => {
        const selected = selectedSpec() ? safeString(selectedSpec().name) : 'no selection';
        status.textContent = `${wb.objects.length} meshes | ${wb.transformMode}/${wb.transformSpace}${wb.transformSnap ? ' snap' : ''} | ${selected}`;
        const snapBtn = shell.querySelector('[data-lab3d-action="snap"]');
        const spaceBtn = shell.querySelector('[data-lab3d-action="space"]');
        const wireBtn = shell.querySelector('[data-lab3d-action="wireframe"]');
        const gridBtn = shell.querySelector('[data-lab3d-action="grid"]');
        if (snapBtn) snapBtn.textContent = wb.transformSnap ? 'Snap On' : 'Snap Off';
        if (spaceBtn) spaceBtn.textContent = wb.transformSpace === 'local' ? 'Local' : 'World';
        if (wireBtn) wireBtn.textContent = wb.wireframe ? 'Wireframe' : 'Shaded';
        if (gridBtn) gridBtn.textContent = wb.showGrid ? 'Grid On' : 'Grid Off';
    };
    const renderProjectSelect = () => {
        const select = shell.querySelector('select[data-wb-project-select="lab_3d"]');
        if (!(select instanceof HTMLSelectElement)) return;
        const rows = moduleWorkbenchProjectList('lab_3d');
        const current = safeString(wb.selectedProjectId);
        select.innerHTML = `<option value="">Select project</option>${rows.map((row) => `<option value="${escapeHtml(safeString(row.id))}">${escapeHtml(`${safeString(row.name)} (${new Date(Number(row.updatedAt) || Date.now()).toLocaleString()})`)}</option>`).join('')}`;
        select.value = rows.some((row) => safeString(row.id) === current) ? current : '';
    };
    const syncAllSpecs = () => {
        wb.objects.forEach((spec) => {
            const mesh = meshes.get(safeString(spec.id));
            if (mesh) updateSpecFromMesh(spec, mesh);
        });
    };
    const applyMaterialVisuals = () => {
        meshes.forEach((mesh) => {
            if (Array.isArray(mesh.material)) {
                mesh.material.forEach((material) => {
                    if (material && 'wireframe' in material) material.wireframe = wb.wireframe;
                });
            } else if (mesh.material && 'wireframe' in mesh.material) {
                mesh.material.wireframe = wb.wireframe;
            }
        });
    };
    const parseImportedObjects = (payloadRaw) => {
        const payload = payloadRaw && typeof payloadRaw === 'object' ? payloadRaw : {};
        const rows = Array.isArray(payload.objects) ? payload.objects : [];
        return rows
            .map((row, index) => {
                const type = safeString(row?.type);
                if (!['box', 'sphere', 'cylinder'].includes(type)) return null;
                return {
                    id: `mesh-${wb.nextId + index}`,
                    name: safeString(row?.name) || `${type[0]?.toUpperCase() || 'M'}${type.slice(1)} ${wb.nextId + index}`,
                    type,
                    color: cleanColor(row?.color),
                    position: ensureVector3(row?.position, { x: 0, y: 0.5, z: 0 }),
                    rotation: ensureVector3(row?.rotation, { x: 0, y: 0, z: 0 }),
                    scale: ensureVector3(row?.scale, { x: 1, y: 1, z: 1 }),
                };
            })
            .filter(Boolean);
    };
    const addMesh = (typeRaw) => {
        const type = safeString(typeRaw) || 'box';
        const spec = {
            id: `mesh-${wb.nextId++}`,
            name: `${type[0]?.toUpperCase() || 'M'}${type.slice(1)} ${wb.nextId - 1}`,
            type,
            color: cleanColor(type === 'sphere' ? '#7fe2ca' : (type === 'cylinder' ? '#ffcf84' : '#7fbfff')),
            position: { x: 0, y: 0.7, z: 0 },
            rotation: { x: 0, y: 0, z: 0 },
            scale: { x: 1, y: 1, z: 1 },
        };
        wb.objects.push(spec);
        rebuildScene();
        setSelection(spec.id);
        renderInspector();
        renderStatus();
    };
    const resize = () => {
        const width = Math.max(320, stage.clientWidth || 320);
        const height = Math.max(220, stage.clientHeight || 220);
        renderer.setSize(width, height);
        camera.aspect = width / height;
        camera.updateProjectionMatrix();
    };

    rebuildScene();
    resize();
    renderInspector();
    renderStatus();
    renderProjectSelect();

    const onPointerDown = (event) => {
        const rect = renderer.domElement.getBoundingClientRect();
        pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
        pointer.y = -(((event.clientY - rect.top) / rect.height) * 2 - 1);
        raycaster.setFromCamera(pointer, camera);
        const hits = raycaster.intersectObjects(Array.from(meshes.values()), false);
        if (!hits.length) {
            setSelection('');
            renderInspector();
            renderStatus();
            return;
        }
        const id = safeString(hits[0]?.object?.userData?.workbenchId);
        setSelection(id);
        renderInspector();
        renderStatus();
    };
    renderer.domElement.addEventListener('pointerdown', onPointerDown);
    transform.addEventListener('objectChange', () => {
        const spec = selectedSpec();
        const mesh = selectedMesh();
        if (!spec || !mesh) return;
        updateSpecFromMesh(spec, mesh);
        renderInspector();
        renderStatus();
    });

    const resizeObserver = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(resize) : null;
    if (resizeObserver) resizeObserver.observe(stage);
    const onWindowResize = () => resize();
    window.addEventListener('resize', onWindowResize);

    let rafId = 0;
    const frame = () => {
        rafId = window.requestAnimationFrame(frame);
        controls.update();
        renderer.render(scene, camera);
    };
    frame();

    shell.addEventListener('click', (event) => {
        if (moduleWorkbenchHandleOssStackClick(event.target)) return;
        const projectActionEl = event.target instanceof Element
            ? event.target.closest('[data-wb-project-action][data-wb-project-mode="lab_3d"]')
            : null;
        if (projectActionEl) {
            const action = safeString(projectActionEl.dataset.wbProjectAction).toLowerCase();
            const select = shell.querySelector('select[data-wb-project-select="lab_3d"]');
            const input = shell.querySelector('input[data-wb-project-name="lab_3d"]');
            const selectedId = safeString(select instanceof HTMLSelectElement ? select.value : wb.selectedProjectId);
            if (action === 'save') {
                syncAllSpecs();
                wb.selectedProjectId = moduleWorkbenchProjectSave('lab_3d', {
                    units: wb.units,
                    objects: wb.objects,
                    transformMode: wb.transformMode,
                    transformSpace: wb.transformSpace,
                    transformSnap: wb.transformSnap,
                    showGrid: wb.showGrid,
                    wireframe: wb.wireframe,
                }, safeString(input instanceof HTMLInputElement ? input.value : ''));
                if (input instanceof HTMLInputElement) input.value = '';
                renderProjectSelect();
                notifyUser('Model project saved.', { tone: 'success', durationMs: 1600, debugKind: 'lab3d' });
                return;
            }
            if (action === 'load') {
                if (!selectedId) return;
                const project = moduleWorkbenchProjectGet('lab_3d', selectedId);
                if (!project?.payload) return;
                const payload = project.payload;
                const nextObjects = parseImportedObjects(payload);
                if (!nextObjects.length) return;
                wb.objects = nextObjects;
                wb.units = safeString(payload.units) || wb.units;
                wb.transformMode = safeString(payload.transformMode) || wb.transformMode;
                wb.transformSpace = safeString(payload.transformSpace) === 'local' ? 'local' : 'world';
                wb.transformSnap = Boolean(payload.transformSnap);
                wb.showGrid = payload.showGrid !== false;
                wb.wireframe = Boolean(payload.wireframe);
                wb.selectedProjectId = selectedId;
                transform.setMode(wb.transformMode);
                transform.setSpace(wb.transformSpace);
                if (wb.transformSnap) {
                    transform.setTranslationSnap(0.25);
                    transform.setRotationSnap(Math.PI / 12);
                    transform.setScaleSnap(0.1);
                } else {
                    transform.setTranslationSnap(null);
                    transform.setRotationSnap(null);
                    transform.setScaleSnap(null);
                }
                gridHelper.visible = wb.showGrid;
                rebuildScene();
                renderInspector();
                renderStatus();
                renderProjectSelect();
                notifyUser(`Loaded model project: ${safeString(project.name)}.`, { tone: 'success', durationMs: 1700, debugKind: 'lab3d' });
                return;
            }
            if (action === 'delete') {
                if (!selectedId) return;
                if (moduleWorkbenchProjectDelete('lab_3d', selectedId)) {
                    wb.selectedProjectId = '';
                    renderProjectSelect();
                    notifyUser('Deleted model project.', { tone: 'warn', durationMs: 1600, debugKind: 'lab3d' });
                }
                return;
            }
        }
        const target = event.target instanceof Element ? event.target.closest('[data-lab3d-add], [data-lab3d-transform], [data-lab3d-action]') : null;
        if (!target) return;
        const addType = safeString(target.dataset.lab3dAdd);
        const transformMode = safeString(target.dataset.lab3dTransform);
        const action = safeString(target.dataset.lab3dAction).toLowerCase();
        if (addType) {
            addMesh(addType);
            return;
        }
        if (transformMode) {
            wb.transformMode = transformMode;
            transform.setMode(transformMode);
            shell.querySelectorAll('[data-lab3d-transform]').forEach((button) => button.classList.toggle('active', safeString(button.dataset.lab3dTransform) === transformMode));
            renderStatus();
            return;
        }
        if (action === 'snap') {
            wb.transformSnap = !wb.transformSnap;
            if (wb.transformSnap) {
                transform.setTranslationSnap(0.25);
                transform.setRotationSnap(Math.PI / 12);
                transform.setScaleSnap(0.1);
            } else {
                transform.setTranslationSnap(null);
                transform.setRotationSnap(null);
                transform.setScaleSnap(null);
            }
            renderStatus();
            return;
        }
        if (action === 'space') {
            wb.transformSpace = wb.transformSpace === 'local' ? 'world' : 'local';
            transform.setSpace(wb.transformSpace);
            renderStatus();
            return;
        }
        if (action === 'wireframe') {
            wb.wireframe = !wb.wireframe;
            applyMaterialVisuals();
            renderStatus();
            return;
        }
        if (action === 'grid') {
            wb.showGrid = !wb.showGrid;
            gridHelper.visible = wb.showGrid;
            renderStatus();
            return;
        }
        if (action === 'import_json') {
            if (importInput instanceof HTMLInputElement) {
                importInput.click();
            }
            return;
        }
        if (action === 'delete' && wb.selectedId) {
            wb.objects = wb.objects.filter((spec) => safeString(spec.id) !== safeString(wb.selectedId));
            wb.selectedId = wb.objects[0] ? safeString(wb.objects[0].id) : '';
            rebuildScene();
            renderInspector();
            renderStatus();
        }
        if (action === 'export') {
            syncAllSpecs();
            moduleWorkbenchCopyJson({ units: wb.units, objects: wb.objects }, '3D Lab Scene JSON');
        }
        if (action === 'export_gltf') {
            syncAllSpecs();
            const exporter = new GLTFExporter();
            const exportScene = new THREE.Scene();
            wb.objects.forEach((spec) => {
                const mesh = meshes.get(safeString(spec.id));
                if (mesh) exportScene.add(mesh.clone(true));
            });
            exporter.parse(
                exportScene,
                (result) => {
                    if (typeof result === 'string') {
                        moduleWorkbenchCopyText(result, '3D Lab GLTF');
                    } else {
                        moduleWorkbenchCopyJson(result, '3D Lab GLTF');
                    }
                },
                (error) => {
                    notifyUser(`GLTF export failed: ${safeString(error?.message) || 'unknown error'}`, { tone: 'warn', durationMs: 2200, debugKind: 'lab3d' });
                },
                { binary: false },
            );
        }
        if (action === 'export_stl' && STLExporter) {
            syncAllSpecs();
            const exporter = new STLExporter();
            const exportScene = new THREE.Scene();
            wb.objects.forEach((spec) => {
                const mesh = meshes.get(safeString(spec.id));
                if (mesh) exportScene.add(mesh.clone(true));
            });
            try {
                const stl = exporter.parse(exportScene, { binary: false });
                const stlText = typeof stl === 'string' ? stl : '';
                if (stlText) {
                    moduleWorkbenchDownloadText('lab3d-scene.stl', stlText, 'model/stl');
                    notifyUser('STL downloaded.', { tone: 'success', durationMs: 1600, debugKind: 'lab3d' });
                } else {
                    notifyUser('STL export produced no text payload.', { tone: 'warn', durationMs: 1900, debugKind: 'lab3d' });
                }
            } catch (error) {
                notifyUser(`STL export failed: ${safeString(error?.message) || 'unknown error'}`, { tone: 'warn', durationMs: 2200, debugKind: 'lab3d' });
            }
        }
    });

    if (importInput instanceof HTMLInputElement) {
        importInput.addEventListener('change', async () => {
            const file = importInput.files?.[0];
            if (!file) return;
            try {
                const raw = await file.text();
                const parsed = JSON.parse(raw);
                const nextObjects = parseImportedObjects(parsed);
                if (!nextObjects.length) {
                    notifyUser('No valid meshes found in imported JSON.', { tone: 'warn', durationMs: 2200, debugKind: 'lab3d' });
                    importInput.value = '';
                    return;
                }
                wb.objects = nextObjects;
                wb.nextId = nextObjects.length + 1;
                wb.selectedId = safeString(nextObjects[0]?.id);
                rebuildScene();
                renderInspector();
                renderStatus();
                notifyUser(`Imported ${nextObjects.length} mesh definitions.`, { tone: 'success', durationMs: 1700, debugKind: 'lab3d' });
            } catch (error) {
                notifyUser(`Import failed: ${safeString(error?.message) || 'invalid JSON'}`, { tone: 'warn', durationMs: 2200, debugKind: 'lab3d' });
            } finally {
                importInput.value = '';
            }
        });
    }
    const projectSelect = shell.querySelector('select[data-wb-project-select="lab_3d"]');
    if (projectSelect instanceof HTMLSelectElement) {
        projectSelect.addEventListener('change', () => {
            wb.selectedProjectId = safeString(projectSelect.value);
        });
    }

    inspector.addEventListener('input', (event) => {
        const target = event.target;
        if (!(target instanceof HTMLInputElement)) return;
        const spec = selectedSpec();
        const mesh = selectedMesh();
        if (!spec || !mesh) return;
        const prop = safeString(target.dataset.lab3dProp);
        if (!prop) return;
        if (prop === 'name') spec.name = safeString(target.value).slice(0, 80);
        if (prop === 'color') spec.color = cleanColor(target.value, spec.color);
        if (prop === 'x' || prop === 'y' || prop === 'z') {
            const next = Number(target.value);
            if (Number.isFinite(next)) {
                spec.position = ensureVector3(spec.position, { x: 0, y: 0.5, z: 0 });
                spec.position[prop] = next;
            }
        }
        if (prop === 'scale') {
            const next = moduleWorkbenchClamp(Number(target.value) || 1, 0.1, 12);
            spec.scale = { x: next, y: next, z: next };
        }
        mesh.position.set(spec.position?.x || 0, spec.position?.y || 0, spec.position?.z || 0);
        mesh.scale.set(spec.scale?.x || 1, spec.scale?.y || 1, spec.scale?.z || 1);
        if (mesh.material?.color) mesh.material.color.set(spec.color || '#7fbfff');
        renderInspector();
        renderStatus();
    });

    wb.ossEngine = {
        dispose: () => {
            window.cancelAnimationFrame(rafId);
            renderer.domElement.removeEventListener('pointerdown', onPointerDown);
            window.removeEventListener('resize', onWindowResize);
            resizeObserver?.disconnect?.();
            transform.detach();
            transform.dispose?.();
            controls.dispose?.();
            meshes.forEach((mesh) => {
                mesh.geometry?.dispose?.();
                if (Array.isArray(mesh.material)) {
                    mesh.material.forEach((material) => material?.dispose?.());
                } else {
                    mesh.material?.dispose?.();
                }
            });
            renderer.dispose?.();
            if (stage.contains(renderer.domElement)) stage.removeChild(renderer.domElement);
        },
    };
    return true;
}

function moduleRenderWorkbenchLab3d(container, wb) {
    if (moduleRenderWorkbenchLab3dOss(container, wb)) return;
    if (!container || !wb) return;
    if (!Array.isArray(wb.shapes)) wb.shapes = [];
    wb.tool = safeString(wb.tool) || 'rect';
    wb.grid = moduleWorkbenchClamp(Number(wb.grid) || 24, 8, 64);
    wb.snap = wb.snap !== false;
    wb.units = safeString(wb.units) || 'mm';
    wb.canvasWidth = moduleWorkbenchClamp(Number(wb.canvasWidth) || 860, 500, 1400);
    wb.canvasHeight = moduleWorkbenchClamp(Number(wb.canvasHeight) || 420, 260, 760);

    moduleWorkbenchHeader(container, '3D Lab Workbench', 'Dispatch fabrication-ready modeling tasks to Thomas and review generated CAD outputs.');
    const shell = document.createElement('section');
    shell.className = 'module-wb-shell module-wb-shell-lab3d';
    shell.innerHTML = `
        <div class="module-wb-toolbar">
            <div class="module-wb-tool-group" data-lab-tools></div>
            <div class="module-wb-toolbar-actions">
                <label class="module-wb-inline-field">Grid <input type="number" data-lab-grid min="8" max="64" step="2" value="${escapeHtml(String(wb.grid))}" /></label>
                <button type="button" class="module-item-btn" data-lab-action="snap">${wb.snap ? 'Snap On' : 'Snap Off'}</button>
                <button type="button" class="module-item-btn" data-lab-action="clear">Clear</button>
                <button type="button" class="module-item-btn" data-lab-action="export">Export</button>
            </div>
        </div>
        <div class="module-wb-main-grid module-wb-main-grid-lab3d">
            <section class="module-wb-stage-card">
                <div class="module-wb-stage-head"><span class="module-wb-stage-title">CAD Surface</span><span class="module-wb-stage-meta" data-lab-status></span></div>
                <canvas class="module-wb-canvas-lab3d" data-lab-canvas width="${escapeHtml(String(wb.canvasWidth))}" height="${escapeHtml(String(wb.canvasHeight))}"></canvas>
                <p class="module-wb-hint">Use Select to move. Other tools draw shapes.</p>
            </section>
            <aside class="module-wb-inspector-card" data-lab-inspector></aside>
        </div>
    `;
    container.appendChild(shell);

    const tools = [
        { id: 'select', icon: 'ph-cursor-click', label: 'Select' },
        { id: 'rect', icon: 'ph-rectangle', label: 'Rect' },
        { id: 'circle', icon: 'ph-circle', label: 'Circle' },
        { id: 'line', icon: 'ph-line-segment', label: 'Line' },
    ];
    const toolsEl = shell.querySelector('[data-lab-tools]');
    const canvas = shell.querySelector('[data-lab-canvas]');
    const inspector = shell.querySelector('[data-lab-inspector]');
    const status = shell.querySelector('[data-lab-status]');
    const gridInput = shell.querySelector('[data-lab-grid]');
    const ctx = canvas instanceof HTMLCanvasElement ? canvas.getContext('2d') : null;

    const selectedShape = () => moduleLab3dShapeById(wb, wb.selectedId);
    const point = (event) => {
        const raw = moduleWorkbenchPointFromEvent(canvas, event);
        const grid = Math.max(4, Number(wb.grid) || 24);
        const x = wb.snap ? Math.round(raw.x / grid) * grid : raw.x;
        const y = wb.snap ? Math.round(raw.y / grid) * grid : raw.y;
        return { x: moduleWorkbenchClamp(x, 0, canvas.width), y: moduleWorkbenchClamp(y, 0, canvas.height) };
    };
    const drawShape = (shape, selected = false, ghost = false) => {
        if (!ctx || !shape) return;
        const type = safeString(shape.type);
        const color = /^#[0-9a-f]{6}$/i.test(safeString(shape.color)) ? safeString(shape.color) : moduleLab3dDefaultColor(type);
        ctx.save();
        ctx.strokeStyle = selected ? '#f7fbff' : color;
        ctx.fillStyle = color;
        ctx.globalAlpha = ghost ? 0.34 : 0.78;
        ctx.lineWidth = selected ? 2.2 : 1.3;
        if (type === 'line') {
            ctx.beginPath();
            ctx.moveTo(Number(shape.x) || 0, Number(shape.y) || 0);
            ctx.lineTo(Number(shape.x2) || 0, Number(shape.y2) || 0);
            ctx.stroke();
        } else if (type === 'circle') {
            const cx = (Number(shape.x) || 0) + ((Number(shape.w) || 0) / 2);
            const cy = (Number(shape.y) || 0) + ((Number(shape.h) || 0) / 2);
            const r = Math.max(3, Math.max(Number(shape.w) || 0, Number(shape.h) || 0) / 2);
            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();
        } else {
            ctx.beginPath();
            ctx.rect(Number(shape.x) || 0, Number(shape.y) || 0, Math.max(1, Number(shape.w) || 0), Math.max(1, Number(shape.h) || 0));
            ctx.fill();
            ctx.stroke();
        }
        ctx.restore();
    };
    const renderInspector = () => {
        if (!inspector) return;
        const shape = selectedShape();
        if (!shape) {
            const totals = wb.shapes.reduce((acc, item) => {
                const m = moduleLab3dMetrics(item);
                acc.area += m.area;
                acc.volume += m.volume;
                return acc;
            }, { area: 0, volume: 0 });
            inspector.innerHTML = `<h4>Inspector</h4><p class="module-wb-mini-note">Select a shape to edit details.</p><div class="module-wb-metrics"><div><span>Bodies</span><strong>${wb.shapes.length}</strong></div><div><span>Area</span><strong>${totals.area.toFixed(1)} ${escapeHtml(wb.units)}^2</strong></div><div><span>Volume</span><strong>${totals.volume.toFixed(1)} ${escapeHtml(wb.units)}^3</strong></div></div>`;
            return;
        }
        const m = moduleLab3dMetrics(shape);
        inspector.innerHTML = `<h4>${escapeHtml(safeString(shape.label) || 'Shape')}</h4><div class="module-wb-field-grid"><label class="module-wb-field">Label<input type="text" data-shape-prop="label" value="${escapeHtml(safeString(shape.label))}" /></label><label class="module-wb-field">Color<input type="color" data-shape-prop="color" value="${escapeHtml(/^#[0-9a-f]{6}$/i.test(safeString(shape.color)) ? safeString(shape.color) : moduleLab3dDefaultColor(shape.type))}" /></label><label class="module-wb-field">X<input type="number" data-shape-prop="x" value="${Math.round(Number(shape.x) || 0)}" /></label><label class="module-wb-field">Y<input type="number" data-shape-prop="y" value="${Math.round(Number(shape.y) || 0)}" /></label>${safeString(shape.type) === 'line' ? `<label class="module-wb-field">End X<input type="number" data-shape-prop="x2" value="${Math.round(Number(shape.x2) || 0)}" /></label><label class="module-wb-field">End Y<input type="number" data-shape-prop="y2" value="${Math.round(Number(shape.y2) || 0)}" /></label>` : `<label class="module-wb-field">Width<input type="number" data-shape-prop="w" value="${Math.round(Number(shape.w) || 0)}" /></label><label class="module-wb-field">Height<input type="number" data-shape-prop="h" value="${Math.round(Number(shape.h) || 0)}" /></label>`}<label class="module-wb-field">Depth<input type="number" min="0" max="200" data-shape-prop="depth" value="${Math.round(Number(shape.depth) || 0)}" /></label></div><div class="module-wb-inspector-actions"><button type="button" class="module-item-btn" data-shape-action="duplicate">Duplicate</button><button type="button" class="module-item-btn" data-shape-action="delete">Delete</button></div><div class="module-wb-metrics"><div><span>Area</span><strong>${m.area.toFixed(1)}</strong></div><div><span>Perimeter</span><strong>${m.perimeter.toFixed(1)}</strong></div><div><span>Volume</span><strong>${m.volume.toFixed(1)}</strong></div></div>`;
    };
    const render = () => {
        if (!ctx || !(canvas instanceof HTMLCanvasElement)) return;
        toolsEl.innerHTML = tools.map((tool) => `<button type="button" class="module-wb-tool-btn${safeString(wb.tool) === tool.id ? ' active' : ''}" data-lab-tool="${tool.id}"><i class="ph ${tool.icon}"></i><span>${tool.label}</span></button>`).join('');
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.strokeStyle = 'rgba(164, 198, 244, 0.12)';
        for (let x = 0; x <= canvas.width; x += Number(wb.grid) || 24) { ctx.beginPath(); ctx.moveTo(x + 0.5, 0); ctx.lineTo(x + 0.5, canvas.height); ctx.stroke(); }
        for (let y = 0; y <= canvas.height; y += Number(wb.grid) || 24) { ctx.beginPath(); ctx.moveTo(0, y + 0.5); ctx.lineTo(canvas.width, y + 0.5); ctx.stroke(); }
        wb.shapes.forEach((shape) => drawShape(shape, safeString(shape.id) === safeString(wb.selectedId)));
        if (wb.draft) drawShape(wb.draft, false, true);
        renderInspector();
        status.textContent = `${wb.shapes.length} shapes | ${wb.snap ? `snap ${wb.grid}px` : 'free'}${selectedShape() ? ` | selected ${safeString(selectedShape().label)}` : ''}`;
    };

    shell.addEventListener('click', (event) => {
        const target = event.target instanceof Element ? event.target.closest('[data-lab-tool], [data-lab-action], [data-shape-action]') : null;
        if (!target) return;
        const tool = safeString(target.dataset.labTool);
        const action = safeString(target.dataset.labAction || target.dataset.shapeAction).toLowerCase();
        if (tool) wb.tool = tool;
        if (action === 'snap') wb.snap = !wb.snap;
        if (action === 'clear') { wb.shapes = []; wb.selectedId = ''; wb.draft = null; wb.dragStart = null; }
        if (action === 'export') moduleWorkbenchCopyJson({ units: wb.units, grid: wb.grid, shapes: wb.shapes }, '3D Lab CAD JSON');
        if (action === 'duplicate' && selectedShape()) { const copy = { ...selectedShape(), id: `shape-${wb.nextId++}`, label: `${safeString(selectedShape().label)} Copy`, x: (Number(selectedShape().x) || 0) + 18, y: (Number(selectedShape().y) || 0) + 18 }; if (safeString(copy.type) === 'line') { copy.x2 = (Number(copy.x2) || 0) + 18; copy.y2 = (Number(copy.y2) || 0) + 18; } wb.shapes.push(copy); wb.selectedId = copy.id; }
        if (action === 'delete' && selectedShape()) { wb.shapes = wb.shapes.filter((shape) => safeString(shape.id) !== safeString(wb.selectedId)); wb.selectedId = ''; }
        render();
    });
    if (gridInput) gridInput.addEventListener('input', () => { wb.grid = moduleWorkbenchClamp(Number(gridInput.value) || 24, 8, 64); render(); });
    if (inspector) inspector.addEventListener('input', (event) => {
        const target = event.target;
        if (!(target instanceof HTMLInputElement)) return;
        const shape = selectedShape();
        if (!shape) return;
        const prop = safeString(target.dataset.shapeProp);
        if (!prop) return;
        if (prop === 'label') shape.label = safeString(target.value).slice(0, 60);
        else if (prop === 'color' && /^#[0-9a-f]{6}$/i.test(safeString(target.value))) shape.color = safeString(target.value);
        else shape[prop] = Number.isFinite(Number(target.value)) ? Number(target.value) : shape[prop];
        render();
    });
    if (canvas instanceof HTMLCanvasElement) {
        canvas.addEventListener('pointerdown', (event) => {
            const p = point(event);
            if (safeString(wb.tool) === 'select') {
                const hit = [...wb.shapes].reverse().find((shape) => moduleLab3dHitShape(shape, p)) || null;
                wb.selectedId = safeString(hit?.id);
                wb.dragStart = hit ? { x: p.x, y: p.y, origin: { ...hit } } : null;
                render();
                return;
            }
            wb.drawing = true;
            wb.draft = {
                id: 'draft',
                type: wb.tool,
                label: 'Draft',
                color: moduleLab3dDefaultColor(wb.tool),
                depth: 12,
                startX: p.x,
                startY: p.y,
                x: p.x,
                y: p.y,
                w: 0,
                h: 0,
                x2: p.x,
                y2: p.y,
            };
            wb.selectedId = '';
            render();
        });
        canvas.addEventListener('pointermove', (event) => {
            const p = point(event);
            if (wb.drawing && wb.draft) {
                if (safeString(wb.draft.type) === 'line') {
                    wb.draft.x2 = p.x;
                    wb.draft.y2 = p.y;
                } else {
                    const sx = Number(wb.draft.startX) || Number(wb.draft.x) || 0;
                    const sy = Number(wb.draft.startY) || Number(wb.draft.y) || 0;
                    wb.draft.x = Math.min(sx, p.x);
                    wb.draft.y = Math.min(sy, p.y);
                    wb.draft.w = Math.abs(p.x - sx);
                    wb.draft.h = Math.abs(p.y - sy);
                    wb.draft.x2 = p.x;
                    wb.draft.y2 = p.y;
                }
                render();
                return;
            }
            if (wb.dragStart && safeString(wb.tool) === 'select') { const shape = selectedShape(); if (!shape) return; const dx = p.x - wb.dragStart.x; const dy = p.y - wb.dragStart.y; shape.x = (Number(wb.dragStart.origin.x) || 0) + dx; shape.y = (Number(wb.dragStart.origin.y) || 0) + dy; if (safeString(shape.type) === 'line') { shape.x2 = (Number(wb.dragStart.origin.x2) || 0) + dx; shape.y2 = (Number(wb.dragStart.origin.y2) || 0) + dy; } render(); }
        });
        const finish = () => {
            if (wb.drawing && wb.draft) {
                const draft = wb.draft;
                const lineLength = Math.hypot((Number(draft.x2) || 0) - (Number(draft.x) || 0), (Number(draft.y2) || 0) - (Number(draft.y) || 0));
                const keep = safeString(draft.type) === 'line'
                    ? lineLength > 6
                    : (Math.max(Number(draft.w) || 0, Number(draft.h) || 0) > 6);
                if (keep) {
                    const shape = {
                        ...draft,
                        id: `shape-${wb.nextId++}`,
                        label: `${safeString(draft.type)} ${wb.nextId - 1}`,
                    };
                    delete shape.startX;
                    delete shape.startY;
                    wb.shapes.push(shape);
                    wb.selectedId = shape.id;
                }
            }
            wb.drawing = false;
            wb.draft = null;
            wb.dragStart = null;
            render();
        };
        canvas.addEventListener('pointerup', finish);
        canvas.addEventListener('pointerleave', finish);
    }
    render();
}

function moduleWorkbenchPushLog(bucket, message, tone = 'ok', cap = 80, prefix = 'log') {
    if (!Array.isArray(bucket)) return;
    bucket.unshift({
        id: moduleWorkbenchMakeId(prefix),
        time: moduleWorkbenchTimeStamp(),
        tone,
        message: safeString(message),
    });
    if (bucket.length > cap) bucket.length = cap;
}

function moduleWorkbenchEnsureLiteGraphNodeType(LiteGraph) {
    if (!LiteGraph?.registerNodeType) return;
    if (LiteGraph.registered_node_types?.['thomas/flow_block']) return;
    class ThomasFlowBlock extends LiteGraph.LGraphNode {
        constructor() {
            super();
            this.title = 'Flow Block';
            this.addInput('in', 'flow');
            this.addOutput('out', 'flow');
            this.properties = {
                blockType: 'custom',
                kind: 'action',
                notes: '',
                approval: false,
            };
            this.size = [210, 86];
        }
    }
    LiteGraph.registerNodeType('thomas/flow_block', ThomasFlowBlock);
}

function moduleWorkbenchLiteGraphLinks(graphDataRaw) {
    const graphData = graphDataRaw && typeof graphDataRaw === 'object' ? graphDataRaw : {};
    const linksRaw = graphData.links;
    if (!linksRaw || typeof linksRaw !== 'object') return [];
    return Object.values(linksRaw)
        .map((entry) => (Array.isArray(entry) ? entry : []))
        .filter((entry) => entry.length >= 4)
        .map((entry) => ({
            originId: Number(entry[1]) || 0,
            targetId: Number(entry[3]) || 0,
        }))
        .filter((entry) => entry.originId > 0 && entry.targetId > 0);
}

function moduleWorkbenchFlowToN8n(graphDataRaw) {
    const graphData = graphDataRaw && typeof graphDataRaw === 'object' ? graphDataRaw : {};
    const nodesRaw = Array.isArray(graphData.nodes) ? graphData.nodes : [];
    const nodes = nodesRaw.map((nodeRaw, index) => {
        const node = nodeRaw && typeof nodeRaw === 'object' ? nodeRaw : {};
        const id = String(Number(node.id) || (index + 1));
        const title = safeString(node.title) || `Flow ${index + 1}`;
        const name = `${title} [${id}]`;
        return {
            _id: id,
            id,
            name,
            type: 'n8n-nodes-base.noOp',
            typeVersion: 1,
            position: [
                Number(node.pos?.[0]) || ((index + 1) * 180),
                Number(node.pos?.[1]) || ((index + 1) * 80),
            ],
            parameters: {
                kind: safeString(node.properties?.kind) || 'action',
                blockType: safeString(node.properties?.blockType) || 'custom',
                notes: safeString(node.properties?.notes),
                approval: Boolean(node.properties?.approval),
            },
        };
    });
    const byId = new Map(nodes.map((node) => [node._id, node]));
    const links = moduleWorkbenchLiteGraphLinks(graphData);
    const connectionMap = new Map();
    links.forEach((edge) => {
        const from = byId.get(String(edge.originId));
        const to = byId.get(String(edge.targetId));
        if (!from || !to) return;
        if (!connectionMap.has(from.name)) connectionMap.set(from.name, []);
        connectionMap.get(from.name).push({
            node: to.name,
            type: 'main',
            index: 0,
        });
    });
    const connections = {};
    nodes.forEach((node) => {
        const outputs = connectionMap.get(node.name) || [];
        if (!outputs.length) return;
        connections[node.name] = {
            main: [outputs],
        };
    });
    return {
        name: 'Thomas Flow Export',
        active: false,
        settings: {},
        nodes: nodes.map((node) => ({
            id: node.id,
            name: node.name,
            type: node.type,
            typeVersion: node.typeVersion,
            position: node.position,
            parameters: node.parameters,
        })),
        connections,
    };
}

function moduleWorkbenchFlowToNodeRed(graphDataRaw) {
    const graphData = graphDataRaw && typeof graphDataRaw === 'object' ? graphDataRaw : {};
    const nodesRaw = Array.isArray(graphData.nodes) ? graphData.nodes : [];
    const tabId = `tab_${Date.now().toString(36)}`;
    const nodes = nodesRaw.map((nodeRaw, index) => {
        const node = nodeRaw && typeof nodeRaw === 'object' ? nodeRaw : {};
        const id = `n_${String(Number(node.id) || (index + 1))}`;
        return {
            id,
            type: 'function',
            z: tabId,
            name: safeString(node.title) || `Flow ${index + 1}`,
            func: `// ${safeString(node.properties?.kind) || 'action'}\nreturn msg;`,
            outputs: 1,
            noerr: 0,
            initialize: '',
            finalize: '',
            libs: [],
            x: Number(node.pos?.[0]) || ((index + 1) * 200),
            y: Number(node.pos?.[1]) || ((index + 1) * 80),
            wires: [[]],
        };
    });
    const byId = new Map(nodes.map((node) => [node.id.replace(/^n_/, ''), node]));
    moduleWorkbenchLiteGraphLinks(graphData).forEach((edge) => {
        const from = byId.get(String(edge.originId));
        const to = byId.get(String(edge.targetId));
        if (!from || !to) return;
        from.wires[0].push(to.id);
    });
    return [
        { id: tabId, type: 'tab', label: 'Thomas Flow', disabled: false, info: '' },
        ...nodes,
    ];
}

function moduleAutomationCoerceValue(rawValue) {
    const text = safeString(rawValue).trim();
    if (!text) return '';
    if (text === 'true') return true;
    if (text === 'false') return false;
    if (text === 'null') return null;
    if (!Number.isNaN(Number(text)) && text !== '') return Number(text);
    if ((text.startsWith('{') && text.endsWith('}')) || (text.startsWith('[') && text.endsWith(']'))) {
        try {
            return JSON.parse(text);
        } catch (_error) {}
    }
    return text;
}

function moduleAutomationCompare(actual, opRaw, expectedRaw) {
    const op = safeString(opRaw) || 'equals';
    const expected = moduleAutomationCoerceValue(expectedRaw);
    if (op === 'equals') return actual === expected;
    if (op === 'not_equals') return actual !== expected;
    if (op === 'contains') return safeString(actual).toLowerCase().includes(safeString(expected).toLowerCase());
    if (op === 'not_contains') return !safeString(actual).toLowerCase().includes(safeString(expected).toLowerCase());
    if (op === 'gt') return Number(actual) > Number(expected);
    if (op === 'lt') return Number(actual) < Number(expected);
    if (op === 'exists') return typeof actual !== 'undefined' && actual !== null && safeString(actual) !== '';
    return actual === expected;
}

function moduleAutomationApplyTemplate(templateRaw, dataRaw) {
    const template = safeString(templateRaw);
    const data = dataRaw && typeof dataRaw === 'object' ? dataRaw : {};
    if (!template) return '';
    return template.replace(/\{\{\s*([a-zA-Z0-9_.-]+)\s*\}\}/g, (_match, path) => {
        const value = moduleWorkbenchPathGet(data, safeString(path));
        if (value === null || typeof value === 'undefined') return '';
        if (typeof value === 'object') return JSON.stringify(value);
        return safeString(value);
    });
}

function moduleAutomationExecuteNode(nodeRaw, payloadRaw, outputsRaw) {
    const node = nodeRaw && typeof nodeRaw === 'object' ? nodeRaw : {};
    const outputs = Array.isArray(outputsRaw) ? outputsRaw : [];
    const props = node.properties && typeof node.properties === 'object' ? node.properties : {};
    const blockType = safeString(props.blockType);
    const kind = safeString(props.kind);
    const payload = moduleWorkbenchDeepClone(payloadRaw && typeof payloadRaw === 'object' ? payloadRaw : {});
    const data = payload && typeof payload === 'object' ? payload : {};
    const result = {
        pass: true,
        pendingApproval: false,
        note: '',
        payload: data,
    };

    if (blockType === 'if_else') {
        const field = safeString(props.field) || 'priority';
        const op = safeString(props.op) || 'equals';
        const actual = moduleWorkbenchPathGet(data, field);
        result.pass = moduleAutomationCompare(actual, op, props.value);
        result.note = result.pass ? `Condition passed (${field} ${op}).` : `Condition failed (${field} ${op}).`;
        return result;
    }

    if (blockType === 'approval_gate') {
        const autoApprove = Boolean(props.autoApprove);
        if (!autoApprove) {
            result.pendingApproval = true;
            result.pass = false;
            result.note = 'Waiting for human approval.';
            return result;
        }
        result.note = 'Auto-approved.';
        return result;
    }

    if (blockType === 'run_script') {
        const operation = safeString(props.operation) || 'set';
        const field = safeString(props.field) || 'result.value';
        if (operation === 'set') {
            moduleWorkbenchPathSet(data, field, moduleAutomationCoerceValue(props.value));
            result.note = `Set ${field}.`;
        } else if (operation === 'inc') {
            const current = Number(moduleWorkbenchPathGet(data, field) || 0);
            const inc = Number(moduleAutomationCoerceValue(props.value) || 1);
            moduleWorkbenchPathSet(data, field, current + inc);
            result.note = `Incremented ${field} by ${inc}.`;
        } else if (operation === 'append_tag') {
            const current = moduleWorkbenchPathGet(data, field);
            const next = Array.isArray(current) ? [...current, safeString(props.value)] : [safeString(props.value)];
            moduleWorkbenchPathSet(data, field, next);
            result.note = `Appended tag on ${field}.`;
        } else if (operation === 'delete') {
            moduleWorkbenchPathDelete(data, field);
            result.note = `Deleted ${field}.`;
        } else {
            result.note = `No-op operation: ${operation}.`;
        }
        return result;
    }

    if (blockType === 'send_message') {
        const template = safeString(props.template) || 'Workflow message: {{subject}}';
        const text = moduleAutomationApplyTemplate(template, data);
        outputs.push({
            channel: safeString(props.channel) || 'inbox',
            text,
        });
        result.note = 'Message action generated.';
        return result;
    }

    if (kind === 'trigger') {
        result.note = 'Trigger emitted payload.';
        return result;
    }
    if (kind === 'logic') {
        result.note = 'Logic gate passed.';
        return result;
    }
    if (kind === 'action') {
        result.note = 'Action executed.';
        return result;
    }
    result.note = 'Node executed.';
    return result;
}

function moduleAutomationRunGraphData(graphDataRaw, inputRaw) {
    const graphData = graphDataRaw && typeof graphDataRaw === 'object' ? graphDataRaw : {};
    const nodes = Array.isArray(graphData.nodes) ? graphData.nodes : [];
    const edges = moduleWorkbenchLiteGraphLinks(graphData);
    const nodeMap = new Map();
    const adjacency = new Map();
    const indegree = new Map();
    nodes.forEach((node) => {
        const id = Number(node?.id) || 0;
        if (!id) return;
        nodeMap.set(id, node);
        adjacency.set(id, []);
        indegree.set(id, 0);
    });
    edges.forEach((edge) => {
        const from = Number(edge.originId) || 0;
        const to = Number(edge.targetId) || 0;
        if (!nodeMap.has(from) || !nodeMap.has(to)) return;
        adjacency.get(from).push(to);
        indegree.set(to, Number(indegree.get(to) || 0) + 1);
    });

    const starts = nodes
        .map((node) => Number(node?.id) || 0)
        .filter((id) => id && (
            safeString(nodeMap.get(id)?.properties?.kind) === 'trigger'
            || Number(indegree.get(id) || 0) === 0
        ));
    const queue = starts.map((id) => ({ id, payload: moduleWorkbenchDeepClone(inputRaw && typeof inputRaw === 'object' ? inputRaw : {}) }));
    const outputs = [];
    const steps = [];
    const guard = new Map();
    let iterations = 0;

    while (queue.length && iterations < 500) {
        iterations += 1;
        const item = queue.shift();
        if (!item) continue;
        const id = Number(item.id) || 0;
        const node = nodeMap.get(id);
        if (!node) continue;
        const key = String(id);
        const seen = Number(guard.get(key) || 0) + 1;
        guard.set(key, seen);
        if (seen > 12) continue;

        const run = moduleAutomationExecuteNode(node, item.payload, outputs);
        steps.push({
            id,
            title: safeString(node.title) || `Node ${id}`,
            pass: Boolean(run.pass),
            pendingApproval: Boolean(run.pendingApproval),
            note: safeString(run.note),
            payload: moduleWorkbenchDeepClone(run.payload),
        });
        if (!run.pass) continue;
        const children = adjacency.get(id) || [];
        children.forEach((childId) => {
            queue.push({ id: childId, payload: moduleWorkbenchDeepClone(run.payload) });
        });
    }

    const lastPayload = steps.length ? moduleWorkbenchDeepClone(steps[steps.length - 1].payload) : moduleWorkbenchDeepClone(inputRaw && typeof inputRaw === 'object' ? inputRaw : {});
    return {
        steps,
        outputs,
        finalPayload: lastPayload,
        nodeCount: nodes.length,
        edgeCount: edges.length,
    };
}

function moduleRenderWorkbenchAutomationsOss(container, wb) {
    if (!container || !wb) return false;
    if (wb.ossError) return false;
    if (!wb.ossReady || !window.LiteGraph) {
        moduleWorkbenchRenderEngineLoading(
            container,
            'Automation Graph Engine',
            'LiteGraph drag/drop canvas with node links and run traces.',
            'Loading LiteGraph...',
            'If loading fails, fallback list mode will open automatically.',
        );
        if (!wb.ossLoading) {
            wb.ossLoading = true;
            void moduleWorkbenchLoadLiteGraph().then(() => {
                wb.ossReady = true;
                wb.ossLoading = false;
                wb.ossError = '';
                moduleWorkbenchRefreshMode('automations');
            }).catch((error) => {
                wb.ossLoading = false;
                wb.ossReady = false;
                wb.ossError = safeString(error?.message) || 'Failed to load LiteGraph.';
                notifyUser('LiteGraph failed to load, using fallback flow list.', { tone: 'warn', durationMs: 2300, debugKind: 'automations' });
                moduleWorkbenchRefreshMode('automations');
            });
        }
        return true;
    }

    const LiteGraph = window.LiteGraph;
    moduleWorkbenchEnsureLiteGraphNodeType(LiteGraph);
    if (!Array.isArray(wb.logs)) wb.logs = [];
    wb.runInput = safeString(wb.runInput) || '{\n  "subject": "Ops status",\n  "priority": "high"\n}';
    if (!wb.runReport || typeof wb.runReport !== 'object') wb.runReport = null;
    wb.selectedProjectId = safeString(wb.selectedProjectId);
    wb.selectedNodeId = safeString(wb.selectedNodeId);

    moduleWorkbenchHeader(container, 'Automation Graph Engine', 'Define orchestration logic for Thomas to execute, then monitor run behavior and approvals.');
    const shell = document.createElement('section');
    shell.className = 'module-wb-shell module-wb-shell-flow-oss';
    shell.innerHTML = `
        <aside class="module-wb-side-card">
            <h4>Block Palette</h4>
            <div class="module-wb-palette" data-flow-palette></div>
            ${moduleWorkbenchRenderProjectControls('automations', 'Flow Projects')}
            <label class="module-wb-field module-wb-field-wide">Run Input JSON<textarea rows="6" data-flow-run-input>${escapeHtml(safeString(wb.runInput) || '{\n  "subject": "Ops status",\n  "priority": "high"\n}')}</textarea></label>
            <div class="module-wb-inspector-actions">
                <button type="button" class="module-item-btn" data-flow-action="run">Test Run</button>
                <button type="button" class="module-item-btn" data-flow-action="run_dry">Dry Run</button>
                <button type="button" class="module-item-btn" data-flow-action="export">Export</button>
                <button type="button" class="module-item-btn" data-flow-action="export_n8n">n8n JSON</button>
                <button type="button" class="module-item-btn" data-flow-action="export_nodered">Node-RED JSON</button>
                <button type="button" class="module-item-btn" data-flow-action="reset">Reset</button>
            </div>
        </aside>
        <section class="module-wb-stage-card">
            <div class="module-wb-stage-head"><span class="module-wb-stage-title">Visual Graph</span><span class="module-wb-stage-meta" data-flow-status></span></div>
            <canvas class="module-wb-flow-canvas" data-flow-canvas></canvas>
            <div class="module-wb-log-list" data-flow-logs></div>
            <div class="module-wb-run-report" data-flow-report></div>
        </section>
        <aside class="module-wb-inspector-card" data-flow-inspector></aside>
        ${moduleWorkbenchRenderOssStack('automations')}
    `;
    container.appendChild(shell);

    const palette = shell.querySelector('[data-flow-palette]');
    const canvas = shell.querySelector('[data-flow-canvas]');
    const logs = shell.querySelector('[data-flow-logs]');
    const report = shell.querySelector('[data-flow-report]');
    const inspector = shell.querySelector('[data-flow-inspector]');
    const status = shell.querySelector('[data-flow-status]');
    const runInputEl = shell.querySelector('[data-flow-run-input]');
    if (!(palette instanceof HTMLElement) || !(canvas instanceof HTMLCanvasElement) || !(logs instanceof HTMLElement) || !(report instanceof HTMLElement) || !(inspector instanceof HTMLElement) || !(status instanceof HTMLElement)) {
        return false;
    }

    if (wb.ossGraphCanvas?.setGraph) {
        try {
            wb.ossGraph?.stop?.();
            wb.ossGraphCanvas.setGraph(null, true);
        } catch (_error) {}
    }

    const graph = new LiteGraph.LGraph();
    const graphCanvas = new LiteGraph.LGraphCanvas(canvas, graph);
    graphCanvas.ds.scale = 0.92;
    graphCanvas.onNodeSelected = (node) => {
        wb.selectedNodeId = safeString(node?.id);
        renderInspector();
    };
    graphCanvas.onNodeDeselected = () => {
        wb.selectedNodeId = '';
        renderInspector();
    };
    graph.start();

    wb.ossGraph = graph;
    wb.ossGraphCanvas = graphCanvas;

    const blockDefs = [
        { id: 'schedule_trigger', kind: 'trigger', label: 'Schedule Trigger' },
        { id: 'email_trigger', kind: 'trigger', label: 'New Email Trigger' },
        { id: 'if_else', kind: 'logic', label: 'If / Else' },
        { id: 'approval_gate', kind: 'logic', label: 'Human Approval' },
        { id: 'send_message', kind: 'action', label: 'Send Message' },
        { id: 'run_script', kind: 'action', label: 'Run Script' },
    ];

    const createNode = (def, pos = [120, 120]) => {
        const node = LiteGraph.createNode('thomas/flow_block');
        if (!node) return null;
        node.title = def.label;
        node.properties.blockType = def.id;
        node.properties.kind = def.kind;
        node.properties.notes = node.properties.notes || '';
        node.properties.approval = Boolean(node.properties.approval);
        node.properties.field = safeString(node.properties.field) || 'priority';
        node.properties.op = safeString(node.properties.op) || 'equals';
        node.properties.value = safeString(node.properties.value) || 'high';
        node.properties.template = safeString(node.properties.template) || 'Workflow alert: {{subject}}';
        node.properties.operation = safeString(node.properties.operation) || 'set';
        node.properties.channel = safeString(node.properties.channel) || 'inbox';
        node.properties.autoApprove = Boolean(node.properties.autoApprove);
        node.pos = [...pos];
        return node;
    };
    const graphNodes = () => Array.isArray(graph?._nodes) ? graph._nodes : [];
    const selectedNode = () => graphNodes().find((node) => safeString(node?.id) === safeString(wb.selectedNodeId)) || null;
    const remember = () => {
        try {
            wb.graphData = graph.serialize();
        } catch (_error) {}
    };
    const parseRunInput = () => {
        const raw = safeString(runInputEl instanceof HTMLTextAreaElement ? runInputEl.value : wb.runInput);
        wb.runInput = raw;
        if (!raw.trim()) return {};
        try {
            const parsed = JSON.parse(raw);
            if (parsed && typeof parsed === 'object') return parsed;
            return { value: parsed };
        } catch (_error) {
            return { _raw: raw };
        }
    };
    const renderProjectSelect = () => {
        const select = shell.querySelector('select[data-wb-project-select="automations"]');
        if (!(select instanceof HTMLSelectElement)) return;
        const rows = moduleWorkbenchProjectList('automations');
        const current = safeString(wb.selectedProjectId);
        select.innerHTML = `<option value="">Select project</option>${rows.map((row) => `<option value="${escapeHtml(safeString(row.id))}">${escapeHtml(`${safeString(row.name)} (${new Date(Number(row.updatedAt) || Date.now()).toLocaleString()})`)}</option>`).join('')}`;
        select.value = rows.some((row) => safeString(row.id) === current) ? current : '';
    };
    const renderLogs = () => {
        logs.innerHTML = wb.logs.length
            ? wb.logs.slice(0, 14).map((entry) => `<article class="module-wb-log-item ${moduleToneClass(entry.tone) || 'ok'}"><span>${escapeHtml(safeString(entry.time))}</span><p>${escapeHtml(safeString(entry.message))}</p></article>`).join('')
            : '<div class="module-wb-ghost">No run logs yet.</div>';
    };
    const renderReport = () => {
        const run = wb.runReport && typeof wb.runReport === 'object' ? wb.runReport : null;
        if (!run) {
            report.innerHTML = '<div class="module-wb-ghost">Run report appears here after Test Run.</div>';
            return;
        }
        const pending = run.steps.filter((step) => Boolean(step.pendingApproval)).length;
        report.innerHTML = `
            <div class="module-wb-metrics">
                <div><span>Nodes</span><strong>${Number(run.nodeCount) || 0}</strong></div>
                <div><span>Edges</span><strong>${Number(run.edgeCount) || 0}</strong></div>
                <div><span>Pending</span><strong>${pending}</strong></div>
            </div>
            <div class="module-wb-log-list">
                ${run.steps.slice(0, 20).map((step) => `<article class="module-wb-log-item ${step.pendingApproval ? 'warn' : (step.pass ? 'ok' : 'error')}"><span>${escapeHtml(safeString(step.title))}</span><p>${escapeHtml(safeString(step.note))}</p></article>`).join('')}
            </div>
            <div class="module-wb-field module-wb-field-wide">
                <label>Final Payload</label>
                <textarea rows="7" readonly>${escapeHtml(JSON.stringify(run.finalPayload || {}, null, 2))}</textarea>
            </div>
            <div class="module-wb-field module-wb-field-wide">
                <label>Generated Outputs</label>
                <textarea rows="6" readonly>${escapeHtml(JSON.stringify(run.outputs || [], null, 2))}</textarea>
            </div>
        `;
    };
    const renderStatus = () => {
        const links = graph?.links ? Object.keys(graph.links).length : 0;
        status.textContent = `${graphNodes().length} nodes | ${links} links`;
    };
    const renderInspector = () => {
        const node = selectedNode();
        if (!node) {
            inspector.innerHTML = `<h4>Inspector</h4><p class="module-wb-mini-note">Select a node on the canvas to edit details.</p><div class="module-wb-metrics"><div><span>Nodes</span><strong>${graphNodes().length}</strong></div><div><span>Links</span><strong>${graph?.links ? Object.keys(graph.links).length : 0}</strong></div><div><span>Approvals</span><strong>${graphNodes().filter((entry) => Boolean(entry?.properties?.approval)).length}</strong></div></div>`;
            return;
        }
        inspector.innerHTML = `
            <h4>${escapeHtml(safeString(node.title) || 'Flow Block')}</h4>
            <div class="module-wb-field-grid">
                <label class="module-wb-field">Label<input type="text" data-flow-prop="title" value="${escapeHtml(safeString(node.title))}" /></label>
                <label class="module-wb-field">Kind<select data-flow-prop="kind">${['trigger', 'logic', 'action'].map((kind) => `<option value="${kind}"${safeString(node.properties?.kind) === kind ? ' selected' : ''}>${kind}</option>`).join('')}</select></label>
                <label class="module-wb-field module-wb-field-check"><input type="checkbox" data-flow-prop="approval" ${node.properties?.approval ? 'checked' : ''} />Require approval</label>
                <label class="module-wb-field">Field<input type="text" data-flow-prop="field" value="${escapeHtml(safeString(node.properties?.field) || 'priority')}" /></label>
                <label class="module-wb-field">Operator<select data-flow-prop="op">${[
                    ['equals', 'Equals'],
                    ['not_equals', 'Not equals'],
                    ['contains', 'Contains'],
                    ['not_contains', 'Not contains'],
                    ['gt', 'Greater than'],
                    ['lt', 'Less than'],
                    ['exists', 'Exists'],
                ].map(([value, label]) => `<option value="${value}"${safeString(node.properties?.op) === value ? ' selected' : ''}>${label}</option>`).join('')}</select></label>
                <label class="module-wb-field">Value<input type="text" data-flow-prop="value" value="${escapeHtml(safeString(node.properties?.value))}" /></label>
                <label class="module-wb-field">Operation<select data-flow-prop="operation">${[
                    ['set', 'Set'],
                    ['inc', 'Increment'],
                    ['append_tag', 'Append tag'],
                    ['delete', 'Delete'],
                ].map(([value, label]) => `<option value="${value}"${safeString(node.properties?.operation) === value ? ' selected' : ''}>${label}</option>`).join('')}</select></label>
                <label class="module-wb-field">Channel<input type="text" data-flow-prop="channel" value="${escapeHtml(safeString(node.properties?.channel) || 'inbox')}" /></label>
                <label class="module-wb-field module-wb-field-check"><input type="checkbox" data-flow-prop="autoApprove" ${node.properties?.autoApprove ? 'checked' : ''} />Auto-approve gate</label>
                <label class="module-wb-field module-wb-field-wide">Notes<textarea rows="5" data-flow-prop="notes">${escapeHtml(safeString(node.properties?.notes))}</textarea></label>
                <label class="module-wb-field module-wb-field-wide">Message Template<textarea rows="3" data-flow-prop="template">${escapeHtml(safeString(node.properties?.template) || 'Workflow alert: {{subject}}')}</textarea></label>
            </div>
            <div class="module-wb-inspector-actions">
                <button type="button" class="module-item-btn" data-flow-action="duplicate">Duplicate</button>
                <button type="button" class="module-item-btn" data-flow-action="delete">Delete</button>
            </div>
        `;
    };

    palette.innerHTML = blockDefs.map((block) => `<button type="button" class="module-wb-palette-btn" data-flow-node-type="${block.id}"><strong>${block.label}</strong><span>${block.kind}</span></button>`).join('');

    if (wb.graphData?.nodes?.length) {
        try {
            graph.configure(wb.graphData);
        } catch (_error) {
            wb.graphData = null;
        }
    }
    if (!graphNodes().length) {
        const trigger = createNode(blockDefs[0], [80, 140]);
        const action = createNode(blockDefs[4], [420, 140]);
        if (trigger) graph.add(trigger);
        if (action) graph.add(action);
        if (trigger && action) trigger.connect(0, action, 0);
    }
    remember();
    renderLogs();
    renderReport();
    renderProjectSelect();
    renderStatus();
    renderInspector();

    graph.onAfterChange = () => {
        remember();
        renderStatus();
        renderInspector();
        renderProjectSelect();
    };

    shell.addEventListener('click', (event) => {
        if (moduleWorkbenchHandleOssStackClick(event.target)) return;
        const projectActionEl = event.target instanceof Element
            ? event.target.closest('[data-wb-project-action][data-wb-project-mode="automations"]')
            : null;
        if (projectActionEl) {
            const action = safeString(projectActionEl.dataset.wbProjectAction).toLowerCase();
            const select = shell.querySelector('select[data-wb-project-select="automations"]');
            const input = shell.querySelector('input[data-wb-project-name="automations"]');
            const selectedId = safeString(select instanceof HTMLSelectElement ? select.value : wb.selectedProjectId);
            if (action === 'save') {
                remember();
                const savedId = moduleWorkbenchProjectSave('automations', {
                    graphData: wb.graphData || graph.serialize(),
                    runInput: wb.runInput,
                }, safeString(input instanceof HTMLInputElement ? input.value : ''));
                wb.selectedProjectId = savedId;
                if (input instanceof HTMLInputElement) input.value = '';
                moduleWorkbenchPushLog(wb.logs, 'Saved flow project.', 'ok', 80, 'flow-log');
                renderLogs();
                renderProjectSelect();
                return;
            }
            if (action === 'load') {
                if (!selectedId) return;
                const project = moduleWorkbenchProjectGet('automations', selectedId);
                if (!project?.payload) return;
                const payload = project.payload;
                graph.clear();
                wb.graphData = payload.graphData && typeof payload.graphData === 'object' ? payload.graphData : null;
                if (wb.graphData?.nodes?.length) {
                    try {
                        graph.configure(wb.graphData);
                    } catch (_error) {
                        wb.graphData = null;
                    }
                }
                wb.runInput = safeString(payload.runInput) || wb.runInput;
                if (runInputEl instanceof HTMLTextAreaElement) runInputEl.value = wb.runInput;
                wb.selectedProjectId = selectedId;
                remember();
                moduleWorkbenchPushLog(wb.logs, `Loaded project: ${safeString(project.name)}.`, 'ok', 80, 'flow-log');
                renderLogs();
                renderStatus();
                renderInspector();
                renderProjectSelect();
                return;
            }
            if (action === 'delete') {
                if (!selectedId) return;
                if (moduleWorkbenchProjectDelete('automations', selectedId)) {
                    wb.selectedProjectId = '';
                    moduleWorkbenchPushLog(wb.logs, 'Deleted flow project.', 'warn', 80, 'flow-log');
                    renderLogs();
                    renderProjectSelect();
                }
                return;
            }
        }
        const target = event.target instanceof Element ? event.target.closest('[data-flow-node-type], [data-flow-action]') : null;
        if (!target) return;
        const nodeType = safeString(target.dataset.flowNodeType);
        const action = safeString(target.dataset.flowAction).toLowerCase();
        if (nodeType) {
            const def = blockDefs.find((block) => block.id === nodeType) || blockDefs[0];
            const offset = graphNodes().length;
            const node = createNode(def, [80 + (offset * 30), 100 + (offset * 20)]);
            if (!node) return;
            graph.add(node);
            wb.selectedNodeId = safeString(node.id);
            moduleWorkbenchPushLog(wb.logs, `Added ${def.label}.`, 'ok', 80, 'flow-log');
            remember();
            renderLogs();
            renderStatus();
            renderInspector();
            return;
        }
        const node = selectedNode();
        if (action === 'run') {
            remember();
            const run = moduleAutomationRunGraphData(wb.graphData || graph.serialize(), parseRunInput());
            wb.runReport = run;
            moduleWorkbenchPushLog(wb.logs, `Run completed: ${run.steps.length} step(s), ${run.outputs.length} output(s).`, 'ok', 80, 'flow-log');
            renderLogs();
            renderReport();
            return;
        }
        if (action === 'run_dry') {
            remember();
            const run = moduleAutomationRunGraphData(wb.graphData || graph.serialize(), parseRunInput());
            wb.runReport = {
                ...run,
                outputs: [],
                steps: run.steps.map((step) => ({ ...step, note: `${safeString(step.note)} (dry run)` })),
            };
            moduleWorkbenchPushLog(wb.logs, `Dry run completed: ${run.steps.length} step(s).`, 'warn', 80, 'flow-log');
            renderLogs();
            renderReport();
            return;
        }
        if (action === 'export') {
            remember();
            moduleWorkbenchCopyJson(wb.graphData || graph.serialize(), 'Automation Flow JSON');
            return;
        }
        if (action === 'export_n8n') {
            remember();
            moduleWorkbenchCopyJson(moduleWorkbenchFlowToN8n(wb.graphData || graph.serialize()), 'n8n Workflow JSON');
            return;
        }
        if (action === 'export_nodered') {
            remember();
            moduleWorkbenchCopyJson(moduleWorkbenchFlowToNodeRed(wb.graphData || graph.serialize()), 'Node-RED Flow JSON');
            return;
        }
        if (action === 'reset') {
            graph.clear();
            wb.graphData = null;
            wb.selectedNodeId = '';
            wb.logs = [];
            wb.runReport = null;
            renderLogs();
            renderReport();
            renderStatus();
            renderInspector();
            return;
        }
        if (action === 'duplicate' && node) {
            const clone = createNode({
                id: safeString(node.properties?.blockType) || 'custom',
                kind: safeString(node.properties?.kind) || 'action',
                label: `${safeString(node.title) || 'Block'} Copy`,
            }, [Number(node.pos?.[0] || 80) + 42, Number(node.pos?.[1] || 80) + 32]);
            if (!clone) return;
            clone.properties.notes = safeString(node.properties?.notes);
            clone.properties.approval = Boolean(node.properties?.approval);
            clone.properties.field = safeString(node.properties?.field);
            clone.properties.op = safeString(node.properties?.op) || 'equals';
            clone.properties.value = safeString(node.properties?.value);
            clone.properties.template = safeString(node.properties?.template);
            clone.properties.operation = safeString(node.properties?.operation) || 'set';
            clone.properties.channel = safeString(node.properties?.channel) || 'inbox';
            clone.properties.autoApprove = Boolean(node.properties?.autoApprove);
            graph.add(clone);
            wb.selectedNodeId = safeString(clone.id);
            remember();
            renderStatus();
            renderInspector();
            return;
        }
        if (action === 'delete' && node) {
            graph.remove(node);
            wb.selectedNodeId = '';
            remember();
            renderStatus();
            renderInspector();
        }
    });

    inspector.addEventListener('input', (event) => {
        const target = event.target;
        if (!(target instanceof HTMLInputElement || target instanceof HTMLSelectElement || target instanceof HTMLTextAreaElement)) return;
        const node = selectedNode();
        if (!node) return;
        const prop = safeString(target.dataset.flowProp);
        if (!prop) return;
        if (prop === 'title') node.title = safeString(target.value).slice(0, 90);
        if (prop === 'kind') node.properties.kind = safeString(target.value);
        if (prop === 'notes') node.properties.notes = safeString(target.value).slice(0, 2200);
        if (prop === 'field') node.properties.field = safeString(target.value).slice(0, 140);
        if (prop === 'op') node.properties.op = safeString(target.value);
        if (prop === 'value') node.properties.value = safeString(target.value).slice(0, 400);
        if (prop === 'template') node.properties.template = safeString(target.value).slice(0, 1800);
        if (prop === 'operation') node.properties.operation = safeString(target.value);
        if (prop === 'channel') node.properties.channel = safeString(target.value).slice(0, 80);
        if (prop === 'approval' && target instanceof HTMLInputElement) node.properties.approval = target.checked;
        if (prop === 'autoApprove' && target instanceof HTMLInputElement) node.properties.autoApprove = target.checked;
        node.setDirtyCanvas(true, true);
        remember();
        renderStatus();
        renderReport();
    });

    if (runInputEl instanceof HTMLTextAreaElement) {
        runInputEl.addEventListener('input', () => {
            wb.runInput = safeString(runInputEl.value);
        });
    }
    const projectSelect = shell.querySelector('select[data-wb-project-select="automations"]');
    if (projectSelect instanceof HTMLSelectElement) {
        projectSelect.addEventListener('change', () => {
            wb.selectedProjectId = safeString(projectSelect.value);
        });
    }

    return true;
}

function moduleRenderWorkbenchAutomations(container, wb) {
    if (moduleRenderWorkbenchAutomationsOss(container, wb)) return;
    if (!container || !wb) return;
    if (!Array.isArray(wb.nodes)) wb.nodes = [];
    if (!Array.isArray(wb.edges)) wb.edges = [];
    if (!Array.isArray(wb.logs)) wb.logs = [];
    wb.selectedId = safeString(wb.selectedId);
    wb.connectingFrom = safeString(wb.connectingFrom);
    wb.nextId = Math.max(1, Number(wb.nextId) || 1);
    wb.runInput = safeString(wb.runInput) || '{\n  "subject": "Ops status",\n  "priority": "high"\n}';
    if (!wb.runReport || typeof wb.runReport !== 'object') wb.runReport = null;
    wb.selectedProjectId = safeString(wb.selectedProjectId);

    moduleWorkbenchHeader(container, 'Automation Flow Builder', 'Compose workflows Thomas runs end to end with live logs, approvals, and recovery visibility.');
    const shell = document.createElement('section');
    shell.className = 'module-wb-shell module-wb-shell-flow';
    shell.innerHTML = `
        <aside class="module-wb-side-card"><h4>Blocks</h4><div class="module-wb-palette" data-flow-palette></div>${moduleWorkbenchRenderProjectControls('automations', 'Flow Projects')}<label class="module-wb-field module-wb-field-wide">Run Input JSON<textarea rows="6" data-flow-run-input>${escapeHtml(wb.runInput)}</textarea></label><div class="module-wb-inspector-actions"><button type="button" class="module-item-btn" data-flow-action="run">Test Run</button><button type="button" class="module-item-btn" data-flow-action="run_dry">Dry Run</button><button type="button" class="module-item-btn" data-flow-action="export">Export</button><button type="button" class="module-item-btn" data-flow-action="export_n8n">n8n JSON</button><button type="button" class="module-item-btn" data-flow-action="export_nodered">Node-RED JSON</button><button type="button" class="module-item-btn" data-flow-action="clear">Reset</button></div></aside>
        <section class="module-wb-stage-card"><div class="module-wb-stage-head"><span class="module-wb-stage-title">Nodes + Links</span><span class="module-wb-stage-meta" data-flow-status></span></div><div class="module-wb-flow-list" data-flow-list></div><div class="module-wb-log-list" data-flow-logs></div><div class="module-wb-run-report" data-flow-report></div></section>
        <aside class="module-wb-inspector-card" data-flow-inspector></aside>
        ${moduleWorkbenchRenderOssStack('automations')}
    `;
    container.appendChild(shell);

    const blockDefs = [
        { id: 'schedule', kind: 'trigger', label: 'Schedule Trigger' },
        { id: 'email', kind: 'trigger', label: 'New Email Trigger' },
        { id: 'if_else', kind: 'logic', label: 'If / Else Branch' },
        { id: 'approval', kind: 'logic', label: 'Human Approval' },
        { id: 'send_message', kind: 'action', label: 'Send Message' },
        { id: 'run_script', kind: 'action', label: 'Run Script' },
    ];
    const byId = (id) => wb.nodes.find((node) => safeString(node.id) === safeString(id)) || null;
    const palette = shell.querySelector('[data-flow-palette]');
    const list = shell.querySelector('[data-flow-list]');
    const logs = shell.querySelector('[data-flow-logs]');
    const report = shell.querySelector('[data-flow-report]');
    const inspector = shell.querySelector('[data-flow-inspector]');
    const status = shell.querySelector('[data-flow-status]');
    const runInputEl = shell.querySelector('[data-flow-run-input]');

    const renderPalette = () => { palette.innerHTML = blockDefs.map((block) => `<button type="button" class="module-wb-palette-btn" data-flow-node-type="${block.id}"><strong>${block.label}</strong><span>${block.kind}</span></button>`).join(''); };
    const renderList = () => {
        list.innerHTML = wb.nodes.length ? wb.nodes.map((node) => `<article class="module-wb-list-item${safeString(node.id) === safeString(wb.selectedId) ? ' selected' : ''}" data-flow-node-id="${escapeHtml(safeString(node.id))}"><strong>${escapeHtml(safeString(node.label))}</strong><span>${escapeHtml(`${safeString(node.kind)} | ${safeString(node.type)}`)}</span><div class="module-wb-inline-actions"><button type="button" class="module-item-btn" data-flow-node-action="from" data-flow-node-id="${escapeHtml(safeString(node.id))}">From</button><button type="button" class="module-item-btn" data-flow-node-action="to" data-flow-node-id="${escapeHtml(safeString(node.id))}">To</button></div></article>`).join('') : '<div class="module-wb-ghost">Add your first workflow block.</div>';
    };
    const renderLogs = () => { logs.innerHTML = wb.logs.length ? wb.logs.slice(0, 16).map((entry) => `<article class="module-wb-log-item ${moduleToneClass(entry.tone) || 'ok'}"><span>${escapeHtml(safeString(entry.time))}</span><p>${escapeHtml(safeString(entry.message))}</p></article>`).join('') : '<div class="module-wb-ghost">No flow logs yet.</div>'; };
    const renderInspector = () => {
        const node = byId(wb.selectedId);
        if (!node) {
            inspector.innerHTML = `<h4>Inspector</h4><p class="module-wb-mini-note">Select a node to edit it.</p><div class="module-wb-metrics"><div><span>Nodes</span><strong>${wb.nodes.length}</strong></div><div><span>Links</span><strong>${wb.edges.length}</strong></div><div><span>Connect</span><strong>${wb.connectingFrom ? escapeHtml(wb.connectingFrom) : 'idle'}</strong></div></div>`;
            return;
        }
        inspector.innerHTML = `<h4>${escapeHtml(safeString(node.label))}</h4><div class="module-wb-field-grid"><label class="module-wb-field">Label<input type="text" data-flow-prop="label" value="${escapeHtml(safeString(node.label))}" /></label><label class="module-wb-field">Type<select data-flow-prop="type">${blockDefs.map((block) => `<option value="${block.id}"${safeString(node.type) === block.id ? ' selected' : ''}>${block.label}</option>`).join('')}</select></label><label class="module-wb-field module-wb-field-check"><input type="checkbox" data-flow-prop="approval" ${node.approval ? 'checked' : ''} />Require approval</label><label class="module-wb-field module-wb-field-wide">Notes<textarea rows="4" data-flow-prop="notes">${escapeHtml(safeString(node.notes))}</textarea></label></div><div class="module-wb-inspector-actions"><button type="button" class="module-item-btn" data-flow-node-action="duplicate">Duplicate</button><button type="button" class="module-item-btn" data-flow-node-action="delete">Delete</button></div>`;
    };
    const renderStatus = () => { status.textContent = `${wb.nodes.length} nodes | ${wb.edges.length} links${wb.connectingFrom ? ` | from ${wb.connectingFrom}` : ''}`; };
    const renderAll = () => { renderList(); renderLogs(); renderReport(); renderInspector(); renderStatus(); renderProjectSelect(); };

    renderPalette();
    renderAll();

    const toGraphData = () => {
        const nodeId = (idRaw, fallback) => {
            const match = safeString(idRaw).match(/\d+/);
            return Number(match?.[0]) || fallback;
        };
        const nodes = wb.nodes.map((node, index) => ({
            id: nodeId(node.id, index + 1),
            title: safeString(node.label) || `Flow ${index + 1}`,
            pos: [120 + (index * 34), 120 + (index * 22)],
            properties: {
                kind: safeString(node.kind) || 'action',
                blockType: safeString(node.type) || 'custom',
                notes: safeString(node.notes),
                approval: Boolean(node.approval),
            },
        }));
        const links = {};
        wb.edges.forEach((edge, index) => {
            const from = nodeId(edge.from, index + 1);
            const to = nodeId(edge.to, index + 2);
            links[index + 1] = [index + 1, from, 0, to, 0, 'flow'];
        });
        return { nodes, links };
    };
    const parseRunInput = () => {
        const raw = safeString(runInputEl instanceof HTMLTextAreaElement ? runInputEl.value : wb.runInput);
        wb.runInput = raw;
        if (!raw.trim()) return {};
        try {
            const parsed = JSON.parse(raw);
            return parsed && typeof parsed === 'object' ? parsed : { value: parsed };
        } catch (_error) {
            return { _raw: raw };
        }
    };
    const renderReport = () => {
        const run = wb.runReport && typeof wb.runReport === 'object' ? wb.runReport : null;
        if (!report) return;
        if (!run) {
            report.innerHTML = '<div class="module-wb-ghost">Run report appears here after Test Run.</div>';
            return;
        }
        report.innerHTML = `
            <div class="module-wb-metrics"><div><span>Nodes</span><strong>${Number(run.nodeCount) || 0}</strong></div><div><span>Edges</span><strong>${Number(run.edgeCount) || 0}</strong></div><div><span>Outputs</span><strong>${Array.isArray(run.outputs) ? run.outputs.length : 0}</strong></div></div>
            <div class="module-wb-log-list">${(Array.isArray(run.steps) ? run.steps : []).slice(0, 20).map((step) => `<article class="module-wb-log-item ${step.pendingApproval ? 'warn' : (step.pass ? 'ok' : 'error')}"><span>${escapeHtml(safeString(step.title))}</span><p>${escapeHtml(safeString(step.note))}</p></article>`).join('')}</div>
        `;
    };
    const renderProjectSelect = () => {
        const select = shell.querySelector('select[data-wb-project-select="automations"]');
        if (!(select instanceof HTMLSelectElement)) return;
        const rows = moduleWorkbenchProjectList('automations');
        const current = safeString(wb.selectedProjectId);
        select.innerHTML = `<option value="">Select project</option>${rows.map((row) => `<option value="${escapeHtml(safeString(row.id))}">${escapeHtml(`${safeString(row.name)} (${new Date(Number(row.updatedAt) || Date.now()).toLocaleString()})`)}</option>`).join('')}`;
        select.value = rows.some((row) => safeString(row.id) === current) ? current : '';
    };

    shell.addEventListener('click', (event) => {
        if (moduleWorkbenchHandleOssStackClick(event.target)) return;
        const projectActionEl = event.target instanceof Element
            ? event.target.closest('[data-wb-project-action][data-wb-project-mode="automations"]')
            : null;
        if (projectActionEl) {
            const action = safeString(projectActionEl.dataset.wbProjectAction).toLowerCase();
            const select = shell.querySelector('select[data-wb-project-select="automations"]');
            const input = shell.querySelector('input[data-wb-project-name="automations"]');
            const selectedId = safeString(select instanceof HTMLSelectElement ? select.value : wb.selectedProjectId);
            if (action === 'save') {
                wb.selectedProjectId = moduleWorkbenchProjectSave('automations', {
                    nodes: wb.nodes,
                    edges: wb.edges,
                    runInput: wb.runInput,
                }, safeString(input instanceof HTMLInputElement ? input.value : ''));
                if (input instanceof HTMLInputElement) input.value = '';
                renderAll();
                return;
            }
            if (action === 'load') {
                if (!selectedId) return;
                const project = moduleWorkbenchProjectGet('automations', selectedId);
                if (!project?.payload) return;
                wb.nodes = Array.isArray(project.payload.nodes) ? project.payload.nodes : [];
                wb.edges = Array.isArray(project.payload.edges) ? project.payload.edges : [];
                wb.runInput = safeString(project.payload.runInput) || wb.runInput;
                if (runInputEl instanceof HTMLTextAreaElement) runInputEl.value = wb.runInput;
                wb.selectedProjectId = selectedId;
                renderAll();
                return;
            }
            if (action === 'delete') {
                if (!selectedId) return;
                moduleWorkbenchProjectDelete('automations', selectedId);
                wb.selectedProjectId = '';
                renderAll();
                return;
            }
        }
        const target = event.target instanceof Element ? event.target.closest('[data-flow-node-type], [data-flow-action], [data-flow-node-id], [data-flow-node-action]') : null;
        if (!target) return;
        const type = safeString(target.dataset.flowNodeType);
        const action = safeString(target.dataset.flowAction).toLowerCase();
        const nodeAction = safeString(target.dataset.flowNodeAction).toLowerCase();
        const nodeId = safeString(target.dataset.flowNodeId);

        if (type) {
            const def = blockDefs.find((item) => item.id === type) || blockDefs[0];
            const id = `flow-${wb.nextId++}`;
            wb.nodes.push({ id, type: def.id, kind: def.kind, label: def.label, approval: false, notes: '' });
            wb.selectedId = id;
            moduleWorkbenchPushLog(wb.logs, `Added ${def.label}.`, 'ok', 80, 'flow-log');
            renderAll();
            return;
        }
        if (action) {
            if (action === 'run') {
                const run = moduleAutomationRunGraphData(toGraphData(), parseRunInput());
                wb.runReport = run;
                moduleWorkbenchPushLog(wb.logs, `Run completed: ${run.steps.length} step(s), ${run.outputs.length} output(s).`, 'ok', 80, 'flow-log');
            } else if (action === 'run_dry') {
                const run = moduleAutomationRunGraphData(toGraphData(), parseRunInput());
                wb.runReport = {
                    ...run,
                    outputs: [],
                    steps: run.steps.map((step) => ({ ...step, note: `${safeString(step.note)} (dry run)` })),
                };
                moduleWorkbenchPushLog(wb.logs, `Dry run completed: ${run.steps.length} step(s).`, 'warn', 80, 'flow-log');
            } else if (action === 'clear') {
                wb.nodes = [];
                wb.edges = [];
                wb.logs = [];
                wb.selectedId = '';
                wb.connectingFrom = '';
                wb.runReport = null;
            } else if (action === 'export') {
                moduleWorkbenchCopyJson({ nodes: wb.nodes, edges: wb.edges }, 'Automation Flow JSON');
            } else if (action === 'export_n8n') {
                moduleWorkbenchCopyJson(moduleWorkbenchFlowToN8n(toGraphData()), 'n8n Workflow JSON');
            } else if (action === 'export_nodered') {
                moduleWorkbenchCopyJson(moduleWorkbenchFlowToNodeRed(toGraphData()), 'Node-RED Flow JSON');
            }
            renderAll();
            return;
        }
        if (nodeId) wb.selectedId = nodeId;
        if (nodeAction === 'from') wb.connectingFrom = nodeId;
        if (nodeAction === 'to' && wb.connectingFrom && nodeId && wb.connectingFrom !== nodeId) {
            const exists = wb.edges.some((edge) => safeString(edge.from) === wb.connectingFrom && safeString(edge.to) === nodeId);
            if (!exists) wb.edges.push({ id: moduleWorkbenchMakeId('edge'), from: wb.connectingFrom, to: nodeId });
            wb.connectingFrom = '';
        }
        if (nodeAction === 'duplicate') {
            const node = byId(wb.selectedId);
            if (node) {
                const copy = { ...node, id: `flow-${wb.nextId++}`, label: `${node.label} Copy` };
                wb.nodes.push(copy);
                wb.selectedId = copy.id;
            }
        }
        if (nodeAction === 'delete') {
            wb.nodes = wb.nodes.filter((node) => safeString(node.id) !== safeString(wb.selectedId));
            wb.edges = wb.edges.filter((edge) => safeString(edge.from) !== safeString(wb.selectedId) && safeString(edge.to) !== safeString(wb.selectedId));
            wb.selectedId = '';
            wb.connectingFrom = '';
        }
        renderAll();
    });

    if (inspector) {
        inspector.addEventListener('input', (event) => {
            const target = event.target;
            if (!(target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement)) return;
            const node = byId(wb.selectedId);
            if (!node) return;
            const prop = safeString(target.dataset.flowProp);
            if (!prop) return;
            if (prop === 'label' || prop === 'notes') node[prop] = safeString(target.value).slice(0, 2000);
            if (prop === 'type') {
                node.type = safeString(target.value);
                const def = blockDefs.find((item) => item.id === node.type);
                if (def) node.kind = def.kind;
            }
            if (prop === 'approval' && target instanceof HTMLInputElement) node.approval = target.checked;
            renderAll();
        });
    }
    if (runInputEl instanceof HTMLTextAreaElement) {
        runInputEl.addEventListener('input', () => {
            wb.runInput = safeString(runInputEl.value);
        });
    }
    const projectSelect = shell.querySelector('select[data-wb-project-select="automations"]');
    if (projectSelect instanceof HTMLSelectElement) {
        projectSelect.addEventListener('change', () => {
            wb.selectedProjectId = safeString(projectSelect.value);
        });
    }
}

function moduleWorkbenchAppSchemaToAppsmith(wb) {
    const components = Array.isArray(wb?.components) ? wb.components : [];
    const widgets = components.map((component, index) => ({
        widgetName: safeString(component.label) || `Widget${index + 1}`,
        type: safeString(component.type).toUpperCase() || 'CONTAINER_WIDGET',
        topRow: (Number(component.y) || 0) * 10,
        bottomRow: ((Number(component.y) || 0) + (Number(component.h) || 1)) * 10,
        leftColumn: (Number(component.x) || 0) * 8,
        rightColumn: ((Number(component.x) || 0) + (Number(component.w) || 1)) * 8,
        dynamicBindingPathList: safeString(component.binding) ? [{ key: 'defaultValue' }] : [],
    }));
    return {
        pageName: 'ThomasApp',
        layout: safeString(wb?.device) === 'mobile' ? 'MOBILE' : 'DESKTOP',
        dsl: {
            widgetName: 'MainContainer',
            type: 'CANVAS_WIDGET',
            children: widgets,
        },
    };
}

function moduleWorkbenchAppSchemaToBudibase(wb) {
    const components = Array.isArray(wb?.components) ? wb.components : [];
    return {
        app: {
            name: 'Thomas Internal Tool',
            device: safeString(wb?.device) === 'mobile' ? 'mobile' : 'desktop',
            screens: [
                {
                    name: 'Main',
                    components: components.map((component, index) => ({
                        id: safeString(component.id) || `c${index + 1}`,
                        type: safeString(component.type) || 'table',
                        label: safeString(component.label) || `Component ${index + 1}`,
                        binding: safeString(component.binding),
                        requiredRole: Boolean(component.required),
                        layout: {
                            x: Number(component.x) || 0,
                            y: Number(component.y) || 0,
                            w: Number(component.w) || 4,
                            h: Number(component.h) || 3,
                        },
                    })),
                },
            ],
        },
    };
}

function moduleWorkbenchAppPreviewWidget(componentRaw) {
    const component = componentRaw && typeof componentRaw === 'object' ? componentRaw : {};
    const type = safeString(component.type) || 'table';
    const label = safeString(component.label) || 'Widget';
    const binding = safeString(component.binding) || '';
    if (type === 'form') {
        return `<form class="wb-preview-form"><label>Name<input placeholder="Type..." /></label><label>Email<input type="email" placeholder="you@team.com" /></label><button type="button">${escapeHtml(label)}</button><small>${escapeHtml(binding || 'form.input')}</small></form>`;
    }
    if (type === 'chart') {
        return `<div class="wb-preview-chart"><div style="height:58%"></div><div style="height:34%"></div><div style="height:72%"></div><div style="height:46%"></div><small>${escapeHtml(binding || 'metrics.series')}</small></div>`;
    }
    if (type === 'button') {
        return `<div class="wb-preview-button-wrap"><button type="button">${escapeHtml(label)}</button><small>${escapeHtml(binding || 'action.trigger')}</small></div>`;
    }
    if (type === 'modal') {
        return `<div class="wb-preview-modal"><header>${escapeHtml(label)}</header><p>Modal body content with approval context and action buttons.</p><footer><button type="button">Cancel</button><button type="button">Confirm</button></footer></div>`;
    }
    if (type === 'tabs') {
        return `<div class="wb-preview-tabs"><nav><button type="button" class="active">Overview</button><button type="button">Details</button><button type="button">History</button></nav><section>Tab content for ${escapeHtml(label)}</section></div>`;
    }
    return `<div class="wb-preview-table"><header>${escapeHtml(label)}</header><table><thead><tr><th>ID</th><th>Name</th><th>Status</th></tr></thead><tbody><tr><td>1</td><td>Alpha</td><td>Active</td></tr><tr><td>2</td><td>Beta</td><td>Pending</td></tr></tbody></table><small>${escapeHtml(binding || 'data.table')}</small></div>`;
}

function moduleWorkbenchAppRuntimeHtml(wb) {
    const components = Array.isArray(wb?.components) ? wb.components : [];
    const sorted = components
        .slice()
        .sort((a, b) => (Number(a?.y) - Number(b?.y)) || (Number(a?.x) - Number(b?.x)));
    const columns = safeString(wb?.device) === 'mobile' ? 4 : 12;
    const blocks = sorted.map((component) => {
        const span = moduleWorkbenchClamp(Number(component?.w) || 3, 1, columns);
        const rowSpan = moduleWorkbenchClamp(Number(component?.h) || 2, 1, 8);
        return `
            <article class="wb-preview-card" style="grid-column: span ${span}; grid-row: span ${rowSpan};">
                <header>
                    <strong>${escapeHtml(safeString(component?.label) || 'Widget')}</strong>
                    <span>${escapeHtml(safeString(component?.type) || 'table')}</span>
                </header>
                ${moduleWorkbenchAppPreviewWidget(component)}
            </article>
        `;
    }).join('');
    return `
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Thomas App Preview</title>
<style>
* { box-sizing: border-box; }
body { margin: 0; background: #0b1726; color: #eaf4ff; font: 13px/1.4 "Segoe UI", system-ui, sans-serif; }
.wb-shell { padding: 14px; display: grid; gap: 10px; }
.wb-shell h1 { margin: 0; font-size: 16px; font-weight: 700; }
.wb-grid { display: grid; grid-template-columns: repeat(${columns}, minmax(0, 1fr)); gap: 8px; }
.wb-preview-card { border: 1px solid rgba(130, 178, 235, 0.35); border-radius: 10px; background: linear-gradient(180deg, rgba(18, 37, 59, 0.95), rgba(11, 22, 37, 0.95)); padding: 8px; display: grid; gap: 8px; min-height: 90px; }
.wb-preview-card > header { display: flex; justify-content: space-between; align-items: center; gap: 6px; }
.wb-preview-card > header strong { font-size: 12px; }
.wb-preview-card > header span { font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; color: #9eb7d4; }
.wb-preview-table table { width: 100%; border-collapse: collapse; font-size: 11px; }
.wb-preview-table th, .wb-preview-table td { border: 1px solid rgba(130, 178, 235, 0.24); padding: 4px 6px; text-align: left; }
.wb-preview-form { display: grid; gap: 6px; }
.wb-preview-form label { display: grid; gap: 4px; font-size: 11px; color: #b9cde7; }
.wb-preview-form input { border: 1px solid rgba(130, 178, 235, 0.3); border-radius: 7px; background: rgba(6, 14, 22, 0.8); color: #f1f7ff; padding: 6px 8px; }
.wb-preview-form button, .wb-preview-button-wrap button, .wb-preview-modal button, .wb-preview-tabs button { border: 1px solid rgba(130, 178, 235, 0.36); border-radius: 8px; background: rgba(80, 141, 212, 0.24); color: #eff7ff; padding: 6px 8px; cursor: pointer; }
.wb-preview-chart { min-height: 96px; display: flex; align-items: end; gap: 6px; }
.wb-preview-chart > div { flex: 1; border-radius: 6px 6px 3px 3px; background: linear-gradient(180deg, #8fcbff, #3d7dcc); }
.wb-preview-modal { display: grid; gap: 8px; }
.wb-preview-modal header { font-weight: 700; }
.wb-preview-modal footer { display: flex; gap: 6px; }
.wb-preview-tabs { display: grid; gap: 8px; }
.wb-preview-tabs nav { display: flex; gap: 6px; }
.wb-preview-tabs nav button.active { background: rgba(116, 201, 169, 0.25); border-color: rgba(116, 201, 169, 0.55); }
small { color: #9ab5d4; font-size: 10px; }
</style>
</head>
<body>
<main class="wb-shell">
    <h1>Thomas Runtime Preview</h1>
    <section class="wb-grid">
        ${blocks || '<article class="wb-preview-card"><p>No components in this app yet.</p></article>'}
    </section>
</main>
</body>
</html>
    `.trim();
}

function moduleRenderWorkbenchAppBuilderOss(container, wb) {
    if (!container || !wb) return false;
    if (wb.ossError) return false;
    if (!wb.ossReady || !window.GridStack) {
        moduleWorkbenchRenderEngineLoading(
            container,
            'App Builder Layout Engine',
            'GridStack drag/resize UI builder with component schema export.',
            'Loading GridStack...',
            'Fallback list editor will open if engine loading fails.',
        );
        if (!wb.ossLoading) {
            wb.ossLoading = true;
            void moduleWorkbenchLoadGridStack().then(() => {
                wb.ossReady = true;
                wb.ossLoading = false;
                wb.ossError = '';
                moduleWorkbenchRefreshMode('app_builder');
            }).catch((error) => {
                wb.ossLoading = false;
                wb.ossReady = false;
                wb.ossError = safeString(error?.message) || 'Failed to load GridStack.';
                notifyUser('GridStack failed to load, using fallback builder list.', { tone: 'warn', durationMs: 2300, debugKind: 'app-builder' });
                moduleWorkbenchRefreshMode('app_builder');
            });
        }
        return true;
    }

    if (!Array.isArray(wb.components)) wb.components = [];
    wb.device = safeString(wb.device) === 'mobile' ? 'mobile' : 'desktop';
    wb.selectedId = safeString(wb.selectedId);
    wb.nextId = Math.max(1, Number(wb.nextId) || 1);
    wb.selectedProjectId = safeString(wb.selectedProjectId);
    wb.previewHtml = safeString(wb.previewHtml);

    const defs = [
        { id: 'table', label: 'Table', w: 4, h: 3 },
        { id: 'form', label: 'Form', w: 4, h: 4 },
        { id: 'chart', label: 'Chart', w: 5, h: 4 },
        { id: 'button', label: 'Button', w: 3, h: 2 },
        { id: 'modal', label: 'Modal', w: 6, h: 5 },
        { id: 'tabs', label: 'Tabs', w: 5, h: 3 },
    ];

    moduleWorkbenchHeader(container, 'App Builder Layout Engine', 'Describe intent and let Thomas generate/edit app layouts while you validate structure and publish readiness.');
    const shell = document.createElement('section');
    shell.className = 'module-wb-shell module-wb-shell-app-oss';
    shell.innerHTML = `
        <aside class="module-wb-side-card">
            <h4>Components</h4>
            <div class="module-wb-palette" data-app-palette></div>
            ${moduleWorkbenchRenderProjectControls('app_builder', 'App Projects')}
            <div class="module-wb-inspector-actions">
                <button type="button" class="module-item-btn" data-app-action="preview">Preview</button>
                <button type="button" class="module-item-btn" data-app-action="publish">Publish</button>
                <button type="button" class="module-item-btn" data-app-action="export">Export</button>
                <button type="button" class="module-item-btn" data-app-action="export_html">Export HTML</button>
                <button type="button" class="module-item-btn" data-app-action="open_preview">Open Preview</button>
                <button type="button" class="module-item-btn" data-app-action="export_appsmith">Appsmith JSON</button>
                <button type="button" class="module-item-btn" data-app-action="export_budibase">Budibase JSON</button>
                <button type="button" class="module-item-btn" data-app-action="reset">Reset</button>
            </div>
        </aside>
        <section class="module-wb-stage-card">
            <div class="module-wb-stage-head"><span class="module-wb-stage-title">Layout Canvas</span><span class="module-wb-stage-meta" data-app-status></span></div>
            <div class="module-wb-device-switch">
                <button type="button" class="module-item-btn" data-app-device="desktop">Desktop</button>
                <button type="button" class="module-item-btn" data-app-device="mobile">Mobile</button>
            </div>
            <div class="module-wb-gridstack-shell${wb.device === 'mobile' ? ' mobile-mode' : ''}">
                <div class="grid-stack module-wb-gridstack" data-app-grid></div>
            </div>
            <div class="module-wb-preview-frame-wrap">
                <div class="module-wb-stage-head"><span class="module-wb-stage-title">Runtime Preview</span><span class="module-wb-stage-meta">live</span></div>
                <iframe class="module-wb-preview-frame" data-app-preview sandbox="allow-scripts"></iframe>
            </div>
        </section>
        <aside class="module-wb-inspector-card" data-app-inspector></aside>
        ${moduleWorkbenchRenderOssStack('app_builder')}
    `;
    container.appendChild(shell);

    const palette = shell.querySelector('[data-app-palette]');
    const gridEl = shell.querySelector('[data-app-grid]');
    const previewFrame = shell.querySelector('[data-app-preview]');
    const status = shell.querySelector('[data-app-status]');
    const inspector = shell.querySelector('[data-app-inspector]');
    if (!(palette instanceof HTMLElement) || !(gridEl instanceof HTMLElement) || !(previewFrame instanceof HTMLIFrameElement) || !(status instanceof HTMLElement) || !(inspector instanceof HTMLElement)) {
        return false;
    }

    if (wb.ossGrid?.destroy) {
        try {
            wb.ossGrid.destroy(false);
        } catch (_error) {}
        wb.ossGrid = null;
    }

    const byId = (idRaw) => wb.components.find((row) => safeString(row?.id) === safeString(idRaw)) || null;
    const findWidgetById = (idRaw) => {
        const id = safeString(idRaw);
        return Array.from(gridEl.querySelectorAll('.grid-stack-item')).find((element) => safeString(element.getAttribute('gs-id')) === id) || null;
    };
    const safeWidget = (raw, index = 0) => ({
        id: safeString(raw?.id) || `ui-${wb.nextId + index}`,
        type: safeString(raw?.type) || 'table',
        label: safeString(raw?.label) || 'Widget',
        binding: safeString(raw?.binding),
        required: Boolean(raw?.required),
        x: moduleWorkbenchClamp(Number(raw?.x) || 0, 0, 120),
        y: moduleWorkbenchClamp(Number(raw?.y) || 0, 0, 200),
        w: moduleWorkbenchClamp(Number(raw?.w) || 4, 1, 12),
        h: moduleWorkbenchClamp(Number(raw?.h) || 3, 1, 12),
    });
    wb.components = wb.components.map((component, index) => safeWidget(component, index));
    if (!wb.components.length) {
        wb.components.push({
            id: `ui-${wb.nextId++}`,
            type: 'table',
            label: 'Primary Table',
            binding: 'data.table',
            required: false,
            x: 0,
            y: 0,
            w: 5,
            h: 3,
        });
    }

    const widgetMarkup = (component) => `
        <div class="module-wb-app-widget" data-app-widget-id="${escapeHtml(safeString(component.id))}">
            <strong>${escapeHtml(safeString(component.label))}</strong>
            <span>${escapeHtml(safeString(component.type))}</span>
            <small>${escapeHtml(safeString(component.binding) || 'unbound')}</small>
        </div>
    `;

    const grid = window.GridStack.init({
        float: true,
        cellHeight: 84,
        margin: 8,
        disableOneColumnMode: false,
    }, gridEl);
    wb.ossGrid = grid;

    const syncSelection = () => {
        Array.from(gridEl.querySelectorAll('.grid-stack-item')).forEach((item) => {
            const id = safeString(item.getAttribute('gs-id'));
            item.classList.toggle('selected', id === wb.selectedId);
        });
    };
    const refreshWidgetContent = (component) => {
        const item = findWidgetById(component.id);
        if (!item) return;
        const content = item.querySelector('.module-wb-app-widget');
        if (content) {
            content.innerHTML = `<strong>${escapeHtml(safeString(component.label))}</strong><span>${escapeHtml(safeString(component.type))}</span><small>${escapeHtml(safeString(component.binding) || 'unbound')}</small>`;
        }
    };
    const renderInspector = () => {
        const component = byId(wb.selectedId);
        if (!component) {
            inspector.innerHTML = `<h4>Inspector</h4><p class="module-wb-mini-note">Select a widget to edit its bindings and dimensions.</p><div class="module-wb-metrics"><div><span>Widgets</span><strong>${wb.components.length}</strong></div><div><span>Device</span><strong>${escapeHtml(wb.device)}</strong></div><div><span>Roles</span><strong>${wb.components.filter((row) => row.required).length}</strong></div></div>`;
            syncSelection();
            return;
        }
        inspector.innerHTML = `
            <h4>${escapeHtml(safeString(component.label))}</h4>
            <div class="module-wb-field-grid">
                <label class="module-wb-field">Label<input type="text" data-app-prop="label" value="${escapeHtml(safeString(component.label))}" /></label>
                <label class="module-wb-field">Type<select data-app-prop="type">${defs.map((entry) => `<option value="${entry.id}"${component.type === entry.id ? ' selected' : ''}>${entry.label}</option>`).join('')}</select></label>
                <label class="module-wb-field">X<input type="number" data-app-prop="x" min="0" value="${component.x}" /></label>
                <label class="module-wb-field">Y<input type="number" data-app-prop="y" min="0" value="${component.y}" /></label>
                <label class="module-wb-field">W<input type="number" data-app-prop="w" min="1" max="12" value="${component.w}" /></label>
                <label class="module-wb-field">H<input type="number" data-app-prop="h" min="1" max="12" value="${component.h}" /></label>
                <label class="module-wb-field module-wb-field-wide">Binding<input type="text" data-app-prop="binding" value="${escapeHtml(safeString(component.binding))}" placeholder="crm.customers" /></label>
                <label class="module-wb-field module-wb-field-check"><input type="checkbox" data-app-prop="required" ${component.required ? 'checked' : ''} />Require role gate</label>
            </div>
            <div class="module-wb-inspector-actions">
                <button type="button" class="module-item-btn" data-app-action="duplicate">Duplicate</button>
                <button type="button" class="module-item-btn" data-app-action="delete">Delete</button>
            </div>
        `;
        syncSelection();
    };
    const renderStatus = () => {
        status.textContent = `${wb.components.length} widget(s) | ${wb.device.toUpperCase()} mode`;
        shell.querySelectorAll('[data-app-device]').forEach((button) => button.classList.toggle('active', safeString(button.dataset.appDevice) === wb.device));
    };
    const renderProjectSelect = () => {
        const select = shell.querySelector('select[data-wb-project-select="app_builder"]');
        if (!(select instanceof HTMLSelectElement)) return;
        const rows = moduleWorkbenchProjectList('app_builder');
        const current = safeString(wb.selectedProjectId);
        select.innerHTML = `<option value="">Select project</option>${rows.map((row) => `<option value="${escapeHtml(safeString(row.id))}">${escapeHtml(`${safeString(row.name)} (${new Date(Number(row.updatedAt) || Date.now()).toLocaleString()})`)}</option>`).join('')}`;
        select.value = rows.some((row) => safeString(row.id) === current) ? current : '';
    };
    const renderPreview = () => {
        wb.previewHtml = moduleWorkbenchAppRuntimeHtml(wb);
        previewFrame.srcdoc = wb.previewHtml;
    };
    const syncFromGridItems = (itemsRaw) => {
        const items = Array.isArray(itemsRaw) ? itemsRaw : [];
        items.forEach((item) => {
            const id = safeString(item?.id || item?.el?.getAttribute?.('gs-id'));
            const component = byId(id);
            if (!component) return;
            component.x = moduleWorkbenchClamp(Number(item.x) || component.x, 0, 120);
            component.y = moduleWorkbenchClamp(Number(item.y) || component.y, 0, 200);
            component.w = moduleWorkbenchClamp(Number(item.w) || component.w, 1, 12);
            component.h = moduleWorkbenchClamp(Number(item.h) || component.h, 1, 12);
        });
    };

    palette.innerHTML = defs.map((entry) => `<button type="button" class="module-wb-palette-btn" data-app-component="${entry.id}"><strong>${entry.label}</strong><span>${entry.w} x ${entry.h}</span></button>`).join('');

    wb.components.forEach((component) => {
        grid.addWidget({
            id: component.id,
            x: component.x,
            y: component.y,
            w: component.w,
            h: component.h,
            content: widgetMarkup(component),
        });
    });
    if (!wb.selectedId && wb.components[0]) wb.selectedId = safeString(wb.components[0].id);
    grid.column(wb.device === 'mobile' ? 4 : 12, 'moveScale');
    renderStatus();
    renderInspector();
    renderProjectSelect();
    renderPreview();

    grid.on('change', (_event, items) => {
        syncFromGridItems(items);
        renderStatus();
        renderInspector();
        renderPreview();
    });

    shell.addEventListener('click', (event) => {
        if (moduleWorkbenchHandleOssStackClick(event.target)) return;
        const projectActionEl = event.target instanceof Element
            ? event.target.closest('[data-wb-project-action][data-wb-project-mode="app_builder"]')
            : null;
        if (projectActionEl) {
            const action = safeString(projectActionEl.dataset.wbProjectAction).toLowerCase();
            const select = shell.querySelector('select[data-wb-project-select="app_builder"]');
            const input = shell.querySelector('input[data-wb-project-name="app_builder"]');
            const selectedId = safeString(select instanceof HTMLSelectElement ? select.value : wb.selectedProjectId);
            if (action === 'save') {
                const savedId = moduleWorkbenchProjectSave('app_builder', {
                    device: wb.device,
                    components: wb.components,
                }, safeString(input instanceof HTMLInputElement ? input.value : ''));
                wb.selectedProjectId = savedId;
                if (input instanceof HTMLInputElement) input.value = '';
                renderProjectSelect();
                notifyUser('App project saved.', { tone: 'success', durationMs: 1600, debugKind: 'app-builder' });
                return;
            }
            if (action === 'load') {
                if (!selectedId) return;
                const project = moduleWorkbenchProjectGet('app_builder', selectedId);
                if (!project?.payload) return;
                const payload = project.payload;
                const components = Array.isArray(payload.components) ? payload.components : [];
                grid.removeAll(false);
                wb.components = components.map((component, index) => safeWidget(component, index));
                wb.device = safeString(payload.device) === 'mobile' ? 'mobile' : 'desktop';
                wb.components.forEach((component) => {
                    grid.addWidget({
                        id: component.id,
                        x: component.x,
                        y: component.y,
                        w: component.w,
                        h: component.h,
                        content: widgetMarkup(component),
                    });
                });
                wb.selectedId = wb.components[0] ? safeString(wb.components[0].id) : '';
                wb.selectedProjectId = selectedId;
                grid.column(wb.device === 'mobile' ? 4 : 12, 'moveScale');
                shell.querySelector('.module-wb-gridstack-shell')?.classList.toggle('mobile-mode', wb.device === 'mobile');
                renderStatus();
                renderInspector();
                renderPreview();
                renderProjectSelect();
                notifyUser(`Loaded app project: ${safeString(project.name)}.`, { tone: 'success', durationMs: 1800, debugKind: 'app-builder' });
                return;
            }
            if (action === 'delete') {
                if (!selectedId) return;
                if (moduleWorkbenchProjectDelete('app_builder', selectedId)) {
                    wb.selectedProjectId = '';
                    renderProjectSelect();
                    notifyUser('Deleted app project.', { tone: 'warn', durationMs: 1700, debugKind: 'app-builder' });
                }
                return;
            }
        }
        const target = event.target instanceof Element ? event.target.closest('[data-app-component], [data-app-action], [data-app-device], .module-wb-app-widget') : null;
        if (!target) return;
        const componentType = safeString(target.dataset.appComponent);
        const action = safeString(target.dataset.appAction).toLowerCase();
        const device = safeString(target.dataset.appDevice);
        const widgetId = safeString(target.dataset.appWidgetId);
        if (widgetId) {
            wb.selectedId = widgetId;
            renderInspector();
            return;
        }
        if (componentType) {
            const def = defs.find((entry) => entry.id === componentType) || defs[0];
            const component = {
                id: `ui-${wb.nextId++}`,
                type: def.id,
                label: `${def.label} ${wb.nextId - 1}`,
                binding: '',
                required: false,
                x: 0,
                y: 0,
                w: def.w,
                h: def.h,
            };
            wb.components.push(component);
            grid.addWidget({
                id: component.id,
                x: component.x,
                y: component.y,
                w: component.w,
                h: component.h,
                content: widgetMarkup(component),
            });
            wb.selectedId = component.id;
            renderStatus();
            renderInspector();
            renderPreview();
            return;
        }
        if (device) {
            wb.device = device === 'mobile' ? 'mobile' : 'desktop';
            grid.column(wb.device === 'mobile' ? 4 : 12, 'moveScale');
            shell.querySelector('.module-wb-gridstack-shell')?.classList.toggle('mobile-mode', wb.device === 'mobile');
            renderStatus();
            renderPreview();
            return;
        }
        const component = byId(wb.selectedId);
        if (action === 'preview') {
            renderPreview();
            notifyUser('Runtime preview refreshed.', { tone: 'success', durationMs: 1300, debugKind: 'app-builder' });
            return;
        }
        if (action === 'publish') {
            notifyUser('App published to internal preview workspace.', { tone: 'success', durationMs: 1700, debugKind: 'app-builder' });
            return;
        }
        if (action === 'export') {
            moduleWorkbenchCopyJson({
                device: wb.device,
                components: wb.components,
            }, 'App Builder Schema');
            return;
        }
        if (action === 'export_html') {
            renderPreview();
            moduleWorkbenchDownloadText('thomas-app-preview.html', wb.previewHtml, 'text/html;charset=utf-8');
            notifyUser('Exported runtime HTML.', { tone: 'success', durationMs: 1600, debugKind: 'app-builder' });
            return;
        }
        if (action === 'open_preview') {
            renderPreview();
            const blob = new Blob([wb.previewHtml], { type: 'text/html;charset=utf-8' });
            const url = URL.createObjectURL(blob);
            window.open(url, '_blank', 'noopener');
            window.setTimeout(() => URL.revokeObjectURL(url), 5000);
            return;
        }
        if (action === 'export_appsmith') {
            moduleWorkbenchCopyJson(moduleWorkbenchAppSchemaToAppsmith(wb), 'Appsmith Page JSON');
            return;
        }
        if (action === 'export_budibase') {
            moduleWorkbenchCopyJson(moduleWorkbenchAppSchemaToBudibase(wb), 'Budibase App JSON');
            return;
        }
        if (action === 'reset') {
            grid.removeAll(false);
            wb.components = [];
            wb.selectedId = '';
            renderStatus();
            renderInspector();
            renderPreview();
            return;
        }
        if (action === 'duplicate' && component) {
            const copy = {
                ...component,
                id: `ui-${wb.nextId++}`,
                label: `${component.label} Copy`,
                x: component.x + 1,
                y: component.y + 1,
            };
            wb.components.push(copy);
            grid.addWidget({
                id: copy.id,
                x: copy.x,
                y: copy.y,
                w: copy.w,
                h: copy.h,
                content: widgetMarkup(copy),
            });
            wb.selectedId = copy.id;
            renderStatus();
            renderInspector();
            renderPreview();
            return;
        }
        if (action === 'delete' && component) {
            const widget = findWidgetById(component.id);
            if (widget) grid.removeWidget(widget, false);
            wb.components = wb.components.filter((row) => safeString(row.id) !== safeString(component.id));
            wb.selectedId = wb.components[0] ? safeString(wb.components[0].id) : '';
            renderStatus();
            renderInspector();
            renderPreview();
        }
    });

    inspector.addEventListener('input', (event) => {
        const target = event.target;
        if (!(target instanceof HTMLInputElement || target instanceof HTMLSelectElement)) return;
        const component = byId(wb.selectedId);
        if (!component) return;
        const prop = safeString(target.dataset.appProp);
        if (!prop) return;
        if (prop === 'label' || prop === 'binding') component[prop] = safeString(target.value).slice(0, 120);
        if (prop === 'type') component.type = safeString(target.value);
        if (prop === 'required' && target instanceof HTMLInputElement) component.required = target.checked;
        if (prop === 'x' || prop === 'y' || prop === 'w' || prop === 'h') {
            const limits = prop === 'w' || prop === 'h'
                ? { min: 1, max: 12 }
                : { min: 0, max: 200 };
            component[prop] = moduleWorkbenchClamp(Number(target.value) || component[prop], limits.min, limits.max);
            const widget = findWidgetById(component.id);
            if (widget) {
                grid.update(widget, {
                    x: component.x,
                    y: component.y,
                    w: component.w,
                    h: component.h,
                });
            }
        }
        refreshWidgetContent(component);
        renderStatus();
        renderInspector();
        renderPreview();
    });

    const projectSelect = shell.querySelector('select[data-wb-project-select="app_builder"]');
    if (projectSelect instanceof HTMLSelectElement) {
        projectSelect.addEventListener('change', () => {
            wb.selectedProjectId = safeString(projectSelect.value);
        });
    }

    return true;
}

function moduleRenderWorkbenchAppBuilder(container, wb) {
    if (moduleRenderWorkbenchAppBuilderOss(container, wb)) return;
    if (!container || !wb) return;
    if (!Array.isArray(wb.components)) wb.components = [];
    wb.selectedId = safeString(wb.selectedId);
    wb.device = safeString(wb.device) === 'mobile' ? 'mobile' : 'desktop';
    wb.nextId = Math.max(1, Number(wb.nextId) || 1);
    wb.selectedProjectId = safeString(wb.selectedProjectId);
    wb.previewHtml = safeString(wb.previewHtml);

    moduleWorkbenchHeader(container, 'App Builder Canvas', 'Guide Thomas-generated app components, bindings, and release-ready schema exports.');
    const shell = document.createElement('section');
    shell.className = 'module-wb-shell module-wb-shell-app';
    shell.innerHTML = `
        <aside class="module-wb-side-card"><h4>UI Blocks</h4><div class="module-wb-palette" data-app-palette></div>${moduleWorkbenchRenderProjectControls('app_builder', 'App Projects')}<div class="module-wb-inspector-actions"><button type="button" class="module-item-btn" data-app-action="preview">Preview</button><button type="button" class="module-item-btn" data-app-action="publish">Publish</button><button type="button" class="module-item-btn" data-app-action="export">Export</button><button type="button" class="module-item-btn" data-app-action="export_html">Export HTML</button><button type="button" class="module-item-btn" data-app-action="open_preview">Open Preview</button><button type="button" class="module-item-btn" data-app-action="export_appsmith">Appsmith JSON</button><button type="button" class="module-item-btn" data-app-action="export_budibase">Budibase JSON</button><button type="button" class="module-item-btn" data-app-action="clear">Clear</button></div></aside>
        <section class="module-wb-stage-card"><div class="module-wb-stage-head"><span class="module-wb-stage-title">Layout</span><span class="module-wb-stage-meta" data-app-status></span></div><div class="module-wb-device-switch"><button type="button" class="module-item-btn" data-app-device="desktop">Desktop</button><button type="button" class="module-item-btn" data-app-device="mobile">Mobile</button></div><div class="module-wb-app-list" data-app-list></div><div class="module-wb-preview-frame-wrap"><div class="module-wb-stage-head"><span class="module-wb-stage-title">Runtime Preview</span><span class="module-wb-stage-meta">live</span></div><iframe class="module-wb-preview-frame" data-app-preview sandbox="allow-scripts"></iframe></div></section>
        <aside class="module-wb-inspector-card" data-app-inspector></aside>
        ${moduleWorkbenchRenderOssStack('app_builder')}
    `;
    container.appendChild(shell);

    const defs = [
        { id: 'table', label: 'Table', w: 220, h: 120 },
        { id: 'form', label: 'Form', w: 220, h: 140 },
        { id: 'chart', label: 'Chart', w: 220, h: 130 },
        { id: 'button', label: 'Button', w: 140, h: 64 },
        { id: 'modal', label: 'Modal', w: 260, h: 170 },
        { id: 'tabs', label: 'Tabs', w: 240, h: 98 },
    ];
    const byId = (id) => wb.components.find((item) => safeString(item.id) === safeString(id)) || null;
    const palette = shell.querySelector('[data-app-palette]');
    const list = shell.querySelector('[data-app-list]');
    const previewFrame = shell.querySelector('[data-app-preview]');
    const status = shell.querySelector('[data-app-status]');
    const inspector = shell.querySelector('[data-app-inspector]');

    const renderPalette = () => { palette.innerHTML = defs.map((entry) => `<button type="button" class="module-wb-palette-btn" data-app-component="${entry.id}"><strong>${entry.label}</strong><span>${entry.w}x${entry.h}</span></button>`).join(''); };
    const renderList = () => { list.innerHTML = wb.components.length ? wb.components.map((item) => `<article class="module-wb-list-item${safeString(item.id) === safeString(wb.selectedId) ? ' selected' : ''}" data-app-item-id="${escapeHtml(safeString(item.id))}"><strong>${escapeHtml(safeString(item.label))}</strong><span>${escapeHtml(`${item.type} | ${item.w}x${item.h} | ${item.binding || 'no binding'}`)}</span></article>`).join('') : '<div class="module-wb-ghost">Add components from the palette.</div>'; };
    const renderInspector = () => {
        const item = byId(wb.selectedId);
        if (!item) { inspector.innerHTML = `<h4>Inspector</h4><p class="module-wb-mini-note">Select a component to configure it.</p><div class="module-wb-metrics"><div><span>Components</span><strong>${wb.components.length}</strong></div><div><span>Device</span><strong>${escapeHtml(wb.device)}</strong></div><div><span>Publish</span><strong>Draft</strong></div></div>`; return; }
        inspector.innerHTML = `<h4>${escapeHtml(safeString(item.label))}</h4><div class="module-wb-field-grid"><label class="module-wb-field">Label<input type="text" data-app-prop="label" value="${escapeHtml(safeString(item.label))}" /></label><label class="module-wb-field">Type<select data-app-prop="type">${defs.map((entry) => `<option value="${entry.id}"${item.type === entry.id ? ' selected' : ''}>${entry.label}</option>`).join('')}</select></label><label class="module-wb-field">Width<input type="number" data-app-prop="w" min="80" value="${Number(item.w) || 80}" /></label><label class="module-wb-field">Height<input type="number" data-app-prop="h" min="40" value="${Number(item.h) || 40}" /></label><label class="module-wb-field module-wb-field-wide">Binding<input type="text" data-app-prop="binding" value="${escapeHtml(safeString(item.binding))}" placeholder="customers.list" /></label><label class="module-wb-field module-wb-field-check"><input type="checkbox" data-app-prop="required" ${item.required ? 'checked' : ''} />Require role gate</label></div><div class="module-wb-inspector-actions"><button type="button" class="module-item-btn" data-app-item-action="duplicate">Duplicate</button><button type="button" class="module-item-btn" data-app-item-action="delete">Delete</button></div>`;
    };
    const renderProjectSelect = () => {
        const select = shell.querySelector('select[data-wb-project-select="app_builder"]');
        if (!(select instanceof HTMLSelectElement)) return;
        const rows = moduleWorkbenchProjectList('app_builder');
        const current = safeString(wb.selectedProjectId);
        select.innerHTML = `<option value="">Select project</option>${rows.map((row) => `<option value="${escapeHtml(safeString(row.id))}">${escapeHtml(`${safeString(row.name)} (${new Date(Number(row.updatedAt) || Date.now()).toLocaleString()})`)}</option>`).join('')}`;
        select.value = rows.some((row) => safeString(row.id) === current) ? current : '';
    };
    const renderPreview = () => {
        wb.previewHtml = moduleWorkbenchAppRuntimeHtml(wb);
        if (previewFrame instanceof HTMLIFrameElement) {
            previewFrame.srcdoc = wb.previewHtml;
        }
    };
    const renderStatus = () => { status.textContent = `${wb.components.length} components | ${wb.device.toUpperCase()} preview`; shell.querySelectorAll('[data-app-device]').forEach((button) => button.classList.toggle('active', safeString(button.dataset.appDevice) === wb.device)); list.classList.toggle('mobile-mode', wb.device === 'mobile'); };
    const renderAll = () => { renderList(); renderInspector(); renderStatus(); renderProjectSelect(); renderPreview(); };

    renderPalette();
    renderAll();

    shell.addEventListener('click', (event) => {
        if (moduleWorkbenchHandleOssStackClick(event.target)) return;
        const projectActionEl = event.target instanceof Element
            ? event.target.closest('[data-wb-project-action][data-wb-project-mode="app_builder"]')
            : null;
        if (projectActionEl) {
            const action = safeString(projectActionEl.dataset.wbProjectAction).toLowerCase();
            const select = shell.querySelector('select[data-wb-project-select="app_builder"]');
            const input = shell.querySelector('input[data-wb-project-name="app_builder"]');
            const selectedId = safeString(select instanceof HTMLSelectElement ? select.value : wb.selectedProjectId);
            if (action === 'save') {
                wb.selectedProjectId = moduleWorkbenchProjectSave('app_builder', { device: wb.device, components: wb.components }, safeString(input instanceof HTMLInputElement ? input.value : ''));
                if (input instanceof HTMLInputElement) input.value = '';
                renderAll();
                return;
            }
            if (action === 'load') {
                if (!selectedId) return;
                const project = moduleWorkbenchProjectGet('app_builder', selectedId);
                if (!project?.payload) return;
                wb.device = safeString(project.payload.device) === 'mobile' ? 'mobile' : 'desktop';
                wb.components = Array.isArray(project.payload.components) ? project.payload.components : [];
                wb.selectedId = wb.components[0] ? safeString(wb.components[0].id) : '';
                wb.selectedProjectId = selectedId;
                renderAll();
                return;
            }
            if (action === 'delete') {
                if (!selectedId) return;
                moduleWorkbenchProjectDelete('app_builder', selectedId);
                wb.selectedProjectId = '';
                renderAll();
                return;
            }
        }
        const target = event.target instanceof Element ? event.target.closest('[data-app-component], [data-app-action], [data-app-device], [data-app-item-id], [data-app-item-action]') : null;
        if (!target) return;
        const addType = safeString(target.dataset.appComponent);
        const action = safeString(target.dataset.appAction).toLowerCase();
        const device = safeString(target.dataset.appDevice);
        const itemId = safeString(target.dataset.appItemId);
        const itemAction = safeString(target.dataset.appItemAction).toLowerCase();
        if (addType) {
            const def = defs.find((entry) => entry.id === addType) || defs[0];
            const id = `ui-${wb.nextId++}`;
            wb.components.push({ id, type: def.id, label: def.label, w: def.w, h: def.h, binding: '', required: false });
            wb.selectedId = id;
            renderAll();
            return;
        }
        if (device) { wb.device = device === 'mobile' ? 'mobile' : 'desktop'; renderStatus(); return; }
        if (action) {
            if (action === 'preview') renderAll();
            if (action === 'publish') notifyUser('App builder draft published to internal preview.', { tone: 'success', durationMs: 1700, debugKind: 'app-builder' });
            if (action === 'export') moduleWorkbenchCopyJson({ device: wb.device, components: wb.components }, 'App Builder Schema');
            if (action === 'export_html') { renderPreview(); moduleWorkbenchDownloadText('thomas-app-preview.html', wb.previewHtml, 'text/html;charset=utf-8'); }
            if (action === 'open_preview') {
                renderPreview();
                const blob = new Blob([wb.previewHtml], { type: 'text/html;charset=utf-8' });
                const url = URL.createObjectURL(blob);
                window.open(url, '_blank', 'noopener');
                window.setTimeout(() => URL.revokeObjectURL(url), 5000);
            }
            if (action === 'export_appsmith') moduleWorkbenchCopyJson(moduleWorkbenchAppSchemaToAppsmith(wb), 'Appsmith Page JSON');
            if (action === 'export_budibase') moduleWorkbenchCopyJson(moduleWorkbenchAppSchemaToBudibase(wb), 'Budibase App JSON');
            if (action === 'clear') { wb.components = []; wb.selectedId = ''; }
            renderAll();
            return;
        }
        if (itemId) wb.selectedId = itemId;
        if (itemAction === 'duplicate') { const item = byId(wb.selectedId); if (item) { const copy = { ...item, id: `ui-${wb.nextId++}`, label: `${item.label} Copy` }; wb.components.push(copy); wb.selectedId = copy.id; } }
        if (itemAction === 'delete') { wb.components = wb.components.filter((item) => safeString(item.id) !== safeString(wb.selectedId)); wb.selectedId = ''; }
        renderAll();
    });

    if (inspector) {
        inspector.addEventListener('input', (event) => {
            const target = event.target;
            if (!(target instanceof HTMLInputElement || target instanceof HTMLSelectElement)) return;
            const item = byId(wb.selectedId);
            if (!item) return;
            const prop = safeString(target.dataset.appProp);
            if (!prop) return;
            if (prop === 'label' || prop === 'binding') item[prop] = safeString(target.value).slice(0, 120);
            if (prop === 'type') item.type = safeString(target.value);
            if (prop === 'w' || prop === 'h') item[prop] = moduleWorkbenchClamp(Number(target.value) || item[prop], prop === 'w' ? 80 : 40, prop === 'w' ? 900 : 700);
            if (prop === 'required' && target instanceof HTMLInputElement) item.required = target.checked;
            renderAll();
        });
    }
}

