function moduleFitEmbeddedSurface(frame, { minHeight = 680, viewportPadding = 20, lockInternalScroll = false, preferContentHeight = true } = {}) {
    if (!(frame instanceof HTMLIFrameElement)) return;
    const minHeightPx = Number.isFinite(minHeight) ? minHeight : 680;
    const viewportPaddingPx = Number.isFinite(viewportPadding) ? viewportPadding : 20;
    const scheduleHeightSync = () => {
        const sync = () => {
            const bounds = frame.getBoundingClientRect();
            let nextHeight = Math.max(minHeightPx, (window.innerHeight || minHeightPx) - Math.max(bounds.top, 0) - viewportPaddingPx);
            try {
                const doc = frame.contentDocument;
                const root = doc?.documentElement;
                const body = doc?.body;
                if (lockInternalScroll && root && body) {
                    root.style.overflowY = 'hidden';
                    body.style.overflowY = 'hidden';
                }
                const contentHeight = Math.max(root?.scrollHeight || 0, body?.scrollHeight || 0, root?.offsetHeight || 0, body?.offsetHeight || 0);
                if (preferContentHeight && contentHeight > 0) {
                    nextHeight = Math.max(nextHeight, contentHeight);
                }
            } catch (_error) {}
            frame.style.height = `${Math.ceil(nextHeight)}px`;
        };
        if (typeof window.requestAnimationFrame === 'function') {
            window.requestAnimationFrame(sync);
            return;
        }
        window.setTimeout(sync, 0);
    };

    if (typeof frame.__moduleEmbeddedCleanup === 'function') {
        try {
            frame.__moduleEmbeddedCleanup();
        } catch (_error) {}
    }

    let resizeObserver = null;
    const onWindowResize = () => scheduleHeightSync();
    const cleanup = () => {
        window.removeEventListener('resize', onWindowResize);
        if (resizeObserver) {
            resizeObserver.disconnect();
            resizeObserver = null;
        }
    };
    frame.__moduleEmbeddedCleanup = cleanup;
    window.addEventListener('resize', onWindowResize);

    const attachObserver = () => {
        try {
            if (typeof ResizeObserver !== 'function') return;
            const doc = frame.contentDocument;
            const root = doc?.documentElement;
            const body = doc?.body;
            resizeObserver = new ResizeObserver(() => scheduleHeightSync());
            if (root) resizeObserver.observe(root);
            if (body && body !== root) resizeObserver.observe(body);
        } catch (_error) {
            resizeObserver = null;
        }
    };

    frame.addEventListener('load', () => {
        attachObserver();
        scheduleHeightSync();
        window.setTimeout(scheduleHeightSync, 120);
        window.setTimeout(scheduleHeightSync, 420);
    }, { once: true });

    if (frame.contentDocument?.readyState === 'complete') {
        attachObserver();
        scheduleHeightSync();
    } else {
        scheduleHeightSync();
    }
}

function moduleRenderEmbeddedSurface(container, { title, src, surfaceMode = 'standard' }) {
    if (!container) return null;
    const existing = container.querySelector(`iframe[data-module-embedded-surface="${src}"]`);
    if (existing instanceof HTMLIFrameElement) {
        if (surfaceMode === 'immersive') {
            moduleFitEmbeddedSurface(existing, { minHeight: 680, viewportPadding: 14, lockInternalScroll: false, preferContentHeight: true });
        }
        return existing;
    }

    const staleEmbedded = container.querySelector('[data-module-embedded-surface]');
    if (staleEmbedded instanceof HTMLIFrameElement && typeof staleEmbedded.__moduleEmbeddedCleanup === 'function') {
        try {
            staleEmbedded.__moduleEmbeddedCleanup();
        } catch (_error) {}
    }
    container.innerHTML = '';

    const shell = document.createElement('section');
    shell.className = 'module-marketplace-shell';
    shell.dataset.moduleSurfaceMode = surfaceMode;

    const frameWrap = document.createElement('section');
    frameWrap.className = 'module-marketplace-stream';
    frameWrap.dataset.moduleSurfaceMode = surfaceMode;

    const frame = document.createElement('iframe');
    frame.setAttribute('title', title);
    frame.setAttribute('sandbox', 'allow-scripts allow-same-origin allow-forms allow-popups allow-modals');
    frame.dataset.moduleEmbeddedSurface = src;
    frame.dataset.moduleEmbeddedMode = surfaceMode;
    frame.loading = 'eager';
    frame.scrolling = 'auto';
    frame.src = src;
    frame.style.width = '100%';
    frame.style.border = '0';
    frame.style.background = 'transparent';

    if (surfaceMode === 'immersive') {
        frame.style.height = '680px';
        frame.style.minHeight = '680px';
        frame.style.borderRadius = '18px';
        moduleFitEmbeddedSurface(frame, { minHeight: 680, viewportPadding: 14, lockInternalScroll: false, preferContentHeight: true });
    } else {
        frame.style.height = '680px';
        frame.style.minHeight = '680px';
        frame.style.borderRadius = '18px';
    }

    frameWrap.appendChild(frame);
    shell.appendChild(frameWrap);
    container.appendChild(shell);
    return frame;
}

function moduleMarketplaceToneKey(toneRaw = '') {
    const tone = safeString(toneRaw).toLowerCase();
    if (!tone) return '';
    return tone.startsWith('tone-') ? tone.slice(5) : tone;
}

function moduleRenderMarketplaceSurface(container) {
    if (!container) return null;
    const staleEmbedded = container.querySelector('[data-module-embedded-surface]');
    if (staleEmbedded instanceof HTMLIFrameElement && typeof staleEmbedded.__moduleEmbeddedCleanup === 'function') {
        try {
            staleEmbedded.__moduleEmbeddedCleanup();
        } catch (_error) {}
    }
    const state = moduleEnsureRuntime();
    if (!state) return null;

    const marketplaceState = state.marketplace && typeof state.marketplace === 'object' ? state.marketplace : null;
    if (marketplaceState) {
        const pendingRefresh = moduleRefreshMarketplace();
        if (pendingRefresh && pendingRefresh !== marketplaceState.uiRenderPromise) {
            marketplaceState.uiRenderPromise = pendingRefresh;
            pendingRefresh.finally(() => {
                const runtime = moduleEnsureRuntime();
                const runtimeMarketplace = runtime?.marketplace && typeof runtime.marketplace === 'object' ? runtime.marketplace : null;
                if (runtimeMarketplace && runtimeMarketplace.uiRenderPromise === pendingRefresh) {
                    runtimeMarketplace.uiRenderPromise = null;
                }
                if (runtime?.activeMode === 'marketplace') {
                    moduleRender('marketplace', { touch: false });
                }
            });
        }
    }

    const apps = Array.isArray(marketplaceState?.apps) ? marketplaceState.apps : [];
    const categories = Array.isArray(marketplaceState?.categories) ? marketplaceState.categories : [];
    const loading = Boolean(marketplaceState?.loading);
    const error = safeString(marketplaceState?.error);
    const searchText = safeString(marketplaceState?.search).trim();
    const activeFilter = safeString(marketplaceState?.filter).toLowerCase() || 'all';
    const generatedAt = safeString(marketplaceState?.generatedAt);
    const titleCase = (value) => safeString(value)
        .replace(/[_-]+/g, ' ')
        .split(' ')
        .filter(Boolean)
        .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
        .join(' ');

    const filteredApps = apps.filter((app) => {
        const filterId = safeString(app?.category_id).toLowerCase() || 'other';
        if (activeFilter !== 'all' && filterId !== activeFilter) return false;
        if (!searchText) return true;
        const blob = [
            safeString(app?.module_id),
            safeString(app?.display_name),
            safeString(app?.subtitle),
            safeString(app?.description),
            safeString(app?.category_label || app?.category),
            safeString(app?.target),
            safeString(app?.mode),
            safeString(app?.mode_id),
            safeString(app?.publisher_name || app?.publisher),
            ...(Array.isArray(app?.capabilities) ? app.capabilities : []),
        ].join(' ').toLowerCase();
        return blob.includes(searchText.toLowerCase());
    }).sort((left, right) => {
        const installableWeight = Number(Boolean(right?.installable)) - Number(Boolean(left?.installable));
        if (installableWeight) return installableWeight;
        const installedWeight = Number(Boolean(right?.installed)) - Number(Boolean(left?.installed));
        if (installedWeight) return installedWeight;
        return safeString(left?.display_name || left?.module_id).localeCompare(safeString(right?.display_name || right?.module_id));
    });

    const selectedId = safeString(marketplaceState?.selectedId);
    const selectedApp = filteredApps.find((app) => safeString(app?.module_id) === selectedId) || null;
    if (marketplaceState && selectedId && !selectedApp) {
        marketplaceState.selectedId = '';
    }

    const categoryFilters = [{ id: 'all', label: 'All Upgrades', count: apps.length }].concat(
        categories.map((row) => ({
            id: safeString(row?.id).toLowerCase() || 'other',
            label: safeString(row?.label) || titleCase(row?.id) || 'Other',
            count: Number(row?.count) || 0,
        })),
    );

    const buildStatus = (app) => {
        if (app?.installable) {
            if (app?.installed && app?.enabled) return { label: 'Installed', tone: 'ready' };
            if (app?.installed) return { label: 'Disabled', tone: 'catalog' };
            return { label: 'Ready to install', tone: 'ready' };
        }
        if (app?.download_available) return { label: 'Downloadable', tone: 'ready' };
        return { label: 'Catalog Only', tone: 'catalog' };
    };

    const buildPrimaryAction = (app) => {
        if (app?.installable) {
            if (app?.installed) {
                return app?.enabled
                    ? { id: 'disable', label: 'Disable' }
                    : { id: 'enable', label: 'Enable' };
            }
            return { id: 'install', label: 'Install' };
        }
        if (app?.download_available) {
            return { id: 'download', label: 'Download ZIP', actionUrl: safeString(app?.install?.release_download_endpoint) };
        }
        return null;
    };

    const buildSecondaryActions = (app) => {
        const downloadUrl = safeString(app?.install?.release_download_endpoint || app?.install?.release_manifest_endpoint);
        const actions = [];
        if (app?.installable && app?.installed) {
            actions.push({ id: 'uninstall', label: 'Uninstall' });
        }
        if (downloadUrl) {
            actions.push({ id: 'download', label: 'Download ZIP', actionUrl: downloadUrl });
        }
        actions.push({ id: 'copy', label: 'Copy ID' });
        return actions;
    };

    const renderActionButton = (app, action, { primary = false } = {}) => {
        if (!action) return '';
        if (action.id === 'copy') {
            return `
                <button
                    type="button"
                    class="marketplace-secondary-btn"
                    data-module-marketplace-copy-id="${escapeHtml(safeString(app?.module_id))}"
                    data-module-mode="marketplace">
                    ${escapeHtml(action.label)}
                </button>
            `;
        }
        const className = primary ? 'module-item-btn marketplace-cta' : 'marketplace-secondary-btn';
        return `
            <button
                type="button"
                class="${className}"
                data-module-mode="marketplace"
                data-module-section="queue"
                data-module-item-id="${escapeHtml(safeString(app?.module_id))}"
                data-module-action-id="${escapeHtml(action.id)}"
                data-module-action-label="${escapeHtml(action.label)}"
                data-module-action-url="${escapeHtml(safeString(action.actionUrl || ''))}">
                ${escapeHtml(action.label)}
            </button>
        `;
    };

    const filterMarkup = categoryFilters.map((filterRow) => {
        const isActive = activeFilter === filterRow.id;
        return `
            <button
                type="button"
                class="marketplace-filter-chip${isActive ? ' is-active' : ''}"
                data-module-marketplace-filter="${escapeHtml(filterRow.id)}"
                data-module-mode="marketplace">
                <span>${escapeHtml(filterRow.label)}</span>
                <strong>${escapeHtml(String(filterRow.count))}</strong>
            </button>
        `;
    }).join('');

    const renderSelectedStrip = (app) => {
        if (!app) return '';
        const primaryAction = buildPrimaryAction(app);
        const secondaryActions = buildSecondaryActions(app);
        const status = buildStatus(app);
        const facts = [
            { label: 'Category', value: safeString(app?.category_label || app?.category) || 'Other' },
            { label: 'Target', value: titleCase(app?.target) || 'Local' },
            { label: 'Mode', value: titleCase(app?.mode_id || app?.mode) || 'Plugin' },
            { label: 'Version', value: `v${safeString(app?.version) || '0.0.0'}` },
            { label: 'Publisher', value: safeString(app?.publisher_name || app?.publisher) || 'Thomas' },
            { label: 'Plugin ID', value: safeString(app?.module_id) },
        ];
        return `
            <section class="marketplace-selected-strip">
                <div class="marketplace-selected-main">
                    <div class="marketplace-selected-copy">
                        <span class="marketplace-selected-kicker">${escapeHtml(status.label)}</span>
                        <h3>${escapeHtml(safeString(app?.display_name) || safeString(app?.module_id))}</h3>
                        <p>${escapeHtml(safeString(app?.subtitle) || safeString(app?.description) || 'No description available.')}</p>
                    </div>
                    <div class="marketplace-selected-actions">
                        ${renderActionButton(app, primaryAction, { primary: true })}
                        ${secondaryActions.map((action) => renderActionButton(app, action)).join('')}
                    </div>
                </div>
                <div class="marketplace-selected-grid">
                    ${facts.map((fact) => `
                        <div class="marketplace-selected-fact">
                            <span>${escapeHtml(fact.label)}</span>
                            <strong>${escapeHtml(fact.value)}</strong>
                        </div>
                    `).join('')}
                </div>
                <p class="marketplace-selected-capabilities"><strong>Capabilities</strong> ${escapeHtml((Array.isArray(app?.capabilities) ? app.capabilities : []).join(', ') || 'No declared capabilities')}</p>
                <p class="marketplace-selected-capabilities"><strong>Requires</strong> ${escapeHtml((Array.isArray(app?.requires) ? app.requires : []).join(', ') || 'No additional dependencies')}</p>
            </section>
        `;
    };

    const cardMarkup = filteredApps.map((app) => {
        const status = buildStatus(app);
        const primaryAction = buildPrimaryAction(app);
        const downloadUrl = safeString(app?.install?.release_download_endpoint || app?.install?.release_manifest_endpoint);
        const isSelected = Boolean(selectedApp) && safeString(selectedApp?.module_id) === safeString(app?.module_id);
        return `
            <article class="marketplace-card${isSelected ? ' is-selected' : ''}">
                <div class="marketplace-card-head">
                    <p class="marketplace-card-locus">${escapeHtml(typeLabel(app))} / ${escapeHtml(safeString(app?.category_label || app?.category) || 'Other')} / ${escapeHtml(installBehaviorLabel(app))}</p>
                    <span class="marketplace-card-status" data-marketplace-status="${escapeHtml(status.tone)}">${escapeHtml(status.label)}</span>
                </div>
                <div class="marketplace-card-copy">
                    <h3 class="marketplace-card-title">${escapeHtml(safeString(app?.display_name) || safeString(app?.module_id))}</h3>
                    <p class="marketplace-card-summary">${escapeHtml(safeString(app?.subtitle) || safeString(app?.description) || 'No description available.')}</p>
                </div>
                <p class="marketplace-card-meta">${escapeHtml(`v${safeString(app?.version) || '0.0.0'} / ${safeString(app?.publisher_name || app?.publisher) || 'Thomas'}`)}</p>
                <p class="marketplace-card-meta">${escapeHtml((Array.isArray(app?.requires) && app.requires.length) ? `Requires: ${app.requires.join(', ')}` : 'No required support components')}</p>
                <div class="marketplace-card-actions">
                    <button
                        type="button"
                        class="marketplace-secondary-btn"
                        data-module-marketplace-select="${escapeHtml(safeString(app?.module_id))}"
                        data-module-mode="marketplace"
                        ${isSelected ? 'disabled' : ''}>
                        ${isSelected ? 'Selected' : 'More Info'}
                    </button>
                    ${renderActionButton(app, primaryAction, { primary: true })}
                    ${!primaryAction && downloadUrl ? renderActionButton(app, { id: 'download', label: 'Download ZIP', actionUrl: downloadUrl }, { primary: true }) : ''}
                </div>
            </article>
        `;
    }).join('');

    const installedCount = apps.filter((app) => app?.installed).length;
    const generatedLabel = generatedAt ? new Date(generatedAt).toLocaleString() : '';
    const emptyMarkup = `
        <section class="marketplace-empty-state${error ? ' marketplace-empty-state-error' : ''}">
            <strong>${escapeHtml(loading ? 'Loading upgrades...' : (searchText ? `No results for \"${searchText}\".` : 'No upgrades match this view.'))}</strong>
            <p>${escapeHtml(error || (loading ? 'Thomas is syncing the marketplace catalog.' : 'Change the search or category filter to widen the results.'))}</p>
        </section>
    `;

    container.innerHTML = `
        <section class="marketplace-surface">
            <div class="marketplace-sticky-head">
                <div class="marketplace-command-bar">
                    <label class="marketplace-search-wrap" aria-label="Search marketplace">
                        <span class="marketplace-field-label">Search Marketplace</span>
                        <input
                            class="marketplace-search-input"
                            type="search"
                            value="${escapeHtml(searchText)}"
                            placeholder="Search upgrades, categories, publishers, capabilities, and support components"
                            data-module-marketplace-search
                            data-module-mode="marketplace">
                    </label>
                    <div class="marketplace-command-actions">
                        <button type="button" class="marketplace-command-btn" data-marketplace-import data-module-mode="marketplace">Install From File</button>
                        ${searchText ? `<button type="button" class="marketplace-command-btn" data-module-marketplace-clear data-module-mode="marketplace">Clear</button>` : ''}
                        <button type="button" class="marketplace-command-btn marketplace-command-btn-primary" data-module-marketplace-refresh data-module-mode="marketplace">Sync Catalog</button>
                    </div>
                </div>
                <div class="marketplace-summary-row">
                    <p class="marketplace-summary-copy">
                        <strong>${escapeHtml(String(apps.length))}</strong> upgrades
                        <span>${escapeHtml(String(installedCount))} installed</span>
                        <span>${escapeHtml(String(categories.length))} categories</span>
                        <span>${escapeHtml(String(filteredApps.length))} visible</span>
                        ${generatedLabel ? `<span>Updated ${escapeHtml(generatedLabel)}</span>` : ''}
                    </p>
                </div>
                <div class="marketplace-filter-rail">
                    ${filterMarkup}
                </div>
            </div>
            <input class="hidden" type="file" accept=".zip,application/zip" data-marketplace-import-input>
            ${renderSelectedStrip(selectedApp)}
            <div class="marketplace-card-grid">
                ${cardMarkup || emptyMarkup}
            </div>
        </section>
    `;

    if (moduleWorkspace) {
        const moduleHeader = moduleWorkspace.querySelector('.module-header');
        const headerHeight = moduleHeader ? Math.ceil(moduleHeader.getBoundingClientRect().height) : 0;
        moduleWorkspace.style.setProperty('--marketplace-sticky-offset', `${Math.max(headerHeight, 0)}px`);
    }

    return container.firstElementChild;
}
function moduleRenderMyStuffSurface(container) {
    const config = moduleGetSpecialSurfaceConfig('my_stuff');
    return moduleRenderEmbeddedSurface(container, config || {
        title: 'Project Board',
        src: '/static/static/my_stuff.html?v=20260318-project-board-3',
        surfaceMode: 'immersive',
    });
}

function moduleRenderSpecialSurface(mode, container) {
    const config = moduleGetSpecialSurfaceConfig(mode);
    if (!config) return null;
    return moduleRenderEmbeddedSurface(container, config);
}

function moduleRenderList(container, { mode, section, rows, emptyText }) {
    if (!container) return;
    container.innerHTML = '';
    const items = Array.isArray(rows) ? rows : [];
    if (!items.length) {
        moduleRenderEmpty(container, emptyText || 'No items right now.');
        return;
    }
    const frag = document.createDocumentFragment();
    items.forEach((item) => {
        const card = document.createElement('article');
        card.className = 'module-item-card';
        const toneClass = moduleToneClass(item?.tone);
        const badgeClass = toneClass ? `module-item-badge ${toneClass}` : 'module-item-badge';
        const actions = Array.isArray(item?.actions) ? item.actions : [];
        const actionsHtml = actions.map((action) => `
            <button
                type="button"
                class="module-item-btn"
                data-module-mode="${escapeHtml(mode)}"
                data-module-section="${escapeHtml(section)}"
                data-module-item-id="${escapeHtml(safeString(item?.id))}"
                data-module-action-id="${escapeHtml(safeString(action?.id))}"
                data-module-action-label="${escapeHtml(safeString(action?.label))}"
                data-module-action-url="${escapeHtml(safeString(action?.actionUrl || action?.url || ''))}">
                ${escapeHtml(safeString(action?.label) || 'Run')}
            </button>
        `).join('');
        card.innerHTML = `
            <div class="module-item-top">
                <h4 class="module-item-title">${escapeHtml(safeString(item?.title) || 'Item')}</h4>
                ${safeString(item?.badge) ? `<span class="${badgeClass}">${escapeHtml(safeString(item?.badge))}</span>` : ''}
            </div>
            <p class="module-item-meta">${escapeHtml(safeString(item?.meta) || '')}</p>
            ${actionsHtml ? `<div class="module-item-actions">${actionsHtml}</div>` : ''}
        `;
        frag.appendChild(card);
    });
    container.appendChild(frag);
}

function moduleRenderActions(definition, mode) {
    if (!moduleActionsGrid) return;
    moduleActionsGrid.innerHTML = '';
    const actions = Array.isArray(definition?.actions) ? definition.actions : [];
    if (!actions.length) {
        moduleRenderEmpty(moduleActionsGrid, 'No quick actions configured.');
        return;
    }
    const frag = document.createDocumentFragment();
    actions.forEach((action) => {
        const actionLabel = withAgentName(safeString(action?.label));
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'module-action-btn';
        button.dataset.moduleMode = mode;
        button.dataset.moduleActionId = safeString(action?.id);
        button.dataset.moduleActionLabel = actionLabel;
        button.innerHTML = `
            <strong>${escapeHtml(actionLabel || 'Action')}</strong>
            <span>${escapeHtml(safeString(action?.meta) || '')}</span>
        `;
        frag.appendChild(button);
    });
    moduleActionsGrid.appendChild(frag);
}

function moduleRenderTriage(definition, mode) {
    if (!moduleTriagePanel || !moduleTriageTitle || !moduleTriageMeta || !moduleTriageFilters || !moduleTriageMessages) return;
    const triage = definition?.triage;
    if (!triage) {
        moduleTriagePanel.classList.add('hidden');
        moduleTriageFilters.innerHTML = '';
        moduleTriageMessages.innerHTML = '';
        return;
    }
    moduleTriagePanel.classList.remove('hidden');
    moduleTriageTitle.textContent = safeString(triage?.title) || 'Triage';
    moduleTriageMeta.textContent = safeString(triage?.meta) || 'Filter and act';

    const state = moduleEnsureRuntime();
    const defaultFilter = safeString(triage?.defaultFilter) || 'all';
    const activeFilter = safeString(state?.triageFilters?.[mode]) || defaultFilter;
    if (state && !safeString(state.triageFilters[mode])) {
        state.triageFilters[mode] = activeFilter;
    }

    moduleTriageFilters.innerHTML = '';
    (triage.filters || []).forEach((filter) => {
        const id = safeString(filter).toLowerCase();
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = `module-filter-btn${activeFilter === id ? ' active' : ''}`;
        btn.dataset.moduleMode = mode;
        btn.dataset.moduleFilter = id;
        btn.textContent = id.replace(/_/g, ' ');
        moduleTriageFilters.appendChild(btn);
    });

    const rows = moduleVisibleItems(mode, 'triage', triage.rows || []).filter((row) => {
        if (activeFilter === 'all') return true;
        const tags = Array.isArray(row?.tags) ? row.tags.map((tag) => safeString(tag).toLowerCase()) : [];
        return tags.includes(activeFilter);
    }).map((row) => ({
        ...row,
        actions: [{ id: 'open', label: 'Open' }, { id: 'ack', label: 'Acknowledge' }],
    }));

    moduleRenderList(moduleTriageMessages, {
        mode,
        section: 'triage',
        rows,
        emptyText: 'No rows for this triage filter.',
    });
}

// 
//   MODULE RENDERING & DISPATCH                                            
//   moduleRender(), moduleEnterMode(), initModuleWorkspace()               
// 

function moduleRender(modeRaw, { touch = true } = {}) {
    const mode = MODULE_NAV_MODE_SET.has(modeRaw) ? modeRaw : 'dashboard';
    const state = moduleEnsureRuntime();
    if (!state) return;
    const modeChanged = safeString(state.lastRenderedMode) !== mode;
    const snapshot = moduleBuildSnapshot();
    const signals = moduleCollectSignals(snapshot);
    const definition = moduleBuildDefinition(mode, snapshot, signals);
    if (touch) moduleTouch(mode);
    const layout = safeString(definition?.layout) || 'hub';
    const specialSurfaceOnly = moduleModeUsesSpecialSurface(mode);
    const specialSurfaceMode = specialSurfaceOnly ? moduleGetSpecialSurfaceMode(mode) : '';
    const queueSurfaceOnly = specialSurfaceOnly || mode === 'marketplace';

    if (moduleWorkspaceTitle) moduleWorkspaceTitle.textContent = definition.title;
    if (moduleWorkspaceSubtitle) moduleWorkspaceSubtitle.textContent = definition.subtitle;
    if (moduleWorkspaceModePill) moduleWorkspaceModePill.textContent = definition.pill;
    if (moduleWorkspace) {
        moduleWorkspace.dataset.layout = layout;
        moduleWorkspace.dataset.mode = mode;
        if (specialSurfaceMode) {
            moduleWorkspace.dataset.embeddedSurfaceMode = specialSurfaceMode;
        } else {
            delete moduleWorkspace.dataset.embeddedSurfaceMode;
        }
        if (queueSurfaceOnly) {
            moduleWorkspace.dataset.surfaceLayout = "full";
        } else {
            delete moduleWorkspace.dataset.surfaceLayout;
        }
        moduleSyncSurfaceScrollState();
        if (modeChanged) {
            if (state.modeEnterTimer) {
                window.clearTimeout(state.modeEnterTimer);
                state.modeEnterTimer = 0;
            }
            moduleWorkspace.classList.remove('mode-enter');
            void moduleWorkspace.offsetWidth;
            moduleWorkspace.classList.add('mode-enter');
            state.modeEnterTimer = window.setTimeout(() => {
                if (moduleWorkspace) moduleWorkspace.classList.remove('mode-enter');
                state.modeEnterTimer = 0;
            }, 420);
        }
    }
    if (moduleWorkspaceMeta) {
        if (mode === 'marketplace') {
            moduleWorkspaceMeta.textContent = 'Marketplace catalog';
        } else if (mode === 'my_stuff') {
            moduleWorkspaceMeta.textContent = 'Local launch shortcuts';
        } else {
            const refreshed = state.refreshedAt[mode] || Date.now();
            moduleWorkspaceMeta.textContent = `Auto-refresh enabled | refreshed ${missionRelativeTime(new Date(refreshed).toISOString())}`;
        }
    }

    const labels = definition?.panelLabels || {};
    if (moduleQueueTitle) moduleQueueTitle.textContent = safeString(labels.queueTitle) || 'Priority Queue';
    if (moduleQueueMeta) moduleQueueMeta.textContent = safeString(labels.queueMeta) || 'Most relevant work on top';
    if (moduleHealthTitle) moduleHealthTitle.textContent = safeString(labels.healthTitle) || 'Health + Status';
    if (moduleHealthMeta) moduleHealthMeta.textContent = safeString(labels.healthMeta) || 'Critical checks and integrations';
    if (moduleActionsTitle) moduleActionsTitle.textContent = safeString(labels.actionsTitle) || 'Quick Actions';
    if (moduleActionsMeta) moduleActionsMeta.textContent = safeString(labels.actionsMeta) || 'Run immediate actions';
    if (moduleActivityTitle) moduleActivityTitle.textContent = safeString(labels.activityTitle) || 'Activity';
    if (moduleActivityMeta) moduleActivityMeta.textContent = safeString(labels.activityMeta) || 'Recent events and auto updates';

    const queueWide = layout === 'hub' || layout === 'catalog' || layout === 'board';
    const activityWide = layout === 'editor_media' || layout === 'editor_code' || layout === 'editor_game' || layout === 'editor_3d' || layout === 'research';
    if (moduleQueuePanel) moduleQueuePanel.classList.toggle('module-panel-wide', queueWide);
    if (moduleActivityPanel) moduleActivityPanel.classList.toggle('module-panel-wide', activityWide);
    if (moduleKpiGrid) {
        if (queueSurfaceOnly) {
            moduleKpiGrid.innerHTML = '';
            moduleKpiGrid.classList.add('hidden');
        } else {
            moduleKpiGrid.classList.remove('hidden');
            moduleRenderKpis(definition);
        }
    }
    if (moduleSubnavRow) {
        if (queueSurfaceOnly) {
            moduleSubnavRow.classList.add('hidden');
        } else {
            moduleRenderSubnav(mode);
        }
    }
    if (moduleFlairRow) {
        if (queueSurfaceOnly) {
            moduleFlairRow.classList.add('hidden');
            moduleFlairRow.innerHTML = '';
        } else {
            moduleRenderFlair(moduleBuildFlair(mode, signals, snapshot));
        }
    }
    if (moduleFocusStrip) {
        if (queueSurfaceOnly) {
            moduleFocusStrip.classList.add('hidden');
            moduleFocusStrip.innerHTML = '';
        } else {
            moduleRenderFocus(moduleBuildFocusCards(mode, snapshot, signals));
        }
    }
    if (moduleSpecialGrid) {
        if (queueSurfaceOnly) {
            moduleSpecialGrid.classList.add('hidden');
            moduleSpecialGrid.innerHTML = '';
        } else {
            moduleRenderSpecialCards(moduleBuildSpecialCards(mode, snapshot, signals, definition));
        }
    }
    if (moduleHealthPanel) moduleHealthPanel.classList.toggle('hidden', queueSurfaceOnly);
    if (moduleActionsPanel) moduleActionsPanel.classList.toggle('hidden', queueSurfaceOnly);
    if (moduleActivityPanel) moduleActivityPanel.classList.toggle('hidden', queueSurfaceOnly);
    if (moduleTriagePanel) moduleTriagePanel.classList.toggle('hidden', queueSurfaceOnly);
    moduleRenderWorkbench(mode, snapshot, signals, definition, { force: modeChanged });
        if (queueSurfaceOnly) {
        if (mode === 'marketplace') {
            moduleRenderMarketplaceSurface(moduleQueueList);
        } else {
            moduleRenderSpecialSurface(mode, moduleQueueList);
        }
        if (moduleHealthList) moduleHealthList.innerHTML = '';
        if (moduleActionsGrid) moduleActionsGrid.innerHTML = '';
        if (moduleActivityList) moduleActivityList.innerHTML = '';
        if (moduleTriageFilters) moduleTriageFilters.innerHTML = '';
        if (moduleTriageMessages) moduleTriageMessages.innerHTML = '';
    } else {
        moduleRenderList(moduleQueueList, {
            mode,
            section: 'queue',
            rows: moduleVisibleItems(mode, 'queue', definition.queueRows),
            emptyText: modulePanelEmptyText(mode, 'queue'),
        });
    }
    if (!queueSurfaceOnly) {
        moduleRenderList(moduleHealthList, {
            mode,
            section: 'health',
            rows: moduleVisibleItems(mode, 'health', definition.healthRows),
            emptyText: modulePanelEmptyText(mode, 'health'),
        });
        moduleRenderActions(definition, mode);
        moduleRenderList(moduleActivityList, {
            mode,
            section: 'activity',
            rows: definition.activityRows,
            emptyText: modulePanelEmptyText(mode, 'activity'),
        });
        moduleRenderTriage(definition, mode);
    }
    state.lastRenderedMode = mode;
}

function moduleEnterMode(modeRaw) {
    const mode = MODULE_NAV_MODE_SET.has(modeRaw) ? modeRaw : 'dashboard';
    const state = moduleEnsureRuntime();
    if (!state) return;
    state.activeMode = mode;
    moduleRender(mode);
}

function moduleLeaveMode() {}

function moduleSyncSurfaceScrollState() {
    if (!moduleWorkspace) return;
    const useSurfaceLayout = safeString(moduleWorkspace.dataset.surfaceLayout) === 'full';
    const isScrolled = useSurfaceLayout && Number(moduleWorkspace.scrollTop) > 8;
    if (isScrolled) {
        moduleWorkspace.dataset.surfaceScrolled = 'true';
    } else {
        delete moduleWorkspace.dataset.surfaceScrolled;
    }
}

function initModuleWorkspace() {
    const state = moduleEnsureRuntime();
    if (!state || state.controlsBound) return;
    state.controlsBound = true;
    if (moduleWorkspace) {
        moduleWorkspace.addEventListener('scroll', moduleSyncSurfaceScrollState, { passive: true });
        window.setTimeout(moduleSyncSurfaceScrollState, 0);
    }

    const itemActionHandler = async (event) => {
        const target = event.target instanceof Element ? event.target.closest('.module-item-btn[data-module-action-id]') : null;
        if (!target) return;
        const mode = MODULE_NAV_MODE_SET.has(target.dataset.moduleMode) ? target.dataset.moduleMode : (state.activeMode || 'dashboard');
        const section = safeString(target.dataset.moduleSection).toLowerCase() || 'queue';
        const itemId = safeString(target.dataset.moduleItemId);
        const actionId = safeString(target.dataset.moduleActionId).toLowerCase();
        const actionLabel = safeString(target.dataset.moduleActionLabel) || 'Action';
        const actionUrl = safeString(target.dataset.moduleActionUrl);
                if (mode === 'marketplace' && itemId) {
            if (target instanceof HTMLButtonElement) target.disabled = true;
            try {
                if (actionId === 'enable' || actionId === 'disable') {
                    const result = await moduleSetMarketplacePluginEnabled(itemId, actionId === 'enable');
                    if (!result?.ok) throw new Error(result?.error || `${actionLabel} failed.`);
                    await moduleRefreshMarketplace({ force: true });
                    if (actionId === 'enable' && result?.plugin?.mode_id) {
                        setSidebarNavMode(result.plugin.mode_id);
                    }
                    moduleRecordActivity(mode, `${actionLabel} completed for ${itemId || 'item'}.`, 'ok');
                    moduleTouch(mode);
                    moduleRender(mode, { touch: false });
                    notifyUser(`${actionLabel} completed.`, { tone: 'success', durationMs: 1500, debugKind: actionId || 'module-action' });
                    return;
                }
                if (actionId === 'install') {
                    const result = await moduleInstallMarketplacePlugin(itemId);
                    if (!result?.ok) throw new Error(result?.error || `${actionLabel} failed.`);
                    await moduleRefreshMarketplace({ force: true });
                    if (result?.plugin?.mode_id) {
                        setSidebarNavMode(result.plugin.mode_id);
                    }
                    moduleRecordActivity(mode, `${actionLabel} completed for ${itemId || 'item'}.`, 'ok');
                    moduleTouch(mode);
                    moduleRender('marketplace', { touch: false });
                    notifyUser(`${actionLabel} completed.`, { tone: 'success', durationMs: 1500, debugKind: actionId || 'module-action' });
                    return;
                }
                if (actionId === 'uninstall') {
                    const result = await moduleUninstallMarketplacePlugin(itemId);
                    if (!result?.ok) throw new Error(result?.error || `${actionLabel} failed.`);
                    await moduleRefreshMarketplace({ force: true });
                    if (safeString(sidebarNavMode) === safeString(moduleInstalledPluginForMode(sidebarNavMode)?.mode_id)) {
                        setSidebarNavMode('marketplace');
                    }
                    moduleRecordActivity(mode, `${actionLabel} completed for ${itemId || 'item'}.`, 'ok');
                    moduleTouch(mode);
                    moduleRender('marketplace', { touch: false });
                    notifyUser(`${actionLabel} completed.`, { tone: 'success', durationMs: 1500, debugKind: actionId || 'module-action' });
                    return;
                }
                if (actionId === 'download' || actionId === 'latest') {
                    if (!actionUrl) {
                        throw new Error('No action URL is configured for this item.');
                    }
                    const opened = window.open(actionUrl, '_blank', 'noopener,noreferrer');
                    if (!opened) {
                        window.location.href = actionUrl;
                    } else {
                        opened.opener = null;
                    }
                    moduleRecordActivity(mode, `${actionLabel} opened for ${itemId || 'item'}.`, 'ok');
                    moduleTouch(mode);
                    moduleRender(mode, { touch: false });
                    notifyUser(`${actionLabel} opened.`, { tone: 'info', durationMs: 1500, debugKind: actionId || 'module-action' });
                    return;
                }
            } catch (error) {
                moduleRecordActivity(mode, `${actionLabel} failed for ${itemId || 'item'}.`, 'error');
                notifyUser(error?.message || `${actionLabel} failed.`, { tone: 'error', durationMs: 2200, debugKind: actionId || 'module-action' });
                return;
            } finally {
                if (target instanceof HTMLButtonElement) target.disabled = false;
            }
        }
        if (MODULE_ITEM_DISMISS_ACTIONS.has(actionId)) {
            moduleHideItem(mode, section, itemId);
        }
        moduleRecordActivity(mode, `${actionLabel} ran for ${itemId || 'item'}.`, MODULE_ITEM_DISMISS_ACTIONS.has(actionId) ? 'warn' : 'ok');
        moduleTouch(mode);
        moduleRender(mode, { touch: false });
        notifyUser(`${actionLabel} executed.`, { tone: 'info', durationMs: 1500, debugKind: actionId || 'module-action' });
    };

    if (moduleQueueList) {
        moduleQueueList.addEventListener('click', itemActionHandler);
        moduleQueueList.addEventListener('input', (event) => {
            const target = event.target instanceof Element ? event.target.closest('input[data-module-marketplace-search][data-module-mode]') : null;
            if (!(target instanceof HTMLInputElement)) return;
            const mode = MODULE_NAV_MODE_SET.has(target.dataset.moduleMode) ? target.dataset.moduleMode : (state.activeMode || 'dashboard');
            if (mode !== 'marketplace') return;
            if (!state.marketplace || typeof state.marketplace !== 'object') return;
            const nextSearch = safeString(target.value);
            if (safeString(state.marketplace.search) === nextSearch) return;
            const selectionStart = typeof target.selectionStart === 'number' ? target.selectionStart : nextSearch.length;
            const selectionEnd = typeof target.selectionEnd === 'number' ? target.selectionEnd : selectionStart;
            state.marketplace.search = nextSearch;
            state.marketplace.searchSelectionStart = selectionStart;
            state.marketplace.searchSelectionEnd = selectionEnd;
            state.marketplace.focusSearchUntil = Date.now() + 2000;
            moduleTouch(mode);
            moduleRender(mode, { touch: false });
            window.requestAnimationFrame(() => {
                const searchInput = moduleQueueList.querySelector('input[data-module-marketplace-search][data-module-mode="marketplace"]');
                if (!(searchInput instanceof HTMLInputElement)) return;
                searchInput.focus({ preventScroll: true });
                const nextStart = Math.max(0, Math.min(selectionStart, searchInput.value.length));
                const nextEnd = Math.max(nextStart, Math.min(selectionEnd, searchInput.value.length));
                try {
                    searchInput.setSelectionRange(nextStart, nextEnd);
                } catch (_error) {}
            });
        });
        moduleQueueList.addEventListener('click', (event) => {
            const clearButton = event.target instanceof Element ? event.target.closest('[data-module-marketplace-clear][data-module-mode]') : null;
            if (!clearButton) return;
            const mode = MODULE_NAV_MODE_SET.has(clearButton.dataset.moduleMode) ? clearButton.dataset.moduleMode : (state.activeMode || 'dashboard');
            if (mode !== 'marketplace') return;
            if (state.marketplace && typeof state.marketplace === 'object') {
                state.marketplace.search = '';
                state.marketplace.searchSelectionStart = 0;
                state.marketplace.searchSelectionEnd = 0;
                state.marketplace.focusSearchUntil = Date.now() + 2000;
            }
            const searchInput = moduleQueueList.querySelector('input[data-module-marketplace-search][data-module-mode="marketplace"]');
            if (searchInput instanceof HTMLInputElement) {
                searchInput.value = '';
            }
            moduleTouch(mode);
            moduleRender(mode, { touch: false });
            window.requestAnimationFrame(() => {
                const nextInput = moduleQueueList.querySelector('input[data-module-marketplace-search][data-module-mode="marketplace"]');
                if (!(nextInput instanceof HTMLInputElement)) return;
                nextInput.focus({ preventScroll: true });
                try {
                    nextInput.setSelectionRange(0, 0);
                } catch (_error) {}
            });
        });
        moduleQueueList.addEventListener('click', async (event) => {
            const refreshButton = event.target instanceof Element ? event.target.closest('[data-module-marketplace-refresh][data-module-mode]') : null;
            if (!refreshButton) return;
            const mode = MODULE_NAV_MODE_SET.has(refreshButton.dataset.moduleMode) ? refreshButton.dataset.moduleMode : (state.activeMode || 'dashboard');
            if (mode !== 'marketplace') return;
            if (refreshButton instanceof HTMLButtonElement) refreshButton.disabled = true;
            try {
                await moduleRefreshMarketplace({ force: true });
            } finally {
                if (refreshButton instanceof HTMLButtonElement) refreshButton.disabled = false;
            }
            moduleTouch(mode);
            moduleRender(mode, { touch: false });
        });
        moduleQueueList.addEventListener('click', (event) => {
            const filterButton = event.target instanceof Element ? event.target.closest('[data-module-marketplace-filter][data-module-mode]') : null;
            if (!filterButton) return;
            const mode = MODULE_NAV_MODE_SET.has(filterButton.dataset.moduleMode) ? filterButton.dataset.moduleMode : (state.activeMode || 'dashboard');
            if (mode !== 'marketplace' || !state.marketplace || typeof state.marketplace !== 'object') return;
            const nextFilter = safeString(filterButton.dataset.moduleMarketplaceFilter).toLowerCase() || 'all';
            if (safeString(state.marketplace.filter).toLowerCase() === nextFilter) return;
            state.marketplace.filter = nextFilter;
            state.marketplace.selectedId = '';
            moduleRender(mode, { touch: false });
        });
        moduleQueueList.addEventListener('click', (event) => {
            const selectButton = event.target instanceof Element ? event.target.closest('[data-module-marketplace-select][data-module-mode]') : null;
            if (!selectButton) return;
            const mode = MODULE_NAV_MODE_SET.has(selectButton.dataset.moduleMode) ? selectButton.dataset.moduleMode : (state.activeMode || 'dashboard');
            if (mode !== 'marketplace' || !state.marketplace || typeof state.marketplace !== 'object') return;
            const nextId = safeString(selectButton.dataset.moduleMarketplaceSelect);
            if (!nextId || safeString(state.marketplace.selectedId) === nextId) return;
            state.marketplace.selectedId = nextId;
            moduleRender(mode, { touch: false });
        });
                moduleQueueList.addEventListener('click', async (event) => {
            const copyButton = event.target instanceof Element ? event.target.closest('[data-module-marketplace-copy-id][data-module-mode]') : null;
            if (!copyButton) return;
            const mode = MODULE_NAV_MODE_SET.has(copyButton.dataset.moduleMode) ? copyButton.dataset.moduleMode : (state.activeMode || 'dashboard');
            if (mode !== 'marketplace') return;
            const pluginId = safeString(copyButton.dataset.moduleMarketplaceCopyId);
            if (!pluginId) return;
            try {
                await navigator.clipboard.writeText(pluginId);
                notifyUser('Plugin ID copied.', { tone: 'success', durationMs: 1200, debugKind: 'copy-plugin-id' });
            } catch (_error) {
                notifyUser('Copy failed.', { tone: 'error', durationMs: 1600, debugKind: 'copy-plugin-id' });
            }
        });
        moduleQueueList.addEventListener('click', (event) => {
            const importButton = event.target instanceof Element ? event.target.closest('[data-marketplace-import][data-module-mode]') : null;
            if (!importButton) return;
            const fileInput = moduleQueueList.querySelector('input[data-marketplace-import-input]');
            if (fileInput instanceof HTMLInputElement) {
                fileInput.click();
            }
        });
        moduleQueueList.addEventListener('change', async (event) => {
            const input = event.target;
            if (!(input instanceof HTMLInputElement) || !input.matches('input[data-marketplace-import-input]')) return;
            const file = input.files && input.files[0] ? input.files[0] : null;
            if (!file) return;
            const result = await moduleImportMarketplacePlugin(file);
            input.value = '';
            if (!result?.ok) {
                notifyUser(result?.error || 'Import failed.', { tone: 'error', durationMs: 2200, debugKind: 'marketplace-import' });
                return;
            }
            await moduleRefreshMarketplace({ force: true });
            if (result?.plugin?.mode_id) {
                setSidebarNavMode(result.plugin.mode_id);
            } else {
                moduleRender('marketplace', { touch: false });
            }
            notifyUser('Plugin imported.', { tone: 'success', durationMs: 1500, debugKind: 'marketplace-import' });
        });
    }
    if (moduleHealthList) moduleHealthList.addEventListener('click', itemActionHandler);
    if (moduleActivityList) moduleActivityList.addEventListener('click', itemActionHandler);
    if (moduleTriageMessages) moduleTriageMessages.addEventListener('click', itemActionHandler);

    if (moduleActionsGrid) {
        moduleActionsGrid.addEventListener('click', (event) => {
            const target = event.target instanceof Element ? event.target.closest('.module-action-btn[data-module-action-id]') : null;
            if (!target) return;
            const mode = MODULE_NAV_MODE_SET.has(target.dataset.moduleMode) ? target.dataset.moduleMode : (state.activeMode || 'dashboard');
            const label = safeString(target.dataset.moduleActionLabel) || 'Action';
            const actionId = safeString(target.dataset.moduleActionId).toLowerCase();
            if (mode === 'vibe_code') {
                if (actionId === 'switch_chat') {
                    setSidebarNavMode('chat');
                    if (composerTextarea) composerTextarea.focus();
                    notifyUser('Switched to chat. Send a message to animate the flow.', { tone: 'info', durationMs: 1700, debugKind: 'vibe-code' });
                    return;
                }
                if (actionId === 'disconnect_edges') {
                    const disconnected = vibeCodeSetVisibleEdgesDisconnected(true);
                    vibeCodeRender();
                    moduleRecordActivity(mode, `Disconnected ${disconnected} visible edge${disconnected === 1 ? '' : 's'}.`, 'warn');
                    moduleTouch(mode);
                    moduleRender(mode, { touch: false });
                    notifyUser(`${disconnected} visible edge${disconnected === 1 ? '' : 's'} disconnected.`, { tone: 'warning', durationMs: 1600, debugKind: 'vibe-code' });
                    return;
                }
                if (actionId === 'reconnect_edges') {
                    const reconnected = vibeCodeSetVisibleEdgesDisconnected(false);
                    vibeCodeRender();
                    moduleRecordActivity(mode, `Reconnected ${reconnected} visible edge${reconnected === 1 ? '' : 's'}.`, 'ok');
                    moduleTouch(mode);
                    moduleRender(mode, { touch: false });
                    notifyUser(`${reconnected} visible edge${reconnected === 1 ? '' : 's'} reconnected.`, { tone: 'success', durationMs: 1500, debugKind: 'vibe-code' });
                    return;
                }
                if (actionId === 'reset_trace') {
                    vibeCodeState.activeTraceId = '';
                    vibeCodeRender();
                    moduleRecordActivity(mode, 'Cleared active trace view.', 'warn');
                    moduleTouch(mode);
                    moduleRender(mode, { touch: false });
                    notifyUser('Active trace reset.', { tone: 'info', durationMs: 1500, debugKind: 'vibe-code' });
                    return;
                }
            }
            moduleRecordActivity(mode, `${label} queued from ${moduleSeed(mode).title}.`, 'ok');
            moduleTouch(mode);
            moduleRender(mode, { touch: false });
            notifyUser(`${label} queued.`, { tone: 'success', durationMs: 1500, debugKind: actionId || 'module-action' });
        });
    }

    if (moduleTriageFilters) {
        moduleTriageFilters.addEventListener('click', (event) => {
            const target = event.target instanceof Element ? event.target.closest('[data-module-filter]') : null;
            if (!target) return;
            const mode = MODULE_NAV_MODE_SET.has(target.dataset.moduleMode) ? target.dataset.moduleMode : (state.activeMode || 'dashboard');
            const filter = safeString(target.dataset.moduleFilter).toLowerCase() || 'all';
            state.triageFilters[mode] = filter;
            moduleTouch(mode);
            moduleRender(mode, { touch: false });
        });
    }

    if (moduleSubnavList) {
        moduleSubnavList.addEventListener('click', (event) => {
            const target = event.target instanceof Element ? event.target.closest('.module-subnav-chip[data-module-section-label]') : null;
            if (!target) return;
            const mode = MODULE_NAV_MODE_SET.has(target.dataset.moduleMode) ? target.dataset.moduleMode : (state.activeMode || 'dashboard');
            const sectionLabel = safeString(target.dataset.moduleSectionLabel) || 'Section';
            state.subnavFocus[mode] = sectionLabel;
            moduleRecordActivity(mode, `Focused ${sectionLabel}.`, 'ok');
            moduleTouch(mode);
            moduleRender(mode, { touch: false });
        });
    }

    state.timerId = window.setInterval(() => {
        if (!MODULE_NAV_MODE_SET.has(sidebarNavMode)) return;
        moduleRender(sidebarNavMode);
    }, MODULE_REFRESH_INTERVAL_MS);

    moduleRender('dashboard', { touch: false });
}

function isUiEditorPreviewShell() {
    try {
        const params = new URLSearchParams(window.location.search || '');
        return params.get('ui_editor_preview') === '1';
    } catch {
        return false;
    }
}

function loadRequestedNavModeFromUrl() {
    try {
        const params = new URLSearchParams(window.location.search || '');
        if (params.get('ui_editor_preview') === '1') {
            return 'chat';
        }
        if (params.has('thomas_deep_link') || (params.has('plugin_id') && params.has('store'))) {
            return 'marketplace';
        }
        if (!params.has('nav')) return '';
        return normalizeNavMode(params.get('nav'));
    } catch {
        return '';
    }
}

function loadRequestedPluginInstallDeepLinkFromUrl() {
    try {
        const params = new URLSearchParams(window.location.search || '');
        const deepLink = safeString(params.get('thomas_deep_link'));
        if (deepLink) return deepLink;
        const pluginId = safeString(params.get('plugin_id'));
        const store = safeString(params.get('store'));
        const channel = safeString(params.get('channel')) || 'stable';
        if (!pluginId || !store) return '';
        return `thomas://install-plugin?plugin_id=${encodeURIComponent(pluginId)}&store=${encodeURIComponent(store)}&channel=${encodeURIComponent(channel)}`;
    } catch {
        return '';
    }
}

function clearRequestedPluginInstallFromUrl() {
    try {
        const url = new URL(window.location.href);
        let changed = false;
        ['thomas_deep_link', 'plugin_id', 'store', 'channel'].forEach((key) => {
            if (url.searchParams.has(key)) {
                url.searchParams.delete(key);
                changed = true;
            }
        });
        if (!changed) return;
        if (safeString(url.searchParams.get('nav')).toLowerCase() === 'marketplace') {
            url.searchParams.delete('nav');
        }
        const nextSearch = url.searchParams.toString();
        const nextUrl = `${url.pathname}${nextSearch ? `?${nextSearch}` : ''}${url.hash || ''}`;
        window.history.replaceState(window.history.state, document.title, nextUrl);
    } catch {
        // Ignore URL rewrite failures.
    }
}

function resolveBootNavMode() {
    const requested = loadRequestedNavModeFromUrl();
    if (requested) return requested;
    const stored = loadStoredNavMode();
    return stored === 'app_builder' ? 'chat' : stored;
}

function loadStoredNavMode() {
    try {
        const requested = loadRequestedNavModeFromUrl();
        if (requested) return requested;
        if (!window?.localStorage) return 'chat';
        return normalizeNavMode(window.localStorage.getItem(UI_NAV_MODE_STORAGE_KEY));
    } catch {
        return 'chat';
    }
}

function saveStoredNavMode(modeRaw) {
    const mode = normalizeNavMode(modeRaw);
    try {
        if (!window?.localStorage || isUiEditorPreviewShell()) return;
        window.localStorage.setItem(UI_NAV_MODE_STORAGE_KEY, mode);
    } catch {
        // Ignore storage failures.
    }
}

function loadStoredSidebarCollapsed() {
    try {
        if (!window?.localStorage) return false;
        return window.localStorage.getItem(UI_SIDEBAR_COLLAPSED_STORAGE_KEY) === '1';
    } catch {
        return false;
    }
}

function saveStoredSidebarCollapsed(collapsed) {
    try {
        if (!window?.localStorage) return;
        window.localStorage.setItem(UI_SIDEBAR_COLLAPSED_STORAGE_KEY, collapsed ? '1' : '0');
    } catch {
        // Ignore storage failures.
    }
}

function loadStoredChatListExpanded() {
    try {
        if (!window?.localStorage) return true;
        const raw = window.localStorage.getItem(UI_CHAT_LIST_EXPANDED_STORAGE_KEY);
        if (raw === null) return true;
        return raw !== '0';
    } catch {
        return true;
    }
}

function saveStoredChatListExpanded(expanded) {
    try {
        if (!window?.localStorage) return;
        window.localStorage.setItem(UI_CHAT_LIST_EXPANDED_STORAGE_KEY, expanded ? '1' : '0');
    } catch {
        // Ignore storage failures.
    }
}

function loadStoredActiveChatId() {
    try {
        if (!window?.localStorage) return '';
        return safeString(window.localStorage.getItem(UI_ACTIVE_CHAT_STORAGE_KEY));
    } catch {
        return '';
    }
}

function saveStoredActiveChatId(chatIdRaw) {
    try {
        if (!window?.localStorage) return;
        const chatId = safeString(chatIdRaw);
        if (chatId) {
            window.localStorage.setItem(UI_ACTIVE_CHAT_STORAGE_KEY, chatId);
        } else {
            window.localStorage.removeItem(UI_ACTIVE_CHAT_STORAGE_KEY);
        }
    } catch {
        // Ignore storage failures.
    }
}

function loadStoredOfficeCameraState() {
    try {
        if (!window?.localStorage) return null;
        const raw = safeString(window.localStorage.getItem(OFFICE_CAMERA_STORAGE_KEY));
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return null;
        const zoom = Number(parsed.zoom);
        const panX = Number(parsed.panX);
        const panY = Number(parsed.panY);
        const followAgentId = safeString(parsed.followAgentId);
        if (!Number.isFinite(zoom) || !Number.isFinite(panX) || !Number.isFinite(panY)) {
            return null;
        }
        return {
            zoom: officeClamp(zoom, OFFICE_ZOOM_MIN, OFFICE_ZOOM_MAX),
            panX,
            panY,
            followAgentId,
        };
    } catch {
        return null;
    }
}

function saveStoredOfficeCameraState(snapshot) {
    try {
        if (!window?.localStorage || !snapshot || typeof snapshot !== 'object') return;
        const payload = {
            zoom: officeClamp(Number(snapshot.zoom) || 1, OFFICE_ZOOM_MIN, OFFICE_ZOOM_MAX),
            panX: Number(snapshot.panX) || 0,
            panY: Number(snapshot.panY) || 0,
            followAgentId: safeString(snapshot.followAgentId || ''),
        };
        window.localStorage.setItem(OFFICE_CAMERA_STORAGE_KEY, JSON.stringify(payload));
    } catch {
        // Ignore storage failures.
    }
}

function loadStoredOfficeLayoutState() {
    try {
        if (!window?.localStorage) return null;
        const raw = safeString(window.localStorage.getItem(OFFICE_LAYOUT_STORAGE_KEY));
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return null;
        return {
            dynamicRooms: Array.isArray(parsed.dynamicRooms) ? parsed.dynamicRooms : [],
            dynamicRoomBySlug: parsed.dynamicRoomBySlug && typeof parsed.dynamicRoomBySlug === 'object'
                ? parsed.dynamicRoomBySlug
                : {},
        };
    } catch {
        return null;
    }
}

function saveStoredOfficeLayoutState(snapshot) {
    try {
        if (!window?.localStorage || !snapshot || typeof snapshot !== 'object') return;
        const payload = {
            dynamicRooms: Array.isArray(snapshot.dynamicRooms) ? snapshot.dynamicRooms : [],
            dynamicRoomBySlug: snapshot.dynamicRoomBySlug && typeof snapshot.dynamicRoomBySlug === 'object'
                ? snapshot.dynamicRoomBySlug
                : {},
        };
        window.localStorage.setItem(OFFICE_LAYOUT_STORAGE_KEY, JSON.stringify(payload));
    } catch {
        // Ignore storage failures.
    }
}

function loadStoredOfficeAgentPrefs() {
    try {
        if (!window?.localStorage) return null;
        const raw = safeString(window.localStorage.getItem(OFFICE_AGENT_PREFS_STORAGE_KEY));
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return null;
        return parsed;
    } catch {
        return null;
    }
}

function saveStoredOfficeAgentPrefs(snapshot) {
    try {
        if (!window?.localStorage || !snapshot || typeof snapshot !== 'object') return;
        window.localStorage.setItem(OFFICE_AGENT_PREFS_STORAGE_KEY, JSON.stringify(snapshot));
    } catch {
        // Ignore storage failures.
    }
}

function loadStoredOfficeRuntimeState() {
    try {
        if (!window?.localStorage) return null;
        const raw = safeString(window.localStorage.getItem(OFFICE_RUNTIME_STORAGE_KEY));
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return null;
        if (Number(parsed.version) !== OFFICE_RUNTIME_SCHEMA_VERSION) return null;
        return parsed;
    } catch {
        return null;
    }
}

function saveStoredOfficeRuntimeState(snapshot) {
    try {
        if (!window?.localStorage || !snapshot || typeof snapshot !== 'object') return;
        window.localStorage.setItem(OFFICE_RUNTIME_STORAGE_KEY, JSON.stringify(snapshot));
    } catch {
        // Ignore storage failures.
    }
}

function officeRuntimeTimerRemaining(now, targetRaw) {
    const target = Number(targetRaw) || 0;
    if (target <= 0) return 0;
    return Math.max(0, Math.round(target - now));
}

function officeRuntimeTimerRestore(now, remainingRaw) {
    const remaining = Math.max(0, Number(remainingRaw) || 0);
    if (!remaining) return 0;
    return now + remaining;
}

function officeCollectRuntimeSnapshot(now = performance.now()) {
    if (!officeState) return null;
    const timerNow = Number(now) || performance.now();
    return {
        version: OFFICE_RUNTIME_SCHEMA_VERSION,
        savedAtEpoch: Date.now(),
        savedAtPerf: timerNow,
        selectedAgentId: safeString(officeState.selectedAgentId),
        followAgentId: safeString(officeState.followAgentId),
        taskCounter: Number(officeState.taskCounter) || 0,
        chatLines: Array.isArray(officeState.chatLines)
            ? officeState.chatLines
                .slice(-OFFICE_MAX_CHAT_LINES)
                .map((line) => ({
                    message: safeString(line?.message),
                    tone: safeString(line?.tone) || 'system',
                    at: Number(line?.at) || Date.now(),
                }))
                .filter((line) => Boolean(line.message))
            : [],
        tasks: Array.isArray(officeState.tasks)
            ? officeState.tasks.map((task) => ({
                id: safeString(task?.id),
                title: safeString(task?.title),
                rawText: safeString(task?.rawText),
                source: safeString(task?.source),
                roomId: safeString(task?.roomId),
                roomLabel: safeString(task?.roomLabel),
                status: safeString(task?.status).toLowerCase(),
                assignedAgentId: safeString(task?.assignedAgentId),
                createdAt: Number(task?.createdAt) || 0,
                startedAt: Number(task?.startedAt) || 0,
                completedAt: Number(task?.completedAt) || 0,
            })).filter((task) => Boolean(task.id))
            : [],
        agents: Array.isArray(officeState.agents)
            ? officeState.agents.map((agent) => {
                const timers = {};
                OFFICE_RUNTIME_TIMER_FIELDS.forEach((field) => {
                    timers[field] = officeRuntimeTimerRemaining(timerNow, agent?.[field]);
                });
                return {
                    id: safeString(agent?.id),
                    name: safeString(agent?.name).slice(0, 24),
                    color: safeString(agent?.color),
                    costume: safeString(agent?.costume || 'none').toLowerCase(),
                    tint: safeString(agent?.tint || officeAgentTintFromColor(agent?.color)).toLowerCase(),
                    x: Number(agent?.x) || 0,
                    y: Number(agent?.y) || 0,
                    targetX: Number(agent?.targetX) || 0,
                    targetY: Number(agent?.targetY) || 0,
                    speed: Number(agent?.speed) || 0,
                    facing: Number(agent?.facing) || 1,
                    laneBias: Number(agent?.laneBias) || 0,
                    state: safeString(agent?.state).toLowerCase(),
                    intent: safeString(agent?.intent).toLowerCase(),
                    taskId: safeString(agent?.taskId),
                    workStreak: Number(agent?.workStreak) || 0,
                    yieldResumeIntent: safeString(agent?.yieldResumeIntent),
                    runawayPhase: safeString(agent?.runawayPhase),
                    runawayExitX: Number(agent?.runawayExitX) || 0,
                    runawayExitY: Number(agent?.runawayExitY) || 0,
                    currentNodeId: safeString(agent?.currentNodeId),
                    routeWaypoints: Array.isArray(agent?.routeWaypoints)
                        ? agent.routeWaypoints.slice(0, 24).map((point) => ({
                            x: Number(point?.x) || 0,
                            y: Number(point?.y) || 0,
                            nodeId: safeString(point?.nodeId),
                        }))
                        : [],
                    routeDestinationNodeId: safeString(agent?.routeDestinationNodeId),
                    reservedLaneEdgeKey: safeString(agent?.reservedLaneEdgeKey),
                    timers,
                };
            }).filter((agent) => Boolean(agent.id))
            : [],
    };
}

function officeApplyRuntimeSnapshot(snapshotRaw, now = performance.now()) {
    if (!officeState || !snapshotRaw || typeof snapshotRaw !== 'object') return false;
    if (Number(snapshotRaw.version) !== OFFICE_RUNTIME_SCHEMA_VERSION) return false;
    const timerNow = Number(now) || performance.now();
    let changed = false;

    const taskList = [];
    const rawTasks = Array.isArray(snapshotRaw.tasks) ? snapshotRaw.tasks : [];
    rawTasks.slice(0, OFFICE_MAX_TASKS).forEach((taskRaw) => {
        const id = safeString(taskRaw?.id);
        if (!id) return;
        const room = officeRoomById(safeString(taskRaw?.roomId)) || officeRoomById('room-lobby');
        const statusRaw = safeString(taskRaw?.status).toLowerCase();
        const status = new Set(['queued', 'active', 'done']).has(statusRaw) ? statusRaw : 'queued';
        taskList.push({
            id,
            title: officeTaskTitle(safeString(taskRaw?.title || taskRaw?.rawText || id)),
            rawText: safeString(taskRaw?.rawText || taskRaw?.title || id),
            source: safeString(taskRaw?.source) || 'runtime-restore',
            roomId: room?.id || 'room-lobby',
            roomLabel: room?.label || 'Main Lobby',
            status,
            assignedAgentId: safeString(taskRaw?.assignedAgentId),
            createdAt: Number(taskRaw?.createdAt) || Date.now(),
            startedAt: Number(taskRaw?.startedAt) || 0,
            completedAt: Number(taskRaw?.completedAt) || 0,
        });
    });
    if (taskList.length) {
        officeState.tasks = taskList;
        officeState.tasksDirty = true;
        changed = true;
    }

    const knownTaskIds = new Set(officeState.tasks.map((task) => task.id));
    const allowedStates = new Set(['idle', 'walking', 'working', 'break', 'yield', 'runaway']);
    const agentById = new Map(officeState.agents.map((agent) => [agent.id, agent]));
    const rawAgents = Array.isArray(snapshotRaw.agents) ? snapshotRaw.agents : [];
    rawAgents.forEach((saved) => {
        const id = safeString(saved?.id);
        if (!id) return;
        const agent = agentById.get(id);
        if (!agent) return;
        const x = officeClamp(Number(saved?.x) || agent.x, 1, 99);
        const y = officeClamp(Number(saved?.y) || agent.y, 1, 99);
        const safePosition = officeNearestWalkablePoint(x, y, agent.x, agent.y);
        agent.x = safePosition.x;
        agent.y = safePosition.y;
        const targetX = officeClamp(Number(saved?.targetX) || agent.x, 1, 99);
        const targetY = officeClamp(Number(saved?.targetY) || agent.y, 1, 99);
        const safeTarget = officeNearestWalkablePoint(targetX, targetY, agent.x, agent.y);
        agent.targetX = safeTarget.x;
        agent.targetY = safeTarget.y;
        agent.name = safeString(saved?.name).slice(0, 24) || agent.name;
        const color = safeString(saved?.color);
        if (/^#[0-9a-f]{6}$/i.test(color)) {
            agent.color = color;
        }
        const costume = safeString(saved?.costume).toLowerCase();
        if (new Set(OFFICE_AGENT_COSTUME_POOL).has(costume)) {
            agent.costume = costume;
        }
        agent.tint = safeString(saved?.tint).toLowerCase() || officeAgentTintFromColor(agent.color);
        agent.speed = officeClamp(Number(saved?.speed) || agent.speed, 1.3, 5.2);
        agent.facing = Number(saved?.facing) >= 0 ? 1 : -1;
        agent.laneBias = officeClamp(Number(saved?.laneBias) || 0, -1, 1);
        const state = safeString(saved?.state).toLowerCase();
        agent.state = allowedStates.has(state) ? state : 'idle';
        agent.intent = safeString(saved?.intent).toLowerCase() || (agent.state === 'working' ? 'task' : 'wander');
        const taskId = safeString(saved?.taskId);
        agent.taskId = knownTaskIds.has(taskId) ? taskId : '';
        agent.workStreak = Math.max(0, Number(saved?.workStreak) || 0);
        agent.yieldResumeIntent = safeString(saved?.yieldResumeIntent) || '';
        agent.runawayPhase = safeString(saved?.runawayPhase) || '';
        agent.runawayExitX = officeClamp(Number(saved?.runawayExitX) || 0, OFFICE_RUNAWAY_EXIT_MARGIN, 100 - OFFICE_RUNAWAY_EXIT_MARGIN);
        agent.runawayExitY = officeClamp(Number(saved?.runawayExitY) || 0, OFFICE_RUNAWAY_EXIT_MARGIN, 100 - OFFICE_RUNAWAY_EXIT_MARGIN);
        agent.currentNodeId = officeState.navMap.has(safeString(saved?.currentNodeId))
            ? safeString(saved?.currentNodeId)
            : officeFindNearestNode(officeState.navMap, agent.x, agent.y);
        agent.routeWaypoints = Array.isArray(saved?.routeWaypoints)
            ? saved.routeWaypoints.slice(0, 24).map((point) => ({
                x: officeClamp(Number(point?.x) || agent.x, 0, 100),
                y: officeClamp(Number(point?.y) || agent.y, 0, 100),
                nodeId: safeString(point?.nodeId),
            }))
            : [];
        const destination = safeString(saved?.routeDestinationNodeId);
        agent.routeDestinationNodeId = officeState.navMap.has(destination) ? destination : '';
        agent.reservedLaneEdgeKey = safeString(saved?.reservedLaneEdgeKey);
        agent.speech = null;
        const timers = saved?.timers && typeof saved.timers === 'object' ? saved.timers : {};
        OFFICE_RUNTIME_TIMER_FIELDS.forEach((field) => {
            agent[field] = officeRuntimeTimerRestore(timerNow, timers[field]);
        });
        agent.lastMoveX = agent.x;
        agent.lastMoveY = agent.y;
        changed = true;
    });

    const selectedAgentId = safeString(snapshotRaw.selectedAgentId);
    if (selectedAgentId && officeState.agents.some((agent) => agent.id === selectedAgentId)) {
        officeState.selectedAgentId = selectedAgentId;
        changed = true;
    }
    const followAgentId = safeString(snapshotRaw.followAgentId);
    if (followAgentId && officeState.agents.some((agent) => agent.id === followAgentId)) {
        officeState.followAgentId = followAgentId;
        changed = true;
    }
    if (Array.isArray(snapshotRaw.chatLines) && snapshotRaw.chatLines.length) {
        officeState.chatLines = snapshotRaw.chatLines
            .map((line) => ({
                message: safeString(line?.message),
                tone: safeString(line?.tone) || 'system',
                at: Number(line?.at) || Date.now(),
            }))
            .filter((line) => Boolean(line.message))
            .slice(-OFFICE_MAX_CHAT_LINES);
        changed = true;
    }
    officeState.taskCounter = Math.max(
        Number(officeState.taskCounter) || 0,
        Number(snapshotRaw.taskCounter) || 0,
        officeState.tasks.length,
    );
    officeState.lastWallClockTickAt = Date.now();
    return changed;
}

function officePersistRuntimeState(now = performance.now(), { force = false } = {}) {
    if (!officeState) return;
    const snapshotNow = Number(now) || performance.now();
    const elapsed = snapshotNow - (officeState.lastRuntimePersistAt || 0);
    if (!force && elapsed < OFFICE_RUNTIME_PERSIST_INTERVAL_MS) return;
    const snapshot = officeCollectRuntimeSnapshot(snapshotNow);
    if (!snapshot) return;
    saveStoredOfficeRuntimeState(snapshot);
    officeState.lastRuntimePersistAt = snapshotNow;
}

function officeSanitizeDynamicRoomSnapshot(roomRaw, index = 0) {
    const room = roomRaw && typeof roomRaw === 'object' ? roomRaw : {};
    const roomId = safeString(room.id) || `room-dynamic-${index + 1}`;
    const x = officeClamp(Number(room.x) || 58, 1, 93);
    const y = officeClamp(Number(room.y) || 58, 1, 95);
    const w = officeClamp(Number(room.w) || 8, 4.8, 18);
    const h = officeClamp(Number(room.h) || 8, 4.8, 18);
    const doorX = officeClamp(Number(room.doorX) || (x + (w / 2)), x, x + w);
    const doorY = officeClamp(Number(room.doorY) || (y + h), y, y + h + 2.2);
    const hallId = safeString(room.hallId) || officeNearestHallId(doorX, doorY);
    return {
        id: roomId,
        label: safeString(room.label) || `Task Pod ${index + 1}`,
        meta: safeString(room.meta) || 'Auto-generated feature room',
        x,
        y,
        w,
        h,
        kind: safeString(room.kind) || 'work',
        theme: safeString(room.theme) || 'dynamic',
        doorX,
        doorY,
        hallId,
        dynamic: true,
    };
}

function officeCollectLayoutSnapshot() {
    if (!officeState) return { dynamicRooms: [], dynamicRoomBySlug: {} };
    const dynamicRooms = officeState.rooms
        .filter((room) => room?.dynamic)
        .map((room) => ({
            id: room.id,
            label: room.label,
            meta: room.meta,
            x: Number(room.x) || 0,
            y: Number(room.y) || 0,
            w: Number(room.w) || 0,
            h: Number(room.h) || 0,
            kind: room.kind || 'work',
            theme: room.theme || 'dynamic',
            doorX: Number(room.doorX) || 0,
            doorY: Number(room.doorY) || 0,
            hallId: room.hallId || '',
        }));
    const dynamicRoomBySlug = {};
    officeState.dynamicRoomBySlug.forEach((roomId, slug) => {
        if (!slug || !roomId) return;
        dynamicRoomBySlug[slug] = roomId;
    });
    return { dynamicRooms, dynamicRoomBySlug };
}

function officePersistLayoutState() {
    if (!officeState) return;
    saveStoredOfficeLayoutState(officeCollectLayoutSnapshot());
}

function officeApplyStoredAgentPrefs(agents, prefsRaw) {
    if (!Array.isArray(agents) || !agents.length) return;
    const prefs = prefsRaw && typeof prefsRaw === 'object' ? prefsRaw : null;
    if (!prefs) return;
    const usedNames = new Set();
    agents.forEach((agent) => {
        const saved = prefs[safeString(agent.id)];
        if (!saved || typeof saved !== 'object') return;
        const proposedName = safeString(saved.name).slice(0, 24);
        const lowered = proposedName.toLowerCase();
        if (proposedName && !usedNames.has(lowered)) {
            agent.name = proposedName;
            usedNames.add(lowered);
        } else {
            usedNames.add(safeString(agent.name).toLowerCase());
        }
        const color = safeString(saved.color);
        if (/^#[0-9a-f]{6}$/i.test(color)) {
            agent.color = color;
        }
        const costume = safeString(saved.costume).toLowerCase();
        if (new Set(['none', 'cap', 'visor', 'headset', 'bowtie']).has(costume)) {
            agent.costume = costume;
        }
        const tint = safeString(saved.tint).toLowerCase();
        if (tint) {
            agent.tint = tint;
        } else {
            agent.tint = officeAgentTintFromColor(agent.color);
        }
    });
}

function officeCollectAgentPrefsSnapshot() {
    if (!officeState) return {};
    const snapshot = {};
    officeState.agents.forEach((agent) => {
        if (!agent) return;
        snapshot[agent.id] = {
            name: safeString(agent.name).slice(0, 24),
            color: /^#[0-9a-f]{6}$/i.test(safeString(agent.color)) ? safeString(agent.color) : '#9ad8ff',
            costume: safeString(agent.costume || 'none'),
            tint: safeString(agent.tint || 'blue'),
        };
    });
    return snapshot;
}

function officePersistAgentPrefs() {
    if (!officeState) return;
    saveStoredOfficeAgentPrefs(officeCollectAgentPrefsSnapshot());
}

function setChatListExpanded(expanded, { persist = true } = {}) {
    chatListExpanded = Boolean(expanded);
    if (navChatBtn) navChatBtn.classList.toggle('chat-list-collapsed', !chatListExpanded);
    if (sidebarChatPanel) {
        sidebarChatPanel.classList.toggle('chat-list-collapsed', !chatListExpanded);
        sidebarChatPanel.classList.toggle('hidden', !(sidebarNavMode === 'chat' || sidebarNavMode === 'search'));
    }
    if (persist) saveStoredChatListExpanded(chatListExpanded);
}

function initContentWorkspace() {
    const state = contentEnsureState();
    if (!state) return;
    if (!state.controlsBound) {
        state.controlsBound = true;
        if (contentRefreshBtn) {
            contentRefreshBtn.addEventListener('click', async () => {
                const ok = await contentRefresh({ silent: true });
                if (ok) {
                    notifyUser('Content Hub refreshed from live mission data.', {
                        tone: 'success',
                        debugKind: 'success',
                        durationMs: 1700,
                    });
                } else {
                    notifyUser('Content Hub refresh failed.', {
                        tone: 'warning',
                        debugKind: 'warning',
                        durationMs: 2600,
                    });
                }
            });
        }
    }
    if (!state.payload) {
        state.payload = contentEmptyPayload();
    }
    contentRender();
    if (sidebarNavMode === 'content') {
        void contentRefresh({ silent: true });
    }
}

// 
//   SIDEBAR & NAVIGATION                                                   
//   Nav mode switching, chat list, office/content workspace init           
// 

function setSidebarNavMode(mode = 'chat', { persist = true } = {}) {
    const requestedMode = normalizeNavMode(mode);
    sidebarNavMode = isUiEditorPreviewShell() && requestedMode === 'app_builder' ? 'chat' : requestedMode;
    const isSearch = sidebarNavMode === 'search';
    const isChat = sidebarNavMode === 'chat' || isSearch;
    const isOffice = sidebarNavMode === 'office';
    const isMission = sidebarNavMode === 'mission';
    const isContent = sidebarNavMode === 'content';
    const isModule = MODULE_NAV_MODE_SET.has(sidebarNavMode);

    if (navChatBtn) navChatBtn.classList.toggle('active', isChat);
    if (navOfficeBtn) navOfficeBtn.classList.toggle('active', isOffice);
    if (navMissionBtn) navMissionBtn.classList.toggle('active', isMission);
    if (navContentBtn) navContentBtn.classList.toggle('active', isContent);
    sidebarModeButtons.forEach((button) => {
        const buttonMode = normalizeNavMode(button.dataset.navMode);
        button.classList.toggle('active', buttonMode === sidebarNavMode);
    });
    moduleRenderInstalledPluginNav();
    if (searchOverlayBar) searchOverlayBar.classList.remove('hidden');
    if (sidebarChatPanel) {
        sidebarChatPanel.classList.toggle('hidden', !isChat);
        sidebarChatPanel.classList.toggle('chat-list-collapsed', !chatListExpanded);
    }
    if (officeWorkspace) officeWorkspace.classList.toggle('hidden', !isOffice);
    if (missionWorkspace) missionWorkspace.classList.toggle('hidden', !isMission);
    if (contentWorkspace) contentWorkspace.classList.toggle('hidden', !isContent);
    if (moduleWorkspace) moduleWorkspace.classList.toggle('hidden', !isModule);
    if (appRoot) {
        appRoot.classList.toggle('office-active', isOffice);
        appRoot.classList.toggle('mission-active', isMission);
        appRoot.classList.toggle('content-active', isContent);
        appRoot.classList.toggle('module-active', isModule);
    }

    if (sidebar) {
        sidebar.classList.toggle('mode-search', isSearch);
        sidebar.classList.toggle('mode-chat', isChat);
        sidebar.classList.toggle('mode-office', isOffice);
        sidebar.classList.toggle('mode-mission', isMission);
        sidebar.classList.toggle('mode-content', isContent);
        sidebar.classList.toggle('mode-module', isModule);
    }

    if (isOffice && officeEnsureState()) {
        officeState.active = true;
        officeResetViewport();
        void officeStartMissionStream();
        if (officeChatInput) {
            window.setTimeout(() => {
                officeChatInput.focus();
            }, 0);
        }
    } else if (officeState) {
        officeState.active = false;
        officeSetEditorOpen(false);
        officeStopMissionStream();
        officePersistRuntimeState(performance.now(), { force: true });
    }

    if (isMission) {
        missionEnterMode();
    } else {
        missionLeaveMode();
    }

    if (isContent) {
        contentEnterMode();
    } else {
        contentLeaveMode();
    }

    if (isModule) {
        moduleEnterMode(sidebarNavMode);
        if (sidebarNavMode === 'finance') void spendRefresh();
        if (sidebarNavMode === 'operations' || sidebarNavMode === 'dashboard') void goalsRefresh();
    } else {
        moduleLeaveMode();
    }

    if (!isChat) {
        chatGameClose({ clearMode: false });
        if (safeString(composerModeSelection?.kind) === 'game') {
            composerClearMode({ closeGame: false });
        }
    }

    setSidebarSearchScope(isModule ? 'general' : sidebarNavMode);

    if (persist && !isSearch) {
        saveStoredNavMode(sidebarNavMode);
    }
    normalizeMainContentScroll();
    updateTaskContinuityVisibility({ refresh: isChat });
    updateDebugDockSnapshot();
}

function setSidebarSearchScope(scope = 'chat') {
    const normalizedScope = safeString(scope).toLowerCase();
    if (normalizedScope === 'office' || normalizedScope === 'mission' || normalizedScope === 'content' || normalizedScope === 'general') {
        sidebarSearchScope = normalizedScope;
    } else if (normalizedScope === 'search' || MODULE_NAV_MODE_SET.has(normalizedScope)) {
        sidebarSearchScope = 'general';
    } else {
        sidebarSearchScope = 'chat';
    }

    let label = 'Search chats';
    if (sidebarSearchScope === 'office') label = 'Search office';
    if (sidebarSearchScope === 'mission') label = 'Search mission control';
    if (sidebarSearchScope === 'content') label = 'Search content hub';
    if (sidebarSearchScope === 'general') label = withAgentName('Search {{agent}}');

    if (globalSearchInput) globalSearchInput.placeholder = label;
    if (sidebarSearchModeLabel) sidebarSearchModeLabel.textContent = label;
    if (sidebarChatHeaderLabel) sidebarChatHeaderLabel.textContent = 'Recent Chats';
    renderSidebarChatList();
    updateDebugDockSnapshot();
}

function renderSidebarChatList() {
    if (!sidebarChatList) return;
    const chatSearchEnabled = sidebarSearchScope === 'chat' || sidebarSearchScope === 'general';
    const queryLower = chatSearchEnabled ? safeString(globalSearchInput?.value).toLowerCase() : '';
    const activeId = safeString(activeChatId) || safeString(sessionId);
    sidebarChatList.innerHTML = '';

    const filteredSessions = sidebarSessions.filter((session) => {
        if (!queryLower) return true;
        const haystack = `${safeString(session?.title)} ${safeString(session?.preview)} ${safeString(session?.model)} ${safeString(session?.id)}`.toLowerCase();
        return haystack.includes(queryLower);
    });

    filteredSessions.forEach((session) => {
        const row = document.createElement('button');
        row.type = 'button';
        row.className = 'sidebar-chat-row';
        if (safeString(session?.id) === activeId) {
            row.classList.add('active');
        }
        row.innerHTML = `
            <span class="sidebar-chat-row-title">${escapeHtml(formatSidebarSessionTitle(session))}</span>
            <span class="sidebar-chat-row-meta">${escapeHtml(formatSidebarSessionMeta(session))}</span>
        `;
        row.addEventListener('click', () => {
            const sid = safeString(session?.id);
            if (!sid) return;
            void loadSessionFromHistory(sid);
        });
        sidebarChatList.appendChild(row);
    });

    if (!sidebarChatList.children.length) {
        const empty = document.createElement('div');
        empty.className = 'sidebar-chat-empty';
        if (queryLower) {
            empty.textContent = 'No matches yet. Try another search term.';
        } else if (sidebarSearchScope === 'general') {
            empty.textContent = withAgentName('Search {{agent}} to find chats and relevant items.');
        } else {
            empty.textContent = 'No chats yet. Start one from New Chat.';
        }
        sidebarChatList.appendChild(empty);
    }
}

function slugifySettingsLabel(label) {
    return safeString(label)
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
}

function isSettingsSectionVisible(section) {
    return Boolean(section && section.getClientRects().length > 0);
}

function setActiveSettingsSectionNav(sectionId) {
    settingsSectionEntries.forEach((entry) => {
        const isActive = Boolean(sectionId) && entry.section.id === sectionId && !entry.link.classList.contains('hidden');
        entry.link.classList.toggle('active', isActive);
        entry.link.setAttribute('aria-current', isActive ? 'true' : 'false');
    });
}

function getVisibleSettingsSectionEntries() {
    return settingsSectionEntries.filter((entry) => !entry.link.classList.contains('hidden') && isSettingsSectionVisible(entry.section));
}

function updateSettingsNavEmptyState() {
    if (!settingsNavEmpty) return;
    const hasVisibleEntries = settingsSectionEntries.some((entry) => !entry.link.classList.contains('hidden'));
    settingsNavEmpty.classList.toggle('hidden', hasVisibleEntries);
}

function updateSettingsSectionNavActive() {
    if (!settingsSections) return;
    const visibleEntries = getVisibleSettingsSectionEntries();
    if (visibleEntries.length === 0) {
        setActiveSettingsSectionNav('');
        return;
    }

    const activeOffset = settingsSections.scrollTop + 56;
    let activeEntry = visibleEntries[0];
    visibleEntries.forEach((entry) => {
        if (entry.section.offsetTop <= activeOffset) {
            activeEntry = entry;
        }
    });
    setActiveSettingsSectionNav(activeEntry.section.id);
}

function queueSettingsSectionNavActiveUpdate() {
    if (settingsNavTicking) return;
    settingsNavTicking = true;
    requestAnimationFrame(() => {
        settingsNavTicking = false;
        updateSettingsSectionNavActive();
    });
}

function updateSettingsSectionNavVisibility() {
    const query = safeString(settingsSectionSearch?.value).toLowerCase();
    const advancedModeEnabled = Boolean(settingsSuite?.classList.contains('advanced-mode'));

    settingsSectionEntries.forEach((entry) => {
        const advancedOnly = entry.section.classList.contains('settings-advanced-only');
        const inMode = advancedModeEnabled || !advancedOnly;
        const matches = !query || entry.labelLower.includes(query);
        entry.link.classList.toggle('hidden', !(inMode && matches));
    });

    updateSettingsNavEmptyState();
    queueSettingsSectionNavActiveUpdate();
}

function scrollToSettingsSection(sectionId) {
    if (!settingsSections || !sectionId) return;
    const section = document.getElementById(sectionId);
    if (!isSettingsSectionVisible(section)) return;
    const top = Math.max(0, section.offsetTop - 8);
    settingsSections.scrollTo({ top, behavior: 'smooth' });
    setActiveSettingsSectionNav(sectionId);
}

function buildSettingsSectionNav() {
    if (!settingsSectionNav || !settingsSections) return;
    settingsSectionNav.innerHTML = '';
    settingsSectionEntries = [];

    const seenIds = new Set();
    const sections = Array.from(settingsSections.querySelectorAll('.settings-section'));
    sections.forEach((section, index) => {
        const heading = section.querySelector('.settings-section-head h3');
        const label = safeString(heading?.textContent) || `Section ${index + 1}`;
        const baseId = safeString(section.id) || `settings-${slugifySettingsLabel(label) || `section-${index + 1}`}`;
        let sectionId = baseId;
        let suffix = 2;
        while (seenIds.has(sectionId)) {
            sectionId = `${baseId}-${suffix}`;
            suffix += 1;
        }
        seenIds.add(sectionId);
        section.id = sectionId;

        const link = document.createElement('button');
        link.type = 'button';
        link.className = 'settings-nav-link';
        link.textContent = label;
        link.dataset.sectionId = sectionId;
        link.setAttribute('aria-current', 'false');
        link.addEventListener('click', () => scrollToSettingsSection(sectionId));
        settingsSectionNav.appendChild(link);

        settingsSectionEntries.push({
            section,
            link,
            labelLower: label.toLowerCase(),
        });
    });

    updateSettingsSectionNavVisibility();
}

function initSettingsSectionNavigation() {
    if (settingsNavBound || !settingsSectionNav || !settingsSections) return;
    settingsNavBound = true;
    buildSettingsSectionNav();

    if (settingsSectionSearch) {
        settingsSectionSearch.addEventListener('input', updateSettingsSectionNavVisibility);
    }

    settingsSections.addEventListener('scroll', queueSettingsSectionNavActiveUpdate, { passive: true });
    window.addEventListener('resize', queueSettingsSectionNavActiveUpdate);
}

// 
//   INITIAL STATE & BOOT                                                   
//   loadInitialState(), session creation, profile loading, preference sync 
// 

async function maybeHandleBootPluginInstall() {
    if (bootPluginInstallPromise) {
        return bootPluginInstallPromise;
    }
    if (bootPluginInstallHandled) {
        return null;
    }
    const deepLink = loadRequestedPluginInstallDeepLinkFromUrl();
    if (!deepLink) {
        return null;
    }
    bootPluginInstallHandled = true;
    clearRequestedPluginInstallFromUrl();
    bootPluginInstallPromise = (async () => {
        setSidebarNavMode('marketplace');
        notifyUser('Installing plugin from Thomas website...', {
            tone: 'info',
            durationMs: 1800,
            debugKind: 'marketplace-install',
        });
        const result = await moduleInstallMarketplacePluginFromDeepLink(deepLink);
        await moduleRefreshMarketplace({ force: true });
        if (!result?.ok) {
            setSidebarNavMode('marketplace');
            moduleRender('marketplace', { touch: false });
            const reason = safeString(result?.error) || 'Unable to install plugin.';
            notifyUser(`Plugin install failed: ${reason} Use Download ZIP and Install From File in Marketplace if needed.`, {
                tone: 'error',
                durationMs: 4800,
                debugKind: 'marketplace-install',
            });
            return result;
        }
        const modeId = safeString(result?.plugin?.mode_id);
        if (modeId) {
            setSidebarNavMode(modeId);
        } else {
            setSidebarNavMode('marketplace');
            moduleRender('marketplace', { touch: false });
        }
        const displayName = safeString(result?.plugin?.display_name) || 'Plugin';
        notifyUser(`${displayName} installed from the Thomas store.`, {
            tone: 'success',
            durationMs: 2200,
            debugKind: 'marketplace-install',
        });
        return result;
    })().finally(() => {
        bootPluginInstallPromise = null;
    });
    return bootPluginInstallPromise;
}

async function loadInitialState() {
    let loadedFromHistory = false;
    try {
        await refreshIdentityState();
        await fetchModels();
        await fetchChatHistory();

        const storedActiveChatId = loadStoredActiveChatId();
        const hasStoredSession = Boolean(storedActiveChatId)
            && sidebarSessions.some((row) => safeString(row?.id) === safeString(storedActiveChatId));
        if (hasStoredSession) {
            await loadSessionFromHistory(storedActiveChatId);
            loadedFromHistory = true;
        } else if (storedActiveChatId) {
            saveStoredActiveChatId('');
        }

        if (!loadedFromHistory && sidebarSessions.length > 0) {
            const latestSessionId = safeString(sidebarSessions[0]?.id);
            if (latestSessionId) {
                await loadSessionFromHistory(latestSessionId);
                loadedFromHistory = true;
            }
        }

        if (!loadedFromHistory) {
            await createNewSessionAndRefresh();
        }
    } catch (e) {
        console.error("Failed to boot session:", e);
        await createNewSessionAndRefresh();
    } finally {
        _positionRobotDock();
        if (!document.querySelector('.chat-robot-landed')) {
            _landRobotAtComposerDock();
        }
        await maybeAutoOpenEasySetup();
        await maybeHandleBootPluginInstall();
    }
}

async function fetchChatHistory() {
    try {
        const res = await fetchJsonSafe('/api/chats');
        if (res.ok) {
            const data = res.data || {};
            const chatRows = Array.isArray(data?.chats) ? data.chats : [];
            if (chatRows.length > 0) {
                sidebarSessions = chatRows
                    .map((row) => mapPersistedChatToSidebarSession(row))
                    .filter(Boolean);
            } else {
                const legacySessions = Array.isArray(data?.sessions) ? data.sessions : [];
                sidebarSessions = legacySessions
                    .map((row) => mapLegacySidebarSession(row))
                    .filter(Boolean);
            }
            sidebarSessions.sort((a, b) => Number(b?.updatedAt || 0) - Number(a?.updatedAt || 0));
            rebuildChatHistorySelector();
            renderSidebarChatList();
            updateDebugDockSnapshot();
        }
    } catch (e) {
        console.error("Failed to fetch chat history:", e);
    }
}

async function createNewSessionAndRefresh() {
    try {
        const res = await fetchJsonSafe('/api/session/new', { method: 'POST' });
        const data = res.data || {};
        if (res.ok && data.session_id) {
            sessionId = data.session_id;
            activeChatId = data.session_id;
            saveStoredActiveChatId(activeChatId);
            pushDebugEvent('chat', `Created session ${sessionId}`);
            // Clear current UI chat
            chatHistory = [];
            chatMessagesInner.innerHTML = '';
            welcomeScreen.classList.remove('hidden');
            chatScrollArea.classList.add('hidden');
            maybeRenderSessionIntro();
            showStarterSuggestionRail({ force: true });
            await fetchChatHistory();
            await refreshTaskContinuity({ sessionOverride: sessionId, force: true });
        }
    } catch (e) { console.error("Error creating new session:", e); }
}

async function saveAgentIdentityName(nameRaw, { source = 'rename' } = {}) {
    const nextName = sanitizeAgentNameInput(nameRaw);
    if (!nextName) {
        notifyUser('Agent name cannot be empty.', {
            tone: 'warning',
            durationMs: 2400,
            debugKind: 'settings',
        });
        return false;
    }

    const currentName = getAgentName();
    if (nextName === currentName) return true;

    const payload = {
        profile: {
            display_name: nextName,
            avatar_url: safeString(currentPreferences?.profile?.avatar_url),
        },
    };

    try {
        const res = await fetch('/api/preferences', {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
        });
        if (!res.ok) {
            const details = await res.text();
            throw new Error(details || `HTTP ${res.status}`);
        }
        currentPreferences = await res.json();
        if (settingsDisplayName) settingsDisplayName.value = resolveAgentName(currentPreferences);
        refreshSettingsAvatarPreview();
        updateSidebarIdentity();
        notifyUser(`Agent renamed to ${getAgentName()}.`, {
            tone: 'success',
            durationMs: 2200,
            debugKind: 'settings',
        });
        emitOnboardingTelemetry('agent.renamed', {
            source: safeString(source) || 'rename',
            name: getAgentName(),
        });
        return true;
    } catch (error) {
        notifyUser(`Could not rename agent: ${safeString(error?.message) || 'unknown error'}`, {
            tone: 'error',
            durationMs: 3000,
            debugKind: 'error',
        });
        return false;
    }
}

async function promptRenameAgentIdentity() {
    const currentName = getAgentName();
    const prompted = window.prompt('Rename your assistant', currentName);
    if (prompted === null) return;
    const nextName = sanitizeAgentNameInput(prompted);
    if (!nextName) {
        notifyUser('Agent name cannot be blank.', {
            tone: 'warning',
            durationMs: 2400,
            debugKind: 'settings',
        });
        return;
    }
    await saveAgentIdentityName(nextName, { source: 'sidebar_pencil' });
}

async function loadSessionFromHistory(sid) {
    activeChatId = sid;
    saveStoredActiveChatId(activeChatId);
    rebuildChatHistorySelector();
    try {
        let sessionData = sidebarSessions.find((row) => safeString(row?.id) === safeString(sid)) || null;
        if (!sessionData) {
            await fetchChatHistory();
            sessionData = sidebarSessions.find((row) => safeString(row?.id) === safeString(sid)) || null;
        }
        if (!sessionData) {
            throw new Error(`Chat ${sid} not found.`);
        }

        const loadedHistory = normalizeConversationHistory(sessionData.messages);
        chatHistory = loadedHistory;
        chatMessagesInner.innerHTML = '';
        if (chatHistory.length > 0) {
            welcomeScreen.classList.add('hidden');
            chatScrollArea.classList.remove('hidden');
            let lastAssistantMessage = '';
            let lastUserMessage = '';
            chatHistory.forEach((msg) => {
                renderMessage(msg);
                if (safeString(msg?.role) === 'user') {
                    lastUserMessage = safeString(msg?.content);
                }
                if (safeString(msg?.role) === 'assistant') {
                    lastAssistantMessage = safeString(msg?.content);
                }
            });
            if (lastAssistantMessage) {
                maybeShowAssistantFollowups({
                    assistantText: lastAssistantMessage,
                    userText: lastUserMessage,
                });
            } else {
                showStarterSuggestionRail({ force: true });
            }
        } else {
            welcomeScreen.classList.remove('hidden');
            chatScrollArea.classList.add('hidden');
            maybeRenderSessionIntro();
            showStarterSuggestionRail({ force: true });
        }

        // Bind runtime to the persisted chat id so multiple tabs/windows
        // stay on one canonical session state for the same chat.
        sessionId = safeString(sid);
    } catch (e) { console.error("Error loading past session", e); }
    syncActiveChatSidebarEntry();
    renderSidebarChatList();
    pushDebugEvent('chat', `Loaded session ${safeString(sid)}`);
    await refreshTaskContinuity({ sessionOverride: sessionId || sid, force: true });
    _positionRobotDock();
    if (!document.querySelector('.chat-robot-landed')) {
        _landRobotAtComposerDock();
    }
}

async function fetchModels() {
    try {
        const res = await fetchJsonSafe('/api/models', { timeoutMs: 8000 });
        if (res.ok) {
            const data = res.data || {};
            availableModelProfiles = Array.isArray(data.profiles) ? data.profiles : [];
            modelSelector.innerHTML = '';
            setupProviderSelector.innerHTML = '';

            // Partition into connected vs. additional providers for the setup picker.
            const active = availableModelProfiles.filter(m => m.has_api_key);

            for (const m of availableModelProfiles) {
                const providerOption = document.createElement('option');
                providerOption.value = m.name;
                providerOption.textContent = m.name;
                setupProviderSelector.appendChild(providerOption);

                const legacyOption = document.createElement('option');
                legacyOption.value = m.name;
                legacyOption.textContent = m.name;
                modelSelector.appendChild(legacyOption);
            }

            // Determine target profile: saved active preference > localStorage backup > server default > first connected
            const savedProfile = safeString(currentPreferences?.advanced?.model?.active_profile)
                || safeString(window.localStorage.getItem('thomas_active_profile'));
            const savedProfileMeta = savedProfile ? availableModelProfiles.find(m => m.name === savedProfile) : null;
            const hasPersistedProfile = Boolean(safeString(currentPreferences?.advanced?.model?.active_profile));
            const targetProfile = (savedProfileMeta && savedProfileMeta.active)
                ? savedProfile
                : (data.default || (active[0] && active[0].name) || (availableModelProfiles[0] && availableModelProfiles[0].name) || '');

            applyProfileSelection(targetProfile, { allowLocalBackup: !hasPersistedProfile });
            renderSetupProviderPickerMenu(targetProfile, { preserveExpanded: false });

            refreshEasySetupProfileOptions();
            updateDebugDockSnapshot();
        }
    } catch (e) { console.error("Failed to fetch models", e); }
}

